-- ▶ billing.sql

-- Repple billing (Stripe). The platform owner charges TRAINERS a subscription
-- (the white-label fee). These tables are written ONLY by the stripe-webhook
-- edge function via the service role; the app reads its own rows. Idempotent.
-- Depends on schema.sql (profiles with a `role` column). Client payments to
-- trainers (Stripe Connect) are a separate later phase — not in this file.

create table if not exists billing_customers (
  trainer_id uuid primary key references profiles(id) on delete cascade,
  stripe_customer_id text not null unique,
  email text,
  created_at timestamptz not null default now()
);

create table if not exists subscriptions (
  trainer_id uuid primary key references profiles(id) on delete cascade,
  stripe_subscription_id text unique,
  plan text,
  status text,                     -- active | trialing | past_due | canceled | unpaid | incomplete
  current_period_end timestamptz,
  cancel_at_period_end boolean not null default false,
  updated_at timestamptz not null default now()
);

create table if not exists invoices (
  id text primary key,             -- stripe invoice id
  trainer_id uuid references profiles(id) on delete set null,
  amount_due integer,              -- cents
  currency text,
  status text,                     -- paid | open | uncollectible | void
  attempt_count integer,
  hosted_invoice_url text,
  created_at timestamptz not null default now()
);
create index if not exists idx_invoices_trainer on invoices (trainer_id, created_at desc);

alter table billing_customers enable row level security;
alter table subscriptions enable row level security;
alter table invoices enable row level security;

-- A trainer sees their own billing; the owner sees everyone's (for dunning).
drop policy if exists cust_read on billing_customers;
create policy cust_read on billing_customers for select using (
  trainer_id = auth.uid() or exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'owner'));
drop policy if exists sub_read on subscriptions;
create policy sub_read on subscriptions for select using (
  trainer_id = auth.uid() or exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'owner'));
drop policy if exists inv_read on invoices;
create policy inv_read on invoices for select using (
  trainer_id = auth.uid() or exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'owner'));

-- ▶ connect.sql

-- Stripe Connect — trainers get paid by THEIR clients (marketplace layer on top
-- of the platform subscription billing in billing.sql). Each trainer is a Stripe
-- Express connected account; clients pay via Checkout with the platform taking an
-- application fee. Connect tables are written by the connect-* edge functions via
-- the service role; trainers manage their own packages directly (RLS). Idempotent.

create table if not exists connect_accounts (
  trainer_id uuid primary key references profiles(id) on delete cascade,
  stripe_account_id text unique,
  charges_enabled boolean not null default false,
  details_submitted boolean not null default false,
  updated_at timestamptz not null default now()
);

create table if not exists trainer_packages (
  id uuid primary key default gen_random_uuid(),
  trainer_id uuid not null references profiles(id) on delete cascade,
  name text not null,
  price_cents integer not null,        -- price in cents
  currency text not null default 'usd',
  sessions integer,                    -- null = membership/one-off; N = a session pack
  active boolean not null default true,
  created_at timestamptz not null default now()
);
create index if not exists idx_packages_trainer on trainer_packages (trainer_id) where active;

create table if not exists client_purchases (
  id uuid primary key default gen_random_uuid(),
  client_id uuid references profiles(id) on delete set null,
  trainer_id uuid references profiles(id) on delete set null,
  package_id uuid references trainer_packages(id) on delete set null,
  stripe_session_id text unique,
  amount_cents integer,
  sessions_total integer,
  sessions_used integer not null default 0,
  status text not null default 'paid',
  created_at timestamptz not null default now()
);
create index if not exists idx_purchases_client on client_purchases (client_id, created_at desc);
create index if not exists idx_purchases_trainer on client_purchases (trainer_id, created_at desc);

alter table connect_accounts enable row level security;
alter table trainer_packages enable row level security;
alter table client_purchases enable row level security;

-- Connect account: the trainer reads their own; the owner reads all.
drop policy if exists conn_read on connect_accounts;
create policy conn_read on connect_accounts for select using (
  trainer_id = auth.uid() or exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'owner'));

-- Packages: any signed-in user reads ACTIVE packages (clients browse); a trainer
-- fully manages their own (create/edit/deactivate) straight from the app.
drop policy if exists pkg_read on trainer_packages;
create policy pkg_read on trainer_packages for select using (active or trainer_id = auth.uid());
drop policy if exists pkg_write on trainer_packages;
create policy pkg_write on trainer_packages for all using (trainer_id = auth.uid()) with check (trainer_id = auth.uid());

-- Purchases: the client sees their own, the trainer sees theirs, the owner all.
drop policy if exists purch_read on client_purchases;
create policy purch_read on client_purchases for select using (
  client_id = auth.uid() or trainer_id = auth.uid()
  or exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'owner'));

-- ▶ session-approvals.sql

-- Client approval of a delivered PT session, with the optional comment the
-- pt-sessions screen has always collected and never sent anywhere.
--
-- The approval lives in its own table rather than as columns on `sessions`
-- because `sessions_client_read` lets a client read sessions belonging to their
-- trainer. A note column on `sessions` would therefore be readable by every
-- other client of that trainer. Row-level security cannot restrict individual
-- columns, so the note gets its own table with its own policy: the client who
-- wrote it, and the trainer who delivered the session.

create table if not exists public.session_approvals (
  session_id  uuid primary key references public.sessions(id) on delete cascade,
  client_id   uuid not null references auth.users(id) on delete cascade,
  approved_at timestamptz not null default now(),
  note        text
);

alter table public.session_approvals enable row level security;

drop policy if exists session_approvals_read on public.session_approvals;
create policy session_approvals_read on public.session_approvals
  for select using (
    client_id = (select auth.uid())
    or exists (
      select 1 from public.sessions s
       where s.id = session_approvals.session_id
         and s.trainer_id = (select auth.uid())
    )
  );

-- Deliberately no insert/update/delete policies. Every write goes through
-- approve_session() so a client cannot approve on someone else's behalf, and
-- cannot reach status or trainer_id while doing it.
grant select on public.session_approvals to authenticated;

create or replace function public.approve_session(p_session uuid, p_note text default null)
returns void
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if not exists (
    select 1 from sessions s
     where s.id = p_session
       and s.client_id = auth.uid()
       and s.status = 'booked'
       and s.starts_at <= now()
  ) then
    -- Covers all three refusals: not yours, not booked, or not yet delivered.
    raise exception 'That session cannot be approved.';
  end if;

  insert into session_approvals (session_id, client_id, note)
  values (p_session, auth.uid(), v_note)
  on conflict (session_id) do update
     set note = excluded.note, approved_at = now();
end
$function$;

revoke all on function public.approve_session(uuid, text) from public;
revoke execute on function public.approve_session(uuid, text) from public, anon;
grant execute on function public.approve_session(uuid, text) to authenticated;

-- Unrelated to approvals, found while reading the policy: clients could read
-- every session of their trainer, including which client was booked into each
-- slot. Every client screen already filters to `available` or `mine`, so
-- narrowing this changes no UI -- it just stops other clients' rows leaving the
-- database.
drop policy if exists sessions_client_read on public.sessions;
create policy sessions_client_read on public.sessions
  for select using (
    client_id = (select auth.uid())
    or (
      status = 'available'
      and exists (
        select 1 from public.clients c
         where c.id = (select auth.uid())
           and c.trainer_id = sessions.trainer_id
      )
    )
  );

-- ▶ trainer-directory.sql

-- Trainer directory → coaching request → roster.
--
-- DUMPED FROM THE LIVE DATABASE (project phgfwzpkkwdysftlgkoq), not authored
-- here. These objects were applied by hand in an earlier session and had never
-- been written down; an earlier reconstruction of them from the app's call sites
-- got several details wrong, so this file is the database's own definition.
-- Re-running it against live is a no-op.

-- ── Public-facing trainer profile ───────────────────────────────────────────
-- Nullable with no defaults, matching live. (A reconstruction had these NOT NULL
-- with defaults, which `add column if not exists` would have silently skipped.)
alter table trainers add column if not exists tagline     text;
alter table trainers add column if not exists offers      text[];
alter table trainers add column if not exists specialties text[];
alter table trainers add column if not exists session_fee numeric;
alter table trainers add column if not exists listed      boolean not null default false;

create index if not exists trainers_listed_idx on trainers(listed) where listed;

alter table trainers enable row level security;

-- Five policies, all SELECT except the trainer's own row. `trainers` is readable
-- far more narrowly than the repo previously suggested.
drop policy if exists trainers_self_rw on trainers;
create policy trainers_self_rw on trainers
  for all using ((select auth.uid()) = id);

drop policy if exists trainers_public_directory_r on trainers;
create policy trainers_public_directory_r on trainers
  for select to authenticated using (listed = true);

drop policy if exists trainers_owner_r on trainers;
create policy trainers_owner_r on trainers
  for select using (is_owner_of(tenant_id));

drop policy if exists trainers_peer_r on trainers;
create policy trainers_peer_r on trainers
  for select using (exists (
    select 1 from trainers t1
     where t1.id = (select auth.uid()) and t1.tenant_id = trainers.tenant_id));

drop policy if exists trainers_assigned_client_r on trainers;
create policy trainers_assigned_client_r on trainers
  for select using (exists (
    select 1 from coach_clients
     where coach_clients.trainer_id = trainers.id
       and coach_clients.id = (select auth.uid())));

-- ── Coaching requests ───────────────────────────────────────────────────────
create table if not exists coach_requests (
  id           uuid primary key default gen_random_uuid(),
  client_id    uuid not null references profiles(id) on delete cascade,
  trainer_id   uuid not null references profiles(id) on delete cascade,
  mode         text not null default 'online'  check (mode in ('online','inperson')),
  status       text not null default 'pending' check (status in ('pending','accepted','declined','withdrawn')),
  note         text,
  created_at   timestamptz not null default now(),
  responded_at timestamptz
);

-- Partial unique: one PENDING request per pair, but a declined request can be
-- sent again later. A plain unique (client_id, trainer_id) would have blocked
-- that forever; this is what makes trainers.tsx's duplicate handling correct.
create unique index if not exists coach_requests_one_pending
  on coach_requests(client_id, trainer_id) where status = 'pending';
create index if not exists coach_requests_client_idx  on coach_requests(client_id, status);
create index if not exists coach_requests_trainer_idx on coach_requests(trainer_id, status);

alter table coach_requests enable row level security;

drop policy if exists coach_requests_client_rw on coach_requests;
create policy coach_requests_client_rw on coach_requests
  for all to authenticated
  using (client_id = (select auth.uid()))
  with check (client_id = (select auth.uid()));

drop policy if exists coach_requests_trainer_r on coach_requests;
create policy coach_requests_trainer_r on coach_requests
  for select to authenticated using (trainer_id = (select auth.uid()));

drop policy if exists coach_requests_trainer_u on coach_requests;
create policy coach_requests_trainer_u on coach_requests
  for update to authenticated
  using (trainer_id = (select auth.uid()))
  with check (trainer_id = (select auth.uid()));

-- ── Coach-created roster entries ────────────────────────────────────────────
-- `id` is not a foreign key: a coach adds clients by hand who have no auth
-- account. `trainer_id` references auth.users directly, not profiles.
create table if not exists coach_clients (
  id         uuid primary key default gen_random_uuid(),
  trainer_id uuid not null references auth.users(id) on delete cascade,
  name       text not null,
  goal       text,
  mode       text not null default 'online' check (mode in ('online','inperson')),
  created_at timestamptz not null default now()
);

create index if not exists coach_clients_trainer_idx on coach_clients(trainer_id, created_at);

alter table coach_clients enable row level security;

-- cc_own and coach_clients_trainer_rw are redundant with each other; both exist
-- live and both are reproduced so this file matches the database exactly.
drop policy if exists cc_own on coach_clients;
create policy cc_own on coach_clients
  for all using (trainer_id = (select auth.uid()))
  with check (trainer_id = (select auth.uid()));

drop policy if exists coach_clients_trainer_rw on coach_clients;
create policy coach_clients_trainer_rw on coach_clients
  for all using ((select auth.uid()) = trainer_id);

drop policy if exists coach_clients_client_r on coach_clients;
create policy coach_clients_client_r on coach_clients
  for select using ((select auth.uid()) = id);

drop policy if exists coach_clients_owner_r on coach_clients;
create policy coach_clients_owner_r on coach_clients
  for select using (exists (
    select 1 from profiles
     where profiles.id = (select auth.uid()) and profiles.role = 'owner'));

-- ▶ trainer-availability.sql

-- Trainer weekly availability template — recurring day-of-week + hour slots.
--
-- DUMPED FROM THE LIVE DATABASE. Note `integer` (not smallint) and the absence
-- of a unique constraint on (trainer_id, dow, hour): availability.ts dedups
-- client-side only, so two devices can still create the same slot twice. Left as
-- live has it rather than silently tightening a constraint on existing rows.

create table if not exists trainer_availability (
  id         uuid primary key default gen_random_uuid(),
  trainer_id uuid not null references auth.users(id) on delete cascade,
  dow        integer not null check (dow >= 0 and dow <= 6),   -- 0 = Sunday
  hour       integer not null check (hour >= 0 and hour <= 23),
  dur        integer not null default 60,                      -- minutes
  created_at timestamptz not null default now()
);

create index if not exists trainer_availability_idx
  on trainer_availability(trainer_id, dow, hour);

alter table trainer_availability enable row level security;

drop policy if exists ta_own on trainer_availability;
create policy ta_own on trainer_availability
  for all using (trainer_id = (select auth.uid()))
  with check (trainer_id = (select auth.uid()));

-- ▶ class-attendance.sql

-- Group-class attendance: the trainer checks members into a class, the owner
-- reads fill rates for payroll and analytics.
--
-- DUMPED FROM THE LIVE DATABASE. The important detail, and the one a
-- reconstruction got wrong: attendance is recorded as `class_bookings.attended_at
-- is not null`. There is no `attended` boolean column. Adding one and switching
-- the functions to it would have orphaned every attendance already recorded.

alter table class_bookings add column if not exists attended_at timestamptz;

create index if not exists idx_class_bookings_user_id on class_bookings(user_id);

-- The owner of the tenant that owns the class can read its bookings.
drop policy if exists class_bookings_owner_r on class_bookings;
create policy class_bookings_owner_r on class_bookings
  for select using (exists (
    select 1 from gym_classes gc
      join trainers t on t.id = gc.trainer_id
     where gc.id = class_bookings.class_id and is_owner_of(t.tenant_id)));

-- ── The check-in roster for one class ───────────────────────────────────────
-- Readable by the class's trainer OR an owner.
create or replace function public.class_roster(p_class uuid)
returns table(user_id uuid, name text, status text, attended boolean)
language sql
security definer
set search_path to 'public'
as $function$
  select cb.user_id,
         coalesce(p.full_name, 'Member') as name,
         cb.status,
         (cb.attended_at is not null) as attended
  from class_bookings cb
  left join profiles p on p.id = cb.user_id
  where cb.class_id = p_class
    and ( exists (select 1 from gym_classes gc where gc.id = p_class and gc.trainer_id = auth.uid())
          or exists (select 1 from profiles o where o.id = auth.uid() and o.role = 'owner') )
  order by name;
$function$;

-- ── Mark one member present or absent ───────────────────────────────────────
create or replace function public.set_class_attendance(p_class uuid, p_user uuid, p_present boolean)
returns void
language plpgsql
security definer
set search_path to 'public'
as $function$
begin
  if not exists (select 1 from gym_classes gc where gc.id = p_class and gc.trainer_id = auth.uid()) then
    raise exception 'not your class';
  end if;
  update class_bookings
     set attended_at = case when p_present then now() else null end
   where class_id = p_class and user_id = p_user;
end; $function$;

-- ── Attendance over a date range ────────────────────────────────────────────
-- Visible to the class's own trainer OR an owner, and the range is half-open
-- (>= p_from, < p_to). Parameter names are load-bearing: PostgREST binds by
-- name, so they must match src/lib/classAttendance.ts exactly.
--
-- Note for anything calling this server-side: the guard is on auth.uid(), which
-- is NULL under the service role, so a service-role call returns zero rows.
create or replace function public.class_attendance_summary(p_from timestamptz, p_to timestamptz)
returns table(class_id uuid, title text, kind text, branch text, trainer_id uuid,
              trainer_name text, starts_at timestamptz, booked integer, attended integer)
language sql
security definer
set search_path to 'public'
as $function$
  select gc.id, gc.title, gc.kind, gc.branch, gc.trainer_id,
         coalesce(tp.full_name, 'Trainer') as trainer_name, gc.starts_at,
         count(cb.id) filter (where cb.status = 'booked')::int as booked,
         count(cb.attended_at)::int as attended
  from gym_classes gc
  left join class_bookings cb on cb.class_id = gc.id
  left join profiles tp on tp.id = gc.trainer_id
  where gc.starts_at >= p_from and gc.starts_at < p_to
    and ( gc.trainer_id = auth.uid()
          or exists (select 1 from profiles o where o.id = auth.uid() and o.role = 'owner') )
  group by gc.id, tp.full_name
  order by gc.starts_at desc;
$function$;

-- ▶ message-notifications.sql

-- Push + in-app notification on a new message.
--
-- An AFTER INSERT trigger on `messages` posts to the `notify-message` edge
-- function via pg_net; that function resolves the recipient, writes the
-- notifications row and sends the Expo push.
--
-- `notify-message` runs with verify_jwt:false, so it is publicly reachable and
-- this shared secret is its ONLY authentication. The secret is read from Vault
-- at call time and is deliberately not a literal here: the original version of
-- this function carried it in plaintext in its body, where anything able to read
-- pg_proc could read it. That value has been rotated.
--
-- Rotating again needs no change to this file — set a new value in BOTH:
--   • Vault secret `hook_secret`  (Dashboard ▸ Project Settings ▸ Vault)
--   • edge function secret `HOOK_SECRET`
-- Between saving the second one and the first, pushes are skipped; messages
-- themselves are unaffected.

create or replace function public.notify_on_message()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_secret text;
begin
  select decrypted_secret into v_secret
    from vault.decrypted_secrets
   where name = 'hook_secret'
   limit 1;

  -- No secret configured: skip rather than post an unauthenticated request.
  if v_secret is null or v_secret = '' then
    return NEW;
  end if;

  perform net.http_post(
    url     := 'https://phgfwzpkkwdysftlgkoq.supabase.co/functions/v1/notify-message',
    headers := jsonb_build_object('Content-Type', 'application/json'),
    body    := jsonb_build_object(
      'secret',    v_secret,
      'client_id', NEW.client_id,
      'sender',    NEW.sender,
      'body',      NEW.body
    )
  );
  return NEW;
-- A failed notification must never block the message itself from being written.
exception when others then
  return NEW;
end;
$function$;

drop trigger if exists on_message_insert on public.messages;
create trigger on_message_insert
  after insert on public.messages
  for each row execute function notify_on_message();

-- ▶ owner-portal-access.sql

-- Owner portal reads.
--
-- `profiles.role = 'owner'` means a GYM owner, scoped to their tenant — the
-- meaning the rest of the policies already assumed via is_owner_of(tenant_id).
-- Reading the live policies, an owner can already see their tenant's profiles,
-- clients, trainers and the tenant row itself. One table was missing.
--
-- Without this an owner cannot read sessions at all, so "sessions delivered"
-- and any payroll figure derived from it have nothing behind them. The portal
-- would show zero and the zero would be a permissions artefact rather than a
-- fact about the gym — which is the exact failure this codebase keeps removing.

drop policy if exists sessions_owner_r on sessions;
create policy sessions_owner_r on sessions
  for select using (
    exists (
      select 1 from trainers t
       where t.id = sessions.trainer_id
         and is_owner_of(t.tenant_id)
    )
  );

-- ▶ fix-profiles-recursion.sql

-- Every authenticated read of `profiles` was failing:
--
--   infinite recursion detected in policy for relation "profiles"
--
-- The visible damage was small and constant. The client dashboard greeted
-- people with "Good afternoon" and no name, the Me screen showed no name, and
-- the avatar fell back to a hardcoded letter. The app swallowed the error and
-- rendered defaults, so it looked like cosmetic polish rather than a table that
-- could not be read at all.
--
-- Three separate cycles, all the same shape — a policy asking a question whose
-- answer lives in a table that is itself policed:
--
--   1. `profiles_trainer_r_peers` / `_r_clients` asked "what is my role?" with a
--      sub-select on `profiles`, from inside a policy ON `profiles`.
--   2. Nine policies across eight other tables asked "am I an owner?" the same
--      way. Reachable from `profiles` via trainers → coach_clients, so they
--      closed the loop from outside.
--   3. `trainers_peer_r` asked "am I a trainer in this tenant?" with a
--      sub-select on `trainers`, from inside a policy ON `trainers`.
--
-- The fix is one idea applied everywhere: ask those questions through a
-- SECURITY DEFINER function, which runs as the table owner and does not
-- re-enter RLS.
--
-- `is_owner_of` looked like it already did this and did not — it was declared
-- STABLE but SECURITY INVOKER, so it recursed like the rest. It is corrected
-- here too.

create or replace function public.my_role()
returns text language sql stable security definer set search_path to 'public'
as $function$ select role from profiles where id = auth.uid() $function$;

create or replace function public.my_tenant()
returns uuid language sql stable security definer set search_path to 'public'
as $function$ select tenant_id from profiles where id = auth.uid() $function$;

revoke all on function public.my_role() from public;
revoke all on function public.my_tenant() from public;
grant execute on function public.my_role() to authenticated;
grant execute on function public.my_tenant() to authenticated;

-- Was SECURITY INVOKER; that is what made it recurse.
create or replace function public.is_owner_of(t uuid)
returns boolean language sql stable security definer set search_path to 'public', 'pg_temp'
as $function$
  select exists (
    select 1 from profiles p
     where p.id = auth.uid() and p.role = 'owner' and p.tenant_id = t
  );
$function$;

-- ── 1. profiles policing profiles ───────────────────────────────────────────
drop policy if exists profiles_trainer_r_peers on profiles;
create policy profiles_trainer_r_peers on profiles
  for select using (my_role() = 'trainer' and role = 'trainer' and tenant_id = my_tenant());

drop policy if exists profiles_trainer_r_clients on profiles;
create policy profiles_trainer_r_clients on profiles
  for select using (
    my_role() = 'trainer'
    and exists (select 1 from coach_clients
                 where coach_clients.trainer_id = auth.uid()
                   and coach_clients.id = profiles.id));

-- ── 2. the "am I an owner?" question, asked from eight other tables ─────────
drop policy if exists app_errors_owner on app_errors;
create policy app_errors_owner on app_errors for select using (my_role() = 'owner');

drop policy if exists purch_read on client_purchases;
create policy purch_read on client_purchases for select using (
  client_id = (select auth.uid()) or trainer_id = (select auth.uid()) or my_role() = 'owner');

drop policy if exists coach_clients_owner_r on coach_clients;
create policy coach_clients_owner_r on coach_clients for select using (my_role() = 'owner');

drop policy if exists conn_read on connect_accounts;
create policy conn_read on connect_accounts for select using (
  trainer_id = (select auth.uid()) or my_role() = 'owner');

drop policy if exists exvid_read on exercise_videos;
create policy exvid_read on exercise_videos for select using (
  trainer_id = (select auth.uid())
  or exists (select 1 from clients c
              where c.id = (select auth.uid()) and c.trainer_id = exercise_videos.trainer_id)
  or my_role() = 'owner');

drop policy if exists fb_owner on feedback;
create policy fb_owner on feedback for select using (
  is_owner_of(tenant_id) or my_role() = 'owner');

drop policy if exists inv_read on invoices;
create policy inv_read on invoices for select using (
  trainer_id = (select auth.uid()) or my_role() = 'owner');

drop policy if exists sub_owner on subscriptions;
create policy sub_owner on subscriptions for select using (my_role() = 'owner');

drop policy if exists tenants_owner_rw on tenants;
create policy tenants_owner_rw on tenants for all
  using (is_owner_of(tenants.id)) with check (is_owner_of(tenants.id));

-- ── 3. trainers policing trainers ───────────────────────────────────────────
drop policy if exists trainers_peer_r on trainers;
create policy trainers_peer_r on trainers
  for select using (my_role() = 'trainer' and tenant_id = my_tenant());

-- ▶ gym-operating-record.sql

-- ── The gym's operating record ──────────────────────────────────────────────
--
-- Phase 1 of the web roadmap. None of this existed, which is why every
-- financial figure in the owner portal read zero: `invoices` and `subscriptions`
-- are keyed on trainer_id and are Repple billing trainers for the product, and
-- `trainer_packages` is a trainer's own PT packages. A gym had nowhere to record
-- a membership or a payment at all.
--
-- Additive only. Nothing here alters an existing table.

-- what the gym sells
create table if not exists membership_plans (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  name text not null,
  price_cents integer not null check (price_cents >= 0),
  currency text not null default 'AED',
  -- `once` covers a day pass or a joining fee; it is not a recurring plan.
  interval text not null default 'month' check (interval in ('month','year','once')),
  active boolean not null default true,
  created_at timestamptz not null default now()
);
create index if not exists idx_membership_plans_tenant on membership_plans(tenant_id, active);

-- who holds one
create table if not exists memberships (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  member_id uuid not null references profiles(id) on delete cascade,
  -- A plan may be retired while a membership sold on it is still running, so
  -- this goes null rather than taking the membership with it.
  plan_id uuid references membership_plans(id) on delete set null,
  started_on date not null default current_date,
  -- null means open-ended, which is not the same as expired.
  ends_on date,
  status text not null default 'active'
    check (status in ('active', 'frozen', 'cancelled', 'expired')),
  note text,
  created_at timestamptz not null default now()
);
create index if not exists idx_memberships_tenant on memberships(tenant_id, status);
create index if not exists idx_memberships_member on memberships(member_id);

-- money the gym actually received. Recorded, never inferred: a row here means
-- somebody took money, and there is no other way for one to appear.
create table if not exists gym_payments (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  member_id uuid references profiles(id) on delete set null,
  membership_id uuid references memberships(id) on delete set null,
  amount_cents integer not null,
  currency text not null default 'AED',
  method text not null default 'card'
    check (method in ('card', 'cash', 'transfer', 'direct_debit', 'other')),
  taken_at timestamptz not null default now(),
  note text,
  recorded_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists idx_gym_payments_tenant on gym_payments(tenant_id, taken_at desc);
create index if not exists idx_gym_payments_member on gym_payments(member_id);

-- what the gym billed
create table if not exists gym_invoices (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  member_id uuid not null references profiles(id) on delete cascade,
  membership_id uuid references memberships(id) on delete set null,
  amount_cents integer not null check (amount_cents >= 0),
  currency text not null default 'AED',
  issued_on date not null default current_date,
  due_on date,
  status text not null default 'open'
    check (status in ('draft', 'open', 'paid', 'overdue', 'void', 'written_off')),
  note text,
  created_at timestamptz not null default now()
);
create index if not exists idx_gym_invoices_tenant on gym_invoices(tenant_id, status, due_on);
create index if not exists idx_gym_invoices_member on gym_invoices(member_id);

-- ── row-level security ──────────────────────────────────────────────────────
-- The helpers are SECURITY DEFINER, so a policy calling them does not re-enter
-- the table it is protecting — the recursion that once made `profiles`
-- unreadable for everyone (see 28-fix-profiles-recursion.sql).
alter table membership_plans enable row level security;
alter table memberships     enable row level security;
alter table gym_payments    enable row level security;
alter table gym_invoices    enable row level security;

drop policy if exists membership_plans_owner on membership_plans;
create policy membership_plans_owner on membership_plans
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

drop policy if exists memberships_owner on memberships;
create policy memberships_owner on memberships
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

drop policy if exists gym_payments_owner on gym_payments;
create policy gym_payments_owner on gym_payments
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

drop policy if exists gym_invoices_owner on gym_invoices;
create policy gym_invoices_owner on gym_invoices
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

-- Anyone in the gym may see what is on sale — a price book is not private, and
-- the member-facing booking pages will need it.
drop policy if exists membership_plans_tenant_r on membership_plans;
create policy membership_plans_tenant_r on membership_plans
  for select using (tenant_id = my_tenant() and active);

-- A member reads their own membership, invoices and payments, and nobody else's.
drop policy if exists memberships_own_r on memberships;
create policy memberships_own_r on memberships
  for select using (member_id = (select auth.uid()));

drop policy if exists gym_payments_own_r on gym_payments;
create policy gym_payments_own_r on gym_payments
  for select using (member_id = (select auth.uid()));

drop policy if exists gym_invoices_own_r on gym_invoices;
create policy gym_invoices_own_r on gym_invoices
  for select using (member_id = (select auth.uid()));

-- ▶ classes-tenant-scope.sql

-- ── Classes belong to a gym, not only to a trainer ──────────────────────────
--
-- Two problems.
--
-- First, `gym_classes` reached its tenant only through trainer_id ->
-- trainers.tenant_id, so a class with no trainer assigned was invisible to the
-- owner of the gym running it — and a gym cannot put a class on the timetable
-- before it knows who is teaching it.
--
-- Second, and worse: `gym_classes_read` was `auth.role() = 'authenticated'`,
-- which let any signed-in person read every class in every gym on the platform.
-- A member of one gym could enumerate a competitor's whole timetable. It was
-- corrected while the table was still empty, so no behaviour changed for
-- existing rows.

alter table gym_classes add column if not exists tenant_id uuid references tenants(id) on delete cascade;
create index if not exists idx_gym_classes_tenant on gym_classes(tenant_id, starts_at);

-- Older code paths (the trainer app) insert a class without naming the gym.
-- Rather than break them, derive it from the trainer so scoping stays direct.
create or replace function public.gym_classes_fill_tenant()
returns trigger language plpgsql security definer set search_path to 'public' as $$
begin
  if new.tenant_id is null and new.trainer_id is not null then
    select t.tenant_id into new.tenant_id from trainers t where t.id = new.trainer_id;
  end if;
  return new;
end $$;

drop trigger if exists trg_gym_classes_fill_tenant on gym_classes;
create trigger trg_gym_classes_fill_tenant
  before insert or update on gym_classes
  for each row execute function public.gym_classes_fill_tenant();

-- ── policies ────────────────────────────────────────────────────────────────
-- A row whose tenant_id is null is invisible to a tenant read rather than
-- visible to everyone: unscoped fails closed.
drop policy if exists gym_classes_read on gym_classes;
create policy gym_classes_read on gym_classes
  for select using (tenant_id = my_tenant());

drop policy if exists gym_classes_owner_rw on gym_classes;
create policy gym_classes_owner_rw on gym_classes
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

-- A trainer keeps managing their own classes.
drop policy if exists gym_classes_write on gym_classes;
create policy gym_classes_write on gym_classes
  for all using (trainer_id = (select auth.uid())) with check (trainer_id = (select auth.uid()));

-- The owner's view of who booked keys off the class's own tenant rather than a
-- second hop through trainers.
drop policy if exists class_bookings_owner_r on class_bookings;
create policy class_bookings_owner_r on class_bookings
  for select using (exists (
    select 1 from gym_classes gc
    where gc.id = class_bookings.class_id and is_owner_of(gc.tenant_id)
  ));

-- An owner marking attendance at the front desk is the whole point of the
-- roster, and previously only the class's own trainer could.
drop policy if exists class_bookings_owner_w on class_bookings;
create policy class_bookings_owner_w on class_bookings
  for update using (exists (
    select 1 from gym_classes gc
    where gc.id = class_bookings.class_id and is_owner_of(gc.tenant_id)
  )) with check (exists (
    select 1 from gym_classes gc
    where gc.id = class_bookings.class_id and is_owner_of(gc.tenant_id)
  ));

-- ▶ drop-ins-and-passes.sql

-- ── Drop-ins, guest passes and class packs ──────────────────────────────────
--
-- Phase 1, F16. A gym takes money from people who are not members: the walk-in
-- who pays for one session, the friend a member brings, the ten-class pack sold
-- at the desk. None of that fits `memberships`, which assumes a profile and a
-- recurring plan, so it was going unrecorded — and every attendance and revenue
-- figure was short by however much of it happens.
--
-- Additive only. Nothing here alters an existing table.

-- ── what the gym sells at the desk ──────────────────────────────────────────
create table if not exists gym_pass_types (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  name text not null,
  -- drop_in: one visit, bought by anyone.
  -- guest:   one visit, bought by (or gifted to) a member for someone else.
  -- pack:    a block of visits used over time.
  kind text not null default 'drop_in' check (kind in ('drop_in','guest','pack')),
  price_cents integer not null check (price_cents >= 0),
  currency text not null default 'AED',
  -- How many visits one purchase is worth. A drop-in is 1; a pack is n.
  uses integer not null default 1 check (uses >= 1),
  -- Days from issue until it expires. Null means it does not expire, which is
  -- a deliberate choice a gym makes, not a missing value.
  valid_days integer check (valid_days is null or valid_days > 0),
  active boolean not null default true,
  created_at timestamptz not null default now()
);
create index if not exists idx_gym_pass_types_tenant on gym_pass_types(tenant_id, active);

-- ── an issued pass ──────────────────────────────────────────────────────────
create table if not exists gym_passes (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  -- A type may be retired while passes sold on it are still valid, so this
  -- goes null rather than taking the pass with it.
  pass_type_id uuid references gym_pass_types(id) on delete set null,
  -- The holder is either a profile (a member, or a walk-in who made an account)
  -- or just a name written at the desk. Requiring an account to sell someone a
  -- day pass would mean the sale went unrecorded, which is how we got here.
  holder_id uuid references profiles(id) on delete set null,
  holder_name text,
  -- Who brought them, when this is a guest pass. Useful on its own: guests of
  -- members convert differently from cold walk-ins.
  host_member_id uuid references profiles(id) on delete set null,
  issued_on date not null default current_date,
  expires_on date,
  uses_total integer not null check (uses_total >= 1),
  uses_spent integer not null default 0 check (uses_spent >= 0),
  -- What was actually taken for it. Null means nobody recorded a price — not
  -- that it was free. `gymPasses.passRevenueCents` returns null for that rather
  -- than quietly counting it as zero.
  paid_cents integer check (paid_cents is null or paid_cents >= 0),
  currency text not null default 'AED',
  note text,
  created_at timestamptz not null default now(),
  -- A pass with no holder at all cannot be checked in against anyone.
  constraint gym_passes_holder_present
    check (holder_id is not null or nullif(btrim(holder_name), '') is not null),
  -- The database refuses to let a pass be spent past its own limit; the app
  -- checks too, but the app is not the last line.
  constraint gym_passes_not_overspent check (uses_spent <= uses_total)
);
create index if not exists idx_gym_passes_tenant on gym_passes(tenant_id, issued_on desc);
create index if not exists idx_gym_passes_holder on gym_passes(holder_id) where holder_id is not null;

-- ── each redemption, kept rather than just decremented ──────────────────────
-- A counter tells you a pass was used; a row tells you when, by whom, and
-- against which class. Only the second can be disputed and resolved.
create table if not exists gym_pass_redemptions (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  pass_id uuid not null references gym_passes(id) on delete cascade,
  class_id uuid references gym_classes(id) on delete set null,
  redeemed_at timestamptz not null default now(),
  -- The staff member who took it, not the person using it.
  redeemed_by uuid references profiles(id) on delete set null
);
create index if not exists idx_gym_pass_redemptions_pass on gym_pass_redemptions(pass_id, redeemed_at desc);
create index if not exists idx_gym_pass_redemptions_tenant on gym_pass_redemptions(tenant_id, redeemed_at desc);

-- ── keep the counter and the rows honest ────────────────────────────────────
-- uses_spent is a cache of count(redemptions). Letting the app maintain both
-- independently guarantees they drift, so the trigger owns it.
create or replace function gym_passes_sync_uses() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  update gym_passes p
     set uses_spent = (select count(*) from gym_pass_redemptions r where r.pass_id = p.id)
   where p.id = coalesce(new.pass_id, old.pass_id);
  return coalesce(new, old);
end $$;

drop trigger if exists trg_gym_pass_redemptions_sync on gym_pass_redemptions;
create trigger trg_gym_pass_redemptions_sync
  after insert or delete on gym_pass_redemptions
  for each row execute function gym_passes_sync_uses();

-- A redemption inherits the pass's tenant, so the desk never has to supply it
-- and can never supply the wrong one.
create or replace function gym_pass_redemptions_fill_tenant() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.tenant_id is null then
    select p.tenant_id into new.tenant_id from gym_passes p where p.id = new.pass_id;
  end if;
  return new;
end $$;

drop trigger if exists trg_gym_pass_redemptions_tenant on gym_pass_redemptions;
create trigger trg_gym_pass_redemptions_tenant
  before insert on gym_pass_redemptions
  for each row execute function gym_pass_redemptions_fill_tenant();

-- ── row-level security ──────────────────────────────────────────────────────
-- The helpers are SECURITY DEFINER, so a policy calling them does not re-enter
-- the table it is protecting — the recursion that once made `profiles`
-- unreadable for everyone (see 28-fix-profiles-recursion.sql).
alter table gym_pass_types       enable row level security;
alter table gym_passes           enable row level security;
alter table gym_pass_redemptions enable row level security;

drop policy if exists gym_pass_types_owner on gym_pass_types;
create policy gym_pass_types_owner on gym_pass_types
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

drop policy if exists gym_passes_owner on gym_passes;
create policy gym_passes_owner on gym_passes
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

drop policy if exists gym_pass_redemptions_owner on gym_pass_redemptions;
create policy gym_pass_redemptions_owner on gym_pass_redemptions
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

-- What is on sale at the desk is not private, and the booking screens need it.
drop policy if exists gym_pass_types_tenant_r on gym_pass_types;
create policy gym_pass_types_tenant_r on gym_pass_types
  for select using (tenant_id = my_tenant() and active);

-- A holder reads their own passes and nobody else's. Note this is scoped to
-- holder_id, so a desk-written walk-in (holder_name only) is visible to the
-- gym alone — there is no account for it to leak to.
drop policy if exists gym_passes_own_r on gym_passes;
create policy gym_passes_own_r on gym_passes
  for select using (holder_id = (select auth.uid()));

drop policy if exists gym_pass_redemptions_own_r on gym_pass_redemptions;
create policy gym_pass_redemptions_own_r on gym_pass_redemptions
  for select using (
    exists (select 1 from gym_passes p
             where p.id = gym_pass_redemptions.pass_id
               and p.holder_id = (select auth.uid()))
  );

-- Staff need to take a pass at the desk without being an owner. A trainer in
-- the gym may record a redemption, but may not issue or price a pass.
drop policy if exists gym_pass_redemptions_staff_w on gym_pass_redemptions;
create policy gym_pass_redemptions_staff_w on gym_pass_redemptions
  for insert with check (tenant_id = my_tenant() and my_role() in ('trainer','owner'));

drop policy if exists gym_passes_staff_r on gym_passes;
create policy gym_passes_staff_r on gym_passes
  for select using (tenant_id = my_tenant() and my_role() in ('trainer','owner'));

-- ▶ door-log.sql

-- ── The door log ────────────────────────────────────────────────────────────
--
-- Phase 1. Attendance is currently only counted where a class was booked and
-- ticked off. Every member who walks in, trains on the floor and leaves is
-- invisible — which in most gyms is the majority of visits.
--
-- That under-count matters beyond the headline: retention is inferred from
-- attendance pattern breaks, so a member who switched from classes to the
-- floor currently looks like a member who stopped coming.
--
-- Additive only. Nothing here alters an existing table.

create table if not exists gym_visits (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  -- Null for an anonymous head-count: a turnstile that counts bodies without
  -- identifying them still tells the gym about capacity, even though it says
  -- nothing about retention.
  member_id uuid references profiles(id) on delete set null,
  -- Set when the visit was paid for with a drop-in or guest pass, so the two
  -- records reconcile instead of double counting the same person.
  pass_id uuid references gym_passes(id) on delete set null,
  -- Set when the visit was attendance at a booked class, so class attendance
  -- and floor attendance can be told apart in the same table.
  class_id uuid references gym_classes(id) on delete set null,
  entered_at timestamptz not null default now(),
  -- Null means either still inside or nobody recorded an exit. The two are
  -- indistinguishable here on purpose — see gymVisits.averageDwellMinutes,
  -- which refuses to average over visits with no exit rather than guessing.
  exited_at timestamptz,
  source text not null default 'desk'
    check (source in ('desk','qr','door','app','manual')),
  note text,
  created_at timestamptz not null default now(),
  -- A visit cannot end before it began. Clock skew on a door terminal is real,
  -- and a negative dwell time poisons every average built on it.
  constraint gym_visits_exit_after_entry
    check (exited_at is null or exited_at >= entered_at)
);

create index if not exists idx_gym_visits_tenant on gym_visits(tenant_id, entered_at desc);
create index if not exists idx_gym_visits_member on gym_visits(member_id, entered_at desc)
  where member_id is not null;
create index if not exists idx_gym_visits_open on gym_visits(tenant_id)
  where exited_at is null;

-- A visit paid for by a pass inherits that pass's tenant, so a terminal never
-- has to supply it and can never supply the wrong one.
create or replace function gym_visits_fill_tenant() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.tenant_id is null and new.pass_id is not null then
    select p.tenant_id into new.tenant_id from gym_passes p where p.id = new.pass_id;
  end if;
  if new.tenant_id is null and new.class_id is not null then
    select c.tenant_id into new.tenant_id from gym_classes c where c.id = new.class_id;
  end if;
  return new;
end $$;

drop trigger if exists trg_gym_visits_tenant on gym_visits;
create trigger trg_gym_visits_tenant
  before insert on gym_visits
  for each row execute function gym_visits_fill_tenant();

-- ── row-level security ──────────────────────────────────────────────────────
-- The helpers are SECURITY DEFINER, so a policy calling them does not re-enter
-- the table it is protecting — the recursion that once made `profiles`
-- unreadable for everyone (see 28-fix-profiles-recursion.sql).
alter table gym_visits enable row level security;

drop policy if exists gym_visits_owner on gym_visits;
create policy gym_visits_owner on gym_visits
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

-- Staff work the door; they may record visits without being an owner.
drop policy if exists gym_visits_staff_rw on gym_visits;
create policy gym_visits_staff_rw on gym_visits
  for select using (tenant_id = my_tenant() and my_role() in ('trainer','owner'));

drop policy if exists gym_visits_staff_w on gym_visits;
create policy gym_visits_staff_w on gym_visits
  for insert with check (tenant_id = my_tenant() and my_role() in ('trainer','owner'));

drop policy if exists gym_visits_staff_u on gym_visits;
create policy gym_visits_staff_u on gym_visits
  for update using (tenant_id = my_tenant() and my_role() in ('trainer','owner'))
  with check (tenant_id = my_tenant() and my_role() in ('trainer','owner'));

-- A member sees their own visit history and nobody else's. This is deliberately
-- readable to them: "when did I actually come in" is their record too, and it
-- is the evidence behind any retention conversation the gym starts.
drop policy if exists gym_visits_own_r on gym_visits;
create policy gym_visits_own_r on gym_visits
  for select using (member_id = (select auth.uid()));

-- ▶ session-outcomes.sql

-- ── What actually happened in a PT session ──────────────────────────────────
--
-- Phase 1. Two problems with `sessions`, both of which reach the owner's
-- payroll figure.
--
-- 1. It has no tenant. A gym cannot see the one-to-one sessions its own
--    trainers deliver on its floor — the same class of gap that made
--    `gym_classes` readable across gyms (see 30-classes-tenant-scope.sql),
--    except here the data is missing rather than over-shared.
--
-- 2. `status` describes the slot, not the outcome: available, booked, blocked.
--    There is nowhere to record that a booked session was actually delivered.
--    So "delivered" has been inferred as "was booked and the clock has since
--    passed" — which counts no-shows, un-cancelled slots and sessions the
--    trainer never turned up to. That inference feeds payroll, so a gym pays
--    for sessions that did not happen.
--
-- Additive only. `status` keeps its meaning; the new `outcome` column carries
-- the delivery result and is null until somebody records one. Null is the
-- honest state: not delivered, not cancelled — not yet known.

alter table public.sessions add column if not exists tenant_id uuid references public.tenants(id) on delete cascade;

alter table public.sessions add column if not exists outcome text
  check (outcome is null or outcome in ('completed','no_show','cancelled','late_cancelled'));

alter table public.sessions add column if not exists outcome_at timestamptz;
alter table public.sessions add column if not exists outcome_by uuid references auth.users(id) on delete set null;

-- The rate at the moment of delivery. Snapshotted so that changing a trainer's
-- fee next month does not silently rewrite what last month cost.
alter table public.sessions add column if not exists rate_cents integer
  check (rate_cents is null or rate_cents >= 0);

create index if not exists idx_sessions_tenant on public.sessions(tenant_id, starts_at desc);
create index if not exists idx_sessions_unmarked on public.sessions(tenant_id, starts_at)
  where outcome is null;

-- ── backfill the tenant from the trainer who owns the slot ──────────────────
update public.sessions s
   set tenant_id = t.tenant_id
  from public.trainers t
 where t.id = s.trainer_id
   and s.tenant_id is null;

-- New rows inherit it, so no caller has to supply it and none can supply the
-- wrong one.
create or replace function public.sessions_fill_tenant() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.tenant_id is null then
    select t.tenant_id into new.tenant_id from public.trainers t where t.id = new.trainer_id;
  end if;
  return new;
end $$;

drop trigger if exists trg_sessions_fill_tenant on public.sessions;
create trigger trg_sessions_fill_tenant
  before insert on public.sessions
  for each row execute function public.sessions_fill_tenant();

-- Stamp who recorded the outcome and when, so a disputed payroll line has an
-- author. Only on transition into an outcome, so an edit does not lose the
-- original time.
create or replace function public.sessions_stamp_outcome() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.outcome is distinct from old.outcome and new.outcome is not null then
    new.outcome_at := coalesce(new.outcome_at, now());
    new.outcome_by := coalesce(new.outcome_by, (select auth.uid()));
  end if;
  if new.outcome is null then
    new.outcome_at := null;
    new.outcome_by := null;
  end if;
  return new;
end $$;

drop trigger if exists trg_sessions_stamp_outcome on public.sessions;
create trigger trg_sessions_stamp_outcome
  before update on public.sessions
  for each row execute function public.sessions_stamp_outcome();

-- ── row-level security ──────────────────────────────────────────────────────
-- Existing policies (09-sessions-access.sql) already cover the trainer who owns
-- the slot and the client who booked it. This adds the gym: an owner may read
-- the sessions delivered on their floor, because that is what they are paying
-- for, and may correct an outcome.
--
-- The helpers are SECURITY DEFINER, so a policy calling them does not re-enter
-- the table it is protecting — the recursion that once made `profiles`
-- unreadable for everyone (see 28-fix-profiles-recursion.sql).

drop policy if exists sessions_gym_owner_r on public.sessions;
create policy sessions_gym_owner_r on public.sessions
  for select using (tenant_id is not null and is_owner_of(tenant_id));

drop policy if exists sessions_gym_owner_u on public.sessions;
create policy sessions_gym_owner_u on public.sessions
  for update using (tenant_id is not null and is_owner_of(tenant_id))
  with check (tenant_id is not null and is_owner_of(tenant_id));

-- ▶ equipment-register.sql

-- ── The equipment register ──────────────────────────────────────────────────
--
-- Phase 1. What the gym owns, what is out of action, and what is due a service.
--
-- The reason this is not just an inventory list: capacity. A class capacity of
-- 14 is a claim about the room, and it stops being true the moment six of the
-- rowers are broken. Studio already reports fill rate against stated capacity,
-- so without this the gym is measuring itself against a number that quietly
-- became fiction.
--
-- Additive only. Nothing here alters an existing table.

create table if not exists gym_equipment (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  name text not null,
  -- Loose on purpose. A gym's own words for its kit beat a taxonomy we impose,
  -- and the capacity check matches on this string.
  category text,
  -- Asset tag, serial, or whatever is written on the sticker.
  identifier text,
  quantity integer not null default 1 check (quantity >= 0),
  status text not null default 'in_service'
    check (status in ('in_service', 'out_of_service', 'retired')),
  purchased_on date,
  -- Null means no service schedule — a decision the gym made, not a gap.
  service_interval_days integer check (service_interval_days is null or service_interval_days > 0),
  -- Null with an interval set means the schedule exists but nobody has recorded
  -- a service. That is NOT the same as "serviced today", and
  -- gymEquipment.serviceState reports it as its own state rather than
  -- computing a due date from a date it does not have.
  last_serviced_on date,
  note text,
  created_at timestamptz not null default now()
);

create index if not exists idx_gym_equipment_tenant on gym_equipment(tenant_id, status);
create index if not exists idx_gym_equipment_category on gym_equipment(tenant_id, category)
  where status = 'in_service';
create index if not exists idx_gym_equipment_service on gym_equipment(tenant_id, last_serviced_on)
  where service_interval_days is not null;

-- ── row-level security ──────────────────────────────────────────────────────
-- The helpers are SECURITY DEFINER, so a policy calling them does not re-enter
-- the table it is protecting — the recursion that once made `profiles`
-- unreadable for everyone (see 28-fix-profiles-recursion.sql).
alter table gym_equipment enable row level security;

drop policy if exists gym_equipment_owner on gym_equipment;
create policy gym_equipment_owner on gym_equipment
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

-- Trainers read the register and may take a machine out of action — they are
-- the ones standing next to it when it breaks. They cannot add, price or
-- retire kit, which is the owner's call.
drop policy if exists gym_equipment_staff_r on gym_equipment;
create policy gym_equipment_staff_r on gym_equipment
  for select using (tenant_id = my_tenant() and my_role() in ('trainer', 'owner'));

drop policy if exists gym_equipment_staff_u on gym_equipment;
create policy gym_equipment_staff_u on gym_equipment
  for update using (tenant_id = my_tenant() and my_role() in ('trainer', 'owner'))
  with check (tenant_id = my_tenant() and my_role() in ('trainer', 'owner'));

-- ▶ class-capacity-and-scope.sql

-- ─────────────────────────────────────────────────────────────────────────
-- class_attendance_summary: add capacity, and scope it to the caller's gym.
--
-- TWO changes, one function.
--
-- 1. CAPACITY. The summary returned booked and attended but not capacity, so
--    the owner's class screen could only ever compute attended/booked. It
--    printed that under the label "fill", while gymSchedule.ts reserves fill
--    for booked/capacity — the same class read 71% on the timetable and 80%
--    on the analytics screen. gym_classes.capacity has been there all along;
--    the summary simply never selected it. With it present the screen can
--    show both rates and mean each honestly.
--
-- 2. TENANT SCOPE — a cross-tenant read. The function is SECURITY DEFINER, so
--    it runs as its owner and RLS on gym_classes does not apply to it. Its own
--    guard was:
--
--      gc.trainer_id = auth.uid()
--      or exists (select 1 from profiles o
--                  where o.id = auth.uid() and o.role = 'owner')
--
--    The second arm asks "is this caller AN owner", never "is this caller the
--    owner of THIS gym". Any owner of any tenant could therefore read every
--    other gym's class titles, trainer names, booking and attendance counts.
--    Every RLS policy added in 30-classes-tenant-scope.sql already uses
--    is_owner_of(tenant_id); this brings the function into line with them.
--
-- The return type changes, so the function has to be dropped rather than
-- replaced. Both signatures are dropped because an older build may have left
-- either behind.
-- ─────────────────────────────────────────────────────────────────────────

drop function if exists public.class_attendance_summary(timestamptz, timestamptz);

create function public.class_attendance_summary(p_from timestamptz, p_to timestamptz)
returns table(class_id uuid, title text, kind text, branch text, trainer_id uuid,
              trainer_name text, starts_at timestamptz,
              capacity integer, booked integer, attended integer)
language sql
security definer
set search_path to 'public'
as $function$
  select gc.id, gc.title, gc.kind, gc.branch, gc.trainer_id,
         coalesce(tp.full_name, 'Trainer') as trainer_name, gc.starts_at,
         coalesce(gc.capacity, 0)::int as capacity,
         count(cb.id) filter (where cb.status = 'booked')::int as booked,
         count(cb.attended_at)::int as attended
  from gym_classes gc
  left join class_bookings cb on cb.class_id = gc.id
  left join profiles tp on tp.id = gc.trainer_id
  where gc.starts_at >= p_from and gc.starts_at < p_to
    and ( gc.trainer_id = auth.uid()
          -- the caller must own THIS class's gym, not merely be an owner
          or is_owner_of(gc.tenant_id) )
  group by gc.id, tp.full_name
  order by gc.starts_at desc;
$function$;

grant execute on function public.class_attendance_summary(timestamptz, timestamptz) to authenticated;

-- ▶ payroll-settlements.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Recording that payroll was actually paid.
--
-- gymSessions.ts already computes what a gym owes and refuses to answer while
-- any session is unmarked. What nothing recorded was that the money went out.
-- Without it a gym can only ask "what do we owe for this period", never "have
-- we paid it" — and the second question is the one that gets asked twice on a
-- Friday afternoon by two different people.
--
-- THE DESIGN PROBLEM this solves is double payment.
--
-- A settlement cannot simply store a date range and an amount, because a
-- session can be marked AFTER its period is settled — a trainer catching up on
-- last week's outcomes. If settlement were range-based, that late session would
-- either be silently unpaid forever (it falls inside a settled range) or paid
-- twice (the range is settled again). Both are real money going wrong quietly.
--
-- So settlement is per SESSION, not per period. Each settled session carries
-- the id of the run that paid it:
--
--   · a session with settlement_id has been paid, and is excluded from what is
--     owed, permanently
--   · a session marked late has no settlement_id, so it simply appears in the
--     next run — late, but paid exactly once
--
-- The amount is snapshotted on the settlement row as well, so a later change to
-- the gym's session fee cannot rewrite what was actually handed over. That is
-- the same reasoning as rate_cents on the session itself: history is what
-- happened, not what today's prices imply.
-- ─────────────────────────────────────────────────────────────────────────

create table if not exists public.payroll_settlements (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  trainer_id uuid not null references public.profiles(id) on delete cascade,

  -- The window the run covered, for reporting. NOT the definition of what was
  -- paid — that is the set of sessions pointing at this row.
  period_from date not null,
  period_to date not null,

  -- What was handed over, snapshotted. Never recomputed.
  amount_cents integer not null check (amount_cents >= 0),
  currency text not null default 'AED',
  sessions_count integer not null check (sessions_count >= 0),

  method text not null default 'transfer'
    check (method in ('transfer', 'cash', 'payroll', 'other')),
  note text,

  settled_at timestamptz not null default now(),
  settled_by uuid references auth.users(id) on delete set null,

  created_at timestamptz not null default now()
);

create index if not exists idx_settlements_tenant
  on public.payroll_settlements(tenant_id, settled_at desc);
create index if not exists idx_settlements_trainer
  on public.payroll_settlements(trainer_id, settled_at desc);

-- The link that makes double payment impossible.
alter table public.sessions
  add column if not exists settlement_id uuid
  references public.payroll_settlements(id) on delete set null;

-- Partial index: the query that matters is "what is still unpaid", and the
-- settled rows grow without bound while the unsettled set stays small.
create index if not exists idx_sessions_unsettled
  on public.sessions(tenant_id, trainer_id)
  where settlement_id is null;

-- ── access ─────────────────────────────────────────────────────────────────
alter table public.payroll_settlements enable row level security;

-- The owner of the gym runs payroll and sees all of it.
drop policy if exists settlements_owner on public.payroll_settlements;
create policy settlements_owner on public.payroll_settlements for all
  using (is_owner_of(tenant_id))
  with check (is_owner_of(tenant_id));

-- A trainer may read their own settlements — what they were paid, and when.
-- Read only: being paid is not something you record about yourself.
drop policy if exists settlements_trainer_read on public.payroll_settlements;
create policy settlements_trainer_read on public.payroll_settlements for select
  using (trainer_id = auth.uid());

-- ▶ member-invites.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Gym → member invites. The hole this fills is a hard one:
--
--   memberships.member_id is `uuid not null references profiles(id)`
--
-- so a membership cannot exist before the person does. A gym owner opening the
-- Studio member screen — or feeding last year's spreadsheet through the CSV
-- importer — hits that wall on the very first row, because their members have
-- names and email addresses, not Repple accounts. There has been no path from
-- "person the gym knows about" to "profiles row". This is that path.
--
-- The shape is deliberately the same as 11-coach-invites.sql and
-- 12-trainer-invites.sql: a pending row addressed to an email, readable by the
-- person it names, redeemed by a security-definer function that does the
-- cross-account writes RLS would otherwise forbid. A gym that has already
-- learned one invite flow should not have to learn a second.
--
-- WHY AN INVITE ROW AND NOT A PLACEHOLDER PROFILE. The tempting shortcut is to
-- relax the foreign key and insert a stub profile per member. That trades one
-- missing feature for a permanent data-quality problem: stub rows that never
-- get claimed are indistinguishable from real accounts, they accumulate, and
-- every count of "members" in the product silently starts including ghosts. An
-- invite is honestly a different kind of thing from a membership, and it is
-- modelled as one.
--
-- Depends on 01-schema.sql (tenants/profiles/clients), 02-domain-schema.sql
-- (is_owner_of) and 29-gym-operating-record.sql (membership_plans/memberships).
-- Idempotent; safe to re-run.
-- ─────────────────────────────────────────────────────────────────────────

create table if not exists public.member_invites (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,

  -- Stored as typed, matched case-insensitively everywhere. Keeping the
  -- original casing means the gym's own record of the address is intact if
  -- they have to read it back to someone over the phone.
  email text not null,

  -- What the gym calls them. Nullable because a gym importing a mailing list
  -- may genuinely only have the address, and a blank name is not a reason to
  -- refuse the import — it is a reason to show the address in the UI.
  full_name text,

  -- The plan the membership opens on. Nullable on purpose: "join the gym, we
  -- will sort the package out at the desk" is a real thing gyms do, and a
  -- forced plan choice would push owners into inventing one.
  plan_id uuid references public.membership_plans(id) on delete set null,

  invited_by uuid references public.profiles(id) on delete set null,

  -- The share link's secret. A uuid rather than encode(gen_random_bytes(...)):
  -- gen_random_bytes needs pgcrypto, which nothing else in this schema assumes
  -- is installed, and 122 random bits is already far beyond guessable for a
  -- value that also has to survive an email-address check to be worth anything.
  token uuid not null unique default gen_random_uuid(),

  -- Only ever the three states somebody DECIDED. 'expired' is deliberately not
  -- in this list — see the note on expires_at below.
  status text not null default 'pending'
    check (status in ('pending', 'accepted', 'revoked')),

  created_at timestamptz not null default now(),

  -- An invite that stays open forever is a permanent unauthenticated way into
  -- a gym's tenant, so every invite carries an expiry. It is a stored column
  -- rather than a derived one so the owner can extend a specific invite for
  -- somebody who was on holiday, without loosening the rule for everyone.
  --
  -- NOTE what does NOT happen here: nothing flips status to 'expired' when the
  -- clock passes. That would need a cron job, and until it ran the row would
  -- lie. Instead expiry is derived at read time — in SQL by accept_member_
  -- invite below, and in TypeScript by inviteState() in src/lib/memberInvites.ts
  -- — so the two never disagree and the table only ever stores facts.
  expires_at timestamptz not null default now() + interval '30 days',

  accepted_at timestamptz,
  accepted_by uuid references public.profiles(id) on delete set null
);

-- One open invite per address per gym. Partial, and only over the pending ones,
-- because a member who joined, left and is being invited back a year later must
-- not be blocked by their own accepted invite from last time. coach_invites
-- uses a plain unique (coach_id, email) and has exactly that problem.
create unique index if not exists uq_member_invites_open
  on public.member_invites (tenant_id, lower(email))
  where status = 'pending';

-- The owner's list view: their gym's invites, newest first.
create index if not exists idx_member_invites_tenant
  on public.member_invites (tenant_id, status, created_at desc);

-- The invitee's lookup, which comes in by address and has no tenant to narrow
-- it. Must be on lower(email) to match the RLS policy, or the policy scans.
create index if not exists idx_member_invites_email
  on public.member_invites (lower(email));

-- ── access ─────────────────────────────────────────────────────────────────
-- A blank email would match an anon caller's empty claim, so it must not
-- be storable. Belt and braces with the nullif in mi_invitee_read below.
alter table public.member_invites
  add constraint member_invites_email_not_blank check (btrim(email) <> '');

alter table public.member_invites enable row level security;

-- The owner of THIS gym manages its invites: create, list, extend, revoke.
-- is_owner_of(tenant_id) asks whether the caller owns this particular tenant,
-- not merely whether they own something.
drop policy if exists mi_owner on public.member_invites;
create policy mi_owner on public.member_invites for all
  using (is_owner_of(tenant_id))
  with check (is_owner_of(tenant_id));

-- The invited person, matched on the email they signed in with, can read the
-- invite addressed to them — that read is what lets the app show "Fit Republic
-- has invited you to join" the first time they open it.
--
-- SELECT only. Accepting is not an UPDATE they are allowed to make; it goes
-- through accept_member_invite, which validates before it writes.
drop policy if exists mi_invitee_read on public.member_invites;
create policy mi_invitee_read on public.member_invites for select
  -- nullif, NOT coalesce(..., ''): an unauthenticated caller has no email
  -- claim, so coalescing to '' would make an invite stored with a blank email
  -- readable by anon. nullif makes that comparison null, which matches nothing.
  using (lower(email) = lower(nullif(auth.jwt() ->> 'email', '')));

-- ── redeeming ──────────────────────────────────────────────────────────────
-- Accept the invite addressed to me: attach my profile to the gym's tenant and
-- open the membership. SECURITY DEFINER because the writes span rows the
-- invitee has no rights over — memberships belongs to the owner under RLS.
--
-- TENANT SCOPING, which is the whole risk in a definer function. Every write
-- below targets inv.tenant_id — the tenant on the invite row the caller proved
-- they are addressed by — and never the caller's current tenant, never "a"
-- tenant, never a tenant read from an argument. The bug this is written
-- against is the one fixed in 35-class-capacity-and-scope.sql, where a definer
-- function guarded on "is this caller AN owner" instead of "does this caller
-- own THIS gym" and leaked every tenant's data to every other tenant's owner.
-- The equivalent mistake here would be trusting a tenant id passed in as a
-- parameter: anyone could then post themselves into any gym. The function
-- therefore takes only the invite id, and derives everything else from the row.
create or replace function public.accept_member_invite(p_invite uuid)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  inv public.member_invites;
  my_email text;
  -- Named caller_* deliberately. my_role() and my_tenant() are existing SQL
  -- helpers in this schema (28-fix-profiles-recursion.sql), and a plpgsql
  -- variable sharing their name is a shadowing accident waiting to happen.
  caller_role text;
  caller_tenant uuid;
  mem uuid;
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;

  select email into my_email from auth.users where id = auth.uid();
  select role, tenant_id into caller_role, caller_tenant from profiles where id = auth.uid();

  select * into inv from member_invites where id = p_invite;
  if inv.id is null then
    raise exception 'invite not found';
  end if;

  -- Identity, first and hardest. The invite id alone proves nothing.
  if lower(inv.email) <> lower(coalesce(my_email, '')) then
    raise exception 'invite not addressed to you';
  end if;

  -- Already settled one way or the other. Distinguished from expiry so the app
  -- can say something true: "you have already joined" is not "this has lapsed".
  if inv.status = 'accepted' then
    raise exception 'invite already accepted';
  elsif inv.status = 'revoked' then
    raise exception 'invite was withdrawn';
  end if;

  if inv.expires_at <= now() then
    raise exception 'invite has expired';
  end if;

  -- WHO MAY BE MOVED. Accepting rewrites profiles.tenant_id, which is the spine
  -- of every RLS policy in the schema, so it must not be able to strip somebody
  -- of a role they hold elsewhere.
  --
  --  · an owner would be moved out of the gym they own, taking is_owner_of with
  --    them and locking them out of their own business
  --  · a trainer would be detached from the roster they coach
  --
  -- Both refuse rather than half-succeed. A trainer holding a membership where
  -- they work is legitimate and is allowed — they are already in that tenant,
  -- so nothing moves and only the membership opens.
  if caller_role = 'owner' then
    raise exception 'an owner cannot join a gym as a member from this account';
  elsif caller_role = 'trainer' and caller_tenant is distinct from inv.tenant_id then
    raise exception 'a trainer cannot be moved to another gym by a member invite';
  end if;

  if caller_role = 'client' then
    update profiles
       set tenant_id = inv.tenant_id,
           -- Only fills a gap. The name the member typed about themselves beats
           -- the one the gym typed about them.
           full_name  = coalesce(nullif(trim(full_name), ''), nullif(trim(inv.full_name), ''))
     where id = auth.uid();

    -- provision_profile() gave them a clients row against their personal tenant
    -- at signup. Left behind it would point at the wrong gym, and the roster
    -- policies read clients.tenant_id — so it moves with the profile. Same
    -- upsert shape as accept_trainer_invite uses for trainers.
    insert into clients (id, tenant_id) values (auth.uid(), inv.tenant_id)
      on conflict (id) do update set tenant_id = excluded.tenant_id;
  end if;

  -- Open the membership — unless one is already running. There is no unique
  -- constraint on (tenant_id, member_id) and there should not be: a member who
  -- cancelled and rejoined has two real, separate membership rows and the gym's
  -- history depends on both surviving. So the guard is on live memberships
  -- only, and it is here rather than in an index.
  select id into mem
    from memberships
   where tenant_id = inv.tenant_id
     and member_id = auth.uid()
     and status in ('active', 'frozen')
   order by started_on desc
   limit 1;

  if mem is null then
    insert into memberships (tenant_id, member_id, plan_id, started_on, status)
    values (inv.tenant_id, auth.uid(), inv.plan_id, current_date, 'active')
    returning id into mem;
  end if;

  update member_invites
     set status = 'accepted', accepted_at = now(), accepted_by = auth.uid()
   where id = p_invite;

  -- The membership, so the app can go straight to it instead of refetching and
  -- guessing which row it just caused.
  return mem;
end $$;

-- The grant to authenticated is not enough on its own. Postgres grants EXECUTE
-- to PUBLIC on every newly created function, and Supabase's default privileges
-- on the public schema add an explicit `anon` grant on top of that — so a bare
-- `grant ... to authenticated` leaves the function callable by a signed-out
-- caller. Verified on the live database: immediately after this file first
-- applied, has_function_privilege('anon', ..., 'EXECUTE') was TRUE and the acl
-- read {=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/...}.
-- Both grants have to come off before the grant back means anything. This is
-- the same convention as 22-session-approvals.sql, 38-tenant-isolation.sql and
-- the sweep in 40-function-grants.sql; its absence here was an omission.
--
-- accept_member_invite raises 'not signed in' when auth.uid() is null, so an
-- anon caller could not have completed a redemption — but it would still have
-- reached the body and the auth.users/profiles reads inside a SECURITY DEFINER
-- context, which is not a surface to leave open.
revoke execute on function public.accept_member_invite(uuid) from public, anon;
grant  execute on function public.accept_member_invite(uuid) to authenticated;


-- ─────────────────────────────────────────────────────────────────────────

-- ▶ tenant-isolation.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Tenant isolation: the three holes that made every other policy decorative.
--
-- A security review of all 37 parts found eleven cross-tenant problems. Eight
-- are the "is this caller AN owner rather than THIS gym's owner" mistake, and
-- they are fixed in 39-owner-policy-scope.sql. The three here are different in
-- kind: while any of them stands, fixing the other eight changes nothing,
-- because an attacker does not need to defeat a policy — they can simply
-- become someone the policy already trusts.
-- ─────────────────────────────────────────────────────────────────────────


-- ── 1 · Anyone could make themselves the owner of any gym ──────────────────
--
-- profiles_self is:
--
--   create policy profiles_self on profiles
--     for all using (id = auth.uid()) with check (id = auth.uid());
--
-- FOR ALL includes UPDATE, and RLS cannot restrict which COLUMNS an update
-- touches. So any signed-in user could run
--
--   update profiles set role = 'owner', tenant_id = '<any gym>' where id = auth.uid();
--
-- and is_owner_of(t) — which is exactly `role = 'owner' and tenant_id = t` —
-- would then return true for a gym they have nothing to do with. Every
-- correctly written policy in parts 29 to 37 was reachable this way.
--
-- RLS is the wrong tool for a column-level rule, so this is a trigger.
--
-- WHY THE current_user TEST: a SECURITY DEFINER function runs as its owner
-- (postgres), while an ordinary request from the app runs as `authenticated`
-- or `anon`. The legitimate ways a person changes tenant — accepting a trainer
-- or member invite — all go through definer functions, so they pass. A direct
-- UPDATE from a client does not. This keeps the invite flows working without
-- needing a flag that a caller could learn to set.
--
-- Note what is NOT blocked: signing up as an owner. That is harmless, because
-- provision_profile() gives every new profile its own fresh tenant — you become
-- the owner of your own empty gym, which is the intended way to start. The
-- danger was never the role; it was moving an existing profile into somebody
-- else's tenant.

create or replace function public.guard_profile_identity()
returns trigger language plpgsql as $$
begin
  if current_user in ('authenticated', 'anon') then
    if new.role is distinct from old.role then
      raise exception 'A profile cannot change its own role. Ask the gym owner to change it for you.'
        using errcode = '42501';
    end if;
    if new.tenant_id is distinct from old.tenant_id then
      raise exception 'A profile cannot move itself between gyms. Joining a gym happens by invitation.'
        using errcode = '42501';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists guard_profile_identity_t on public.profiles;
create trigger guard_profile_identity_t
  before update on public.profiles
  for each row execute function public.guard_profile_identity();


-- NOTE ON REVOKE, learned the hard way against the live database: `revoke
-- execute ... from anon` accomplishes nothing on its own. Postgres grants
-- EXECUTE to PUBLIC on every new function, and that is the grant anon actually
-- resolves through — has_function_privilege('anon', ...) stayed true after
-- revoking from anon alone. Every revoke here therefore names PUBLIC, and the
-- roles that should still call the function are granted back explicitly.


-- ── 2 · link_coaching() had no authorization at all ────────────────────────
--
-- It is SECURITY DEFINER, never references auth.uid(), and nothing revoked it
-- from PUBLIC — so it was callable as an RPC by anyone holding the anon key,
-- which ships inside the mobile bundle. It re-points any client at any trainer:
--
--   update clients set trainer_id = p_coach where id = p_client;
--
-- and is_my_client() then opens that member's workouts, measurements, check-ins,
-- habit logs, scans, food logs and their private coach conversation. Pointing a
-- stranger's client record at yourself was a complete read of their health
-- history.
--
-- Other definer functions in this schema (all_member_ids, approve_session) do
-- revoke from anon, so this was an omission rather than a convention.
--
-- The rule: you may create a coaching link only if you are one of the two
-- people in it, or you own the gym they belong to. Anything else raises.

create or replace function public.link_coaching(
  p_coach uuid, p_client uuid, p_mode text default 'online'
) returns void
language plpgsql
security definer
set search_path = public
as $$
declare client_tenant uuid;
begin
  select tenant_id into client_tenant from profiles where id = p_client;

  if not (
    auth.uid() = p_coach
    or auth.uid() = p_client
    or (client_tenant is not null and is_owner_of(client_tenant))
  ) then
    raise exception 'You can only link a coach and a client you are part of.'
      using errcode = '42501';
  end if;

  insert into coaching_relationships (coach_id, client_id, mode, status)
  values (p_coach, p_client, coalesce(p_mode, 'online'), 'active')
  on conflict (coach_id, client_id) do update set mode = excluded.mode, status = 'active';

  update clients set trainer_id = p_coach where id = p_client;
end $$;

revoke execute on function public.link_coaching(uuid, uuid, text) from public, anon;
grant execute on function public.link_coaching(uuid, uuid, text) to authenticated;


-- ── 3 · Four tables never had row-level security switched on ───────────────
--
-- tenants, exercise_videos, availability_templates and session_waitlist all
-- hold tenant data and none of them had `enable row level security`.
--
-- The trap is that 28-fix-profiles-recursion.sql creates policies for tenants
-- and exercise_videos, so reading the migrations they look protected. A policy
-- on a table without RLS enabled is inert: Postgres never consults it, and
-- Supabase's default grants to anon and authenticated apply in full. The anon
-- key is compiled into the shipped app, so every gym's name, brand colour, plan
-- and session_fee was world-readable AND world-writable — including the
-- tenants.id values needed to exploit the profiles hole above.

alter table public.tenants enable row level security;
alter table public.exercise_videos enable row level security;
alter table public.availability_templates enable row level security;
alter table public.session_waitlist enable row level security;

-- Your own gym: everybody inside it can read it (the app shows its name and
-- brand everywhere); only its owner can change it.
drop policy if exists tenants_read on public.tenants;
create policy tenants_read on public.tenants for select
  using (id = my_tenant());

drop policy if exists tenants_owner_rw on public.tenants;
create policy tenants_owner_rw on public.tenants for all
  using (is_owner_of(id)) with check (is_owner_of(id));

-- Exercise demos are content, not customer data, and the whole point is that a
-- client can watch one. Readable by any signed-in user; writable only by the
-- owner of the gym that added it.
drop policy if exists exvid_read on public.exercise_videos;
create policy exvid_read on public.exercise_videos for select
  to authenticated using (true);

-- exercise_videos has no tenant_id — it is keyed on trainer_id, and a NULL
-- trainer means a platform-wide "Academy" video belonging to nobody. So the
-- write rule reaches the tenant through the trainer, and platform videos are
-- deliberately not writable by any gym.
drop policy if exists exvid_trainer_rw on public.exercise_videos;
create policy exvid_trainer_rw on public.exercise_videos for all
  using (trainer_id = auth.uid()) with check (trainer_id = auth.uid());

drop policy if exists exvid_owner_rw on public.exercise_videos;
create policy exvid_owner_rw on public.exercise_videos for all
  using (exists (
    select 1 from trainers tr
    where tr.id = exercise_videos.trainer_id and is_owner_of(tr.tenant_id)))
  with check (exists (
    select 1 from trainers tr
    where tr.id = exercise_videos.trainer_id and is_owner_of(tr.tenant_id)));

-- A trainer's working pattern. Theirs to set; their gym's owner may see it.
drop policy if exists avail_self on public.availability_templates;
create policy avail_self on public.availability_templates for all
  using (trainer_id = auth.uid()) with check (trainer_id = auth.uid());

drop policy if exists avail_owner_r on public.availability_templates;
create policy avail_owner_r on public.availability_templates for select
  using (exists (
    select 1 from trainers tr
    where tr.id = availability_templates.trainer_id and is_owner_of(tr.tenant_id)));

-- session_waitlist is (session_id, client_id) against `sessions`, not classes —
-- it is the PT waitlist, not the class one. A queue entry belongs to the client
-- on it; the trainer whose session it is, and that gym's owner, may see it.
drop policy if exists waitlist_self on public.session_waitlist;
create policy waitlist_self on public.session_waitlist for all
  using (client_id = auth.uid()) with check (client_id = auth.uid());

drop policy if exists waitlist_gym_r on public.session_waitlist;
create policy waitlist_gym_r on public.session_waitlist for select
  using (exists (
    select 1 from sessions s
    where s.id = session_waitlist.session_id
      and (s.trainer_id = auth.uid() or is_owner_of(s.tenant_id))));


-- ── 4 · class_roster() — the leak that 35 missed ───────────────────────────
--
-- 35-class-capacity-and-scope.sql fixed class_attendance_summary and left its
-- neighbour in the same file carrying a byte-identical guard. This one is
-- worse: the summary gave counts, this gives member NAMES.

drop function if exists public.class_roster(uuid);

create function public.class_roster(p_class uuid)
returns table(user_id uuid, name text, status text, attended boolean)
language sql
security definer
set search_path to 'public'
as $function$
  select cb.user_id,
         coalesce(p.full_name, 'Member') as name,
         cb.status,
         (cb.attended_at is not null) as attended
  from class_bookings cb
  join gym_classes gc on gc.id = cb.class_id
  left join profiles p on p.id = cb.user_id
  where cb.class_id = p_class
    and ( gc.trainer_id = auth.uid()
          -- the caller must own THIS class's gym, not merely be an owner
          or is_owner_of(gc.tenant_id) );
$function$;

revoke execute on function public.class_roster(uuid) from public, anon;
grant execute on function public.class_roster(uuid) to authenticated;


-- ── 5 · Three more unguarded definer functions ─────────────────────────────

-- all_member_ids() tested only that the caller was AN owner, and its select had
-- no join to the caller's tenant — so it returned every member id on the
-- platform. Ids alone are low value, but they are the join key that made the
-- other leaks usable.
create or replace function public.all_member_ids()
returns setof uuid
language sql
security definer
set search_path = public
as $$
  select c.id from clients c where is_owner_of(c.tenant_id);
$$;

-- class_counts() had no guard whatsoever, so any signed-in user could read
-- booking counts for every class in every gym.
create or replace function public.class_counts()
returns table(class_id uuid, booked bigint)
language sql
security definer
set search_path = public
as $$
  select cb.class_id, count(*)::bigint
  from class_bookings cb
  join gym_classes gc on gc.id = cb.class_id
  where gc.tenant_id = my_tenant()
  group by cb.class_id;
$$;

revoke execute on function public.class_counts() from public, anon;
grant execute on function public.class_counts() to authenticated;


-- ── 6 · announcements were world-readable and anyone could plant one ───────
--
--   create policy ann_read on announcements for select using (true);
--   create policy ann_write on announcements for insert with check (author_id = auth.uid());
--
-- ann_read had no `to authenticated`, so it covered anon — and the anon key is
-- in the app bundle. ann_write constrained only the author, never the
-- tenant_id, so any user could post an announcement into a competitor's gym
-- and have it appear to their members as if the gym had written it.

drop policy if exists ann_read on public.announcements;
create policy ann_read on public.announcements for select
  using (tenant_id = my_tenant());

drop policy if exists ann_write on public.announcements;
create policy ann_write on public.announcements for insert
  with check (author_id = auth.uid() and is_owner_of(tenant_id));

drop policy if exists ann_owner_rw on public.announcements;
create policy ann_owner_rw on public.announcements for all
  using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));


-- ── 7 · book_class() could take a seat in another gym's class ──────────────
--
-- Both functions are SECURITY DEFINER and their only filter is `where id =
-- p_class`, so a member of gym A could book — and hold — seats in gym B's
-- classes. The return value ('booked' / 'waitlist' / 'notfound') also confirmed
-- cross-tenant whether a class existed and whether it was full, which is a
-- capacity denial-of-service with a built-in progress indicator.
--
-- The guard is the same question the rest of this file asks: is this class in
-- the caller's gym? Returning 'notfound' rather than raising is deliberate — a
-- distinct error would still confirm the class exists to someone who should not
-- know that.

create or replace function public.book_class(p_class uuid)
returns text language plpgsql security definer set search_path = public as $$
declare v_cap int; v_count int; v_status text; v_tenant uuid;
begin
  perform 1 from gym_classes where id = p_class for update;
  select capacity, tenant_id into v_cap, v_tenant from gym_classes where id = p_class;
  if v_cap is null then return 'notfound'; end if;
  -- A class outside your gym is indistinguishable from one that is not there.
  if v_tenant is distinct from my_tenant() then return 'notfound'; end if;

  select count(*) into v_count from class_bookings where class_id = p_class and status = 'booked';
  v_status := case when v_count < v_cap then 'booked' else 'waitlist' end;
  insert into class_bookings (class_id, user_id, status) values (p_class, auth.uid(), v_status)
    on conflict (class_id, user_id) do update set status = excluded.status;
  return v_status;
end; $$;

create or replace function public.cancel_class(p_class uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  -- Cancelling only ever touches the caller's own booking, so the tenant check
  -- guards the promotion below rather than the delete.
  delete from class_bookings where class_id = p_class and user_id = auth.uid();

  if not exists (select 1 from gym_classes gc
                 where gc.id = p_class and gc.tenant_id = my_tenant()) then
    return;
  end if;

  update class_bookings set status = 'booked'
   where id = (
     select cb.id from class_bookings cb join gym_classes gc on gc.id = cb.class_id
     where cb.class_id = p_class and cb.status = 'waitlist'
       and (select count(*) from class_bookings b where b.class_id = p_class and b.status = 'booked') < gc.capacity
     order by cb.created_at asc limit 1
   );
end; $$;

revoke execute on function public.book_class(uuid) from public, anon;
revoke execute on function public.cancel_class(uuid) from public, anon;
grant execute on function public.book_class(uuid) to authenticated;
grant execute on function public.cancel_class(uuid) to authenticated;


-- ── 8 · An owner could not read their own members' profiles ────────────────
--
-- Not a leak — the opposite, and found while fixing the leaks. There is no
-- owner-scoped SELECT policy on `profiles` anywhere in the schema: only
-- profiles_self and three trainer-scoped ones. So a gym owner could read their
-- own row and nobody else's.
--
-- 27-owner-portal-access.sql opens by asserting "an owner can already see their
-- tenant's profiles". That is not true of the checked-in policies, and several
-- things were quietly built on the assumption — the member search on the Studio
-- members screen queries profiles by tenant and would have returned an empty
-- list for every owner, which reads as "nobody matches" rather than "you are
-- not allowed to ask".
--
-- WHY my_role()/my_tenant() AND NOT is_owner_of(): this policy is ON profiles,
-- and is_owner_of() is a plain `stable` function that selects from profiles —
-- so it would re-enter this policy and Postgres would raise infinite recursion.
-- my_role() and my_tenant() are SECURITY DEFINER precisely so they can be used
-- here; that is what 28-fix-profiles-recursion.sql exists for.

drop policy if exists profiles_owner_r on public.profiles;
create policy profiles_owner_r on public.profiles for select
  using (my_role() = 'owner' and tenant_id = my_tenant());

-- ▶ owner-policy-scope.sql

-- ── "AN owner" is not "the owner of THIS row" ───────────────────────────────
--
-- `profiles.role = 'owner'` used to mean the PLATFORM owner — one person, who
-- was genuinely allowed to read everything. 27-owner-portal-access.sql redefined
-- it to mean a GYM owner, scoped to their own tenant, and every policy written
-- from that point on asks the scoped question through is_owner_of(tenant_id).
--
-- The policies written BEFORE that redefinition were never revisited. Nine of
-- them still ask the unscoped question, in one of two spellings:
--
--     exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'owner')
--     my_role() = 'owner'
--
-- Both mean "is this caller an owner of some gym, anywhere on the platform".
-- Neither mentions the row being read. So the owner of gym A could read gym B's
-- Stripe customer ids, subscription status and invoice amounts, gym B's clients'
-- purchase history, gym B's Connect payout accounts, gym B's coach rosters,
-- gym B's crash logs and gym B's members' written feedback. Every gym owner on
-- the platform is a signed-in user, so this is not a theoretical hole: it is
-- readable today from the app's own Supabase client with no special tooling.
-- 35-class-capacity-and-scope.sql fixed the same mistake inside
-- class_attendance_summary; this file finishes the job for the RLS policies.
--
-- WHY THIS IS NOT A ONE-WORD SWAP. The billing tables (billing_customers,
-- subscriptions, invoices, connect_accounts, client_purchases) have no
-- tenant_id column at all — they are keyed on trainer_id, because they were
-- built when billing was platform→trainer and a gym was not part of the model.
-- Their tenant has to be reached by joining trainers, which is exactly the hop
-- 27-owner-portal-access.sql already makes for sessions:
--
--     exists (select 1 from trainers tr
--              where tr.id = <table>.trainer_id and is_owner_of(tr.tenant_id))
--
-- That join is safe to write inline because `trainers` has trainers_owner_r
-- (is_owner_of(tenant_id)), so an owner can read the rows the join needs.
--
-- DUPLICATES. Several of these tables carry TWO stale policies — the original
-- in 20/21, and a rewrite in 28-fix-profiles-recursion.sql that swapped the
-- profiles sub-select for my_role() without noticing it was preserving an
-- unscoped test. Same policy name in both files for most of them, but
-- `subscriptions` has sub_read (20) AND sub_owner (28) under different names.
-- Permissive policies OR together, so dropping one and leaving the other fixes
-- nothing. Every stale name is dropped below.
--
-- SELF-ACCESS IS PRESERVED. A trainer still reads their own billing, Connect
-- and invoice rows; a client still reads their own purchases; a member still
-- reads their own feedback (fb_own, untouched). Only the owner arm narrows.

-- ── a tenant lookup that does not re-enter RLS ──────────────────────────────
-- Two of the nine tables cannot use the inline trainers join.
--
--   * `coach_clients` would deadlock on it. trainers has
--     trainers_assigned_client_r, whose USING clause reads coach_clients — so a
--     coach_clients policy that reads trainers closes a cycle and Postgres
--     raises "infinite recursion detected in policy for relation". That is the
--     precise failure 28-fix-profiles-recursion.sql existed to remove, and the
--     remedy there applies here: ask through SECURITY DEFINER.
--
--   * `app_errors` reaches its tenant only through profiles, and there is no
--     owner-scoped SELECT policy on profiles — an inline sub-select would
--     return no rows for the very caller it is meant to authorise, silently
--     emptying the owner's crash inbox.
--
-- profiles.tenant_id is the spine (37-member-invites.sql rewrites it, and
-- clients.tenant_id, when a member moves gyms), so it is the right source. The
-- trainers row wins when both exist because trainers.tenant_id is NOT NULL and
-- is what the billing joins above key on; this keeps the two paths agreeing.
create or replace function public.tenant_of_user(u uuid)
returns uuid language sql stable security definer set search_path to 'public', 'pg_temp'
as $function$
  select coalesce(
    (select t.tenant_id from trainers t where t.id = u),
    (select p.tenant_id from profiles p where p.id = u)
  );
$function$;

revoke all on function public.tenant_of_user(uuid) from public;
grant execute on function public.tenant_of_user(uuid) to authenticated;

-- ── billing: trainer_id → trainers.tenant_id ────────────────────────────────
-- Stripe customer ids and the email they were opened with. Leaked the identity
-- of every other gym's trainers as Stripe billing contacts.
drop policy if exists cust_read on billing_customers;
create policy cust_read on billing_customers for select using (
  trainer_id = (select auth.uid())
  or exists (select 1 from trainers tr
              where tr.id = billing_customers.trainer_id and is_owner_of(tr.tenant_id)));

-- Both stale policies dropped: sub_read (20-billing.sql) had the self arm,
-- sub_owner (28) was owner-only. They OR'd, so the pair behaved as one policy
-- and is replaced by one — plan, status and renewal date for a competitor's
-- trainers is commercial intelligence, not gym data.
drop policy if exists sub_read on subscriptions;
drop policy if exists sub_owner on subscriptions;
create policy sub_read on subscriptions for select using (
  trainer_id = (select auth.uid())
  or exists (select 1 from trainers tr
              where tr.id = subscriptions.trainer_id and is_owner_of(tr.tenant_id)));

-- Invoice amounts and the hosted Stripe URL. The URL is the sharper end of it:
-- it renders a payable invoice document, not just a number.
drop policy if exists inv_read on invoices;
create policy inv_read on invoices for select using (
  trainer_id = (select auth.uid())
  or exists (select 1 from trainers tr
              where tr.id = invoices.trainer_id and is_owner_of(tr.tenant_id)));

-- Connect payout accounts — which of a rival's trainers can actually take money
-- and which are still stuck in onboarding.
drop policy if exists conn_read on connect_accounts;
create policy conn_read on connect_accounts for select using (
  trainer_id = (select auth.uid())
  or exists (select 1 from trainers tr
              where tr.id = connect_accounts.trainer_id and is_owner_of(tr.tenant_id)));

-- Client purchases: who bought what, for how much, and how much of the pack is
-- used. The client and the selling trainer keep their own rows; the owner arm
-- now only covers trainers who belong to the owner's gym.
drop policy if exists purch_read on client_purchases;
create policy purch_read on client_purchases for select using (
  client_id = (select auth.uid())
  or trainer_id = (select auth.uid())
  or exists (select 1 from trainers tr
              where tr.id = client_purchases.trainer_id and is_owner_of(tr.tenant_id)));

-- ── tables that already carry their tenant, or reach it through a person ────
-- feedback.tenant_id was already being checked — and then undone on the very
-- next line. `is_owner_of(tenant_id) or my_role() = 'owner'` is two permissive
-- arms in one policy: the second is strictly wider than the first, so the
-- scoped test never decided anything. Dropping it is the whole fix. Rows with
-- a null tenant_id are now invisible to owners rather than visible to all of
-- them; their author still reads them via fb_own.
drop policy if exists fb_owner on feedback;
create policy fb_owner on feedback for select using (is_owner_of(tenant_id));

-- Crash logs carry a stack trace and whatever the message happened to contain,
-- attributed to a named user. Scoped through the reporting user's tenant.
-- app_errors_insert allows a null user_id (an error caught before sign-in);
-- those rows have no tenant to belong to and are now readable by nobody
-- through RLS, which is the fail-closed side of the choice.
drop policy if exists app_errors_owner on app_errors;
create policy app_errors_owner on app_errors for select using (
  is_owner_of(tenant_of_user(user_id)));

-- Coach rosters — client names and goals, typed in by hand for people who have
-- no account. coach_clients.trainer_id references auth.users directly and the
-- table has no tenant_id, so the coach's own tenant is the row's tenant. Via
-- tenant_of_user rather than a trainers join: see the note on the function.
drop policy if exists coach_clients_owner_r on coach_clients;
create policy coach_clients_owner_r on coach_clients for select using (
  is_owner_of(tenant_of_user(trainer_id)));

-- ── exercise_videos: deliberately NOT touched here ──────────────────────────
-- The ninth stale policy was exvid_read, whose `or my_role() = 'owner'` arm let
-- any owner read any gym's coaching videos. 38-tenant-isolation.sql — which
-- sorts immediately before this file and therefore runs immediately before it —
-- has already replaced that policy, and answered the underlying question
-- differently: it treats exercise demos as content rather than customer data,
-- opens SELECT to every authenticated user, and scopes WRITES to the gym via
-- `exists (select 1 from trainers tr where tr.id = exercise_videos.trainer_id
-- and is_owner_of(tr.tenant_id))`. Either answer closes the owner leak — 38's
-- version has no owner-specific read arm left to escalate through.
--
-- Re-creating exvid_read here would win purely on filename order and revert a
-- deliberate product decision without either author noticing. So it is left
-- alone on purpose. If the demos-are-private reading is the one you want, the
-- change belongs in 38 next to its own reasoning, not silently after it.

-- ▶ function-grants.sql

-- ─────────────────────────────────────────────────────────────────────────
-- No function in this schema is callable without signing in.
--
-- Postgres grants EXECUTE to PUBLIC on every function it creates. That default
-- is what `anon` resolves through, and `anon` is the key compiled into the
-- shipped mobile app — so every RPC was reachable by anyone who extracted it.
-- Thirty-two SECURITY DEFINER functions had no revoke at all, and the three
-- that did named `anon` rather than PUBLIC, which does nothing.
--
-- Two ways this kept coming back:
--
--   · A new function silently inherits the PUBLIC grant. Nobody has to make a
--     mistake for the hole to exist; it is there unless someone removes it.
--   · `drop function` takes the ACL with it, so recreating a function to fix
--     something else quietly restores the default. That happened today: the
--     class-attendance fix dropped and recreated its function, and the
--     recreated one was anon-callable again until the revoke was re-applied.
--
-- So this is written as a loop over the catalogue rather than a list of names.
-- A list would go stale the first time somebody adds a function, which is
-- exactly how the schema arrived here.
--
-- Trigger functions are skipped: they return `trigger`, PostgREST does not
-- expose them as RPCs, and they are invoked by the trigger rather than called.
--
-- Every function gets `authenticated`, which is strictly narrower than the
-- PUBLIC grant it replaces. This is not the authorization — each function
-- still carries its own tenant check, and that is what stops one gym reading
-- another. This only ensures a caller has proved who they are first.
--
-- Nothing in the product needs anon RPC access. Every call site was checked:
-- record_referral, the one that looks like a pre-auth candidate, records the
-- SIGNED-IN user and runs after sign-up returns a session.
--
-- RE-RUN THIS after adding or recreating any function. It is idempotent.
-- ─────────────────────────────────────────────────────────────────────────

do $$
declare r record;
begin
  for r in
    select p.oid::regprocedure as sig
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.prokind = 'f'
      and pg_get_function_result(p.oid) <> 'trigger'
  loop
    execute format('revoke execute on function %s from public', r.sig);
    execute format('revoke execute on function %s from anon', r.sig);
    execute format('grant execute on function %s to authenticated', r.sig);
  end loop;
end $$;

-- ▶ account-deletion.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Make "delete my account" actually delete the account.
--
-- request_account_deletion() has existed since 02-domain-schema.sql and does
-- one thing:
--
--   update profiles set deletion_requested_at = now() where id = auth.uid();
--
-- Nothing anywhere reads that column. Grepped the whole repo: written in one
-- place, read in zero. So a member tapped the button, got a success response,
-- and their data stayed indefinitely with nobody even notified. That is worse
-- than not offering deletion at all — it is a promise the software does not
-- keep, and Google Play is about to require a public page describing it.
--
-- WHY A TRUE DELETE IS POSSIBLE HERE. profiles.id references auth.users(id) on
-- delete cascade, and 26 tables cascade directly from profiles — 39 once the
-- cascade is followed all the way down. Removing the auth user therefore
-- removes the person's data by construction rather than by a hand-maintained
-- list of DELETE statements that would drift the first time somebody adds a
-- table. Seventeen further columns across 13 tables are `on delete set null`:
-- those rows survive with the person detached, which is right for payments,
-- door-log visits and guest passes a gym must keep for tax and legal reasons.
--
-- INVOICES AND MEMBERSHIPS ARE NOT IN THAT SURVIVING SET. An earlier version
-- of this comment said they were, and it was wrong: gym_invoices.member_id and
-- memberships.member_id are both `not null references profiles(id) on delete
-- cascade`, so deleting a member takes their invoices and memberships with
-- them. Counted from the live catalogue, not from memory:
--
--   select confdeltype, count(*) from pg_constraint
--   where contype='f' and confrelid='public.profiles'::regclass
--   group by confdeltype;   -- c: 29 cols / 26 tables, n: 17 cols / 13 tables
--
-- That matters beyond tidiness. The public deletion page and the owner's
-- confirmation dialog both tell people what survives, and a gym with a tax
-- obligation to retain invoices needs to know this deletes them.
--
-- The cascade is the design. This file adds who may pull the trigger, a record
-- that it happened, and a way for a gym to see what is waiting.
-- ─────────────────────────────────────────────────────────────────────────


-- ── the queue ──────────────────────────────────────────────────────────────
--
-- deletion_requested_at already exists. This adds the other half: when it was
-- actioned, and by whom, so a gym can show its own compliance record after the
-- profile itself is gone.

create table if not exists public.deletion_log (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references public.tenants(id) on delete set null,
  -- Deliberately NOT a foreign key to profiles. The whole point is that the
  -- profile no longer exists once this row is written; a reference would either
  -- block the delete or null itself and destroy the audit trail.
  subject_id uuid not null,
  subject_label text,
  requested_at timestamptz,
  actioned_at timestamptz not null default now(),
  actioned_by uuid references auth.users(id) on delete set null,
  note text
);

create index if not exists idx_deletion_log_tenant
  on public.deletion_log(tenant_id, actioned_at desc);

alter table public.deletion_log enable row level security;

drop policy if exists deletion_log_owner on public.deletion_log;
create policy deletion_log_owner on public.deletion_log for select
  using (is_owner_of(tenant_id));


-- ── what a gym can see ─────────────────────────────────────────────────────
--
-- Pending requests for this gym only. A view rather than a policy on profiles,
-- because the owner needs the request date and a name to act on, and nothing
-- more — this is not a general window onto member records.

create or replace view public.pending_deletions
with (security_invoker = true) as
  select p.id            as subject_id,
         p.tenant_id,
         p.full_name,
         p.role,
         p.deletion_requested_at,
         -- How long the gym has left. The public page promises 30 days.
         greatest(0, 30 - extract(day from (now() - p.deletion_requested_at))::int) as days_remaining
  from public.profiles p
  where p.deletion_requested_at is not null;

grant select on public.pending_deletions to authenticated;


-- ── withdrawing ────────────────────────────────────────────────────────────
--
-- The public page promises a grace period during which a request can be taken
-- back. Without this the promise is unkeepable: nothing could clear the flag.

create or replace function public.withdraw_account_deletion()
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  update profiles set deletion_requested_at = null where id = auth.uid();
end $$;

revoke execute on function public.withdraw_account_deletion() from public, anon;
grant execute on function public.withdraw_account_deletion() to authenticated;


-- ── actioning it ───────────────────────────────────────────────────────────
--
-- Deletes the auth user, which cascades. Restricted to the owner of the gym
-- the person belongs to, and only for someone who actually asked — a gym
-- cannot use this to remove a member who has not requested it, which would be
-- a deletion tool wearing a compliance label.
--
-- The log row is written BEFORE the delete. Afterwards the profile is gone and
-- there is nothing left to read a name or a tenant from.

create or replace function public.action_account_deletion(p_subject uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  subj_tenant uuid;
  subj_name text;
  subj_requested timestamptz;
begin
  select tenant_id, full_name, deletion_requested_at
    into subj_tenant, subj_name, subj_requested
  from profiles where id = p_subject;

  if not found then
    raise exception 'No such account.' using errcode = 'P0002';
  end if;

  if subj_requested is null then
    raise exception 'That member has not asked to be deleted.' using errcode = '42501';
  end if;

  if not is_owner_of(subj_tenant) then
    raise exception 'Only the owner of that gym can action this.' using errcode = '42501';
  end if;

  insert into deletion_log (tenant_id, subject_id, subject_label, requested_at, actioned_by)
  values (subj_tenant, p_subject, subj_name, subj_requested, auth.uid());

  -- Cascades: 26 tables directly, 39 following the chain down.
  -- Seventeen columns are `on delete set null`, so payments, visits and
  -- passes survive with the person detached. Invoices and memberships do
  -- NOT — they cascade. See the header.
  delete from auth.users where id = p_subject;
end $$;

revoke execute on function public.action_account_deletion(uuid) from public, anon;
grant execute on function public.action_account_deletion(uuid) to authenticated;

-- ▶ deletion-request-idempotent.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Asking twice must not push the deadline away from you.
--
-- request_account_deletion() has been unconditional since 02-domain-schema.sql:
--
--   update profiles set deletion_requested_at = now() where id = auth.uid();
--
-- So a second call overwrites the first timestamp with a later one. The clock
-- the public page promises — actioned within 30 days of asking — restarts, and
-- pending_deletions.days_remaining jumps back up to 30. The person waited
-- longer by asking again, which is the opposite of what pressing the button
-- twice means.
--
-- This is not hypothetical. The client settings screen offers the request
-- again whenever it cannot READ the current state (a failed read must not
-- block anyone's right to erasure), so the double-call path is one dropped
-- connection away, and it is reachable by exactly the person least likely to
-- notice their deadline moved.
--
-- The fix is a where-clause, not a raise. Asking to be deleted when you have
-- already asked is not an error to be shouted at — the state you wanted is the
-- state you are in. It returns quietly, the original timestamp stands, and the
-- call stays idempotent for a client that retries.
--
-- Withdrawing still clears the flag, so withdraw-then-ask-again correctly
-- starts a fresh clock. That is a different act from asking twice.
--
-- `create or replace` keeps the function's existing ACL — only `drop function`
-- discards it — so the authenticated-only grant from 40-function-grants.sql
-- survives this. Verified with has_function_privilege after applying rather
-- than assumed, because that exact assumption was wrong earlier in this
-- schema's history.
-- ─────────────────────────────────────────────────────────────────────────

create or replace function public.request_account_deletion()
returns void language plpgsql security definer set search_path = public as $$
begin
  update profiles
     set deletion_requested_at = now()
   where id = auth.uid()
     and deletion_requested_at is null;   -- the first ask is the one that counts
end $$;

-- ▶ trainer-rota.sql

-- ── The trainer rota ────────────────────────────────────────────────────────
--
-- Phase 1. Who is on the gym floor when — and, the part that makes it worth
-- building, whether that lines up with what the floor is actually doing.
--
-- A rota that is only a calendar adds nothing over the spreadsheet it replaces.
-- The reason this table exists is that the gym already records demand: classes
-- sit in `gym_classes` with a start and a duration, one-to-ones sit in
-- `sessions`. Put the supply on the same timeline and two questions answer
-- themselves — which hours have work booked and nobody rostered, and which
-- hours have somebody rostered against nothing at all. Neither is answerable
-- from a rota alone, and neither is answerable from the timetable alone.
--
-- ── Why concrete timestamps and not a weekly pattern ────────────────────────
--
-- `trainer_availability` (part 24) already holds the recurring pattern: dow +
-- hour, the shape of a trainer's normal week. That is a different fact. A rota
-- is what is happening in THIS week — the cover for someone off sick, the
-- public holiday, the Saturday somebody swapped. Those are edits to a single
-- occurrence, and a recurrence rule cannot carry them without growing an
-- exceptions table that is these rows under another name. `gymSchedule
-- .weeklyOccurrences` made the same call for classes, for the same reason.
--
-- Storing timestamptz rather than (date, time) is what makes the comparison
-- sound: shifts, classes and sessions then live on one timeline and no part of
-- the app has to reconcile a wall clock against a timezone to ask whether an
-- hour was covered.
--
-- Additive only. Nothing here alters an existing table.

create table if not exists gym_shifts (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  -- `trainers`, not `profiles`: a shift belongs to somebody who works here. A
  -- trainer leaving takes their future shifts with them, which is right — a
  -- rota row for a person who is gone is not history, it is a hole nobody has
  -- noticed yet.
  trainer_id uuid not null references trainers(id) on delete cascade,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  -- A zero-length or reversed shift is always a typo, and it would silently
  -- cover no hours at all while looking like cover on the screen.
  constraint gym_shifts_span check (ends_at > starts_at),
  -- What they are on for. Loose enough to be useful, closed enough that the
  -- rota can be read at a glance. 'floor' is the default because that is what
  -- the roadmap item asks about — who is out there if a member needs someone.
  role text not null default 'floor'
    check (role in ('floor', 'classes', 'pt', 'desk', 'admin')),
  -- A pulled shift is kept rather than deleted. "Somebody was rostered and
  -- dropped out" and "nobody was ever rostered" produce the same hole in the
  -- cover, but they are different problems and the owner needs to tell them
  -- apart. gymRota counts neither as cover.
  status text not null default 'scheduled'
    check (status in ('scheduled', 'cancelled')),
  note text,
  created_at timestamptz not null default now()
);

-- The rota is always read as a week of one gym, and written as one trainer's
-- run of shifts. Both directions get an index.
create index if not exists idx_gym_shifts_tenant on gym_shifts(tenant_id, starts_at);
create index if not exists idx_gym_shifts_trainer on gym_shifts(trainer_id, starts_at);

-- NOT ENFORCED, deliberately: two overlapping shifts for one trainer. The
-- exclusion constraint that would catch it needs btree_gist, which this schema
-- does not install, and an overlap is a rota mistake rather than a corruption —
-- it is visible on the week view as the same name twice in one row.

-- ── row-level security ──────────────────────────────────────────────────────
-- Enabled before any policy is written. A policy on a table without RLS on is
-- inert — Postgres never consults it and Supabase's default grants to anon and
-- authenticated apply in full, which is exactly how four tables ended up
-- world-writable until 38-tenant-isolation.sql.
--
-- The helpers are SECURITY DEFINER, so a policy calling them does not re-enter
-- the table it is protecting (see 28-fix-profiles-recursion.sql).
alter table gym_shifts enable row level security;

-- The rota is the owner's instrument: they write it, and `is_owner_of` scopes
-- them to THIS gym rather than merely to being an owner somewhere.
drop policy if exists gym_shifts_owner on gym_shifts;
create policy gym_shifts_owner on gym_shifts
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

-- Trainers read it. A rota nobody rostered on it can see is a rota that gets
-- re-typed into WhatsApp, which is how it stops being true. Read only: when
-- their own shift changes it is because the gym moved it, and a trainer who
-- could edit the rota could quietly uncover the floor.
drop policy if exists gym_shifts_staff_r on gym_shifts;
create policy gym_shifts_staff_r on gym_shifts
  for select using (tenant_id = my_tenant() and my_role() in ('trainer', 'owner'));

-- No functions are added here, so nothing needs the revoke-from-PUBLIC
-- treatment that 40-function-grants.sql applies. If one is ever added to this
-- file, re-run that part: Postgres grants EXECUTE to PUBLIC by default and
-- `anon` resolves through it.

-- ▶ gym-pt-schedule.sql

-- ── One-to-ones on the gym's own timetable ──────────────────────────────────
--
-- Phase 1, the half that was still open. The gym's board (studio-web
-- /timetable) showed classes only, so at 18:00 an owner saw three classes and
-- had no way to know that four trainers were also on the floor with clients,
-- or that the studio was holding a class and a one-to-one at the same hour.
-- The booking half of PT lived in the trainer's private calendar; only the
-- outcome and payroll half (33, 36) had ever reached the gym.
--
-- ── WHY `sessions` AND NOT A NEW TABLE ──────────────────────────────────────
--
-- A one-to-one already IS a row in `sessions`: trainer, client, starts_at,
-- duration_min, and the slot's status — plus, since 33-session-outcomes.sql,
-- its tenant, its delivery outcome, the rate snapshotted at delivery, and (36)
-- the payroll run that paid for it.
--
-- The booking and the outcome are the same appointment. A parallel
-- `pt_bookings` table would fork them: payroll prices `sessions`
-- (src/lib/gymSessions.ts), so anything scheduled into a second table is
-- either invisible to payroll, or has to be copied into `sessions` as well —
-- two rows for one hour, which is how a gym ends up paying twice, or not at
-- all. It would also duplicate the tenant backfill, the fill-tenant trigger,
-- the outcome stamping and six RLS policies, and then have to keep all of it
-- in step with the original by hand.
--
-- So this part adds only what a *gym-owned* timetable needs and `sessions`
-- does not already have: where in the building the hour happens, and the right
-- for the gym — not only the trainer — to put a slot on the board and take one
-- off again.

-- ── where on the floor ──────────────────────────────────────────────────────
-- gym_classes has carried `room` since 02-domain-schema.sql. Without the same
-- column here, the single most useful question a merged board can answer —
-- "is the studio double-booked at six?" — cannot be asked at all, because half
-- the things in the room are not on the board.
alter table public.sessions add column if not exists room text;

-- The timetable reads a week at a time, per gym. idx_sessions_tenant
-- (33-session-outcomes.sql) is (tenant_id, starts_at desc) and Postgres scans
-- it backwards for an ascending window, so no second index is added here.


-- ── the gym may schedule, not only observe ──────────────────────────────────
--
-- 33-session-outcomes.sql gave the owner SELECT and UPDATE: they could read
-- the record and correct an outcome that was wrong. There was no INSERT and no
-- DELETE, so an owner could not put a one-to-one on their own timetable at
-- all. The slot had to be created by the trainer, in the trainer's calendar —
-- which is precisely the split this part exists to close.
--
-- WHY THE CHECK REACHES THE TENANT THROUGH `trainers` rather than testing
-- sessions.tenant_id directly, for two independent reasons:
--
--   * trg_sessions_fill_tenant copies tenant_id FROM the named trainer. So a
--     `is_owner_of(tenant_id)` check would be testing a value derived from the
--     row being written: name another gym's trainer and tenant_id becomes that
--     gym's, and the check would be asked about the wrong gym. Asking
--     "is this trainer mine?" cannot be steered that way.
--   * it does not depend on when the BEFORE INSERT trigger runs relative to
--     the WITH CHECK, which is a detail no policy should rest on.
--
-- The inline join is safe to write: `trainers` has trainers_owner_r
-- (23-trainer-directory.sql), so an owner can read the row the join needs, and
-- is_owner_of() has been SECURITY DEFINER since 28-fix-profiles-recursion.sql
-- so it does not re-enter RLS on profiles.
drop policy if exists sessions_gym_owner_i on public.sessions;
create policy sessions_gym_owner_i on public.sessions
  for insert with check (
    exists (select 1 from public.trainers tr
             where tr.id = sessions.trainer_id and is_owner_of(tr.tenant_id)));

-- Taking a slot back off the board. Scoped to the gym that owns it; the
-- protection for slots that have become part of the record is the trigger
-- below, not this policy, for the reason given there.
drop policy if exists sessions_gym_owner_d on public.sessions;
create policy sessions_gym_owner_d on public.sessions
  for delete using (tenant_id is not null and is_owner_of(tenant_id));


-- ── a session that has been marked or paid is a record, not a plan ──────────
--
-- Deleting one destroys the evidence behind a payroll line. The settlement row
-- survives with its amount and its sessions_count, but the sessions it covered
-- are gone, so the run can never be reconciled against the work again — and
-- settleableSessions() only ever knew a session was already paid because the
-- row carried a settlement_id.
--
-- Both the owner's new DELETE right above and the trainer's existing
-- sessions_trainer policy (09-sessions-access.sql, FOR ALL — which has always
-- included DELETE) could do it today.
--
-- WHY A TRIGGER RATHER THAN A NARROWER POLICY: RLS filters rows out silently.
-- A policy of `using (... and outcome is null)` would make the delete affect
-- zero rows and return no error, so a caller that checked only `.error` — the
-- house pattern — would report "removed" for a session that is still there.
-- Raising says no out loud, and says which of the two reasons it was.
--
-- WHY THE current_user TEST, exactly as in 38-tenant-isolation.sql: a
-- SECURITY DEFINER function runs as its owner, an app request runs as
-- `authenticated` or `anon`. action_account_deletion() (41) deletes auth.users
-- and relies on the cascade reaching sessions; that path must not start
-- raising because a trainer once had a session settled. Erasure stays
-- unblocked; the app cannot quietly rewrite payroll history.
-- NOT security definer, and that is the whole point.
--
-- `current_user` inside a SECURITY DEFINER function reports the function's
-- OWNER, not the caller. This was written as definer, which made current_user
-- always 'postgres', so the guard below could never be true and the trigger
-- silently protected nothing — a control that looks real and does nothing,
-- which is the exact class of fault recorded at the end of the runbook.
--
-- Verified against the live database rather than reasoned about:
--   set local role authenticated;
--   select current_user, _probe_invoker(), _probe_definer();
--   -> authenticated | authenticated | postgres
--
-- As an invoker function it needs no elevated rights: it only reads OLD and
-- raises. The guard still lets action_account_deletion()'s cascade through,
-- because that runs as postgres and so fails the in ('authenticated','anon')
-- test — which is the behaviour that was wanted.
create or replace function public.sessions_block_delete_of_record() returns trigger
language plpgsql set search_path = public as $$
begin
  if current_user in ('authenticated', 'anon') then
    if old.settlement_id is not null then
      raise exception 'That session has already been paid. Reverse the settlement before removing it.'
        using errcode = '42501';
    end if;
    if old.outcome is not null then
      raise exception 'That session has an outcome recorded and is part of the pay record. Undo the outcome first if it should not have one.'
        using errcode = '42501';
    end if;
  end if;
  return old;
end $$;

drop trigger if exists trg_sessions_block_delete_of_record on public.sessions;
create trigger trg_sessions_block_delete_of_record
  before delete on public.sessions
  for each row execute function public.sessions_block_delete_of_record();

-- ▶ progress-photos.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Progress photos — make them real, and make deleting them real too.
--
-- WHAT WAS THERE. `progress_photos` has existed since 01-schema.sql with RLS
-- enabled and, in this repo, zero policies — so a fresh project got a table
-- nobody could write to. Live, two policies had been added by hand and never
-- written down (the same drift that produced parts 23–25). The `photos` bucket
-- existed, private, with NO policies on storage.objects at all: the only
-- bucket-scoped policies live were `exvid_obj_insert/read/delete` for
-- `exercise-videos`. Nothing could put a byte in `photos` or read one out.
-- Meanwhile app/(client)/scans.tsx held photos in useState and told the member
-- how many were "on screen", because saying "saved" would have been a lie.
--
-- This file is the storage side of making that label true.
--
-- ── THE THING THAT MAKES THIS HARD ───────────────────────────────────────
--
-- `progress_photos.client_id` cascades from `clients`, so account deletion
-- removes the ROWS. It does not remove the FILES. There is no cascade from a
-- database table into object storage, and Supabase now blocks the obvious
-- workaround outright: `storage.objects` carries a BEFORE DELETE trigger,
-- `protect_objects_delete`, whose function raises
--
--   'Direct deletion from storage tables is not allowed. Use the Storage API
--    instead.'  HINT: 'This prevents accidental data loss from orphaned objects.'
--
-- unless `storage.allow_delete_query` is set. Read that hint carefully: it is
-- Supabase confirming that deleting the metadata row leaves the bytes behind.
-- So a trigger that deletes from storage.objects would either fail outright or,
-- if forced, produce exactly the orphan it looks like it is preventing.
--
-- The only thing that removes the bytes is a DELETE against the Storage HTTP
-- API. That needs a credential, and at the moment of account deletion the
-- person is not the one holding it — an owner actions the deletion, possibly
-- 30 days after the member last opened the app.
--
-- ── THE SOLUTION, IN TWO HALVES ──────────────────────────────────────────
--
-- 1. REMEMBER. An AFTER DELETE trigger on `progress_photos` copies the storage
--    path into `photo_purge` before the row is gone for good. This fires for a
--    single-photo delete AND for the account-deletion cascade. Without it the
--    paths are simply unknowable afterwards — the row that held the path is
--    the thing that was deleted. Everything else depends on this step.
--
-- 2. PURGE. `purge_photo_file()` issues a DELETE to the Storage API over
--    pg_net, authenticating with the project's service_role key read from
--    Vault at call time — the pattern already used by `notify_on_message()` in
--    26-message-notifications.sql, for the same reason (a key in a function
--    body is readable by anything that can read pg_proc).
--
--    pg_net is asynchronous: the call queues the request and a background
--    worker sends it, so nothing blocks the delete or the cascade. The reply
--    lands in `net._http_response`, and `confirm_photo_purges()` reads it back
--    and stamps `purged_at` ONLY on a response that actually says the object
--    is gone. Nothing in here marks a file deleted because it asked nicely.
--
-- OPERATOR STEP, AND WHAT HAPPENS WITHOUT IT.  This needs one Vault secret:
--
--     name:  storage_service_key
--     value: the project's service_role key
--            (Dashboard ▸ Project Settings ▸ API ▸ service_role)
--     put it in: Dashboard ▸ Project Settings ▸ Vault
--
-- Until that exists, every delete still lands in `photo_purge`, `purged_at`
-- stays null and `note` reads 'no storage_service_key in Vault'. That is the
-- honest failure: the work is recorded and visibly outstanding, rather than
-- silently skipped. After creating the secret, run
--
--     select public.purge_progress_photo_files();
--
-- once and the backlog drains. It is safe to run at any time; it only ever
-- touches paths whose database row is already deleted.
--
-- To see what is outstanding (SQL editor / service role — photo_purge has RLS
-- on and no policies, so no end user can read it):
--
--     select path, subject_id, queued_at, attempts, note
--       from public.photo_purge where purged_at is null order by queued_at;
--
-- ── WHY THE TRIGGER FUNCTION IS NOT `SECURITY DEFINER`-WITH-A-`current_user`-
--    GUARD.  It is security definer (it must write photo_purge past RLS and
--    call pg_net), but it tests nothing about who the caller is. Inside a
--    definer function `current_user` is the function's OWNER, not the caller,
--    so a `current_user` guard in here would never fire and would read like
--    protection while providing none. The authorisation that matters is on the
--    DELETE that fires this trigger, and it is RLS, above.
-- ─────────────────────────────────────────────────────────────────────────


-- ═════════════════════════════════════════════════════════════════════════
-- 1 · Storage policies for the `photos` bucket
-- ═════════════════════════════════════════════════════════════════════════
--
-- Own-folder access, keyed on the first path segment, exactly as the
-- exercise-videos policies do. The difference is READ: `exercise-videos` is a
-- public bucket and `exvid_obj_read` is bucket-wide. `photos` is PRIVATE, and
-- read here is own-folder too — a progress photo is read through a signed URL
-- minted by its owner, never a public URL.
--
-- RLS on storage.objects is enabled by Supabase itself. Asserting it rather
-- than assuming it, because a policy on a table with RLS off is inert and
-- would look like a working restriction.

do $$
begin
  if not exists (
    select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'storage' and c.relname = 'objects' and c.relrowsecurity
  ) then
    raise exception 'storage.objects does not have RLS enabled — the policies below would be inert.';
  end if;
end $$;

drop policy if exists photos_obj_insert on storage.objects;
create policy photos_obj_insert on storage.objects for insert to authenticated
  with check (
    bucket_id = 'photos'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

drop policy if exists photos_obj_read on storage.objects;
create policy photos_obj_read on storage.objects for select to authenticated
  using (
    bucket_id = 'photos'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

drop policy if exists photos_obj_delete on storage.objects;
create policy photos_obj_delete on storage.objects for delete to authenticated
  using (
    bucket_id = 'photos'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );


-- ═════════════════════════════════════════════════════════════════════════
-- 2 · Row policies on progress_photos
-- ═════════════════════════════════════════════════════════════════════════
--
-- RLS was enabled in 01-schema.sql, which runs first. Re-declaring the owner
-- policy here puts it in the repo, where it was missing.
--
-- `for all` with no `with check` means the USING expression is also the check,
-- so a member cannot insert a row naming somebody else as its subject.

drop policy if exists progress_photos_owner on public.progress_photos;
create policy progress_photos_owner on public.progress_photos for all
  using (client_id = (select auth.uid()))
  with check (client_id = (select auth.uid()));

-- ── COACH ACCESS: deliberately none. ─────────────────────────────────────
--
-- Live carried a `progress_photos_trainer_read` policy — a SELECT for the
-- linked trainer, mirroring scans_trainer_read from 19-trainer-read-access.sql.
-- It is dropped here on purpose, and this is the reasoning, so that nobody
-- re-adds it by pattern-matching on the other tables:
--
--   · A progress photo is not a weight number. It is typically taken in
--     underwear, alone, in a bathroom. A coach seeing a client's body-fat
--     percentage is the product working; a coach seeing that photo without the
--     client choosing it is a different act entirely.
--   · There is no consent step. The app has no per-photo sharing control, no
--     indicator that anyone else can see them, and no way to take it back. A
--     read policy would mean people upload believing it is private and are
--     wrong. Sharing has to be something you DO, not something that is true by
--     default because of who your coach is.
--   · It buys nothing today. Nothing in the coach app renders client progress
--     photos, so the policy granted access no screen used — a standing
--     exposure with no feature behind it.
--   · It was latent, which is worse than open. The row also carries
--     `image_path`. The day somebody adds a coach-side signed-URL helper, the
--     photos become visible with no review of consent, because the "hard part"
--     already looked done.
--
-- When per-photo sharing ships, it wants a `shared_with_coach boolean not null
-- default false` on this table, a SELECT policy gated on it, AND a matching
-- storage.objects policy — the row and the file have to be granted separately,
-- which is the whole shape of this file. Until then: no coach access at either
-- layer, stated rather than inherited.

drop policy if exists progress_photos_trainer_read on public.progress_photos;

create index if not exists idx_progress_photos_client
  on public.progress_photos (client_id, taken_at);


-- ═════════════════════════════════════════════════════════════════════════
-- 3 · The purge queue
-- ═════════════════════════════════════════════════════════════════════════
--
-- Deliberately NOT a foreign key to anything. The point of this table is that
-- it outlives the row, the client, the profile and the auth user — a reference
-- would either block the cascade or null itself and lose the path, which is
-- the one column that matters.

create table if not exists public.photo_purge (
  path            text primary key,
  subject_id      uuid not null,
  queued_at       timestamptz not null default now(),
  attempts        int not null default 0,
  last_attempt_at timestamptz,
  request_id      bigint,            -- pg_net request; reply in net._http_response
  purged_at       timestamptz,       -- set only from a response that confirms it
  note            text
);

create index if not exists idx_photo_purge_pending
  on public.photo_purge (queued_at) where purged_at is null;

-- RLS on, and no policies. Nothing an end user does should read or write this
-- directly; the functions below are security definer and reach it as their
-- owner, and an operator reads it in the SQL editor. RLS is enabled BEFORE any
-- policy exists, per the house rule — here there simply are none, which is the
-- restriction.
alter table public.photo_purge enable row level security;


-- ═════════════════════════════════════════════════════════════════════════
-- 4 · Purging
-- ═════════════════════════════════════════════════════════════════════════

-- Read back what pg_net actually got, and stamp purged_at only on an answer
-- that means the object is no longer there. 200 = deleted. 404 = it was
-- already gone, which is the same end state and is the normal case when the
-- app deleted the file itself before deleting the row. Anything else is
-- recorded and left pending for a retry.
--
-- net._http_response is pruned by pg_net after a few hours. A request whose
-- reply has aged out simply stays pending and gets re-sent; a DELETE of an
-- absent object is idempotent, so re-sending costs nothing.
create or replace function public.confirm_photo_purges()
returns int
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  r record;
  v_status int;
  v_err text;
  v_body text;
  v_absent boolean;
  n int := 0;
begin
  for r in
    select path, request_id from public.photo_purge
     where purged_at is null and request_id is not null
     limit 500
  loop
    select status_code, error_msg, content
      into v_status, v_err, v_body
      from net._http_response where id = r.request_id;

    -- Supabase Storage answers a DELETE for a MISSING object with HTTP 400
    -- whose BODY carries the real story:
    --
    --   status_code 400
    --   {"statusCode":"404","error":"not_found","message":"Object not found",
    --    "code":"NoSuchKey"}
    --
    -- The check was `v_status in (200, 204, 404)`, so an already-absent file
    -- was NEVER confirmed: it stayed pending, was re-sent on every drain, and
    -- the queue could not empty. An infinite retry for a file already in the
    -- state we wanted.
    --
    -- Found by queueing a correctly-shaped path for a file that does not
    -- exist and reading net._http_response, rather than accepting that a
    -- dispatched request meant a working one.
    v_absent := v_body is not null
                and (v_body like '%NoSuchKey%' or v_body like '%"statusCode":"404"%'
                     or v_body like '%not_found%');

    if v_status in (200, 204, 404) or (v_status = 400 and v_absent) then
      update public.photo_purge
         set purged_at = now(),
             note = case when v_status in (200, 204) then 'deleted' else 'already absent' end
       where path = r.path;
      n := n + 1;
    elsif v_status is not null then
      update public.photo_purge
      -- Keep the body. "storage returned 400" alone is what made this hard to
      -- read: 400 covers both a missing file and a genuine refusal.
         set note = 'storage returned ' || v_status
                    || coalesce(' — ' || left(coalesce(v_body, v_err), 200), '')
       where path = r.path;
    elsif v_err is not null then
      update public.photo_purge set note = v_err where path = r.path;
    end if;
    -- v_status and v_err both null: the reply has not arrived or has aged out.
    -- Leave it pending; the next drain re-sends.
  end loop;
  return n;
end $$;

revoke execute on function public.confirm_photo_purges() from public, anon;
grant execute on function public.confirm_photo_purges() to authenticated;


-- Send one DELETE to the Storage API for one queued path.
--
-- Callable by any signed-in user, and that is safe on purpose: it acts ONLY on
-- a path already sitting in photo_purge with purged_at null — that is, a file
-- whose database row is already deleted and which is already destined for
-- removal. There is no argument shape that makes it touch anything else. It
-- takes no caller identity into account because it is not making an
-- authorisation decision; the decision was made when the row was deleted.
create or replace function public.purge_photo_file(p_path text)
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_key text;
  v_req bigint;
begin
  if p_path is null or not exists (
    select 1 from public.photo_purge where path = p_path and purged_at is null
  ) then
    return;
  end if;

  -- The path goes into a URL. Ours are '<uuid>/<millis>-<token>.jpg' and need
  -- no escaping; anything else is refused rather than sent half-encoded, where
  -- it could address a different object.
  if p_path !~ '^[0-9a-fA-F-]{36}/[A-Za-z0-9._-]{1,120}$' then
    update public.photo_purge
       set note = 'path is not in the expected <uid>/<name> shape — not sent'
     where path = p_path;
    return;
  end if;

  select decrypted_secret into v_key
    from vault.decrypted_secrets where name = 'storage_service_key' limit 1;

  if v_key is null or v_key = '' then
    update public.photo_purge
       set note = 'no storage_service_key in Vault — file NOT deleted'
     where path = p_path;
    return;
  end if;

  select net.http_delete(
    url     := 'https://phgfwzpkkwdysftlgkoq.supabase.co/storage/v1/object/photos/' || p_path,
    headers := jsonb_build_object(
      'Authorization', 'Bearer ' || v_key,
      'apikey',        v_key)
  ) into v_req;

  update public.photo_purge
     set request_id = v_req,
         attempts = attempts + 1,
         last_attempt_at = now(),
         note = 'sent'
   where path = p_path;
end $$;

revoke execute on function public.purge_photo_file(text) from public, anon;
grant execute on function public.purge_photo_file(text) to authenticated;


-- Confirm what is outstanding, then re-send everything still pending. The
-- operator's entry point, and the retry. Bounded so it cannot become a
-- thundering herd against our own storage.
create or replace function public.purge_progress_photo_files()
returns table (confirmed int, sent int)
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  r record;
  n int := 0;
begin
  confirmed := public.confirm_photo_purges();
  for r in
    select path from public.photo_purge
     where purged_at is null order by queued_at limit 200
  loop
    perform public.purge_photo_file(r.path);
    n := n + 1;
  end loop;
  sent := n;
  return next;
end $$;

revoke execute on function public.purge_progress_photo_files() from public, anon;
grant execute on function public.purge_progress_photo_files() to authenticated;


-- The app's way to hand back a file it uploaded but could not attach to a row,
-- or could not delete itself. Own-folder only: the first path segment must be
-- the caller's own uid, which is the same rule the storage policies enforce.
-- Without this, a failed row insert after a successful upload would leave a
-- file that nothing in the system knows the name of.
create or replace function public.queue_photo_file_purge(p_path text)
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if p_path is null or split_part(p_path, '/', 1) <> v_uid::text then
    raise exception 'that is not your file' using errcode = '42501';
  end if;

  insert into public.photo_purge (path, subject_id, note)
  values (p_path, v_uid, 'orphan handed back by the app')
  on conflict (path) do nothing;

  perform public.purge_photo_file(p_path);
end $$;

revoke execute on function public.queue_photo_file_purge(text) from public, anon;
grant execute on function public.queue_photo_file_purge(text) to authenticated;


-- ═════════════════════════════════════════════════════════════════════════
-- 5 · The trigger — the half that cannot be added later
-- ═════════════════════════════════════════════════════════════════════════
--
-- The queue INSERT is outside the exception block on purpose. A plpgsql
-- EXCEPTION block is a savepoint: catching an error rolls back everything done
-- inside it. Putting the insert in there would mean a failing pg_net call
-- silently discarded the record of the file as well, which is precisely the
-- outcome this whole file exists to prevent.
--
-- The send IS inside one, because nothing about object storage may block a
-- person's deletion — least of all an account deletion cascade.

create or replace function public.on_progress_photo_deleted()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  if OLD.image_path is not null and OLD.image_path <> '' then
    insert into public.photo_purge (path, subject_id)
    values (OLD.image_path, OLD.client_id)
    on conflict (path) do update set purged_at = null, note = 'requeued';

    begin
      perform public.purge_photo_file(OLD.image_path);
    exception when others then
      -- Recorded above; a later purge_progress_photo_files() re-sends it.
      null;
    end;
  end if;
  return OLD;
end $$;

drop trigger if exists on_progress_photo_delete on public.progress_photos;
create trigger on_progress_photo_delete
  after delete on public.progress_photos
  for each row execute function public.on_progress_photo_deleted();

-- ▶ session-duration.sql

-- ── How long the session ran ────────────────────────────────────────────────
--
-- One column, `workouts.session_mins`, so that a training session can be
-- written back to Apple Health.
--
-- ── Why the app needed a new fact ───────────────────────────────────────────
--
-- HealthKit will not accept a workout without a start AND an end. Repple knew
-- the start of everything and the end of almost nothing: `cardio.mins` covers a
-- run or a row, `zones` covers anything recorded against a live heart-rate
-- source, and neither exists for the case that makes up most of this log — a
-- strength session, which records reps and weight and no clock at all.
--
-- The tempting fix is to assume a length. It is also the one thing that must
-- not happen here: a nominal 45 minutes would land in a person's permanent
-- health record indistinguishable from a measurement, and every figure in this
-- product has to trace to something real. Deriving it from how long the logging
-- screen was open is worse, not better — people log on the walk home, so it
-- would write "4 min" for a 50-minute session and it would look measured.
--
-- So the length is asked for. A number the person types is evidence from
-- whoever was in the room, the same standing as the reps, the load and the RPE
-- already stored beside it, and the same thing Apple's own Health app asks for
-- when you add a workout by hand.
--
-- ── Why nullable, and why no default ────────────────────────────────────────
--
-- NULL is the honest state and has to stay reachable: it means nobody has said
-- how long this session was. A session in that state cannot be written to
-- Health, and the Watch & devices screen says exactly that rather than quietly
-- skipping it. A DEFAULT of any kind would erase the distinction between "50
-- minutes, stated" and "nobody knows", which is the whole point of the column.
--
-- The check refuses 0 and negatives for the same reason. A zero-minute workout
-- is not a short workout; it is an unfinished form, and HealthKit would accept
-- it as a real event with a zero duration.
--
-- ── Why it sits on `workouts` and not a new `sessions` table ────────────────
--
-- A session is already represented here: one session writes all of its
-- exercises as rows sharing `performed_at` (see the comment on
-- `WorkoutEntry.id` in src/lib/mockData.ts). The length is a fact about that
-- group, so every row in the group carries the same value and the app writes
-- them together in a single statement keyed on (user_id, performed_at). A
-- separate table would add a join and a second source of truth for grouping
-- that the timestamp already provides.
--
-- Additive only. Nothing here alters an existing column or policy; existing
-- rows keep NULL, which reads back as "not known" rather than as a duration.

alter table workouts add column if not exists session_mins int;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'workouts_session_mins_positive'
  ) then
    alter table workouts
      add constraint workouts_session_mins_positive
      check (session_mins is null or session_mins > 0);
  end if;
end $$;

comment on column workouts.session_mins is
  'Whole-session length in minutes. NULL = nobody has stated it; never defaulted. '
  'Populated only from a measured source or from the person''s own entry.';

-- ▶ share-progress-photo.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Sending a progress photo to your coach — the consent model.
--
-- 45-progress-photos.sql closed coach access at BOTH layers and wrote down
-- why: a progress photo is typically taken in underwear, alone, in a bathroom,
-- and a coach seeing one without the client choosing it is a different act from
-- a coach seeing a body-fat percentage. It ended with the shape this file has
-- to fill in:
--
--     "When per-photo sharing ships, it wants … a SELECT policy gated on it,
--      AND a matching storage.objects policy — the row and the file have to be
--      granted separately, which is the whole shape of this file."
--
-- This is that file. Nothing here widens the default: with no rows in
-- `progress_photo_shares`, both policies below are false for every coach and
-- every photo, and `progress_photos_owner` remains the only access that exists.
--
-- ── WHAT THIS IS NOT ─────────────────────────────────────────────────────
--
-- It is NOT a `shared_with_coach boolean` on `progress_photos`, which is what
-- part 45 sketched. A boolean says "my coach may see this", and "my coach" is
-- whoever holds that job today. Change coach and every photo you ever sent the
-- last one is handed to the new one, silently, because the column never named
-- anybody. Consent was given to a PERSON, so the grant records that person.
--
-- It is NOT a setting, a preference, or anything you can turn on. There is no
-- row shape here that means "all of them" or "from now on". One row is one
-- photo sent to one coach. Sharing today's photo cannot share tomorrow's,
-- because tomorrow's photo does not have a row and nothing will write one for
-- it. That is requirement 1 enforced by the data model rather than by care.
--
-- ── THE FOUR PROPERTIES, AND WHERE EACH ONE LIVES ────────────────────────
--
-- 1 · PER PHOTO.       primary key (photo_id, coach_id). See above.
-- 2 · REVOCABLE.       Unsharing DELETES the grant row. Both policies read the
--                      grant, so the row and the file go dark together, at the
--                      same instant, from one delete. (The one honest caveat:
--                      a signed URL already minted stays valid until it
--                      expires. src/lib/photoShare.ts mints coach URLs with a
--                      five-minute TTL for exactly this reason, and the app
--                      says so rather than claiming instant erasure.)
-- 3 · VISIBLE.         The client reads their own grants (policy `pps_client`)
--                      and the Progress screen labels every photo with what it
--                      finds. A grant that exists is a photo the coach can
--                      open; there is no third state.
-- 4 · ENDS WITH THE    Two mechanisms, deliberately:
--     RELATIONSHIP.      (a) every grant is re-checked against a LIVE coaching
--                            link on every read — `coaching_link_active()`;
--                        (b) triggers DELETE the grants outright when the link
--                            is ended or the client's trainer changes.
--                      (a) alone would be enough for access. (b) exists so the
--                      client's list in requirement 3 stops listing grants that
--                      no longer grant anything. Re-hiring the same coach does
--                      NOT bring the old grants back: the rows are gone, and
--                      the client sends again if they still want to.
--
-- ── WHY "ACTIVE LINK" MEANS BOTH LINKS, NOT EITHER ───────────────────────
--
-- This project records a coach↔client link in TWO places. 06-account-
-- provisioning.sql's `link_coaching()` writes both in one statement:
--
--     insert into coaching_relationships … status = 'active';
--     update clients set trainer_id = p_coach where id = p_client;
--
-- and nothing in the repo un-links today — grep finds no writer of
-- status='ended' and none of `trainer_id = null`. So the shape of the future
-- unlink is unknown, and it may well write only one of the two.
--
-- `coaching_link_active()` therefore requires BOTH, with AND. Ending the
-- relationship by EITHER mechanism ends photo access. The failure mode of AND
-- is that a half-linked pair cannot share — visible immediately, and the app
-- says "no coach linked" rather than lying. The failure mode of OR is that a
-- coach who was let go keeps seeing the photos. For this feature those are not
-- comparable, so this fails closed.
--
-- ── SECURITY DEFINER, AND THE BUG THAT IS NOT IN HERE ────────────────────
--
-- Four functions below are `security definer`. NONE of them tests
-- `current_user`. Inside a definer function `current_user` is the function's
-- OWNER, so a `current_user` guard never fires and reads as protection while
-- providing none — that exact bug shipped in this project today.
--
-- What they use instead is `auth.uid()`, which is a different thing entirely:
-- it reads the request's JWT claim out of a GUC, so it is the CALLER either
-- way and is unaffected by SECURITY DEFINER. That is the only reason the
-- predicates below can be definer at all.
--
-- The two trigger functions test no identity of any kind. They decide purely
-- from OLD and NEW — "this link stopped being active", "this client's trainer
-- changed" — which is a fact about the row, not a claim about who is speaking.
-- ─────────────────────────────────────────────────────────────────────────


-- ═════════════════════════════════════════════════════════════════════════
-- 0 · Assertions — a policy on a table with RLS off is inert
-- ═════════════════════════════════════════════════════════════════════════
--
-- Asserted rather than assumed, the same way 45 does. If any of these were
-- false, everything below would LOOK like a restriction and be none.

do $$
begin
  if not exists (
    select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'storage' and c.relname = 'objects' and c.relrowsecurity
  ) then
    raise exception 'storage.objects does not have RLS enabled — photos_obj_read_shared would be inert.';
  end if;

  if not exists (
    select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relname = 'progress_photos' and c.relrowsecurity
  ) then
    raise exception 'public.progress_photos does not have RLS enabled — progress_photos_shared_read would be inert.';
  end if;

  -- progress_photos must NOT force RLS on its owner. The object-level
  -- predicate below resolves a storage object name back to its photo row as
  -- the table owner; under FORCE ROW LEVEL SECURITY that lookup would return
  -- nothing and a coach would get a row they can read with a file they cannot
  -- — a broken image, which is exactly the split this file exists to prevent.
  if exists (
    select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relname = 'progress_photos' and c.relforcerowsecurity
  ) then
    raise exception 'public.progress_photos has FORCE ROW LEVEL SECURITY — progress_photo_object_shared_with_viewer() cannot resolve a path and shared files would 403 while shared rows read fine.';
  end if;
end $$;


-- ═════════════════════════════════════════════════════════════════════════
-- 1 · The grant
-- ═════════════════════════════════════════════════════════════════════════
--
-- One row = one photo, sent to one coach, by its owner. There is no revoked_at
-- and no soft delete: a grant that has been taken back is DELETED. A retained
-- row filtered by `revoked_at is null` would put that predicate in every policy
-- and every query on this table, and this feature is one forgotten predicate
-- away from showing somebody's body to a person they took it back from. The
-- audit trail is not worth that; `shared_at` on the live row is.
--
-- client_id is denormalised from progress_photos.client_id so the policies and
-- the predicates never have to join back to a table whose own RLS is the thing
-- being decided. It is kept honest by the WITH CHECK on `pps_client`, which
-- refuses any insert whose photo is not actually the caller's.

create table if not exists public.progress_photo_shares (
  photo_id  uuid        not null references public.progress_photos(id) on delete cascade,
  coach_id  uuid        not null references public.profiles(id)        on delete cascade,
  client_id uuid        not null references public.profiles(id)        on delete cascade,
  shared_at timestamptz not null default now(),
  primary key (photo_id, coach_id)
);

-- The client's "what can my coach see" read, and the coach's "what did this
-- client send me" read.
create index if not exists idx_pps_client on public.progress_photo_shares (client_id, shared_at desc);
create index if not exists idx_pps_coach  on public.progress_photo_shares (coach_id, client_id, shared_at desc);

-- The object-level predicate resolves storage.objects.name back to a photo
-- row. Without this that is a sequential scan of progress_photos for every
-- object the storage policy is asked about.
create index if not exists idx_progress_photos_image_path on public.progress_photos (image_path);

-- RLS on BEFORE any policy exists. Between this statement and the two policies
-- below the table is closed to everyone, which is the safe direction to be
-- caught halfway through.
alter table public.progress_photo_shares enable row level security;

-- Supabase's default privileges hand new public tables to anon as well as
-- authenticated. anon has no auth.uid() so every policy below is false for it
-- anyway; taking the grant away too means that is true for two reasons.
revoke all on public.progress_photo_shares from anon;
grant select, insert, delete on public.progress_photo_shares to authenticated;


-- ═════════════════════════════════════════════════════════════════════════
-- 2 · Is the coaching relationship live?
-- ═════════════════════════════════════════════════════════════════════════
--
-- The single definition of requirement 4, used by every policy in this file so
-- that "the coach was let go" cannot mean one thing to the row and another to
-- the file. BOTH links required — see the header.
--
-- Definer because it must answer for a (client, coach) pair from whichever of
-- the two sides is asking, and `clients` and `coaching_relationships` each
-- expose only one side to each party. The `auth.uid() in (…)` line is what
-- stops that becoming an oracle: this answers only about a relationship the
-- caller is themselves part of. That test is on auth.uid(), NOT current_user,
-- which inside a definer function would be the owner and would always fail.

create or replace function public.coaching_link_active(p_client uuid, p_coach uuid)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $$
  select
    (select auth.uid()) in (p_client, p_coach)
    and exists (
      select 1 from public.coaching_relationships r
       where r.client_id = p_client and r.coach_id = p_coach and r.status = 'active'
    )
    and exists (
      select 1 from public.clients c
       where c.id = p_client and c.trainer_id = p_coach
    );
$$;

revoke execute on function public.coaching_link_active(uuid, uuid) from public, anon;
grant execute on function public.coaching_link_active(uuid, uuid) to authenticated;


-- ═════════════════════════════════════════════════════════════════════════
-- 3 · The two predicates — one rule, expressed once
-- ═════════════════════════════════════════════════════════════════════════
--
-- Requirement 5 says the row and the file grant separately, and that opening
-- one without the other gives either a broken image or a file with no record
-- of it. They are separate GRANTS below — two policies on two tables in two
-- schemas — but they must never be able to disagree about WHO. So the file
-- predicate is defined in terms of the row predicate: an object is readable
-- if and only if the photo row that names it is readable. Not "the same
-- condition, written twice"; literally the same function, called.

-- Row-level: is this photo one the signed-in viewer was sent, by a client
-- whose coach they still are?
--
-- Reads the grant table directly as the owner rather than through
-- `pps_coach_read`. That is deliberate: it keeps the progress_photos policy
-- from depending on the progress_photo_shares policy, which is how RLS
-- recursion starts. Nothing here reads progress_photos, so nothing here can
-- re-enter the policy that calls it.
create or replace function public.progress_photo_shared_with_viewer(p_photo_id uuid)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $$
  select exists (
    select 1 from public.progress_photo_shares s
     where s.photo_id = p_photo_id
       and s.coach_id = (select auth.uid())
       and public.coaching_link_active(s.client_id, s.coach_id)
  );
$$;

revoke execute on function public.progress_photo_shared_with_viewer(uuid) from public, anon;
grant execute on function public.progress_photo_shared_with_viewer(uuid) to authenticated;


-- Object-level: same question, asked with the storage key instead of the id,
-- because a policy on storage.objects has the name and nothing else.
create or replace function public.progress_photo_object_shared_with_viewer(p_name text)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $$
  select exists (
    select 1 from public.progress_photos p
     where p.image_path = p_name
       and public.progress_photo_shared_with_viewer(p.id)
  );
$$;

revoke execute on function public.progress_photo_object_shared_with_viewer(text) from public, anon;
grant execute on function public.progress_photo_object_shared_with_viewer(text) to authenticated;


-- ═════════════════════════════════════════════════════════════════════════
-- 4 · Policies on the grant table
-- ═════════════════════════════════════════════════════════════════════════

-- The client owns their grants: they can list them, create them and take them
-- back. No UPDATE is granted at all — there is nothing about a grant to amend,
-- and an updatable grant is a grant whose subject could be moved.
--
-- The WITH CHECK is where the honesty of this table is enforced:
--   · client_id is the caller             — you cannot file a grant as someone else
--   · the photo is the caller's own       — you cannot hand out another member's photo
--   · the coach link is live              — you cannot send to a stranger
--   · coach_id is not the caller          — a self-grant is meaningless, and would
--                                           make your own row satisfy the coach policy
--
-- The `exists` on progress_photos is evaluated under that table's own RLS, so
-- it passes only for a row `progress_photos_owner` already lets the caller see.
-- Two independent reasons for the same answer.
drop policy if exists pps_client on public.progress_photo_shares;
create policy pps_client on public.progress_photo_shares for all to authenticated
  using (client_id = (select auth.uid()))
  with check (
    client_id = (select auth.uid())
    and coach_id <> (select auth.uid())
    and exists (
      select 1 from public.progress_photos p
       where p.id = progress_photo_shares.photo_id
         and p.client_id = (select auth.uid())
    )
    and public.coaching_link_active(progress_photo_shares.client_id, progress_photo_shares.coach_id)
  );

-- The coach may read grants addressed to them, and only while they are still
-- the coach. SELECT only: a coach can neither create a grant nor delete one.
-- Taking it back is the client's act alone, so there is no way for a coach to
-- clear the record that they were given access.
drop policy if exists pps_coach_read on public.progress_photo_shares;
create policy pps_coach_read on public.progress_photo_shares for select to authenticated
  using (
    coach_id = (select auth.uid())
    and public.coaching_link_active(progress_photo_shares.client_id, progress_photo_shares.coach_id)
  );


-- ═════════════════════════════════════════════════════════════════════════
-- 5 · LAYER ONE — the row
-- ═════════════════════════════════════════════════════════════════════════
--
-- Added ALONGSIDE `progress_photos_owner`, which is untouched. Permissive
-- policies OR together, so the owner still reaches every one of their rows by
-- the rule 45 wrote, and a coach reaches exactly the rows they were sent.
--
-- FOR SELECT and nothing else. A coach cannot edit or delete a photo they were
-- shown; the sender remains the only person who can change or remove it.
--
-- This does grant the whole row, weight_kg and body_fat_pct included. Those two
-- numbers are already visible to a linked coach through `scans_trainer_read`
-- (19-trainer-read-access.sql), so nothing new is disclosed — but RLS grants
-- rows, not columns, and it is worth having said so out loud.
drop policy if exists progress_photos_shared_read on public.progress_photos;
create policy progress_photos_shared_read on public.progress_photos for select to authenticated
  using (public.progress_photo_shared_with_viewer(progress_photos.id));

-- Still dropped, still on purpose. 45 removed the blanket
-- `progress_photos_trainer_read`; the point of this file is that a coach reads
-- photos because one was SENT, never because of who they are. Re-stated here
-- so that applying 47 cannot be read as the moment it came back.
drop policy if exists progress_photos_trainer_read on public.progress_photos;


-- ═════════════════════════════════════════════════════════════════════════
-- 6 · LAYER TWO — the file
-- ═════════════════════════════════════════════════════════════════════════
--
-- Without this, a coach gets a row carrying `image_path` and a 403 on the
-- bytes: a name for a photo they cannot see, which is worse than either
-- answer. Without §5 and with only this, a coach could fetch bytes with no row
-- to say whose they are or that they were ever given.
--
-- A SEPARATE policy rather than an edit to `photos_obj_read`: 45 owns that one,
-- own-folder access is a different rule with a different reason, and permissive
-- SELECT policies OR. Nobody loses their own folder if this is ever dropped,
-- and dropping this is a complete, single-statement retreat.
--
-- The `bucket_id` test comes first so the predicate is not called for objects
-- in `exercise-videos` or `scans`.
drop policy if exists photos_obj_read_shared on storage.objects;
create policy photos_obj_read_shared on storage.objects for select to authenticated
  using (
    bucket_id = 'photos'
    and public.progress_photo_object_shared_with_viewer(name)
  );


-- ═════════════════════════════════════════════════════════════════════════
-- 7 · Ending the relationship ends the grants
-- ═════════════════════════════════════════════════════════════════════════
--
-- `coaching_link_active()` already means a former coach reads nothing, from
-- the instant either link stops. These triggers are the second half: they
-- remove the grant ROWS, so the client's "what can my coach see" list is not
-- carrying entries that no longer mean anything. Requirement 3 says no ambient
-- uncertainty, and a list of grants you have to know are dead is exactly that.
--
-- Definer, because the person ending the relationship is often the COACH, and
-- a coach has no right to delete rows the client owns — `pps_client` is keyed
-- on the client. The function tests NOTHING about who is calling: it reads OLD
-- and NEW and nothing else. There is no `current_user` in here, and there must
-- never be one — see the header.
--
-- Deliberately NOT granted to authenticated. It is reachable only as a trigger;
-- a direct call would fail on TG_OP anyway, and least privilege beats symmetry
-- with the house rule for a function nobody is meant to call.

create or replace function public.revoke_photo_shares_on_unlink()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  if TG_TABLE_NAME = 'clients' then
    -- The client's trainer changed. Every outstanding grant was addressed to
    -- the coach they had; none of them survives the change, and the incoming
    -- coach starts with nothing. Photos are not part of the handover.
    delete from public.progress_photo_shares where client_id = OLD.id;

  elsif TG_OP = 'DELETE' then
    delete from public.progress_photo_shares
     where client_id = OLD.client_id and coach_id = OLD.coach_id;

  elsif NEW.status <> 'active' then
    -- 'ended', and also 'pending' — a relationship put back to pending is not
    -- one that should still be showing somebody's body.
    delete from public.progress_photo_shares
     where client_id = NEW.client_id and coach_id = NEW.coach_id;
  end if;
  return null;
end $$;

revoke execute on function public.revoke_photo_shares_on_unlink() from public, anon, authenticated;

drop trigger if exists on_coaching_unlink_revoke_photo_shares on public.coaching_relationships;
create trigger on_coaching_unlink_revoke_photo_shares
  after update or delete on public.coaching_relationships
  for each row execute function public.revoke_photo_shares_on_unlink();

drop trigger if exists on_trainer_change_revoke_photo_shares on public.clients;
create trigger on_trainer_change_revoke_photo_shares
  after update of trainer_id on public.clients
  for each row when (NEW.trainer_id is distinct from OLD.trainer_id)
  execute function public.revoke_photo_shares_on_unlink();


-- ═════════════════════════════════════════════════════════════════════════
-- 8 · The purge queue still owns deletion
-- ═════════════════════════════════════════════════════════════════════════
--
-- Nothing above touches it, and that is checked rather than assumed.
--
-- `progress_photo_shares.photo_id … on delete cascade` means deleting a SHARED
-- photo deletes its grants as part of the same statement. The order is the
-- thing that matters: referential-integrity cascades run as the statement
-- proceeds, and `on_progress_photo_delete` is an AFTER DELETE row trigger on
-- progress_photos, so it fires for the photo row regardless of what the cascade
-- did to the child. The path still reaches `photo_purge`, and the file is still
-- purged — for a single delete and for the account-deletion cascade alike.
--
-- The share row is a GRANT, not a record of bytes, so unlike photo_purge it is
-- right for it to die with the photo, the client and the coach. It carries no
-- storage path and there is nothing about it that has to outlive anything.
--
-- The assertion below is the same class as §0: it fails loudly at apply time if
-- a future edit ever removes the trigger this feature quietly depends on.

do $$
begin
  if not exists (
    select 1 from pg_trigger
    where tgrelid = 'public.progress_photos'::regclass
      and tgname = 'on_progress_photo_delete'
      and not tgisinternal
  ) then
    raise exception 'on_progress_photo_delete is missing from progress_photos — deleting a photo would leave its file in storage with nothing holding the path (see 45-progress-photos.sql).';
  end if;
end $$;

-- ▶ photo-purge-schedule.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Actually drain the photo purge queue.
--
-- 45-progress-photos.sql built the queue and the sender; 47 made photos
-- shareable. What neither did is RUN it. Until now the only thing that called
-- purge_progress_photo_files() was a person typing it into the SQL editor.
--
-- That gap is not cosmetic. Deleting a progress photo removes the row
-- immediately and records the file's path; the FILE goes only when the queue is
-- drained. So without a schedule, a member deletes a photo of themselves, the
-- app truthfully says it is gone from their account, and the image sits in
-- storage indefinitely. web/delete-account.html promises the file is chased and
-- confirmed. A promise nobody executes is the same class of fault as
-- request_account_deletion() writing a timestamp that nothing ever read.
--
-- WHY A CRON JOB RATHER THAN DOING IT INLINE. The delete cannot remove the file
-- itself: storage.objects carries Supabase's protect_objects_delete trigger,
-- which refuses direct deletion and says to use the Storage API. That means an
-- HTTP call, and an HTTP call inside the transaction that deletes a member's
-- account would make erasure depend on the storage service answering. It must
-- not: the row deletion has to succeed even when storage is down, with the file
-- chased afterwards. pg_net posts asynchronously and the queue remembers.
--
-- EVERY FIVE MINUTES, not every minute. A purge is a DELETE against a file
-- nobody can reach any more — the row is already gone and both the row policy
-- and the storage policy read from it. Minutes of latency cost nothing, and the
-- queue holds each path until storage confirms, so a missed run is picked up by
-- the next one rather than losing the file forever.
--
-- The drain is idempotent by construction: purge_photo_file() returns
-- immediately for any path already marked purged, and DELETE of an absent
-- object is itself idempotent, which is why an already-absent file is a
-- success rather than an error.
-- ─────────────────────────────────────────────────────────────────────────

create extension if not exists pg_cron;

-- Unschedule first so re-running this file does not accumulate duplicate jobs
-- each firing the same drain.
do $$
begin
  if exists (select 1 from cron.job where jobname = 'purge-progress-photo-files') then
    perform cron.unschedule('purge-progress-photo-files');
  end if;
end $$;

select cron.schedule(
  'purge-progress-photo-files',
  '*/5 * * * *',
  $cron$ select public.purge_progress_photo_files(); $cron$
);

-- The job runs as the table owner, so nothing here widens what a signed-in
-- person can reach. purge_progress_photo_files is already revoked from public
-- and anon by 45-progress-photos.sql.

-- ▶ exercise-video-library.sql

-- ── Exercise videos: a library that survives the phone it was recorded on ───
--
-- The trainer video library has never once written a row. `exercise_videos`
-- declares `exercise_id text not null references exercises(id)` and `title text
-- not null`; the app inserts `{trainer_id, name, muscle_group, url}` and
-- supplies neither. Postgres refused every insert with 23502, supabase-js
-- returned that as `{ data: null, error }` rather than throwing, and the catch
-- in src/ui/exerciseVideos.ts fell through to an AsyncStorage-only entry. So a
-- trainer recorded a clip, watched it appear in their library, and lost it on
-- the next device — while the screen said "Added". The live table today holds
-- zero rows and the bucket holds zero files, which is the proof: the remote
-- path has never worked, and nothing here can lose data that was never stored.
--
-- Three things had to be true before this could be fixed rather than patched.
--
-- 1 · An exercise had to become a thing, not a spelling. `exercises` has been
--     in the schema since 01 and has never held a single row; the app names an
--     exercise with a free-text display string and joins video to exercise with
--     a bidirectional substring match at render time, so "Squat" matches
--     whichever of Back, Front or Goblet Squat happens to sort first. This
--     seeds the catalogue from the three vocabularies the app already ships
--     (the builder's picker, focus.ts, machines.ts), deduped on a slug, and
--     lets a trainer's custom movement mint its own slug on demand. The
--     NOT NULLs are then satisfiable rather than in the way, so they stay.
--
-- 2 · The bucket had to stop being public. `exercise-videos` was created by
--     hand in the dashboard, written down nowhere, and marked public — so a
--     clip of a named trainer demonstrating an exercise was readable by anyone
--     who ever saw the URL, whatever the table's policies said. It is declared
--     here and flipped to private; `video_path` (the column 01 defined and
--     nothing ever wrote) becomes the durable handle, and the app signs a
--     short-lived URL when someone is actually allowed to watch. `url` stays
--     for the other case: a link to a video hosted somewhere else entirely.
--
-- 3 · Visibility had to be the trainer's decision. 38-tenant-isolation.sql
--     opened SELECT to every authenticated user on the reasoning that "exercise
--     demos are content, not customer data", and 39-owner-policy-scope.sql then
--     declined to narrow it from a later file, saying the change "belongs in 38
--     next to its own reasoning". This file argues with that paragraph directly,
--     so here is the argument: it is true of a stock demo of a barbell row and
--     false of a clip with a named coach in it, and the table cannot tell them
--     apart because nobody ever asked. Now it asks. `visibility` carries the
--     answer per clip — private, this trainer's clients, the whole gym, or
--     genuinely public — plus an explicit grant list for "this person, this
--     clip". A platform clip with no trainer behind it is public by default,
--     which preserves 38's intent for exactly the content 38 was describing.
-- ───────────────────────────────────────────────────────────────────────────

-- ── 1 · The exercise catalogue ─────────────────────────────────────────────
-- Slug rule, mirrored exactly by exerciseSlug() in src/lib/exerciseId.ts:
-- lowercase, every run of non-alphanumerics becomes a single hyphen, trimmed.
-- 'Back Squat' → 'back-squat', 'Push-up' → 'push-up'. It is what collapses
-- 'Bent-over Row' and 'Bent-Over Row' into one row rather than two movements.

insert into public.exercises (id, name, muscle_group, is_cardio) values
  ('ab-crunch', 'Ab Crunch', 'Core', false),
  ('air-bike', 'Air Bike', 'Full body', true),
  ('assisted-pull-up', 'Assisted Pull-up', 'Back', false),
  ('back-extension', 'Back Extension', 'Lower back', false),
  ('back-squat', 'Back Squat', 'Legs', false),
  ('barbell-curl', 'Barbell Curl', 'Arms', false),
  ('bench-press', 'Bench Press', 'Chest', false),
  ('bent-over-row', 'Bent-over Row', 'Back', false),
  ('bicep-curl', 'Bicep Curl', 'Arms', false),
  ('bulgarian-split-squat', 'Bulgarian Split Squat', 'Legs', false),
  ('cable-crossover', 'Cable Crossover', 'Chest', false),
  ('cable-crunch', 'Cable Crunch', 'Core', false),
  ('cable-kickback', 'Cable Kickback', 'Glutes', false),
  ('cable-machine', 'Cable Machine', 'Full body', false),
  ('calf-raise', 'Calf Raise', 'Calves', false),
  ('chest-press', 'Chest Press', 'Chest', false),
  ('deadlift', 'Deadlift', 'Back', false),
  ('elliptical', 'Elliptical', 'Full body', true),
  ('face-pull', 'Face Pull', 'Shoulders', false),
  ('front-squat', 'Front Squat', 'Legs', false),
  ('glute-bridge', 'Glute Bridge', 'Glutes', false),
  ('good-morning', 'Good Morning', 'Hamstrings', false),
  ('hack-squat', 'Hack Squat', 'Legs', false),
  ('hammer-curl', 'Hammer Curl', 'Arms', false),
  ('hanging-leg-raise', 'Hanging Leg Raise', 'Core', false),
  ('hip-abduction', 'Hip Abduction', 'Glutes', false),
  ('hip-thrust', 'Hip Thrust', 'Glutes', false),
  ('incline-dumbbell-press', 'Incline Dumbbell Press', 'Chest', false),
  ('lat-pulldown', 'Lat Pulldown', 'Back', false),
  ('lateral-raise', 'Lateral Raise', 'Shoulders', false),
  ('leg-curl', 'Leg Curl', 'Hamstrings', false),
  ('leg-extension', 'Leg Extension', 'Legs', false),
  ('leg-press', 'Leg Press', 'Legs', false),
  ('nordic-curl', 'Nordic Curl', 'Hamstrings', false),
  ('overhead-press', 'Overhead Press', 'Shoulders', false),
  ('overhead-tricep-extension', 'Overhead Tricep Extension', 'Arms', false),
  ('pec-deck', 'Pec Deck', 'Chest', false),
  ('plank', 'Plank', 'Core', false),
  ('pull-up', 'Pull-up', 'Back', false),
  ('push-up', 'Push-up', 'Chest', false),
  ('rear-delt-fly', 'Rear Delt Fly', 'Shoulders', false),
  ('romanian-deadlift', 'Romanian Deadlift', 'Hamstrings', false),
  ('rowing-machine', 'Rowing Machine', 'Full body', true),
  ('russian-twist', 'Russian Twist', 'Core', false),
  ('seated-calf-raise', 'Seated Calf Raise', 'Calves', false),
  ('seated-row', 'Seated Row', 'Back', false),
  ('shoulder-press', 'Shoulder Press', 'Shoulders', false),
  ('ski-erg', 'Ski Erg', 'Full body', true),
  ('smith-machine', 'Smith Machine', 'Full body', false),
  ('stair-climber', 'Stair Climber', 'Legs', true),
  ('standing-calf-raise', 'Standing Calf Raise', 'Calves', false),
  ('treadmill', 'Treadmill', 'Legs', true),
  ('tricep-pushdown', 'Tricep Pushdown', 'Arms', false),
  ('triceps-pushdown', 'Triceps Pushdown', 'Arms', false),
  ('upright-bike', 'Upright Bike', 'Legs', true),
  ('walking-lunge', 'Walking Lunge', 'Legs', false)
on conflict (id) do nothing;

-- The catalogue had no row-level security at all, which — per 38's own third
-- section — means the policies it never had were not the problem: the anon key
-- is compiled into the shipped app, so the table was world-writable. Reading is
-- open to anyone signed in, because a catalogue is only useful if everyone
-- resolves the same slug to the same movement. Writing is how a trainer's
-- custom exercise gets a durable id, so it is open to staff and closed to
-- clients. Nothing here can be deleted through the API.
alter table public.exercises enable row level security;

drop policy if exists exercises_read on public.exercises;
create policy exercises_read on public.exercises for select
  to authenticated using (true);

drop policy if exists exercises_staff_w on public.exercises;
create policy exercises_staff_w on public.exercises for insert
  to authenticated with check (my_role() in ('trainer', 'owner'));

-- ── 2 · Reconciling exercise_videos with what the app actually writes ──────
-- name, muscle_group and url exist in the live database and in no SQL file in
-- this repo — added by hand at some point and never written down. Declaring
-- them here is what stops the next person reading 01-schema.sql and believing
-- the table is something it is not. `title` and `exercise_id` keep their NOT
-- NULL: section 1 is what makes them answerable.
alter table public.exercise_videos add column if not exists name         text;
alter table public.exercise_videos add column if not exists muscle_group text;
alter table public.exercise_videos add column if not exists url          text;

-- Who may watch this clip. Default 'clients': a coach who records a demo means
-- it for the people they coach, and a default that silently published it to the
-- platform would be the wrong way round to be wrong.
alter table public.exercise_videos add column if not exists visibility text not null default 'clients';

alter table public.exercise_videos drop constraint if exists exercise_videos_visibility_chk;
alter table public.exercise_videos add constraint exercise_videos_visibility_chk
  check (visibility in ('private', 'clients', 'gym', 'public'));

create index if not exists idx_exercise_videos_exercise on public.exercise_videos(exercise_id);
create index if not exists idx_exercise_videos_trainer  on public.exercise_videos(trainer_id);

-- ── 3 · "Whoever the trainer gives permissions to" ─────────────────────────
-- The four visibility levels answer the common cases; this answers the precise
-- one. A row here is a named person the trainer handed one clip to, and it is
-- additive only — it can widen who sees a private clip and can never narrow a
-- public one.
create table if not exists public.exercise_video_grants (
  video_id   uuid not null references public.exercise_videos(id) on delete cascade,
  client_id  uuid not null references public.profiles(id) on delete cascade,
  granted_at timestamptz not null default now(),
  primary key (video_id, client_id)
);
create index if not exists idx_exvid_grants_client on public.exercise_video_grants(client_id);

alter table public.exercise_video_grants enable row level security;

-- The trainer who owns the clip manages its grants. The join to exercise_videos
-- is safe to write inline for the same reason 39 gives for its trainers join:
-- exvid_trainer_rw already lets that trainer read the row this asks about.
drop policy if exists exvid_grants_trainer_rw on public.exercise_video_grants;
create policy exvid_grants_trainer_rw on public.exercise_video_grants for all
  using (exists (select 1 from public.exercise_videos v
                  where v.id = exercise_video_grants.video_id and v.trainer_id = (select auth.uid())))
  with check (exists (select 1 from public.exercise_videos v
                  where v.id = exercise_video_grants.video_id and v.trainer_id = (select auth.uid())));

-- A person may see that they were given something.
drop policy if exists exvid_grants_client_r on public.exercise_video_grants;
create policy exvid_grants_client_r on public.exercise_video_grants for select
  using (client_id = (select auth.uid()));

-- ── 4 · The read rule ──────────────────────────────────────────────────────
-- Replaces 38's `using (true)`. Each arm is one sentence of the product rule,
-- in the order a person would say them.
drop policy if exists exvid_read on public.exercise_videos;
create policy exvid_read on public.exercise_videos for select to authenticated using (
  -- the trainer's own clip, whatever it is set to
  trainer_id = (select auth.uid())
  -- a platform clip belonging to no trainer, which is what 38 meant by content
  or (trainer_id is null and visibility in ('public', 'clients', 'gym'))
  -- anything a trainer deliberately published
  or visibility = 'public'
  -- their own coach's clip, the ordinary case
  or (visibility = 'clients' and exists (
        select 1 from public.clients c
         where c.id = (select auth.uid()) and c.trainer_id = exercise_videos.trainer_id))
  -- shared with the whole gym: any member or staff of the tenant that trainer is in
  or (visibility = 'gym' and exists (
        select 1 from public.trainers tr
         where tr.id = exercise_videos.trainer_id and tr.tenant_id = my_tenant()))
  -- handed to this person by name, which can reach even a private clip
  or exists (select 1 from public.exercise_video_grants g
              where g.video_id = exercise_videos.id and g.client_id = (select auth.uid()))
  -- the owner of the gym the trainer belongs to
  or exists (select 1 from public.trainers tr
              where tr.id = exercise_videos.trainer_id and is_owner_of(tr.tenant_id))
);

-- ── 5 · The bucket, and the file behind the row ────────────────────────────
-- Declared here because it was not declared anywhere. Private: a signed URL is
-- what carries permission to the player, so the table's rule above is the only
-- way in rather than a suggestion sitting in front of a public URL.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('exercise-videos', 'exercise-videos', false, 524288000,
        array['video/mp4', 'video/quicktime', 'video/webm'])
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Whether the caller may watch the file at this storage path.
--
-- Deliberately SECURITY INVOKER — the opposite of the usual advice in this
-- schema, and for a reason worth stating. Running as the caller means the
-- select inside it is filtered by exvid_read above, so the storage rule cannot
-- drift away from the table rule: there is exactly one definition of who may
-- watch a clip, and this asks it rather than restating it. There is no
-- recursion hazard because exercise_videos' policy never reads storage.
create or replace function public.can_watch_exercise_video(p_path text)
returns boolean language sql stable security invoker set search_path to 'public'
as $function$
  select exists (select 1 from public.exercise_videos v where v.video_path = p_path);
$function$;

revoke execute on function public.can_watch_exercise_video(text) from public, anon;
grant execute on function public.can_watch_exercise_video(text) to authenticated;

-- A trainer owns the folder named after them; nobody writes into anyone else's.
-- This is the convention the upload code already follows: `${uid}/${epoch}.mp4`.
drop policy if exists exvid_object_w on storage.objects;
create policy exvid_object_w on storage.objects for insert to authenticated
  with check (bucket_id = 'exercise-videos'
              and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists exvid_object_u on storage.objects;
create policy exvid_object_u on storage.objects for update to authenticated
  using (bucket_id = 'exercise-videos'
         and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists exvid_object_d on storage.objects;
create policy exvid_object_d on storage.objects for delete to authenticated
  using (bucket_id = 'exercise-videos'
         and (storage.foldername(name))[1] = (select auth.uid())::text);

-- Reading is whatever the table said.
drop policy if exists exvid_object_r on storage.objects;
create policy exvid_object_r on storage.objects for select to authenticated
  using (bucket_id = 'exercise-videos' and public.can_watch_exercise_video(name));

-- ▶ interventions.sql

-- ── The intervention loop ───────────────────────────────────────────────────
--
-- Phase 4. Retention already SURFACES who is drifting, in three places: the
-- Studio retention roll-up, the Studio members screen and the coach's client
-- book. All three read the same model — `assessDrift` in clientDrift.ts, a
-- break in a person's OWN pattern rather than a level — so they name the same
-- member. What none of them could do was close the loop.
--
-- There was nowhere to record that anybody was contacted. So the gym surfaced
-- the same person every Monday, two staff rang them in the same week, and no
-- one could ever say whether anything the gym does makes a difference. This
-- table is the missing half.
--
-- Additive only. Nothing here alters an existing table.
--
-- ── WHAT THIS TABLE IS NOT, AND WHY THAT IS THE DESIGN ──────────────────────
--
-- 1. IT IS NOT ATTENDANCE. A phone call is not a training session. Nothing in
--    this table is ever read as a sign of life: `activityFor` in gymRetention
--    .ts builds its events from visits, ticked-off class bookings and delivered
--    one-to-ones, and this table is deliberately not one of the four parts a
--    `RetentionRecord` carries. If logging a call nudged a member's drift
--    verdict toward healthy, the loop would report its own activity back to the
--    gym as retention — the tool would get better at looking useful in exactly
--    the moment it stopped being useful. src/lib/interventions.ts takes a
--    finished `Drift` as INPUT and never contributes to one.
--
-- 2. IT IS NOT A SCOREBOARD. There is no `worked boolean` column, and there
--    will not be one, because nobody at the desk can know. A member who came
--    back may have come back anyway; a member who left may have left despite a
--    good call. What the record can honestly carry is what was TRIED (below)
--    and what FOLLOWED (computed, in interventions.ts, from the member's own
--    attendance either side of the contact — a sequence, never a cause). The
--    one column that comes close, `outcome`, is about the CONVERSATION — did
--    anybody actually pick up — and is not about whether the member returned.
--
-- 3. IT IS NOT A REMINDER LIST. `at` is when the contact HAPPENED. A row for a
--    call somebody intends to make on Thursday is a plan, and a plan recorded
--    as a contact would start the measurement window on a day nothing occurred.
--    The trigger below refuses a future `at` outright.
--
-- ── WHY `at` AND `created_at` ARE BOTH HERE ─────────────────────────────────
--
-- `at` is when the person was contacted; `created_at` is when somebody typed it
-- in. They differ whenever a call is written up later, which is most of them.
-- Every window in interventions.ts hangs off `at`, and keeping `created_at`
-- separate means a backfilled fortnight of calls is visible as a backfill
-- rather than looking like a fortnight of diligent same-day logging.
--
-- ── MEMBER ACCESS: DELIBERATELY NONE, AND THAT IS NOT SETTLED ───────────────
--
-- There is no member SELECT policy below. `gym_visits` has one, on the stated
-- grounds that "when did I actually come in" is the member's record too — this
-- is a different kind of row. These are staff notes ABOUT a person ("said the
-- 6am is too early, offered the 7:15"), and a note the subject can read is a
-- note that stops being written honestly, which would empty the one column
-- that keeps a second caller from repeating the first one's call.
--
-- That is a product decision, not a legal one, and it should be flagged rather
-- than quietly inherited: this is personal data about an identified person, so
-- a subject access request covers it whatever the policy says. `src/lib/gdpr.ts`
-- builds the member's own export and does NOT include this table. Somebody has
-- to decide whether it should — this comment exists so that decision is made on
-- purpose instead of by omission.

create table if not exists member_interventions (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  -- Cascade, matching `memberships`: when a member's account is deleted the
  -- notes somebody wrote about them go with it. An intervention row that
  -- outlived its subject would be a retained note about a deleted person.
  member_id uuid not null references profiles(id) on delete cascade,

  -- When the contact happened. Not defaulted to now() on purpose: a value
  -- somebody had to supply is a value somebody had to think about, and the
  -- application sends the real time. See the trigger for the future guard.
  at timestamptz not null,

  -- HOW. Closed enough to count, loose enough to be true. 'other' exists so
  -- nobody files a conversation in the car park under 'call'.
  channel text not null
    check (channel in ('call','text','email','whatsapp','app_message','in_person','other')),

  -- WHO. `on delete set null` rather than cascade: a trainer leaving must not
  -- erase the record that the call was made. `by_name` is denormalised for
  -- exactly that moment — once the profile is gone, the id is a dead uuid and
  -- the name written down at the time is the only thing left that answers
  -- "has anybody already spoken to her?".
  by_id uuid references profiles(id) on delete set null,
  by_name text,

  -- WHAT CAME OF THE CONTACT ITSELF — not of the member. 'reached' means a
  -- human answered, nothing more. The default is 'unknown' rather than
  -- 'reached' because a row nobody finished filling in must not assert that
  -- somebody was spoken to.
  --
  -- 'bounced' earns its place: a dead number or a hard-bouncing address is a
  -- finding about the gym's own records, and it is invisible if it is filed
  -- under 'no_answer'.
  outcome text not null default 'unknown'
    check (outcome in ('reached','replied','no_answer','left_message','bounced','declined','unknown')),

  -- WHAT WAS SAID. The whole reason two people do not make the same call.
  note text,

  created_at timestamptz not null default now()
);

-- The two directions this is read: one gym's recent interventions (the Studio
-- panel, and the quietening pass over the surfaced list), and one member's
-- history (the row detail, and every follow-up window, which walks a member's
-- contacts in order to find where the next one truncates the last).
create index if not exists idx_member_interventions_tenant
  on member_interventions(tenant_id, at desc);
create index if not exists idx_member_interventions_member
  on member_interventions(member_id, at desc);

-- NOT ENFORCED, deliberately: a uniqueness rule on (member_id, at). Two staff
-- genuinely can contact the same member on the same day — that is the duplicate
-- effort this table exists to make visible, and a constraint would hide it by
-- refusing the second row. interventions.ts surfaces it instead: a second
-- contact inside the first one's judgement window makes that window
-- unjudgeable, and says so.


-- ── the integrity trigger ───────────────────────────────────────────────────
--
-- NOT `security definer`, and that is the point rather than an oversight.
--
-- 38-tenant-isolation.sql's `guard_profile_identity` tests `current_user` to
-- tell an app request ('authenticated'/'anon') from a definer function running
-- as its owner. That test only works because the function is an ORDINARY one:
-- inside a `security definer` function `current_user` is the function's OWNER,
-- so the same guard would compare 'postgres' against 'authenticated', never
-- fire, and read like protection while providing none. That bug shipped in this
-- codebase, so it is written down where the next trigger gets copied from.
--
-- This function does not need to know who the caller is at all. Every rule
-- below is about the ROW, and authorisation lives in the policies underneath.
-- It stays an invoker function so that it cannot acquire a privilege it has no
-- use for.
create or replace function public.guard_member_intervention()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  -- A contact cannot have happened in the future. A few minutes of slack for a
  -- browser clock that is ahead of the database; beyond that it is a plan, a
  -- typo, or a timezone bug, and all three would open a measurement window over
  -- days that have not happened yet.
  if new.at > now() + interval '5 minutes' then
    raise exception 'An intervention is a record of a contact that happened, not one that is planned. "%" is in the future.', new.at
      using errcode = '22007';
  end if;

  if TG_OP = 'UPDATE' then
    -- `at` and `member_id` are the two columns every follow-up window hangs
    -- off. Letting them move re-dates conclusions that were already drawn and
    -- reported, silently. Correcting the note or the outcome is ordinary
    -- write-up; moving the contact to a different person or a different week is
    -- rewriting history, and the way to do that is to delete the row and log
    -- the real one — which leaves the deletion where an owner can see it.
    if new.member_id is distinct from old.member_id then
      raise exception 'An intervention cannot be moved to a different member. Delete it and log the one that actually happened.'
        using errcode = '42501';
    end if;
    if new.at is distinct from old.at then
      raise exception 'When a contact happened is not editable — every "did it work?" window is measured from it. Delete it and log the one that actually happened.'
        using errcode = '42501';
    end if;
    if new.tenant_id is distinct from old.tenant_id then
      raise exception 'An intervention cannot be moved between gyms.'
        using errcode = '42501';
    end if;
  end if;

  return new;
end $$;

drop trigger if exists guard_member_intervention_t on public.member_interventions;
create trigger guard_member_intervention_t
  before insert or update on public.member_interventions
  for each row execute function public.guard_member_intervention();


-- ── row-level security ──────────────────────────────────────────────────────
--
-- Enabled BEFORE any policy is written. A policy on a table with RLS off is
-- inert: Postgres never consults it and Supabase's default grants to anon and
-- authenticated apply in full — the exact shape that left four tables
-- world-writable until 38-tenant-isolation.sql. The anon key ships inside the
-- mobile bundle, so "inert" here would mean these notes were public.
--
-- The helpers are SECURITY DEFINER, so a policy calling them does not re-enter
-- the table it protects (28-fix-profiles-recursion.sql).
alter table member_interventions enable row level security;

-- The owner's table: they read the whole gym's loop and they are the only role
-- that may correct or remove a row.
--
-- Note that this `for all` does NOT carry the `by_id = auth.uid()` check the
-- trainer insert below does, and RLS takes the most permissive matching policy
-- — so an owner may file a contact under another name. That is deliberate and
-- narrow: the person at the desk on a Saturday often has no account of their
-- own, and the owner writing up "Priya rang her" is the only way that call gets
-- recorded at all. It is stated here so it is a decision rather than a gap
-- somebody finds later.
drop policy if exists member_interventions_owner on member_interventions;
create policy member_interventions_owner on member_interventions
  for all using (is_owner_of(tenant_id)) with check (is_owner_of(tenant_id));

-- Trainers READ the whole gym's interventions. This is the point of the table:
-- a trainer about to ring a client has to be able to see that the desk rang
-- them on Tuesday. Scoped to their own gym via my_tenant(), never to "is a
-- trainer somewhere" — the mistake 39-owner-policy-scope.sql exists to undo.
drop policy if exists member_interventions_staff_r on member_interventions;
create policy member_interventions_staff_r on member_interventions
  for select using (tenant_id = my_tenant() and my_role() in ('trainer','owner'));

-- Trainers LOG their own. `by_id = auth.uid()` is enforced in the check rather
-- than trusted from the client: without it a trainer could file a call under a
-- colleague's name, and "who has already tried" — the one thing that stops the
-- second call — would be unreliable exactly where it matters.
drop policy if exists member_interventions_staff_w on member_interventions;
create policy member_interventions_staff_w on member_interventions
  for insert with check (
    tenant_id = my_tenant()
    and my_role() in ('trainer','owner')
    and by_id = (select auth.uid())
  );

-- Supabase's default privileges hand SELECT/INSERT/UPDATE/DELETE on every new
-- public table to BOTH `anon` and `authenticated` — verified on this table in a
-- rolled-back transaction, not assumed. RLS above is what actually stops an
-- anonymous caller, and it does: none of the three policies can be satisfied
-- without a signed-in profile. This revoke is belt and braces on top of it.
--
-- It is worth having because the anon key is compiled into the shipped mobile
-- app, and because these rows are free-text staff notes about named people —
-- the highest-consequence thing on this page to get wrong. Nothing in any of
-- the three apps reads this table as `anon`.
--
-- Note that the sibling tables (gym_visits, memberships, …) do NOT carry this
-- and rely on RLS alone. That is not an inconsistency to copy back over them
-- blindly; it is one table taking a second lock because of what it holds.
revoke all on table public.member_interventions from anon;

-- No trainer UPDATE and no trainer DELETE, deliberately. A log its own author
-- can rewrite or remove is not a record — the value of "somebody already called
-- her on Tuesday" is that it cannot quietly stop being true. Owners can, and an
-- owner editing their gym's own record is the accountable case.

-- No member policy. See the header: this is a product decision with a subject
-- access consequence that has not been settled.

-- No functions are added here beyond the trigger function, which is reached by
-- the trigger rather than called, so nothing needs the revoke-from-PUBLIC
-- treatment 40-function-grants.sql applies. If a callable function is ever
-- added to this file, re-run that part: Postgres grants EXECUTE to PUBLIC by
-- default on every new function and `anon` resolves through PUBLIC, so
-- `revoke ... from anon` alone accomplishes nothing — it must name PUBLIC and
-- grant back to `authenticated` explicitly.

-- ▶ advisor-tidy.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Clearing the security advisor, and recording which of it mattered.
--
-- Three notices on 27 Aug 2026. None of them was a hole. Written down because
-- the advisor will raise them again for the next person, and "we looked, and
-- here is why it is fine" is worth more on disk than in somebody's memory.
--
-- 1. Nine trigger functions carried EXECUTE for anon and authenticated.
--
--    40-function-grants.sql skips trigger functions on purpose and says why:
--    PostgREST does not expose a function returning `trigger` as an RPC, so
--    there is no route to reach one, and plpgsql refuses to run a trigger
--    function outside a trigger even if there were. The advisor reads the
--    grant rather than the route, so it flags them.
--
--    Revoked here anyway. It costs nothing, and a grant nobody can account for
--    is one somebody later mistakes for deliberate.
--
--    Triggers keep firing. Postgres checks EXECUTE when a trigger is CREATED,
--    not each time it fires, and the proof is already in production:
--    handle_new_user and provision_profile have carried no anon or
--    authenticated grant all along and run on every single signup.
--
-- 2. public.photo_purge has RLS enabled and no policies.
--
--    That already denies everyone except service_role and the SECURITY
--    DEFINER functions that work the queue, which is exactly what this table
--    wants. But the denial is implicit, and an implicit denial reads like an
--    unfinished table — one `create policy` away from somebody "completing"
--    it. Made explicit instead.
--
-- 3. guard_profile_identity has a mutable search_path.
--
--    Worth being accurate about: it is SECURITY INVOKER, not DEFINER. It runs
--    as the caller, so the search_path escalation that makes this dangerous on
--    a DEFINER function does not apply, and its body resolves no tables at all.
--    Set regardless, so every function in the schema answers the same way.
--
-- Idempotent. Safe to re-run, and worth re-running after adding any trigger.
-- ─────────────────────────────────────────────────────────────────────────

-- 1 ── trigger functions are not callable by anyone.
do $$
declare r record;
begin
  for r in
    select p.oid::regprocedure as sig
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.prokind = 'f'
      and pg_get_function_result(p.oid) = 'trigger'
  loop
    execute format('revoke execute on function %s from public', r.sig);
    execute format('revoke execute on function %s from anon', r.sig);
    execute format('revoke execute on function %s from authenticated', r.sig);
  end loop;
end $$;

-- 3 ── and they all pin a search_path, as the rest of the schema does.
do $$
declare r record;
begin
  for r in
    select p.oid::regprocedure as sig
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.prokind = 'f'
      and pg_get_function_result(p.oid) = 'trigger'
      and p.proconfig is null
  loop
    execute format('alter function %s set search_path = public', r.sig);
  end loop;
end $$;

-- 2 ── the purge queue says out loud that it is nobody's to read.
drop policy if exists "photo_purge belongs to the purge job" on public.photo_purge;
create policy "photo_purge belongs to the purge job"
  on public.photo_purge
  for all
  to anon, authenticated
  using (false)
  with check (false);

-- ▶ coach-exercises.sql

-- ─────────────────────────────────────────────────────────────────────────
-- A coach's own exercise names, kept.
--
-- Raised by a tester on 27 Aug 2026: "When saving a new exercise does it save
-- it to the app's catalogue of exercises or just specific to the user saving?"
-- The honest answer was neither. Typing a name into the builder's Add exercise
-- sheet put it in that one program and nowhere else — the client receiving the
-- program saw it, and the coach retyped it the next time.
--
-- Why not the existing `exercises` table: it has no tenant_id and no coach_id.
-- It is a global platform catalogue, currently 56 rows, and the exercise-video
-- library writes to it. Letting the builder write there would put one gym's
-- "Dave's Special Carry" in every other gym's picker. That is a decision about
-- the product, not a place to put a convenience.
--
-- So: per coach, exactly as program_templates already is. A coach's vocabulary
-- is their own, it follows them between gyms, and nobody else sees it.
-- ─────────────────────────────────────────────────────────────────────────

create table if not exists public.coach_exercises (
  coach_id     uuid not null references profiles(id) on delete cascade,
  name         text not null,
  muscle_group text not null default '',
  created_at   timestamptz not null default now(),
  -- Case-insensitive, so "back squat" typed twice is one row, not two entries
  -- a coach then has to look at and wonder about.
  primary key (coach_id, name)
);

create unique index if not exists idx_coach_exercises_ci
  on public.coach_exercises (coach_id, lower(name));

alter table public.coach_exercises enable row level security;

-- A coach reads and writes only their own.
drop policy if exists coach_exercises_self on public.coach_exercises;
create policy coach_exercises_self on public.coach_exercises for all
  using (coach_id = auth.uid()) with check (coach_id = auth.uid());

-- Trigger functions in this schema are not callable; see 51-advisor-tidy.sql.
-- Nothing here adds one, but the grant sweep in 40-function-grants.sql should
-- be re-run after any migration that does.

-- ▶ coach-logged-workouts.sql

-- ─────────────────────────────────────────────────────────────────────────
-- A coach can log the session they just ran, into the client's own record.
--
-- Until now they could not. The policies were:
--
--     workouts_own         ALL     user_id = auth.uid()
--     workouts_coach_read  SELECT  is_my_client(user_id)
--
-- so a coach could read a client's training and never write it. A trainer
-- standing next to somebody through an hour of squats had nowhere to record
-- what was done, and the client's progress, PRs and calories simply missed it.
--
-- ── Who may change what, and why ─────────────────────────────────────────
--
-- The client can DELETE a workout their coach logged. It is their training
-- record and their personal data, and this app already lets them export and
-- erase all of it. Crucially it costs the coach nothing they are paid on:
-- session delivery lives in `sessions` with its own outcome and approval, and
-- nothing here touches that. `workouts` feeds the client's progress; `sessions`
-- feeds payroll. Deleting one does not disturb the other.
--
-- The client can also EDIT it — but never silently. The alternative was
-- considered and is worse: a client who cannot correct "he wrote 8 reps, it was
-- 10" simply deletes the entry and logs their own, so the coach loses the
-- record entirely AND does not know why. A visible amendment beats a silent
-- disappearance. `amended_at` is stamped by the trigger below, and both sides
-- render "Logged by <coach> · amended by you".
--
-- What is genuinely locked is `logged_by`. Who recorded something is not the
-- subject's to rewrite, in either direction — a client cannot erase the
-- attribution, and cannot forge one either.
-- ─────────────────────────────────────────────────────────────────────────

alter table public.workouts
  add column if not exists logged_by  uuid references public.profiles(id) on delete set null,
  add column if not exists amended_at timestamptz;

comment on column public.workouts.logged_by is
  'The coach who recorded this on the client''s behalf. Null means the client logged it themselves.';
comment on column public.workouts.amended_at is
  'Set when the client changed a workout their coach had logged. Null means untouched since.';

-- A coach may insert only for their own client, and only in their own name.
-- `logged_by = auth.uid()` in the CHECK is what stops a coach attributing a
-- workout to somebody else.
drop policy if exists workouts_coach_insert on public.workouts;
create policy workouts_coach_insert on public.workouts for insert
  with check (is_my_client(user_id) and logged_by = auth.uid());

create or replace function public.guard_workout_attribution()
returns trigger language plpgsql
set search_path = public
as $$
begin
  -- Attribution is not editable by anyone through this path.
  if new.logged_by is distinct from old.logged_by then
    raise exception 'Who logged a workout cannot be changed.' using errcode = '42501';
  end if;

  -- auth.uid(), not current_user. This function is SECURITY INVOKER so
  -- current_user would be the connected role ("authenticated") for every
  -- caller alike, which is the trap guard_profile_identity documents.
  if old.logged_by is not null
     and auth.uid() = old.user_id
     and (new.exercise     is distinct from old.exercise
       or new.sets         is distinct from old.sets
       or new.cardio       is distinct from old.cardio
       or new.kcal         is distinct from old.kcal
       or new.performed_at is distinct from old.performed_at)
  then
    new.amended_at := now();
  end if;

  return new;
end $$;

drop trigger if exists guard_workout_attribution_t on public.workouts;
create trigger guard_workout_attribution_t
  before update on public.workouts
  for each row execute function public.guard_workout_attribution();

-- Trigger functions are reachable by nobody; see 51-advisor-tidy.sql.
revoke execute on function public.guard_workout_attribution() from public, anon, authenticated;

-- ▶ video-policy-recursion.sql

-- ─────────────────────────────────────────────────────────────────────────
-- The exercise video library could not be read by anybody. At all.
--
--     ERROR 42P17: infinite recursion detected in policy for relation
--                  "exercise_videos"
--
-- Two policies from 49-exercise-video-library.sql referred to each other:
--
--   exercise_videos.exvid_read (SELECT)
--       … or exists (select 1 from exercise_video_grants g
--                    where g.video_id = id and g.client_id = auth.uid())
--
--   exercise_video_grants.exvid_grants_trainer_rw (ALL — so SELECT too)
--       exists (select 1 from exercise_videos v
--               where v.id = video_id and v.trainer_id = auth.uid())
--
-- Reading a video evaluates the grants policy, which reads videos, which
-- evaluates the grants policy. Postgres detects the loop and refuses the
-- statement, so EVERY read of exercise_videos failed for every signed-in user.
--
-- It never showed as a crash because the app handles the error properly —
-- `useExerciseVideos` reports it and the screens say "your library could not be
-- read", which is exactly right and is what made this look like an empty
-- library rather than a broken one. It was found by inserting an Academy clip
-- and trying to read it back as a member.
--
-- The fix is the standard one: the grants policy asks a SECURITY DEFINER
-- function instead of querying the table under RLS. A definer function does not
-- re-enter the policy, so the cycle is cut. It is the narrowest possible
-- question — "do I own this one video" — and answers nothing else.
-- ─────────────────────────────────────────────────────────────────────────

create or replace function public.owns_exercise_video(p_video uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from public.exercise_videos v
    where v.id = p_video and v.trainer_id = (select auth.uid())
  );
$$;

comment on function public.owns_exercise_video(uuid) is
  'Whether the caller owns this clip. SECURITY DEFINER on purpose: called from '
  'the exercise_video_grants policy, and a plain query there re-enters the '
  'exercise_videos policy and recurses. See 54-video-policy-recursion.sql.';

drop policy if exists exvid_grants_trainer_rw on public.exercise_video_grants;
create policy exvid_grants_trainer_rw on public.exercise_video_grants for all
  using (public.owns_exercise_video(video_id))
  with check (public.owns_exercise_video(video_id));

-- Callable by signed-in users because a policy is evaluated as the querying
-- role. anon has no business asking.
revoke execute on function public.owns_exercise_video(uuid) from public, anon;
grant execute on function public.owns_exercise_video(uuid) to authenticated;

-- ▶ coach-join-code.sql

-- ─────────────────────────────────────────────────────────────────────────
-- A code a coach can say out loud, so joining does not depend on spelling.
--
-- ── The failure this removes ─────────────────────────────────────────────
--
-- Coach → client invitations are matched on the email address the coach typed:
--
--     select * from coach_invites where email ilike <the client's email>
--
-- Case-insensitive, and otherwise exact. A coach who types gloria@gmail.com
-- for gloria.smith@gmail.com creates an invitation that NEITHER PARTY CAN EVER
-- SEE. The coach's screen shows it pending, so it looks sent. The client's
-- screen shows nothing, because nothing addressed to them exists. There is no
-- error, nobody is told, and no amount of retrying from either side fixes it —
-- the two are looking at different strings.
--
-- It also cannot work before the client has an account, which is the ordinary
-- case: the coach signs somebody up in the gym, on the spot.
--
-- ── Why a code ───────────────────────────────────────────────────────────
--
-- The David Lloyd app asks a joining member for a membership number and says
-- where to find it, with "I don't have a membership number" underneath leading
-- to a real free tier. The shape is what matters: a short token the club issues
-- and the member types, so identity is established by something the member
-- HOLDS rather than by two people independently spelling the same address.
--
-- The client already has the browse-and-request path (the trainer directory),
-- which is the "I don't have one" branch. What was missing is the direct one,
-- for the far commoner case where the two people are standing next to each
-- other and already know it.
--
-- The alphabet excludes O, 0, I and 1. Codes get read aloud across a gym floor.
-- ─────────────────────────────────────────────────────────────────────────

alter table public.trainers
  add column if not exists join_code text;

comment on column public.trainers.join_code is
  'Short code a coach shares so a client can join without either side typing an email address.';

-- Case-insensitively unique: the lookup below folds case, so two coaches
-- holding "K7M2QX" and "k7m2qx" would make it ambiguous.
create unique index if not exists trainers_join_code_uniq
  on public.trainers (upper(join_code)) where join_code is not null;

/**
 * Six characters from a 32-character alphabet — 32^6, about 1.07 billion codes.
 *
 * (An earlier version of this comment said 30 letters and 730 million. Counted:
 * 24 letters, I and O excluded, plus the digits 2-9.)
 *
 * Generated server-side, never by the app: a client that picks its own would
 * race another client picking the same one, and the retry loop below is only
 * correct when one writer owns the whole read-check-write.
 */
create or replace function public.generate_join_code()
returns text language plpgsql security definer set search_path = public as $$
declare
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  candidate text;
  tries int := 0;
begin
  loop
    candidate := '';
    for i in 1..6 loop
      candidate := candidate || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    end loop;
    -- Collision is vanishingly unlikely and still has to be handled: a
    -- duplicate would raise on the unique index and lose the caller's code.
    exit when not exists (select 1 from public.trainers t where upper(t.join_code) = candidate);
    tries := tries + 1;
    if tries > 20 then
      raise exception 'could not allocate a unique join code';
    end if;
  end loop;
  return candidate;
end; $$;

/** The signed-in coach's code, allocated on first ask and stable thereafter. */
create or replace function public.my_join_code()
returns text language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  code text;
begin
  if uid is null then
    raise exception 'not signed in';
  end if;
  select join_code into code from public.trainers where id = uid;
  if code is not null then
    return code;
  end if;
  -- No row at all means this account is not a trainer. Say so rather than
  -- silently handing back null, which the app would render as a blank code
  -- for somebody to read out.
  if not found then
    raise exception 'no trainer profile for this account';
  end if;
  code := public.generate_join_code();
  update public.trainers set join_code = code where id = uid;
  return code;
end; $$;

/**
 * Join a coach by their code.
 *
 * Returns the coach's name so the client sees WHO they just asked for — a
 * mistyped code that happens to hit a real coach must be visible immediately,
 * not discovered when a stranger accepts.
 *
 * SECURITY DEFINER because the client cannot read `trainers` rows for coaches
 * they have no relationship with, which is the whole point of the code. It
 * discloses one name for one exact six-character match and nothing else; a
 * wrong code is indistinguishable from an unused one.
 */
create or replace function public.join_by_code(p_code text)
returns table (trainer_id uuid, trainer_name text, already boolean)
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  t_id uuid;
  t_name text;
  existing boolean;
begin
  if uid is null then
    raise exception 'not signed in';
  end if;

  select tr.id into t_id
  from public.trainers tr
  where tr.join_code is not null
    and upper(tr.join_code) = upper(btrim(coalesce(p_code, '')));

  if t_id is null then
    raise exception 'no coach uses that code';
  end if;

  -- A coach cannot request themselves. Nothing stops the code being pasted
  -- into the coach's own client-app account, and a self-referential row would
  -- put them on their own roster.
  if t_id = uid then
    raise exception 'that is your own code';
  end if;

  select coalesce(nullif(btrim(p.full_name), ''), 'Your coach') into t_name
  from public.profiles p where p.id = t_id;

  -- Already linked, or already asked. Either way this is not an error and must
  -- not create a second pending row — the coach would see the same person
  -- twice and have to decide about them twice.
  select exists (
    select 1 from public.coaching_relationships r
    where r.coach_id = t_id and r.client_id = uid
  ) or exists (
    select 1 from public.coach_requests q
    where q.trainer_id = t_id and q.client_id = uid and q.status = 'pending'
  ) into existing;

  if not existing then
    insert into public.coach_requests (client_id, trainer_id, mode, status)
    values (uid, t_id, 'inperson', 'pending');
  end if;

  return query select t_id, coalesce(t_name, 'Your coach'), existing;
end; $$;

revoke all on function public.generate_join_code() from public, anon, authenticated;
grant execute on function public.my_join_code() to authenticated;
grant execute on function public.join_by_code(text) to authenticated;

-- ▶ join-code-tracking.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Knowing where a client came from, and being able to change a code.
--
-- 55-coach-join-code.sql shipped the code itself and tracked almost nothing
-- about it. Asked "how do you track them?", the honest answer was: barely.
-- Three things were missing and one was wrong.
--
--   1. A request created by spending a code was indistinguishable from one
--      sent from the directory. So "is the code working?" — the first question
--      anybody asks about a referral mechanism — had no answer.
--
--   2. There was no way to change a code. A code read aloud in a gym, printed
--      on a card and texted to twenty people is not a secret, and the moment a
--      coach wants a new one there was nothing to give them.
--
--   3. `mode` was hardcoded 'inperson'. An online-only coach had every client
--      who used their code marked as training in person, which is wrong on the
--      client's own profile and wrong in the coach's roster.
--
-- The code is recorded ON THE REQUEST as well as on the trainer, because codes
-- rotate: the code a client actually typed is a fact about that moment, and
-- reading it back off `trainers` after a rotation would report a code that
-- client never saw.
-- ─────────────────────────────────────────────────────────────────────────

alter table public.coach_requests
  add column if not exists source    text,
  add column if not exists via_code  text;

comment on column public.coach_requests.source is
  'How this request was made: ''code'', ''directory'', or null for rows predating this column.';
comment on column public.coach_requests.via_code is
  'The code as it stood when it was spent. Codes rotate; this does not.';

-- Null is honest for the rows that already exist: they were created before
-- anything recorded a source, and backfilling them with a guess would make
-- fabricated data indistinguishable from measured data.
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'coach_requests_source_ck'
  ) then
    alter table public.coach_requests
      add constraint coach_requests_source_ck
      check (source is null or source in ('code', 'directory'));
  end if;
end $$;

-- The one-argument version MUST go first.
--
-- Adding a defaulted parameter does not replace a function in Postgres, it
-- OVERLOADS it: join_by_code(text) and join_by_code(text, text default) would
-- both exist, and the app's existing one-argument call becomes ambiguous —
-- "function join_by_code(text) is not unique" — which breaks joining entirely
-- for everyone until somebody notices.
drop function if exists public.join_by_code(text);

/**
 * Join a coach by code, recording how and with which code.
 *
 * `p_mode` comes from the client — they know whether their coach trains them in
 * person or online, and the previous version simply asserted 'inperson'.
 * Anything unrecognised falls back to 'online', which is the safer default: a
 * client wrongly marked online sees a slightly thinner set of features, while
 * one wrongly marked in-person appears on an in-person roster for sessions
 * nobody is going to run.
 */
create or replace function public.join_by_code(p_code text, p_mode text default 'online')
returns table (trainer_id uuid, trainer_name text, already boolean)
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  t_id uuid;
  t_name text;
  t_code text;
  existing boolean;
  mode_in text := case when p_mode = 'inperson' then 'inperson' else 'online' end;
begin
  if uid is null then
    raise exception 'not signed in';
  end if;

  select tr.id, tr.join_code into t_id, t_code
  from public.trainers tr
  where tr.join_code is not null
    and upper(tr.join_code) = upper(btrim(coalesce(p_code, '')));

  if t_id is null then
    raise exception 'no coach uses that code';
  end if;

  if t_id = uid then
    raise exception 'that is your own code';
  end if;

  select coalesce(nullif(btrim(p.full_name), ''), 'Your coach') into t_name
  from public.profiles p where p.id = t_id;

  select exists (
    select 1 from public.coaching_relationships r
    where r.coach_id = t_id and r.client_id = uid
  ) or exists (
    select 1 from public.coach_requests q
    where q.trainer_id = t_id and q.client_id = uid and q.status = 'pending'
  ) into existing;

  if not existing then
    insert into public.coach_requests (client_id, trainer_id, mode, status, source, via_code)
    values (uid, t_id, mode_in, 'pending', 'code', upper(t_code));
  end if;

  return query select t_id, coalesce(t_name, 'Your coach'), existing;
end; $$;

/**
 * Issue the signed-in coach a new code, retiring the old one immediately.
 *
 * Requests already made with the old code keep it in `via_code`, so rotating
 * does not rewrite the history of who arrived how.
 */
create or replace function public.rotate_join_code()
returns text language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  code text;
begin
  if uid is null then
    raise exception 'not signed in';
  end if;
  if not exists (select 1 from public.trainers where id = uid) then
    raise exception 'no trainer profile for this account';
  end if;
  code := public.generate_join_code();
  update public.trainers set join_code = code where id = uid;
  return code;
end; $$;

/** How many people have joined this coach by code, and how many are waiting. */
create or replace function public.my_join_code_stats()
returns table (joined bigint, pending bigint)
language sql security definer stable set search_path = public as $$
  select
    count(*) filter (where q.status = 'accepted') as joined,
    count(*) filter (where q.status = 'pending')  as pending
  from public.coach_requests q
  where q.trainer_id = (select auth.uid()) and q.source = 'code';
$$;

grant execute on function public.join_by_code(text, text) to authenticated;
grant execute on function public.rotate_join_code() to authenticated;
grant execute on function public.my_join_code_stats() to authenticated;

-- ▶ coaching-mode-hybrid.sql

-- ── Coaching mode: hybrid, and the constraint that was eating profile saves ──
--
-- A person can be coached in the room, online, or both. Five tables carry a
-- coaching mode and every one of them was CHECK-constrained to
-- ('online','inperson'), so "both" could not be stored anywhere.
--
-- Widening is additive — every existing row already satisfies the wider
-- constraint — which is why this is safe to run against a live database and
-- safe to re-run.
--
-- ── The bug this also fixes ─────────────────────────────────────────────────
--
-- `clients.mode` additionally needed 'solo', for somebody training with no
-- coach at all. The app was already writing 'solo' into it. The old constraint
-- refused the row, and because that write travelled with the rest of the
-- profile, Postgres discarded the whole update: name, goal, diet, allergens,
-- injuries and manual weight went with it, silently. Nine client rows contained
-- no 'solo' at the time of writing, because none could ever be written.
--
-- 'solo' belongs to `clients` alone. It describes a person, never a
-- relationship — a coaching relationship with nobody in it is not a row.
--
-- ── Why clients.mode is created here ────────────────────────────────────────
--
-- The live database had this column; supabase/parts did not declare it
-- anywhere. The two had drifted, so a database built from this repo would not
-- have had a column the app writes to. Adding it here brings the schema-as-code
-- back in step with production rather than leaving the gap for the next person.

-- The column the repo was missing.
alter table public.clients
  add column if not exists mode text not null default 'online';

alter table public.clients drop constraint if exists clients_mode_check;
alter table public.clients add constraint clients_mode_check
  check (mode in ('online','inperson','hybrid','solo'));

alter table public.coach_clients drop constraint if exists coach_clients_mode_check;
alter table public.coach_clients add constraint coach_clients_mode_check
  check (mode in ('online','inperson','hybrid'));

alter table public.coach_invites drop constraint if exists coach_invites_mode_check;
alter table public.coach_invites add constraint coach_invites_mode_check
  check (mode in ('online','inperson','hybrid'));

alter table public.coach_requests drop constraint if exists coach_requests_mode_check;
alter table public.coach_requests add constraint coach_requests_mode_check
  check (mode in ('online','inperson','hybrid'));

alter table public.coaching_relationships drop constraint if exists coaching_relationships_mode_check;
alter table public.coaching_relationships add constraint coaching_relationships_mode_check
  check (mode in ('online','inperson','hybrid'));

-- ── join_by_code ────────────────────────────────────────────────────────────
--
-- This collapsed anything that was not 'inperson' down to 'online', so a hybrid
-- client joining by code landed on their coach's roster as online-only, and the
-- coach was never told otherwise. Replaces the version in
-- 56-join-code-tracking.sql; only `mode_in` differs.
create or replace function public.join_by_code(p_code text, p_mode text default 'online')
returns table(trainer_id uuid, trainer_name text, already boolean)
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  uid uuid := auth.uid();
  t_id uuid;
  t_name text;
  t_code text;
  existing boolean;
  -- An unrecognised mode still falls back to 'online' rather than raising: not
  -- knowing how somebody will be coached is no reason to refuse them a coach.
  mode_in text := case when p_mode in ('inperson','hybrid') then p_mode else 'online' end;
begin
  if uid is null then
    raise exception 'not signed in';
  end if;

  select tr.id, tr.join_code into t_id, t_code
  from public.trainers tr
  where tr.join_code is not null
    and upper(tr.join_code) = upper(btrim(coalesce(p_code, '')));

  if t_id is null then
    raise exception 'no coach uses that code';
  end if;

  if t_id = uid then
    raise exception 'that is your own code';
  end if;

  select coalesce(nullif(btrim(p.full_name), ''), 'Your coach') into t_name
  from public.profiles p where p.id = t_id;

  select exists (
    select 1 from public.coaching_relationships r
    where r.coach_id = t_id and r.client_id = uid
  ) or exists (
    select 1 from public.coach_requests q
    where q.trainer_id = t_id and q.client_id = uid and q.status = 'pending'
  ) into existing;

  if not existing then
    insert into public.coach_requests (client_id, trainer_id, mode, status, source, via_code)
    values (uid, t_id, mode_in, 'pending', 'code', upper(t_code));
  end if;

  return query select t_id, coalesce(t_name, 'Your coach'), existing;
end; $function$;

-- ▶ coach-checklist.sql

-- ─────────────────────────────────────────────────────────────────────────
-- A coach can put an item on one client's daily checklist.
--
-- TF-31: "What generates the daily checklist? Is it actually useful?" It was
-- generated by a five-element array literal in src/ui/habits.tsx — the same
-- "10,000 steps" and "Sleep 7h+" for every account on the platform, and no way
-- for anybody to add, remove or change a line. The product owner's answer was
-- that it should come "from your plan and targets — as well as the ones set by
-- the coach". The plan and targets the app already holds; this table is the
-- half that had nowhere to live.
--
-- Additive only. Nothing here alters an existing table, and every statement is
-- guarded so the file is safe to re-run.
--
-- ── Why a row per item, and not jsonb on one row per client ─────────────────
--
-- `assigned_programs` and `coach_nutrition` both take the other shape — one row
-- per client, the payload in a column — and either would have been less work
-- here. They are the wrong shape for this, for one reason: a tick is a row in
-- `habit_logs` keyed (user_id, habit, done_on), and `habit` is a TEXT id the
-- client's app sends. Inside a jsonb array the only identifier an item has is
-- its position, so a coach reordering their list on Tuesday would silently
-- reattach Monday's ticks to different items, and a coach who deleted the first
-- of five would shift four days of history by one. A uuid primary key is an
-- identifier that survives both, and survives a rename as well: the client's
-- app keys the habit on 'coach:' || id (see COACH_ID_PREFIX in
-- src/lib/checklist.ts), so a coach fixing a typo does not cost the client
-- their streak.
--
-- ── Why `active` rather than deleting the row ──────────────────────────────
--
-- A coach taking an item off the list should not take the record of it with
-- them. The client's ticks stay in `habit_logs` either way — nothing here
-- cascades to them — but with the row gone, neither app can say what
-- 'coach:8f3e…' in that history meant. Deactivating keeps last month's ticks
-- legible. A coach who genuinely wants the row gone can still delete it; the
-- app's own remove path sets `active` to false.
--
-- ── What this table is NOT ─────────────────────────────────────────────────
--
-- It is not a place for the coach to record whether the client did the thing.
-- There is no `done` column and there must not be one: the tick belongs to the
-- client, in `habit_logs`, where the client's own policy governs it. A coach
-- column saying "done" would be a second answer to a question only one person
-- can answer.
--
-- ── A correction to the sentence that used to end that paragraph ───────────
--
-- It read "and the coach dashboard already reads the client's real ticks". No
-- such reader existed. `habit_logs_coach_read` in 02-domain-schema.sql has
-- granted it all along — `for select using (is_my_client(user_id))` — and not
-- one query in either app or the console used the grant, so an item went onto
-- a client's list and nothing on the coach's side could say whether any of it
-- was ever done. The decision above stands on its own and did not need the
-- reassurance; what the reassurance did was describe a screen that was not
-- there, which is the most expensive shape a comment can take, because it is
-- the reason nobody went looking for the gap. The read exists now, on the
-- coach's checklist screen in the phone app: it reads `habit_logs` over a
-- four-week window and states only what those rows can support
-- (app/(trainer)/checklists.tsx, and src/lib/adherence.ts for the arithmetic
-- and for the several things it deliberately refuses to say). The console's
-- editor at /coach/checklists reads the same window through the same module,
-- so the two cannot drift into telling a coach different things about the same
-- client.
-- ─────────────────────────────────────────────────────────────────────────

create table if not exists public.coach_checklist_items (
  id uuid primary key default gen_random_uuid(),

  -- Cascade on both sides, matching coach_feedback. A checklist item is a thing
  -- one person set for another; with either of them deleted it is not a row
  -- anybody can read, act on or account for.
  client_id uuid not null references public.profiles(id) on delete cascade,
  coach_id  uuid not null references public.profiles(id) on delete cascade,

  -- What the client reads on the line. Bounded because it is rendered on one
  -- row of a phone screen, and non-empty because an unlabelled circle to tick
  -- is worse than no line at all — the app drops blank labels too, but the
  -- constraint is what stops one being stored in the first place.
  label text not null check (btrim(label) <> '' and length(label) <= 80),

  -- One emoji, optional. Empty means "the app picks", not "no icon" — the
  -- client's app substitutes its own so a line never renders short.
  icon text not null default '' check (length(icon) <= 8),

  -- Off, not gone. See the header.
  active boolean not null default true,

  -- The coach's own ordering. Ties break on created_at so a list where nobody
  -- has set an order is still stable between reads rather than shuffling.
  sort int not null default 0,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- Nobody coaches themselves, and a self-row would satisfy the client policy
  -- and the coach policy at once — which is a way around the relationship check
  -- below rather than a use case.
  constraint coach_checklist_items_not_self check (coach_id <> client_id)
);

-- The client's app reads this list on every launch, filtered to their own
-- active rows and ordered. This is that query.
create index if not exists idx_coach_checklist_client
  on public.coach_checklist_items (client_id, active, sort, created_at);

-- The coach's app reads their own list for one client.
create index if not exists idx_coach_checklist_coach
  on public.coach_checklist_items (coach_id, client_id);

comment on table public.coach_checklist_items is
  'Daily-checklist items a coach set for one client. The client''s ticks live in habit_logs under the id ''coach:'' || id.';

alter table public.coach_checklist_items enable row level security;

-- ── The client reads their own, and nothing else ───────────────────────────
--
-- SELECT only. A client who could edit these could quietly delete the item they
-- keep missing, and their coach would have no way to tell that from a coach who
-- never set it — which is the same class of bug as the one TF-31 is about.
-- Removing an item is a conversation with the coach, not a swipe.
--
-- Inactive rows come back too. The client's app filters them out; the policy
-- does not, because a client's own history is the one thing they are always
-- entitled to read, and a coach deactivating an item is not a reason to hide
-- what they were asked to do last month.
drop policy if exists coach_checklist_client_read on public.coach_checklist_items;
create policy coach_checklist_client_read on public.coach_checklist_items for select
  using (client_id = auth.uid());

-- ── The coach writes, for the clients they actually coach ──────────────────
--
-- `is_my_client` (02-domain-schema.sql) is the same predicate that already
-- governs every coach read of a client's domain data — workouts, measurements,
-- check_ins and habit_logs all hang off it — so a coach who can see a client's
-- ticks is exactly the coach who can add to the list those ticks are against.
-- Using it here rather than a second hand-written EXISTS is deliberate: two
-- spellings of "my client" that can drift apart is how a coach ends up able to
-- write a row they cannot then read.
--
-- `coach_id = auth.uid()` in the CHECK is what stops a coach setting an item in
-- somebody else's name. It is in the USING clause as well, so a coach cannot
-- edit or deactivate an item a colleague set for a client they share.
drop policy if exists coach_checklist_coach_write on public.coach_checklist_items;
create policy coach_checklist_coach_write on public.coach_checklist_items for all
  using      (coach_id = auth.uid() and public.is_my_client(client_id))
  with check (coach_id = auth.uid() and public.is_my_client(client_id));

-- ── updated_at ──────────────────────────────────────────────────────────────
--
-- Stamped here rather than trusted from the client, because "when did my coach
-- last change my list" is the sort of thing an app will eventually show and a
-- value the writer supplies is a value the writer can get wrong.
create or replace function public.touch_coach_checklist_item()
returns trigger language plpgsql
set search_path = public
as $$
begin
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists touch_coach_checklist_item_t on public.coach_checklist_items;
create trigger touch_coach_checklist_item_t
  before update on public.coach_checklist_items
  for each row execute function public.touch_coach_checklist_item();

-- Trigger functions are reachable by nobody; see 51-advisor-tidy.sql.
revoke execute on function public.touch_coach_checklist_item() from public, anon, authenticated;

-- ▶ goal-targets.sql

-- ─────────────────────────────────────────────────────────────────────────
-- What a client is working toward.
--
-- TF-28: "the only goal you can set is a target weight." Two problems, and the
-- second is the larger one.
--
-- ── It was one metric ──────────────────────────────────────────────────────
--
-- Weight is the goal the app could offer, not the goal most people have. A
-- client recomposing wants a body-fat number; somebody who has just come off a
-- long illness wants muscle back; plenty of goals are not a number at all
-- ("get through a session without my knee complaining"). Three of the four
-- kinds here are measured against a series the app already records — scans and
-- check-ins give weight, body fat and skeletal muscle — and the fourth is not
-- measured at all, deliberately.
--
-- ── It was never leaving the phone ─────────────────────────────────────────
--
-- The target lived in AsyncStorage under 'repple.goalTarget' and was written
-- nowhere else. So:
--   · a coach could not see what their client was aiming at, in an app whose
--     entire premise is that a coach is watching;
--   · a new phone, or a reinstall, silently reset it to nothing;
--   · the console had nothing to show on a client's page.
-- That is why this is a table and not another column on `clients`.
--
-- ── target_value is nullable on purpose ────────────────────────────────────
--
-- A 'custom' goal has no number, and giving it one — 0, or 1 for "done" —
-- would let every screen that computes progress compute a percentage of a
-- sentence. The check constraint below makes the two shapes mutually
-- exclusive so no code has to guess which kind it is holding.
-- ─────────────────────────────────────────────────────────────────────────

create table if not exists public.goal_targets (
  id           uuid primary key default gen_random_uuid(),
  client_id    uuid not null references public.clients(id) on delete cascade,
  kind         text not null check (kind in ('weight','bodyfat','muscle','custom')),
  -- In the metric's own unit: kg for weight and muscle, percent for bodyfat.
  -- Always null for 'custom'.
  target_value numeric(6,2),
  -- The client's own words. Always null for the measured kinds, whose name is
  -- the metric — storing "Target weight" would be the app talking to itself.
  title        text,
  target_date  date,
  -- Set when they say they have got there. For a measured goal that is a claim
  -- the series can be checked against; for a custom one it is the only signal
  -- there will ever be, which is the whole reason it is a column and not a
  -- computed value.
  achieved_at  timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),

  -- A measured goal is a number; a custom goal is a sentence. Never both,
  -- never neither.
  constraint goal_targets_shape check (
    (kind = 'custom'  and target_value is null and title is not null and btrim(title) <> '')
    or
    (kind <> 'custom' and target_value is not null and title is null)
  )
);

-- One live target per measured metric. A client aiming at two different weights
-- at once is a bug in whatever wrote the second row, not a state to render.
-- Custom goals are excluded: having several at a time is the normal case.
create unique index if not exists idx_goal_targets_one_per_metric
  on public.goal_targets (client_id, kind)
  where kind <> 'custom';

create index if not exists idx_goal_targets_client
  on public.goal_targets (client_id);

alter table public.goal_targets enable row level security;

-- The client owns their goals outright.
drop policy if exists goal_targets_own on public.goal_targets;
create policy goal_targets_own on public.goal_targets for all
  using (client_id = auth.uid()) with check (client_id = auth.uid());

-- Their coach can READ them, on the same terms as workouts, measurements and
-- check-ins (02-domain-schema.sql). Read only: a goal is the client's own
-- statement of what they want, and a coach silently editing it would make the
-- screen the client is looking at stop being theirs. A coach who disagrees has
-- the messaging thread.
drop policy if exists goal_targets_coach_read on public.goal_targets;
create policy goal_targets_coach_read on public.goal_targets for select
  using (public.is_my_client(client_id));

-- Trigger functions in this schema are not callable; see 51-advisor-tidy.sql.
-- Nothing here adds one, but the grant sweep in 40-function-grants.sql should
-- be re-run after any migration that does.

-- ▶ daily-targets.sql

-- ─────────────────────────────────────────────────────────────────────────
-- A step goal and a sleep goal, per client.
--
-- The daily checklist offered "10,000 steps" and "Sleep 7h+" to every account
-- on the platform for as long as it existed. Both were literals in a five-
-- element array in src/ui/habits.tsx. Nobody had chosen either number, no
-- screen could change them, and nothing in the product recorded what any
-- individual client was aiming for.
--
-- Rebuilding the checklist from the client's own targets (TF-31) took those two
-- lines out, because there was no target to put in their place: no column, no
-- setting, no screen. It could not even prompt for one — "set a step goal"
-- pointing at a screen that does not exist is its own small lie. These are the
-- columns that make the prompt honest.
--
-- ── Why here and not in goal_targets ───────────────────────────────────────
--
-- `goal_targets` (part 59) holds things you REACH: a weight by a date, with a
-- baseline, a percentage and a finish. These are things you DO, every day, with
-- no end state — 10,000 steps is not 40% done on Tuesday. Same word, different
-- shape, and giving them a target_date and an achieved_at would invite every
-- screen that reads goals to compute progress toward a habit.
--
-- They sit beside `meals_per_day`, which is the same kind of thing: a standing
-- daily preference that belongs to the client.
--
-- ── Both nullable, with no default ─────────────────────────────────────────
--
-- NULL means "they have not said", and the checklist renders no row for a NULL
-- rather than a row built on a number nobody chose. Defaulting either to a
-- plausible figure would recreate the exact bug this replaces, with the added
-- problem that it would then look like the client's own answer.
-- ─────────────────────────────────────────────────────────────────────────

alter table public.clients
  add column if not exists step_goal int;

alter table public.clients
  add column if not exists sleep_goal_hours numeric(3,1);

-- Bounds, not defaults. They exist to catch a fat-fingered entry or a unit
-- mix-up (a client typing minutes into the sleep field), and they are wide
-- enough not to argue with anybody's real target.
alter table public.clients drop constraint if exists clients_step_goal_check;
alter table public.clients add constraint clients_step_goal_check
  check (step_goal is null or (step_goal >= 500 and step_goal <= 100000));

alter table public.clients drop constraint if exists clients_sleep_goal_hours_check;
alter table public.clients add constraint clients_sleep_goal_hours_check
  check (sleep_goal_hours is null or (sleep_goal_hours >= 3 and sleep_goal_hours <= 14));

comment on column public.clients.step_goal is
  'Daily step target the client set. NULL means they have not set one — never a default.';
comment on column public.clients.sleep_goal_hours is
  'Nightly sleep target in hours. NULL means they have not set one — never a default.';

-- ▶ unit-preference.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Which units a client reads their own body in.
--
-- TF-37 asked for a default plus real conversion. The conversion is
-- src/lib/units.ts. This is the half that decides whether the client has to
-- answer the question again on their next phone.
--
-- ── Why it cannot stay on the device ───────────────────────────────────────
--
-- The preference lived in AsyncStorage under 'repple.settings', alongside the
-- two notification toggles, and was written nowhere else. That is the same
-- shape as the goal target before part 59 and the step goal before part 60, and
-- it fails the same three ways:
--
--   · a reinstall, or a new phone, silently resets it — and unlike a lost
--     notification toggle, this one changes what every number on screen SAYS.
--     A client who reads in pounds opens the app on a new handset and their
--     weight has apparently changed by a factor of 2.2;
--   · a client with a phone and a tablet gets a different answer on each;
--   · the coach's console and any coach-facing figure have nothing to read, so
--     a coach cannot see a client's numbers the way the client sees them.
--
-- ── Two columns, not one ───────────────────────────────────────────────────
--
-- A single 'metric' / 'imperial' switch is tidier and wrong for the population
-- this product actually has. A great many people — most of the UK, and a good
-- share of the UAE's expat residents — think about body weight in one system
-- and height in the other. Forcing them to pick a side means one of the two
-- numbers on their profile is always in a unit they have to convert in their
-- head, which is the thing this ticket is about.
--
-- length_unit covers height AND tape measurements together, because those are
-- the same instrument to the person holding it. Height in 'in' is rendered as
-- feet and inches; a waist in 'in' is rendered as plain inches. Same stored
-- centimetres, same column, different presentation — see src/lib/units.ts.
--
-- ── Both nullable, with no default ─────────────────────────────────────────
--
-- NULL means the client has never touched the setting. It does NOT mean 'kg'.
-- The app's default is the app's to choose (it chooses metric, in
-- src/ui/settings.tsx, because this is a UAE-based product and the UAE is
-- metric), and keeping NULL distinct from a real choice is what lets that
-- default improve later — a locale-aware first guess, say — without silently
-- overwriting the answer of every client who deliberately chose kilograms.
-- Writing 'kg' as a column default would make those two states identical and
-- that door closes for good.
-- ─────────────────────────────────────────────────────────────────────────

alter table public.clients
  add column if not exists weight_unit text;

alter table public.clients
  add column if not exists length_unit text;

-- The check allows NULL explicitly rather than relying on the fact that NULL
-- passes an IN test by evaluating to unknown. Stating it is the difference
-- between "we thought about the unset case" and "we got away with it".
alter table public.clients drop constraint if exists clients_weight_unit_check;
alter table public.clients add constraint clients_weight_unit_check
  check (weight_unit is null or weight_unit in ('kg', 'lb'));

alter table public.clients drop constraint if exists clients_length_unit_check;
alter table public.clients add constraint clients_length_unit_check
  check (length_unit is null or length_unit in ('cm', 'in'));

comment on column public.clients.weight_unit is
  'How this client reads body weight: kg or lb. NULL means they have not chosen — the app applies its own default and does not write one here. Storage is always kilograms; this only changes presentation and entry (src/lib/units.ts).';
comment on column public.clients.length_unit is
  'How this client reads height and tape measurements: cm or in. NULL means they have not chosen. Storage is always centimetres.';

-- No policy changes. `clients` already carries the client-owns-their-row and
-- coach-can-read policies from 08-roster-access.sql / 38-tenant-isolation.sql,
-- and a unit preference is exactly as sensitive as `diet` sitting beside it.
--
-- Trigger functions in this schema are not callable; see 51-advisor-tidy.sql.
-- Nothing here adds one. `npm run db:build` must be re-run so this part reaches
-- supabase/setup.sql before the migration is applied.

-- ▶ day-types.sql

-- ─────────────────────────────────────────────────────────────────────────
-- What kind of day a client INTENDS a date to be.
--
-- TF-20: "I want to plan ahead on the calendar." Everything the calendar could
-- show was retrospective — sessions a coach had opened, workouts already
-- logged. A client who knows on Sunday that Thursday is a write-off and Friday
-- is legs had nowhere to put either, so the plan they were actually following
-- existed only in their head, and their coach — whose whole job is to watch it
-- — could not see it at all.
--
-- ── The vocabulary is the one the app already had ──────────────────────────
--
-- `day_type` is not a new set of words. The three buttons on the Nutrition
-- screen (`DAY_TYPES` in app/(client)/nutrition.tsx) have been training / off /
-- rest since macro cycling shipped, each with a definition written for a tester
-- who asked what they meant, and that file says in its own comment that the
-- wording was chosen to survive exactly this change. 'off' is stored rather
-- than the prettier 'standard' for the same reason: two spellings of one day
-- type is how a day planned on the calendar stops matching the day the meal
-- plan is built for.
--
-- 'deload' is the one addition, and it is not a new concept either — the app
-- has `deloadCheck` (src/lib/training.ts), a 'deload' action on every lift
-- (src/lib/progression.ts) and a screen that tells clients when a deload week
-- is due (app/(client)/restday.tsx). Only the planning half was missing.
--
-- Refeed days and travel days were asked for and are deliberately NOT types.
-- Nothing in the product can act on either — the macro engine cycles on
-- training and rest alone — and a day type that changes nothing anywhere is a
-- sticker that looks like a setting. They go in `note` until there is something
-- for them to do, which is what the picker tells the client.
--
-- ── This table holds intentions, and nothing else ──────────────────────────
--
-- There is no `completed`, no `done` and no `actual_type`, and there must not
-- be. What happened on a day is in `workouts`, which is the client's own record
-- of what they did; a second column here saying whether the plan was kept would
-- be a claim nobody measured. A planned rest day that passes with an empty log
-- looks identical to a rest day that was taken, to a session that was never
-- logged, and to a day spent in bed with flu — see planOutcome in
-- src/lib/dayPlan.ts, which is where that distinction is kept honest.
--
-- Nor does the row take a position on the client's PROGRAM. A client marking a
-- rest day on a Tuesday their plan schedules as Push is a disagreement worth
-- surfacing to both of them, not something to be silently resolved in either
-- direction, so nothing here edits `assigned_programs` and nothing there edits
-- this.
--
-- Additive only. Nothing below alters an existing table, and every statement is
-- guarded so the file is safe to re-run.
-- ─────────────────────────────────────────────────────────────────────────

create table if not exists public.planned_days (
  -- `clients.id` IS the auth user id (01-schema.sql), which is what lets the
  -- policies below read `client_id = auth.uid()` directly, exactly as
  -- goal_targets does.
  client_id uuid not null references public.clients(id) on delete cascade,

  -- A calendar day, not an instant. `date` and never `timestamptz`: "Thursday
  -- is a travel day" is a statement about the client's own Thursday, and
  -- storing it with a time would make it start and end at different moments for
  -- a client and a coach in different zones. src/lib/localDate.ts is the two
  -- bugs this repo has already shipped by reading a bare date as UTC midnight.
  on_date date not null,

  -- The vocabulary, closed. A build that does not know a value must not guess
  -- at it, so the app filters unknown types out rather than defaulting them
  -- (isPlannedDayType, src/lib/dayPlan.ts) — and this constraint is what stops
  -- an unknown one being written in the first place.
  day_type text not null check (day_type in ('training','off','rest','deload')),

  -- The client's own words about the day, optional. This is where "flying to
  -- Berlin" and "refeed" live: it carries no behaviour anywhere in the app, and
  -- it is bounded because it is rendered on one line under a date. Empty string
  -- is not a note — the app sends NULL — so the check refuses a blank that
  -- would render as an empty second line.
  note text check (note is null or (btrim(note) <> '' and length(note) <= 140)),

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- One row per client per date. A client cannot intend Thursday to be two
  -- different kinds of day, and a second row would mean the calendar's answer
  -- depended on read order. It also makes re-marking a day an upsert rather
  -- than a delete-then-insert, which is one round trip and cannot half-fail.
  primary key (client_id, on_date)
);

-- The client's app reads their whole set on launch and the coach reads one
-- client's; the primary key already serves both, so there is no second index
-- to keep in step.

comment on table public.planned_days is
  'What kind of day a client intends a date to be. An intention, never a record — what happened is in workouts.';
comment on column public.planned_days.day_type is
  'The app''s own day-type vocabulary: training / off (Standard) / rest / deload. Matches DAY_TYPES in app/(client)/nutrition.tsx.';
comment on column public.planned_days.note is
  'The client''s own words. Where a travel or refeed day goes while the app has no behaviour for either. NULL means none.';

alter table public.planned_days enable row level security;

-- The client owns their plans outright — reading, marking, changing their mind
-- and unmarking. Same shape as goal_targets: what a person intends to do is
-- theirs to state.
drop policy if exists planned_days_own on public.planned_days;
create policy planned_days_own on public.planned_days for all
  using (client_id = auth.uid()) with check (client_id = auth.uid());

-- Their coach can READ them, on the same terms as workouts, measurements and
-- check-ins (`is_my_client`, 02-domain-schema.sql). That predicate rather than
-- a second hand-written EXISTS is deliberate and is the established idiom here:
-- two spellings of "my client" that drift apart is how somebody ends up able to
-- write a row they cannot then read.
--
-- Read only, and that is the point of the feature. A coach who could edit these
-- would be answering a question only the client can answer — the calendar would
-- stop showing the client what THEY planned and start showing them what they
-- have been assigned, which is what `assigned_programs` is already for. A coach
-- who disagrees with a planned rest day has the messaging thread; the app
-- surfaces the disagreement to both of them rather than settling it.
drop policy if exists planned_days_coach_read on public.planned_days;
create policy planned_days_coach_read on public.planned_days for select
  using (public.is_my_client(client_id));

-- ── updated_at ──────────────────────────────────────────────────────────────
--
-- Stamped here rather than trusted from the client, for the reason spelled out
-- in 58-coach-checklist.sql: "when did they last change their plan" is a thing
-- a coach's screen will eventually want, and a value the writer supplies is a
-- value the writer can get wrong. It matters more here than there, because an
-- upsert on a changed mark is otherwise indistinguishable from the original.
create or replace function public.touch_planned_day()
returns trigger language plpgsql
set search_path = public
as $$
begin
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists touch_planned_day_t on public.planned_days;
create trigger touch_planned_day_t
  before update on public.planned_days
  for each row execute function public.touch_planned_day();

-- Trigger functions are reachable by nobody; see 51-advisor-tidy.sql.
revoke execute on function public.touch_planned_day() from public, anon, authenticated;

-- ▶ clients-schema-drift.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Five columns production has that this repo never declared.
--
-- `clients` is defined in 01-schema.sql with twelve columns, and part 05 adds
-- `avoid`. Production carries five more that no file here creates:
--
--     injuries              text[]
--     focus_areas           text[]
--     manual_weight_kg      numeric
--     manual_body_fat_pct   numeric
--     manual_at             timestamptz
--
-- src/ui/clientData.tsx selects and updates every one of them. They were added
-- to the live database by hand at some point and the migration was never
-- written down, which is the same drift that hid `clients.mode` until part 57.
--
-- ── Why this is not merely untidy ──────────────────────────────────────────
--
-- PostgREST rejects the WHOLE statement for one unknown column. So on any
-- database built from this repo — a new environment, a staging copy, a local
-- stack — the profile write in clientData.tsx fails entirely, and it fails
-- silently in a debounced effect: the client's name, goal, diet, allergens,
-- injuries, focus areas AND their manually entered weight are all lost
-- together, having looked saved. That is the identical failure mode as the
-- 'solo' coaching mode, arrived at from the other end — a constraint refusing
-- a value there, a column not existing here.
--
-- Production is fine and always has been; the columns are there. This closes
-- the gap so the next environment does not inherit a broken profile save.
--
-- ── Types match production exactly ─────────────────────────────────────────
--
-- Read back with format_type() rather than guessed. The two numerics carry no
-- precision or scale, which is what production has — NOT the numeric(5,1) that
-- `scans.weight_kg` uses. Tightening them here would be a schema change
-- disguised as a transcription, and an unconstrained numeric already holds
-- everything the app puts in it.
-- ─────────────────────────────────────────────────────────────────────────

-- What the client tells us about themselves, alongside what a scan measures.
alter table public.clients add column if not exists injuries    text[];
alter table public.clients add column if not exists focus_areas text[];

-- A weight and body fat the client typed, for people without an InBody. Read
-- in preference to the newest scan only while `manual_at` is more recent than
-- it — see the `manualIsCurrent` logic in src/ui/clientData.tsx. That is why
-- the timestamp is a column and not a derived value: without it there is no way
-- to tell a fresh manual entry from one left over from six months ago.
alter table public.clients add column if not exists manual_weight_kg    numeric;
alter table public.clients add column if not exists manual_body_fat_pct numeric;
alter table public.clients add column if not exists manual_at           timestamptz;

comment on column public.clients.manual_at is
  'When the manual weight/body-fat were entered. The app prefers them over the newest scan only while this is more recent than that scan.';

-- ▶ coach-name-for-client.sql

-- ─────────────────────────────────────────────────────────────────────────
-- A client can learn their own coach's name.
--
-- TF-32 was a display bug: the client's Messages, Calendar and Bookings
-- screens headed a thread with `useCoachProfile()`, which loads the SIGNED-IN
-- user's own profile — so under "Your coach" sat the reader's own name, and
-- under it their own face. That is fixed in the app.
--
-- Fixing it exposed the real gap underneath. There is no policy on `profiles`
-- that runs client → coach: `profiles_self` is `id = auth.uid()`, and
-- `profiles_trainer_read` and both policies in 28-fix-profiles-recursion.sql
-- all run trainer → client. So the honest rendering became a labelled dash on
-- every one of those screens — correct, and a poor experience for a product
-- whose premise is that somebody is coaching you.
--
-- ── Why a function and not a policy ────────────────────────────────────────
--
-- A policy on `profiles` wide enough to let clients read their coach's row
-- would expose the whole row, and `profiles` carries more than a name. It
-- would also have to be written as a subquery over `clients` and
-- `coaching_relationships`, which is exactly the recursion that
-- 28-fix-profiles-recursion.sql exists to undo.
--
-- This returns one column, for one person, and takes no arguments. Without a
-- parameter there is nothing to probe: it can only ever answer about the
-- coach of whoever is calling it. That is the same property the `auth.uid() in
-- (…)` line gives `coaching_link_active` in 47-share-progress-photo.sql, got
-- here by construction rather than by a check.
--
-- ── Why both links are required ────────────────────────────────────────────
--
-- A coach↔client link is recorded in two places — `clients.trainer_id` and a
-- row in `coaching_relationships` — and 47's header documents that nothing in
-- the repo un-links today, so the two can drift. `fetchMyCoach` in
-- src/lib/photoShare.ts already requires both before it will name a coach as
-- somebody who can see your photographs. This uses the same test, so "who is
-- my coach" has one answer across the app rather than a stricter one for
-- photos and a looser one for names.
--
-- ── Null is a real answer ──────────────────────────────────────────────────
--
-- No rows means no active coach. One row with a null `coach_name` means there
-- is a coach who has not set a name. The app renders those differently, so the
-- function must not collapse them — hence the left join and the nullif rather
-- than a coalesce to some placeholder.
-- ─────────────────────────────────────────────────────────────────────────

create or replace function public.my_coach()
returns table(coach_id uuid, coach_name text)
language sql
security definer
stable
set search_path to 'public'
as $function$
  select c.trainer_id,
         nullif(btrim(p.full_name), '')
  from public.clients c
  left join public.profiles p on p.id = c.trainer_id
  where c.id = (select auth.uid())
    and c.trainer_id is not null
    and exists (
      select 1 from public.coaching_relationships r
      where r.client_id = c.id
        and r.coach_id = c.trainer_id
        and r.status = 'active'
    );
$function$;

-- Signed-in callers only. `anon` must not reach a definer function that reads
-- profiles, even one that answers only about auth.uid() — with no session
-- auth.uid() is null, the where clause matches nothing, and the honest place
-- to stop that is the grant rather than the query.
revoke execute on function public.my_coach() from public, anon;
grant execute on function public.my_coach() to authenticated;

-- ▶ end-coaching.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Ending a coaching relationship. The other half of `link_coaching()`.
--
-- 06-account-provisioning.sql has made a coach↔client link since the first
-- week of this project, and it writes the link in TWO places in one statement:
--
--     insert into coaching_relationships … status = 'active';
--     update clients set trainer_id = p_coach where id = p_client;
--
-- Nothing has ever undone either one. Grep the repo before this file and there
-- is no writer of `status = 'ended'` and none of `trainer_id = null`; the
-- header of 47-share-progress-photo.sql says so out loud, and adds that the
-- shape of the future unlink is unknown and "may well write only one of the
-- two". This is that file, and it writes BOTH or neither.
--
-- Until now a client could not leave a coach and a coach could not let a
-- client go. `removeClient` in src/ui/roster.tsx deleted a `coach_clients`
-- row — the manually-added-client table, which a linked client has no row in —
-- and returned true, so the coach watched somebody vanish from the roster and
-- come back on the next launch with full access to their body data intact.
--
-- ── WHO MAY CALL IT ───────────────────────────────────────────────────────
--
-- Either party, and nobody else. The only argument is the OTHER person, so
-- there is no way to name a pair the caller is not in: every predicate below
-- pins one side of the pair to `auth.uid()`, and the caller supplies the other.
--
-- The identity test is on `auth.uid()` and NEVER on `current_user`. Inside a
-- SECURITY DEFINER function `current_user` is the function's OWNER, so a
-- `current_user` guard reads as protection while providing none — 47's header
-- records that exact bug shipping in this project. `auth.uid()` reads the
-- request's JWT claim out of a GUC, so it is the CALLER either way and is
-- unaffected by SECURITY DEFINER. That is the only reason this can be definer.
--
-- Definer is not a convenience here, it is required in both directions:
--   · a coach has no UPDATE on `clients` at all (08-roster-access.sql grants
--     them SELECT and nothing more), so a coach cannot clear `trainer_id`;
--   · a client has no way to reach the coach's side of anything.
-- One function, owned by the database, is the only place both writes can
-- happen together.
--
-- ── ATOMIC, BECAUSE HALF OF THIS IS THE BUG ───────────────────────────────
--
-- A function that set `status = 'ended'` and then failed before clearing
-- `trainer_id` would leave exactly the drift this exists to remove — and the
-- worse half of it, because `is_my_client()` reads `trainer_id`, so the coach
-- would keep every ounce of access while both apps showed the relationship as
-- over. plpgsql gives that for free and it is worth saying why: a function body
-- runs inside the caller's transaction, PostgREST wraps each request in one, so
-- an exception anywhere in here aborts the whole call and neither write lands.
-- Nothing below commits, and nothing below is allowed to swallow an exception.
--
-- ── WHAT A COACH LOSES ────────────────────────────────────────────────────
--
-- Clearing `clients.trainer_id` is the load-bearing half. `is_my_client(c)` is
--
--     exists (select 1 from clients where id = c and trainer_id = auth.uid())
--
-- and it governs the coach's read of `workouts`, `measurements`, `check_ins`,
-- `habit_logs` (02-domain-schema.sql), `messages` (10), `goal_targets` (59),
-- `coach_checklist_items` (58) and `day_types` (62). The same shape written
-- long-hand governs `scans` and `food_logs` (01-schema.sql) and the client's
-- own `profiles` row (08). All of it goes dark in the same statement:
--
--   · every workout, measurement, check-in and habit log
--   · every InBody scan and food log
--   · the message thread (read AND write — `msg_coach` is FOR ALL)
--   · goals, checklist items and day types
--   · the client's name and avatar, so the roster stops listing them
--   · progress photos, twice over — see the trigger section below
--   · the ability to be booked: `book_session()` requires the link, so the
--     client can no longer take a slot from this coach's calendar
--
-- ── WHAT A COACH KEEPS, AND WHY THAT IS DELIBERATE ────────────────────────
--
-- A coach's own record of work they did and were paid for is theirs. None of
-- it is keyed on `clients.trainer_id`, so none of it moves:
--
--   · `sessions` — `sessions_trainer` is `trainer_id = auth.uid()` on the
--     session's OWN column (09-sessions-access.sql). Every session they ever
--     delivered stays readable, with its date, duration and outcome.
--   · `payroll_settlements` (36), `invoices`, `subscriptions`,
--     `billing_customers` (20, 39) — all keyed on the coach's own id.
--   · `client_tags` (14) — `coach_id = auth.uid()`, the coach's own notes.
--
-- One honest cost of that, stated rather than hidden: those session and payroll
-- rows carry a client_id, and the coach can no longer read that person's
-- `profiles` row, so a past client's NAME on a historical session renders as a
-- dash. The row, the money and the date all survive; the name does not. That is
-- the safe direction — a policy wide enough to keep the name would outlive the
-- relationship and the client could never take it back — and it is the reason
-- this file adds no new SELECT policy to `profiles`.
--
-- Booked future sessions are NOT cancelled. A slot somebody paid for is not
-- swept away by an unlink happening in another screen; either party cancels it
-- deliberately, and the client keeps reading it through `client_id =
-- auth.uid()` either way.
--
-- ── THE RESIDUE THIS FILE DOES NOT CLEAR ──────────────────────────────────
--
-- `coach_feedback`, `coach_nutrition` and `assigned_programs` are policed in
-- 02-domain-schema.sql as `coach_id = auth.uid() or client_id = auth.uid()` —
-- keyed on the relationship's own coach_id column, NOT on `trainer_id`. So a
-- former coach keeps read and write on the feedback, macro adjustments and
-- assigned programs they wrote for this client. Those are their own words about
-- their own work, which is arguable either way, but the WRITE half is not: a
-- coach who was let go can still assign a program. Narrowing those three
-- policies is a change to 02, not to this file, and it is named here so the
-- next reader finds it rather than discovers it.
--
-- ── THE PHOTO TRIGGER, WHICH HAS NEVER ONCE FIRED ─────────────────────────
--
-- 47-share-progress-photo.sql created two triggers whose entire purpose is this
-- moment, and neither has ever run, because nothing in the repo unlinked:
--
--     on_coaching_unlink_revoke_photo_shares
--       after update or delete on coaching_relationships, for each row
--     on_trainer_change_revoke_photo_shares
--       after update of trainer_id on clients, for each row
--       when (NEW.trainer_id is distinct from OLD.trainer_id)
--
-- Both fire on this function, and it is worth being precise about how that was
-- established rather than assumed:
--
--   · The first has no WHEN clause and covers plain UPDATE. The statement below
--     is an UPDATE on `coaching_relationships` matching the pair's row, so the
--     trigger runs with TG_OP = 'UPDATE'. `revoke_photo_shares_on_unlink()`
--     takes its third branch — `elsif NEW.status <> 'active'` — because the row
--     now says 'ended', and DELETEs every `progress_photo_shares` grant for
--     that (client, coach).
--   · The second is gated on `trainer_id` actually changing. The second
--     statement sets it to null and is guarded by `trainer_id is not null`, so
--     NEW is distinct from OLD whenever it matches at all, and the trigger
--     runs. It takes the first branch — `TG_TABLE_NAME = 'clients'` — and
--     deletes every grant that client holds, whoever it was addressed to.
--   · Neither trigger tests any identity, so it does not matter which party
--     made the call. They decide from OLD and NEW alone, which is a fact about
--     the row rather than a claim about who is speaking.
--
-- Either statement alone would revoke the grants; both firing is belt and
-- braces, and the delete is idempotent. Access itself was already closed by
-- `coaching_link_active()`, which requires BOTH links — the triggers exist so
-- the client's "what can my coach see" list stops listing grants that no longer
-- grant anything. Section 0 asserts the first trigger is really there, because
-- this file's central claim is false without it.
--
-- Re-hiring the same coach does NOT bring the old photo grants back. The rows
-- are deleted, not flagged, and 47 chose that on purpose.
--
-- ── ENDED, NOT DELETED — AND REVERSIBLE ───────────────────────────────────
--
-- `status = 'ended'` rather than `delete from coaching_relationships`, and the
-- `unique (coach_id, client_id)` row is kept. Three reasons, in order of how
-- much they cost if ignored:
--
--   1. That the two of you worked together is a FACT, and one both parties may
--      later need — a dispute about a session, a payroll settlement that names
--      a client the coach can otherwise no longer identify, a client asking who
--      wrote a program they are still following. A delete destroys it silently
--      and there is no recovering it.
--   2. `link_coaching()` is already written as `on conflict (coach_id,
--      client_id) do update set status = 'active'`, so re-hiring is a single
--      existing call that flips the same row back and rewrites `trainer_id`.
--      Ending is therefore reversible BY DESIGN, not by accident: nothing here
--      is destructive except the photo grants, which 47 decided must be.
--   3. A deleted row and a never-existed row are indistinguishable, which is
--      the same class of lie this codebase keeps finding on its screens.
--
-- `ended_at` and `ended_by` are added below so "ended" is a record and not just
-- a flag. Without them the row still says the relationship is over but cannot
-- say when, and `created_at` alone would have the roster reporting a span that
-- is still open.
--
-- Idempotent throughout: `add column if not exists`, `create or replace`, and a
-- second call for a pair that is already ended writes nothing and still answers
-- true, because the honest answer to "are we unlinked" does not change on the
-- second ask.
-- ─────────────────────────────────────────────────────────────────────────


-- ═════════════════════════════════════════════════════════════════════════
-- 0 · Assertions — the dependencies this file's promises rest on
-- ═════════════════════════════════════════════════════════════════════════
--
-- Asserted rather than assumed, in the manner of 45 and 47. Each of these is
-- something the header above claims; if one were false the claim would be a
-- comment rather than a behaviour.

do $$
begin
  -- The whole point of the photo trigger is that it fires HERE. If 47 has not
  -- been applied, this function would end the relationship and leave the
  -- client's shared-photo list naming grants that no longer grant anything.
  if not exists (
    select 1 from pg_trigger
     where tgrelid = 'public.coaching_relationships'::regclass
       and tgname = 'on_coaching_unlink_revoke_photo_shares'
       and not tgisinternal
  ) then
    raise exception 'on_coaching_unlink_revoke_photo_shares is missing from coaching_relationships — apply 47-share-progress-photo.sql first, or ending a relationship will leave live photo grants listed to the client (see 47 §7).';
  end if;

  -- 'ended' has been a legal value of the CHECK constraint since 06 and has
  -- never been written. If a later edit narrowed it, every call below would
  -- fail at the first statement — which is the safe half of the transaction to
  -- fail in, but a failure nobody could explain from the app.
  if not exists (
    select 1 from pg_constraint
     where conrelid = 'public.coaching_relationships'::regclass
       and contype = 'c'
       and pg_get_constraintdef(oid) ilike '%ended%'
  ) then
    raise exception 'coaching_relationships has no CHECK admitting status = ''ended'' — end_coaching() could never write it.';
  end if;
end $$;


-- ═════════════════════════════════════════════════════════════════════════
-- 1 · When it ended, and who ended it
-- ═════════════════════════════════════════════════════════════════════════
--
-- Both nullable and both null for every row that exists today, which is
-- correct: no relationship in the database has ever been ended, so there is no
-- date to backfill and inventing one would be worse than the gap. A row with
-- status = 'ended' and a null ended_at can only be one written by hand before
-- this file existed, and reads as "we do not know when" rather than as a date.
--
-- ended_by is `on delete set null` rather than cascade for the same reason the
-- relationship row is kept at all: if the person who ended it later deletes
-- their account, THAT the relationship ended is still true, and taking the row
-- with them would erase a fact about somebody else's history.

alter table public.coaching_relationships
  add column if not exists ended_at timestamptz;
alter table public.coaching_relationships
  add column if not exists ended_by uuid references public.profiles(id) on delete set null;

comment on column public.coaching_relationships.ended_at is
  'When end_coaching() ended this relationship. Null on an active or pending row, and also on an ''ended'' row written before 68-end-coaching.sql — which means the date is unknown, not that it ended at the epoch.';
comment on column public.coaching_relationships.ended_by is
  'Which of the two parties called end_coaching(). Either may; null once that account is deleted.';


-- ═════════════════════════════════════════════════════════════════════════
-- 2 · The unlink
-- ═════════════════════════════════════════════════════════════════════════
--
-- ── Why the pair is treated as unordered ──────────────────────────────────
--
-- The obvious version works out which party is calling and branches. This does
-- not, and the symmetry is what makes it safe to read: every predicate below is
-- "(this side is me and that side is them) OR (this side is them and that side
-- is me)". The caller can only ever name the OTHER person, and `auth.uid()`
-- appears on one side of every disjunct, so there is no pair reachable from
-- here that the caller is not half of. No role detection, and nothing to get
-- backwards.
--
-- It also handles the one case a role branch would get wrong: `unique
-- (coach_id, client_id)` permits rows in both directions, so two coaches who
-- coach each other have two relationships. Ending is mutual, so both go.
--
-- ── Why the return value is what it is ────────────────────────────────────
--
-- `true`  — there was a record of a link between you two, and there is now no
--           live one. Answered from state read BEFORE the writes, so a second
--           call on an already-ended pair still says true. The caller asked to
--           be unlinked; they are unlinked; saying false the second time would
--           read as a failure.
-- `false` — no record of any link between you and that person, in either
--           direction, of any status. NOTHING was written. src/ui/roster.tsx
--           relies on this to tell a real linked client from a manually-added
--           `coach_clients` row, which is a different table with different ids.
--
-- It raises rather than returning false for the three things that are mistakes
-- rather than answers — no session, no argument, yourself — because each one
-- means the caller is confused about what they are asking, and a quiet false
-- would be indistinguishable from "you two were never linked".

create or replace function public.end_coaching(p_other uuid)
returns boolean
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_me    uuid := auth.uid();
  v_known boolean;
begin
  if v_me is null then
    raise exception 'not signed in';
  end if;

  if p_other is null then
    raise exception 'no one to end coaching with';
  end if;

  -- `link_coaching()` carries no such guard — only `join_by_code()` in part 55
  -- refuses your own code — so a self-referential row is reachable and the
  -- symmetric predicates below would match it twice. Refusing here keeps the
  -- answer honest as well as the SQL: there is no relationship to leave.
  if p_other = v_me then
    raise exception 'you cannot end a coaching relationship with yourself';
  end if;

  -- Read BEFORE the writes. Afterwards there is nothing left to distinguish
  -- "we ended it just now" from "there was never anything here", and those are
  -- the two answers this function exists to keep apart.
  --
  -- Either record on its own counts. A pair that has already drifted — a live
  -- `trainer_id` with no relationship row, or the reverse — is exactly the
  -- state this file was written to clean up, and refusing to touch it because
  -- the other half is missing would strand it forever.
  select
    exists (
      select 1 from public.coaching_relationships r
       where (r.coach_id = v_me     and r.client_id = p_other)
          or (r.coach_id = p_other  and r.client_id = v_me)
    )
    or exists (
      select 1 from public.clients c
       where (c.id = p_other and c.trainer_id = v_me)
          or (c.id = v_me    and c.trainer_id = p_other)
    )
  into v_known;

  if not v_known then
    return false;
  end if;

  -- Record one. `status <> 'ended'` keeps a re-run from restamping ended_at
  -- with a later date and re-firing the photo trigger for grants that were
  -- deleted the first time — the second call must be a no-op, not a rewrite of
  -- when the relationship ended.
  update public.coaching_relationships
     set status   = 'ended',
         ended_at = now(),
         ended_by = v_me
   where status <> 'ended'
     and ((coach_id = v_me    and client_id = p_other)
       or (coach_id = p_other and client_id = v_me));

  -- Record two, and the one that actually closes the coach's reads —
  -- `is_my_client()` is a lookup of this exact column.
  --
  -- Matching on `trainer_id = <the other party>` rather than on the client id
  -- alone is what makes a re-run harmless AND what makes the photo trigger
  -- correct: a row is only touched when it currently names the other party, so
  -- NEW.trainer_id is always distinct from OLD.trainer_id when this matches,
  -- which is precisely the WHEN clause on on_trainer_change_revoke_photo_shares.
  -- A row already cleared, or since re-linked to a different coach, matches
  -- nothing and is left alone — nobody else's link is disturbed by this call.
  update public.clients
     set trainer_id = null
   where (id = p_other and trainer_id = v_me)
      or (id = v_me    and trainer_id = p_other);

  return true;
end
$function$;


-- ═════════════════════════════════════════════════════════════════════════
-- 3 · Grants
-- ═════════════════════════════════════════════════════════════════════════
--
-- Matching 67-coach-name-for-client.sql. `anon` must not reach a definer
-- function that writes to `clients` and `coaching_relationships`, even one that
-- can only act on a pair containing auth.uid() — with no session auth.uid() is
-- null and the first statement raises, but the honest place to stop that is the
-- grant rather than the function body.

revoke execute on function public.end_coaching(uuid) from public, anon;
grant  execute on function public.end_coaching(uuid) to authenticated;

comment on function public.end_coaching(uuid) is
  'Ends the coaching relationship between the caller and p_other, writing both records — coaching_relationships.status = ''ended'' and clients.trainer_id = null — or neither. Callable by either party only. Returns false, having written nothing, when the two were never linked.';

-- ▶ coach-content-scope.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Who may write a training programme, a nutrition plan, or coach feedback.
--
-- Three tables carry content a coach produces FOR one named client:
-- `assigned_programs`, `coach_nutrition` and `coach_feedback`. All three were
-- policed the same way in 02-domain-schema.sql:
--
--     using      (coach_id = auth.uid() or client_id = auth.uid())
--     with check (coach_id = auth.uid())
--
-- ── The hole ───────────────────────────────────────────────────────────────
--
-- The WITH CHECK constrains `coach_id` and says NOTHING about `client_id`. So
-- any signed-in account could insert a row naming ANY client, provided it put
-- its own id in `coach_id`. The receiving client's app reads these by
-- `client_id = auth.uid()` and renders them as their plan — so a stranger could
-- put a training programme in somebody's Train tab, and a `carb_delta` in
-- `coach_nutrition` shifts the calorie and macro targets the client eats to.
-- No coaching link was required at any point.
--
-- Nothing in the app does this: every writer is a coach screen acting on a
-- client from their own roster. The policy simply never required it.
--
-- ── The residue ────────────────────────────────────────────────────────────
--
-- The second problem is at the other end. `end_coaching()` (part 68) clears
-- `clients.trainer_id`, which is what `is_my_client()` reads, and that is how
-- ending a relationship revokes a coach's access to workouts, measurements,
-- check-ins, habit logs, goals and the checklist. These three tables were not
-- gated on it, so a FORMER coach kept read and write and could still assign a
-- programme to somebody who had left them.
--
-- ── The shape now ──────────────────────────────────────────────────────────
--
-- Split in two, because the two parties are not doing the same thing.
--
-- The coach writes, and only their own rows, and only for a client who is
-- theirs RIGHT NOW. `is_my_client()` in the WITH CHECK closes the hole; the
-- same call in the USING clause ends the access when the relationship does,
-- with no extra bookkeeping and nothing for `end_coaching()` to remember.
--
-- The client READS, always, and cannot write. Their access is deliberately NOT
-- conditioned on the relationship: a plan somebody is following does not stop
-- being theirs because they changed coach, and a client who leaves keeps the
-- programme they were given. Dropping the write is a real narrowing — the old
-- policy let a client DELETE feedback written about them, which is a coach's
-- record of the working relationship and not the client's to remove.
--
-- ── What this does NOT do ──────────────────────────────────────────────────
--
-- It does not delete or rewrite a single row. Existing content stays exactly
-- where it is; what changes is who may reach it from here on. A coach who has
-- lost access to rows they wrote has not lost the rows.
-- ─────────────────────────────────────────────────────────────────────────

do $$
declare t text;
begin
  foreach t in array array['assigned_programs', 'coach_nutrition', 'coach_feedback']
  loop
    -- The single ALL policy these had. Replaced by the pair below; dropped by
    -- name so re-running this file is a no-op rather than a duplicate.
    execute format('drop policy if exists %s on public.%I;',
                   case t when 'assigned_programs' then 'prog_rw'
                          when 'coach_nutrition'   then 'nutri_rw'
                          else 'feedback_rw' end, t);

    execute format($f$
      drop policy if exists %1$s_coach_rw on public.%1$I;
      create policy %1$s_coach_rw on public.%1$I for all
        using      (coach_id = (select auth.uid()) and public.is_my_client(client_id))
        with check (coach_id = (select auth.uid()) and public.is_my_client(client_id));
    $f$, t);

    execute format($f$
      drop policy if exists %1$s_client_read on public.%1$I;
      create policy %1$s_client_read on public.%1$I for select
        using (client_id = (select auth.uid()));
    $f$, t);
  end loop;
end $$;

-- ▶ water-goal.sql

-- ─────────────────────────────────────────────────────────────────────────
-- A daily water goal, per client.
--
-- `const waterGoal = 8;` — one line in src/ui/habits.tsx, and every client on
-- the platform was told to drink eight glasses of water a day. Nobody had
-- chosen the figure, no screen could change it, and it was not decoration: the
-- daily checklist stated it as a target ("Drink 8 glasses of water"), the
-- Recovery hero drew an arc against it, the home screen counted "3 of 8", and
-- readinessScore divided by it — so a client who drank four glasses was scored
-- as half-hydrated against a number invented by a developer.
--
-- Part 60 took the same line out of steps and sleep. The comment left behind on
-- the water constant said a per-client goal, when there was one, would replace
-- that line and nothing else. This is that column.
--
-- ── Why here, beside step_goal and sleep_goal_hours ────────────────────────
--
-- Same shape and the same reason: a standing daily preference belonging to the
-- client, with no end state to reach. `goal_targets` (part 59) is for things
-- you finish — a weight by a date, with a baseline and a percentage. Eight
-- glasses of water is not 62% done on a Tuesday afternoon.
--
-- ── Nullable, with no default ──────────────────────────────────────────────
--
-- NULL means "they have not said". A DEFAULT 8 would put the exact bug this
-- replaces back into the database, and make it worse than it was: in the app it
-- was at least visibly a constant, whereas a defaulted column reads to every
-- screen — and to the coach looking at their client — as the client's own
-- answer. Nothing here may invent a figure, so a NULL renders as a prompt to
-- set one and scores as untracked, never as zero glasses and never as eight.
--
-- Bounds, not a default. Wide enough not to argue with anybody's real target —
-- a large person in a hot country genuinely drinks a dozen-plus glasses — and
-- tight enough to catch a fat-fingered 80 or a client typing millilitres into a
-- field asking for glasses.
-- ─────────────────────────────────────────────────────────────────────────

alter table public.clients
  add column if not exists water_goal_glasses int;

alter table public.clients drop constraint if exists clients_water_goal_glasses_check;
alter table public.clients add constraint clients_water_goal_glasses_check
  check (water_goal_glasses is null or (water_goal_glasses >= 1 and water_goal_glasses <= 30));

comment on column public.clients.water_goal_glasses is
  'Daily water target in glasses, set by the client. NULL means they have not set one — never a default.';

-- ▶ exercise-catalogue.sql

-- ─────────────────────────────────────────────────────────────────────────
-- The exercise catalogue: 917 movements, up from 56.
--
-- GENERATED by scripts/build-exercise-catalogue.mjs from the vendored
-- public-domain dataset at data/free-exercise-db.json. Do not hand-edit: the
-- next build overwrites it. Change the generator instead.
--
-- ── What this adds ────────────────────────────────────────────────────────
--
-- The catalogue was 56 rows typed by hand, which is roughly a seventh of
-- what a lifting app is expected to know. An exercise we did not list had no
-- demo, no muscle list and no instructions — it was not a thing to us at all,
-- and a coach who wrote it into a program got nothing on the client's screen.
--
-- Every column beyond the original four carries what a client asks when they
-- do not know a movement: what it works, what equipment it needs, how hard it
-- is, and how to do it.
--
-- ── The 15 rows that were already ours ──────────────────────────────────
--
-- Where a dataset entry has the same slug as one we already ship, our NAME and
-- GROUP win and the rest is enrichment. Programs, focus areas and the
-- progress-photo recommendation map are written against our strings; taking the
-- dataset's spelling would silently unlink them.
--
-- ── The 10 rows the dataset does not have ─────────────────────────────────
--
-- Kept exactly as they were, with no instructions and no images. An honest gap
-- rather than an invented row. Which ones, and what they might map to, is in
-- docs/exercise-mapping-review.tsv — deliberately for a human, because a
-- similarity match paired 'Back Squat' with 'Hack Squat' at 0.90 and
-- 'Hip Abduction' with 'Cable Hip Adduction', the opposite movement.
--
-- ── Images ────────────────────────────────────────────────────────────────
--
-- `image_paths` holds RELATIVE paths into the source repository, not URLs and
-- not blobs. A URL bakes somebody else's uptime into our catalogue, and blobs
-- put 130MB of JPEG into a migration. Whatever serves them — our own bucket, a
-- CDN, or a licensed animation pack that replaces them entirely — resolves
-- these paths at read time, so swapping the media never touches this table.
-- ─────────────────────────────────────────────────────────────────────────

alter table public.exercises add column if not exists category         text;
alter table public.exercises add column if not exists equipment        text;
alter table public.exercises add column if not exists level            text;
alter table public.exercises add column if not exists mechanic         text;
alter table public.exercises add column if not exists force            text;
alter table public.exercises add column if not exists primary_muscles   text[];
alter table public.exercises add column if not exists secondary_muscles text[];
alter table public.exercises add column if not exists instructions      text[];
alter table public.exercises add column if not exists image_paths       text[];
alter table public.exercises add column if not exists source            text;

comment on column public.exercises.image_paths is
  'Relative paths into the source dataset, resolved at read time — never URLs, so the media can be swapped without touching this table.';
comment on column public.exercises.source is
  'Where the row came from: ''repple'' for the hand-written originals, ''free-exercise-db'' for the public-domain import.';

insert into public.exercises
  (id, name, muscle_group, is_cardio, category, equipment, level, mechanic, force,
   primary_muscles, secondary_muscles, instructions, image_paths, source) values
  ('3-4-sit-up', '3/4 Sit-Up', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Lie down on the floor and secure your feet. Your legs should be bent at the knees.', 'Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.', 'Flex your hips and spine to raise your torso toward your knees.', 'At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.', 'Repeat for the recommended amount of repetitions.'], array['3_4_Sit-Up/0.jpg', '3_4_Sit-Up/1.jpg'], 'free-exercise-db'),
  ('90-90-hamstring', '90/90 Hamstring', 'Hamstrings', false, 'stretching', 'body only', 'beginner', null, 'push', array['hamstrings'], array['calves'], array['Lie on your back, with one leg extended straight out.', 'With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.', 'Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.', 'Repeat for 10-20 repetitions, and then switch to the other leg.'], array['90_90_Hamstring/0.jpg', '90_90_Hamstring/1.jpg'], 'free-exercise-db'),
  ('ab-crunch', 'Ab Crunch', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.', 'Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.', 'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.', 'After the one second contraction, begin to come down slowly again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Crunches/0.jpg', 'Crunches/1.jpg'], 'repple+free-exercise-db'),
  ('ab-crunch-machine', 'Ab Crunch Machine', 'Core', false, 'strength', 'machine', 'intermediate', 'isolation', 'pull', array['abdominals'], null, array['Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.', 'At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.', 'After a second pause, slowly return to the starting position as you breathe in.', 'Repeat the movement for the prescribed amount of repetitions.'], array['Ab_Crunch_Machine/0.jpg', 'Ab_Crunch_Machine/1.jpg'], 'free-exercise-db'),
  ('ab-roller', 'Ab Roller', 'Core', false, 'strength', 'other', 'intermediate', 'compound', 'pull', array['abdominals'], array['shoulders'], array['Hold the Ab Roller with both hands and kneel on the floor.', 'Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.'], array['Ab_Roller/0.jpg', 'Ab_Roller/1.jpg'], 'free-exercise-db'),
  ('adductor', 'Adductor', 'Legs', false, 'stretching', 'foam roll', 'intermediate', 'isolation', 'static', array['adductors'], null, array['Lie face down with one leg on a foam roll.', 'Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.', 'While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg.'], array['Adductor/0.jpg', 'Adductor/1.jpg'], 'free-exercise-db'),
  ('adductor-groin', 'Adductor/Groin', 'Legs', false, 'stretching', null, 'intermediate', null, 'static', array['adductors'], null, array['Lie on your back with your feet raised towards the ceiling.', 'Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.', 'Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.', 'Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.'], array['Adductor_Groin/0.jpg', 'Adductor_Groin/1.jpg'], 'free-exercise-db'),
  ('advanced-kettlebell-windmill', 'Advanced Kettlebell Windmill', 'Core', false, 'strength', 'kettlebells', 'intermediate', 'isolation', 'push', array['abdominals'], array['glutes', 'hamstrings', 'shoulders'], array['Clean and press a kettlebell overhead with one arm.', 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.', 'Lower yourself as far as possible.', 'Pause for a second and reverse the motion back to the starting position.'], array['Advanced_Kettlebell_Windmill/0.jpg', 'Advanced_Kettlebell_Windmill/1.jpg'], 'free-exercise-db'),
  ('air-bike', 'Air Bike', 'Full body', true, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.', 'Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.', 'Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.', 'Go back to the initial position as you breathe in.', 'Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.', 'Continue alternating in this manner until all of the recommended repetitions for each side have been completed.'], array['Air_Bike/0.jpg', 'Air_Bike/1.jpg'], 'free-exercise-db'),
  ('all-fours-quad-stretch', 'All Fours Quad Stretch', 'Legs', false, 'stretching', 'body only', 'intermediate', null, 'static', array['quadriceps'], array['quadriceps'], array['Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.', 'Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.', 'Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides.'], array['All_Fours_Quad_Stretch/0.jpg', 'All_Fours_Quad_Stretch/1.jpg'], 'free-exercise-db'),
  ('alternate-hammer-curl', 'Alternate Hammer Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.'], array['Alternate_Hammer_Curl/0.jpg', 'Alternate_Hammer_Curl/1.jpg'], 'free-exercise-db'),
  ('alternate-heel-touchers', 'Alternate Heel Touchers', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.', 'Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.', 'Now go back slowly to the starting position as you inhale.', 'Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.', 'Continue alternating sides in this manner until all prescribed repetitions are done.'], array['Alternate_Heel_Touchers/0.jpg', 'Alternate_Heel_Touchers/1.jpg'], 'free-exercise-db'),
  ('alternate-incline-dumbbell-curl', 'Alternate Incline Dumbbell Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.', 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbell back to starting position as your breathe in.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.'], array['Alternate_Incline_Dumbbell_Curl/0.jpg', 'Alternate_Incline_Dumbbell_Curl/1.jpg'], 'free-exercise-db'),
  ('alternate-leg-diagonal-bound', 'Alternate Leg Diagonal Bound', 'Legs', false, 'plyometrics', null, 'beginner', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings'], array['Assume a comfortable stance with one foot slightly in front of the other.', 'Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.', 'It may help to use a line on the ground to guage distance from side to side.', 'Repeat the sequence with the other leg.'], array['Alternate_Leg_Diagonal_Bound/0.jpg', 'Alternate_Leg_Diagonal_Bound/1.jpg'], 'free-exercise-db'),
  ('alternating-cable-shoulder-press', 'Alternating Cable Shoulder Press', 'Shoulders', false, 'strength', 'cable', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Move the cables to the bottom of the tower and select an appropriate weight.', 'Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.', 'Keeping your head and chest up, extend through the elbow to press one side directly over head.', 'After pausing at the top, return to the starting position and repeat on the opposite side.'], array['Alternating_Cable_Shoulder_Press/0.jpg', 'Alternating_Cable_Shoulder_Press/1.jpg'], 'free-exercise-db'),
  ('alternating-deltoid-raise', 'Alternating Deltoid Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], null, array['In a standing position, hold a pair of dumbbells at your side.', 'Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.', 'Return the weights to your side.', 'On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.', 'Return the weights to the starting position and continue alternating to the front and side.'], array['Alternating_Deltoid_Raise/0.jpg', 'Alternating_Deltoid_Raise/1.jpg'], 'free-exercise-db'),
  ('alternating-floor-press', 'Alternating Floor Press', 'Chest', false, 'strength', 'kettlebells', 'beginner', 'compound', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Lie on the floor with two kettlebells next to your shoulders.', 'Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.', 'Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.', 'Raise the kettlebell and repeat on the opposite side.'], array['Alternating_Floor_Press/0.jpg', 'Alternating_Floor_Press/1.jpg'], 'free-exercise-db'),
  ('alternating-hang-clean', 'Alternating Hang Clean', 'Hamstrings', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['hamstrings'], array['biceps', 'calves', 'forearms', 'glutes', 'lower back', 'traps'], array['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.', 'Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.'], array['Alternating_Hang_Clean/0.jpg', 'Alternating_Hang_Clean/1.jpg'], 'free-exercise-db'),
  ('alternating-kettlebell-press', 'Alternating Kettlebell Press', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.', 'Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .', 'Lower the pressed kettlebell to the starting position and immediately press with your other arm.'], array['Alternating_Kettlebell_Press/0.jpg', 'Alternating_Kettlebell_Press/1.jpg'], 'free-exercise-db'),
  ('alternating-kettlebell-row', 'Alternating Kettlebell Row', 'Back', false, 'strength', 'kettlebells', 'intermediate', 'isolation', 'pull', array['middle back'], array['biceps', 'lats'], array['Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.', 'Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.', 'Lower the kettlebell in the working arm and repeat with your other arm.'], array['Alternating_Kettlebell_Row/0.jpg', 'Alternating_Kettlebell_Row/1.jpg'], 'free-exercise-db'),
  ('alternating-renegade-row', 'Alternating Renegade Row', 'Back', false, 'strength', 'kettlebells', 'expert', 'compound', 'pull', array['middle back'], array['abdominals', 'biceps', 'chest', 'lats', 'triceps'], array['Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.', 'Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.', 'Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps.'], array['Alternating_Renegade_Row/0.jpg', 'Alternating_Renegade_Row/1.jpg'], 'free-exercise-db'),
  ('ankle-circles', 'Ankle Circles', 'Calves', false, 'stretching', null, 'beginner', 'isolation', 'pull', array['calves'], null, array['Use a sturdy object like a squat rack to hold yourself.', 'Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.', 'When you are done with the right foot, then repeat with the left leg.'], array['Ankle_Circles/0.jpg', 'Ankle_Circles/1.jpg'], 'free-exercise-db'),
  ('ankle-on-the-knee', 'Ankle On The Knee', 'Glutes', false, 'stretching', null, 'beginner', null, 'static', array['glutes'], null, array['From a lying position, bend your knees and keep your feet on the floor.', 'Place your ankle of one foot on your opposite knee.', 'Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides.'], array['Ankle_On_The_Knee/0.jpg', 'Ankle_On_The_Knee/1.jpg'], 'free-exercise-db'),
  ('anterior-tibialis-smr', 'Anterior Tibialis-SMR', 'Calves', false, 'stretching', 'other', 'intermediate', null, 'static', array['calves'], null, array['Begin seated on the ground with your legs bent and your feet on the floor.', 'Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg.'], array['Anterior_Tibialis-SMR/0.jpg', 'Anterior_Tibialis-SMR/1.jpg'], 'free-exercise-db'),
  ('anti-gravity-press', 'Anti-Gravity Press', 'Shoulders', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['shoulders'], array['middle back', 'traps', 'triceps'], array['Place a bar on the ground behind the head of an incline bench.', 'Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.', 'To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement.', 'Return to the starting position and repeat to complete the set.'], array['Anti-Gravity_Press/0.jpg', 'Anti-Gravity_Press/1.jpg'], 'free-exercise-db'),
  ('arm-circles', 'Arm Circles', 'Shoulders', false, 'stretching', null, 'beginner', 'isolation', 'push', array['shoulders'], array['traps'], array['Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.', 'Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.', 'Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction.'], array['Arm_Circles/0.jpg', 'Arm_Circles/1.jpg'], 'free-exercise-db'),
  ('arnold-dumbbell-press', 'Arnold Dumbbell Press', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.', 'Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.', 'Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.', 'After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.'], array['Arnold_Dumbbell_Press/0.jpg', 'Arnold_Dumbbell_Press/1.jpg'], 'free-exercise-db'),
  ('around-the-worlds', 'Around The Worlds', 'Chest', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['chest'], array['shoulders'], array['Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.', 'Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.', 'Reverse the movement to return the weight to the starting position as you exhale.'], array['Around_The_Worlds/0.jpg', 'Around_The_Worlds/1.jpg'], 'free-exercise-db'),
  ('assisted-pull-up', 'Assisted Pull-up', 'Back', false, 'strength', 'other', 'beginner', 'compound', null, array['lats'], array['abdominals', 'forearms', 'middle back'], array['Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.', 'Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.', 'Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.', 'After a brief pause, return to the starting position.'], array['Band_Assisted_Pull-Up/0.jpg', 'Band_Assisted_Pull-Up/1.jpg'], 'repple+free-exercise-db'),
  ('atlas-stone-trainer', 'Atlas Stone Trainer', 'Lower back', false, 'strongman', 'other', 'intermediate', 'compound', 'pull', array['lower back'], array['biceps', 'forearms', 'glutes', 'hamstrings', 'quadriceps'], array['This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe.', 'Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips.', 'Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest.', 'Finish the movement by extending through your hips and knees to raise the weight as high as possible. The weight can be returned to the lap or to the ground for successive repetitions.'], array['Atlas_Stone_Trainer/0.jpg', 'Atlas_Stone_Trainer/1.jpg'], 'free-exercise-db'),
  ('atlas-stones', 'Atlas Stones', 'Lower back', false, 'strongman', 'other', 'expert', 'compound', 'pull', array['lower back'], array['abdominals', 'adductors', 'biceps', 'calves', 'forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps'], array['Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.', 'Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.', 'As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.', 'Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible.'], array['Atlas_Stones/0.jpg', 'Atlas_Stones/1.jpg'], 'free-exercise-db'),
  ('axle-deadlift', 'Axle Deadlift', 'Lower back', false, 'strongman', 'other', 'intermediate', 'compound', 'pull', array['lower back'], array['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps'], array['Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.', 'With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.', 'After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.'], array['Axle_Deadlift/0.jpg', 'Axle_Deadlift/1.jpg'], 'free-exercise-db'),
  ('back-extension', 'Back Extension', 'Lower back', false, 'strength', 'other', 'beginner', 'isolation', 'pull', array['lower back'], array['glutes', 'hamstrings'], array['Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.', 'Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.', 'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.', 'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.', 'Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.', 'Repeat for the recommended amount of repetitions.'], array['Hyperextensions_Back_Extensions/0.jpg', 'Hyperextensions_Back_Extensions/1.jpg'], 'repple+free-exercise-db'),
  ('back-flyes-with-bands', 'Back Flyes - With Bands', 'Shoulders', false, 'strength', 'bands', 'beginner', 'compound', 'pull', array['shoulders'], array['middle back', 'triceps'], array['Run a band around a stationary post like that of a squat rack.', 'Grab the band by the handles and stand back so that the tension in the band rises.', 'Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.', 'As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.', 'After a pause, go back to the original position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Back_Flyes_-_With_Bands/0.jpg', 'Back_Flyes_-_With_Bands/1.jpg'], 'free-exercise-db'),
  ('back-squat', 'Back Squat', 'Legs', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Squat/0.jpg', 'Barbell_Squat/1.jpg'], 'repple+free-exercise-db'),
  ('backward-drag', 'Backward Drag', 'Legs', false, 'strongman', 'other', 'beginner', 'compound', 'pull', array['quadriceps'], array['calves', 'forearms', 'glutes', 'hamstrings', 'lower back'], array['Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.', 'Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible.'], array['Backward_Drag/0.jpg', 'Backward_Drag/1.jpg'], 'free-exercise-db'),
  ('backward-medicine-ball-throw', 'Backward Medicine Ball Throw', 'Shoulders', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'push', array['shoulders'], null, array['This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.', 'Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.', 'Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.', 'Your partner can then roll the ball back to you. Repeat for the desired number of repetitions.'], array['Backward_Medicine_Ball_Throw/0.jpg', 'Backward_Medicine_Ball_Throw/1.jpg'], 'free-exercise-db'),
  ('balance-board', 'Balance Board', 'Calves', false, 'strength', 'other', 'beginner', 'compound', null, array['calves'], array['hamstrings', 'quadriceps'], array['Place a balance board in front of you.', 'Stand up on it and try to balance yourself.', 'Hold the balance for as long as desired.'], array['Balance_Board/0.jpg', 'Balance_Board/1.jpg'], 'free-exercise-db'),
  ('ball-leg-curl', 'Ball Leg Curl', 'Hamstrings', false, 'strength', 'exercise ball', 'beginner', 'isolation', 'pull', array['hamstrings'], array['calves', 'glutes'], array['Begin on the floor laying on your back with your feet on top of the ball.', 'Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.', 'Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.', 'Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.', 'After a brief pause, return to the starting position.'], array['Ball_Leg_Curl/0.jpg', 'Ball_Leg_Curl/1.jpg'], 'free-exercise-db'),
  ('band-assisted-pull-up', 'Band Assisted Pull-Up', 'Back', false, 'strength', 'other', 'beginner', 'compound', null, array['lats'], array['abdominals', 'forearms', 'middle back'], array['Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.', 'Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.', 'Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.', 'After a brief pause, return to the starting position.'], array['Band_Assisted_Pull-Up/0.jpg', 'Band_Assisted_Pull-Up/1.jpg'], 'free-exercise-db'),
  ('band-good-morning', 'Band Good Morning', 'Hamstrings', false, 'powerlifting', 'bands', 'beginner', 'compound', 'pull', array['hamstrings'], array['glutes', 'lower back'], array['Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.', 'Keeping your legs straight, extend through the hips to come to a near vertical position.', 'Ensure that you do not round your back as you go down back to the starting position.'], array['Band_Good_Morning/0.jpg', 'Band_Good_Morning/1.jpg'], 'free-exercise-db'),
  ('band-good-morning-pull-through', 'Band Good Morning (Pull Through)', 'Hamstrings', false, 'powerlifting', 'bands', 'beginner', 'compound', 'pull', array['hamstrings'], array['glutes', 'lower back'], array['Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.', 'Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.', 'Return to the starting position be driving through with the hips to come back to a standing position.'], array['Band_Good_Morning_Pull_Through/0.jpg', 'Band_Good_Morning_Pull_Through/1.jpg'], 'free-exercise-db'),
  ('band-hip-adductions', 'Band Hip Adductions', 'Legs', false, 'strength', 'bands', 'beginner', 'isolation', 'pull', array['adductors'], null, array['Anchor a band around a solid post or other object.', 'Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.', 'Stand up straight and hold onto the post if needed. This will be your starting position.', 'Keeping the knee straight, raise your right legs out to the side as far as you can.', 'Return to the starting position and repeat for the desired rep count.', 'Switch sides.'], array['Band_Hip_Adductions/0.jpg', 'Band_Hip_Adductions/1.jpg'], 'free-exercise-db'),
  ('band-pull-apart', 'Band Pull Apart', 'Shoulders', false, 'strength', 'bands', 'beginner', 'isolation', 'pull', array['shoulders'], array['middle back', 'traps'], array['Begin with your arms extended straight out in front of you, holding the band with both hands.', 'Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.', 'Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.', 'Pause as you complete the movement, returning to the starting position under control.'], array['Band_Pull_Apart/0.jpg', 'Band_Pull_Apart/1.jpg'], 'free-exercise-db'),
  ('band-skull-crusher', 'Band Skull Crusher', 'Arms', false, 'strength', 'bands', 'beginner', 'isolation', 'push', array['triceps'], null, array['Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.', 'Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.', 'Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.'], array['Band_Skull_Crusher/0.jpg', 'Band_Skull_Crusher/1.jpg'], 'free-exercise-db'),
  ('barbell-ab-rollout', 'Barbell Ab Rollout', 'Core', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['abdominals'], array['lower back', 'shoulders'], array['For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.', 'While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.', 'After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Ab_Rollout/0.jpg', 'Barbell_Ab_Rollout/1.jpg'], 'free-exercise-db'),
  ('barbell-ab-rollout-on-knees', 'Barbell Ab Rollout - On Knees', 'Core', false, 'strength', 'barbell', 'expert', 'compound', 'pull', array['abdominals'], array['lower back', 'shoulders'], array['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.', 'Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.'], array['Barbell_Ab_Rollout_-_On_Knees/0.jpg', 'Barbell_Ab_Rollout_-_On_Knees/1.jpg'], 'free-exercise-db'),
  ('barbell-bench-press-medium-grip', 'Barbell Bench Press - Medium Grip', 'Chest', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.', 'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.'], array['Barbell_Bench_Press_-_Medium_Grip/0.jpg', 'Barbell_Bench_Press_-_Medium_Grip/1.jpg'], 'free-exercise-db'),
  ('barbell-curl', 'Barbell Curl', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Curl/0.jpg', 'Barbell_Curl/1.jpg'], 'free-exercise-db'),
  ('barbell-curls-lying-against-an-incline', 'Barbell Curls Lying Against An Incline', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.', 'While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.', 'After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Curls_Lying_Against_An_Incline/0.jpg', 'Barbell_Curls_Lying_Against_An_Incline/1.jpg'], 'free-exercise-db'),
  ('barbell-deadlift', 'Barbell Deadlift', 'Lower back', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['lower back'], array['calves', 'forearms', 'glutes', 'hamstrings', 'lats', 'middle back', 'quadriceps', 'traps'], array['Stand in front of a loaded barbell.', 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.', 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.', 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.', 'Perform the amount of repetitions prescribed in the program.'], array['Barbell_Deadlift/0.jpg', 'Barbell_Deadlift/1.jpg'], 'free-exercise-db'),
  ('barbell-full-squat', 'Barbell Full Squat', 'Legs', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.', 'Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Full_Squat/0.jpg', 'Barbell_Full_Squat/1.jpg'], 'free-exercise-db'),
  ('barbell-glute-bridge', 'Barbell Glute Bridge', 'Glutes', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['glutes'], array['calves', 'hamstrings'], array['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.', 'Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.', 'Extend as far as possible, then reverse the motion to return to the starting position.'], array['Barbell_Glute_Bridge/0.jpg', 'Barbell_Glute_Bridge/1.jpg'], 'free-exercise-db'),
  ('barbell-guillotine-bench-press', 'Barbell Guillotine Bench Press', 'Chest', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.', 'As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.'], array['Barbell_Guillotine_Bench_Press/0.jpg', 'Barbell_Guillotine_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('barbell-hack-squat', 'Barbell Hack Squat', 'Legs', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'forearms', 'hamstrings'], array['Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', 'While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.', 'Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Hack_Squat/0.jpg', 'Barbell_Hack_Squat/1.jpg'], 'free-exercise-db'),
  ('barbell-hip-thrust', 'Barbell Hip Thrust', 'Glutes', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['glutes'], array['calves', 'hamstrings'], array['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.', 'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.', 'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.'], array['Barbell_Hip_Thrust/0.jpg', 'Barbell_Hip_Thrust/1.jpg'], 'free-exercise-db'),
  ('barbell-incline-bench-press-medium-grip', 'Barbell Incline Bench Press - Medium Grip', 'Chest', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on you upper chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.'], array['Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg', 'Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg'], 'free-exercise-db'),
  ('barbell-incline-shoulder-raise', 'Barbell Incline Shoulder Raise', 'Shoulders', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['shoulders'], array['chest'], array['Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.', 'While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.', 'Bring back the bar to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Incline_Shoulder_Raise/0.jpg', 'Barbell_Incline_Shoulder_Raise/1.jpg'], 'free-exercise-db'),
  ('barbell-lunge', 'Barbell Lunge', 'Legs', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.'], array['Barbell_Lunge/0.jpg', 'Barbell_Lunge/1.jpg'], 'free-exercise-db'),
  ('barbell-rear-delt-row', 'Barbell Rear Delt Row', 'Shoulders', false, 'strength', 'barbell', 'beginner', 'compound', 'pull', array['shoulders'], array['biceps', 'lats', 'middle back'], array['Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.', 'Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter "T". Now you are ready to begin the exercise.', 'While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.', 'Slowly go back to the initial position as you breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Rear_Delt_Row/0.jpg', 'Barbell_Rear_Delt_Row/1.jpg'], 'free-exercise-db'),
  ('barbell-rollout-from-bench', 'Barbell Rollout from Bench', 'Core', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['abdominals'], array['glutes', 'hamstrings', 'lats', 'shoulders'], array['Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.', 'To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.', 'When the bar has been moved as far forward as possible, return to the starting position.'], array['Barbell_Rollout_from_Bench/0.jpg', 'Barbell_Rollout_from_Bench/1.jpg'], 'free-exercise-db'),
  ('barbell-seated-calf-raise', 'Barbell Seated Calf Raise', 'Calves', false, 'strength', 'barbell', 'beginner', 'isolation', 'push', array['calves'], null, array['Place a block about 12 inches in front of a flat bench.', 'Sit on the bench and place the ball of your feet on the block.', 'Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.', 'Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.', 'After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Seated_Calf_Raise/0.jpg', 'Barbell_Seated_Calf_Raise/1.jpg'], 'free-exercise-db'),
  ('barbell-shoulder-press', 'Barbell Shoulder Press', 'Shoulders', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['shoulders'], array['chest', 'triceps'], array['Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).', 'Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the shoulders slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Shoulder_Press/0.jpg', 'Barbell_Shoulder_Press/1.jpg'], 'free-exercise-db'),
  ('barbell-shrug', 'Barbell Shrug', 'Back', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['traps'], null, array['Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Shrug/0.jpg', 'Barbell_Shrug/1.jpg'], 'free-exercise-db'),
  ('barbell-shrug-behind-the-back', 'Barbell Shrug Behind The Back', 'Back', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['traps'], array['forearms', 'middle back'], array['Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.', 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Shrug_Behind_The_Back/0.jpg', 'Barbell_Shrug_Behind_The_Back/1.jpg'], 'free-exercise-db'),
  ('barbell-side-bend', 'Barbell Side Bend', 'Core', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['abdominals'], array['lower back'], array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.', 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.', 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Side_Bend/0.jpg', 'Barbell_Side_Bend/1.jpg'], 'free-exercise-db'),
  ('barbell-side-split-squat', 'Barbell Side Split Squat', 'Legs', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'hamstrings', 'lower back'], array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.', 'Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.', 'Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.', 'After performing the recommended amount of reps, repeat the movement with the opposite leg.'], array['Barbell_Side_Split_Squat/0.jpg', 'Barbell_Side_Split_Squat/1.jpg'], 'free-exercise-db'),
  ('barbell-squat', 'Barbell Squat', 'Legs', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Squat/0.jpg', 'Barbell_Squat/1.jpg'], 'free-exercise-db'),
  ('barbell-squat-to-a-bench', 'Barbell Squat To A Bench', 'Legs', false, 'strength', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.', '', 'Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Barbell_Squat_To_A_Bench/0.jpg', 'Barbell_Squat_To_A_Bench/1.jpg'], 'free-exercise-db'),
  ('barbell-step-ups', 'Barbell Step Ups', 'Legs', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'quadriceps'], array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.'], array['Barbell_Step_Ups/0.jpg', 'Barbell_Step_Ups/1.jpg'], 'free-exercise-db'),
  ('barbell-walking-lunge', 'Barbell Walking Lunge', 'Legs', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Begin standing with your feet shoulder width apart and a barbell across your upper back.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.'], array['Barbell_Walking_Lunge/0.jpg', 'Barbell_Walking_Lunge/1.jpg'], 'free-exercise-db'),
  ('battling-ropes', 'Battling Ropes', 'Shoulders', false, 'strength', 'other', 'beginner', 'compound', 'push', array['shoulders'], array['chest', 'forearms'], array['For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.', 'Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.', 'As you let that arm drop to the starting position, raise the opposite side.', 'Continue alternating your left and right arms, whipping the ropes up and down as fast as you can.'], array['Battling_Ropes/0.jpg', 'Battling_Ropes/1.jpg'], 'free-exercise-db'),
  ('bear-crawl-sled-drags', 'Bear Crawl Sled Drags', 'Legs', false, 'strongman', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Wearing either a harness or a loose weight belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that your hands are on the ground. Your back should be flat and knees bent. This is your starting position.', 'Begin by driving with legs, alternating left and right. Use your hands to maintain balance and to help pull. Try to keep your back flat as you move over a given distance.'], array['Bear_Crawl_Sled_Drags/0.jpg', 'Bear_Crawl_Sled_Drags/1.jpg'], 'free-exercise-db'),
  ('behind-head-chest-stretch', 'Behind Head Chest Stretch', 'Chest', false, 'stretching', 'other', 'expert', 'isolation', 'static', array['chest'], array['shoulders'], array['Sit upright on the floor with your partner behind you.', 'Place your hands behind your hand, and push your elbows back as far as you can. Your partner should hold your elbows. This will be your starting position.', 'Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds. Your partner should prevent your elbows from moving.', 'Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.'], array['Behind_Head_Chest_Stretch/0.jpg', 'Behind_Head_Chest_Stretch/1.jpg'], 'free-exercise-db'),
  ('bench-dips', 'Bench Dips', 'Arms', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.', 'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.', 'Using your triceps to bring your torso up again, lift yourself back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Bench_Dips/0.jpg', 'Bench_Dips/1.jpg'], 'free-exercise-db'),
  ('bench-jump', 'Bench Jump', 'Legs', false, 'plyometrics', 'body only', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.', 'Perform a short squat in preparation for the jump; swing your arms behind you.', 'Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.', 'Jump over the bench, landing with the knees bent, absorbing the impact through the legs.', 'Turn around and face the opposite direction, then jump back over the bench.'], array['Bench_Jump/0.jpg', 'Bench_Jump/1.jpg'], 'free-exercise-db'),
  ('bench-press', 'Bench Press', 'Chest', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.', 'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.'], array['Barbell_Bench_Press_-_Medium_Grip/0.jpg', 'Barbell_Bench_Press_-_Medium_Grip/1.jpg'], 'repple+free-exercise-db'),
  ('bench-press-powerlifting', 'Bench Press - Powerlifting', 'Arms', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'forearms', 'lats', 'shoulders'], array['Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', 'However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.', 'Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.', 'Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.'], array['Bench_Press_-_Powerlifting/0.jpg', 'Bench_Press_-_Powerlifting/1.jpg'], 'free-exercise-db'),
  ('bench-press-with-bands', 'Bench Press - With Bands', 'Chest', false, 'strength', 'bands', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Using a flat bench secure a band under the leg of the bench that is nearest to your head.', 'Once the band is secure, grab it by both handles and lie down on the bench.', 'Extend your arms so that you are holding the band handles in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.', 'As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.'], array['Bench_Press_-_With_Bands/0.jpg', 'Bench_Press_-_With_Bands/1.jpg'], 'free-exercise-db'),
  ('bench-press-with-chains', 'Bench Press with Chains', 'Arms', false, 'powerlifting', 'barbell', 'expert', 'compound', 'push', array['triceps'], array['chest', 'lats', 'shoulders'], array['Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.', 'Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.', 'Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.', 'Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.'], array['Bench_Press_with_Chains/0.jpg', 'Bench_Press_with_Chains/1.jpg'], 'free-exercise-db'),
  ('bench-sprint', 'Bench Sprint', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Stand on the ground with one foot resting on a bench or box with your heel close to the edge.', 'Push off with your foot on top of the bench, extending through the hip and knee.', 'Land with the opposite foot on top of the box, returning your other foot back to the start position.', 'Continue alternating from one foot to another to complete the set.'], array['Bench_Sprint/0.jpg', 'Bench_Sprint/1.jpg'], 'free-exercise-db'),
  ('bent-arm-barbell-pullover', 'Bent-Arm Barbell Pullover', 'Back', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['lats'], array['chest', 'lats', 'shoulders', 'triceps'], array['Lie on a flat bench with a barbell using a shoulder grip width.', 'Hold the bar straight over your chest with a bend in your arms. This will be your starting position.', 'While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.', 'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.'], array['Bent-Arm_Barbell_Pullover/0.jpg', 'Bent-Arm_Barbell_Pullover/1.jpg'], 'free-exercise-db'),
  ('bent-arm-dumbbell-pullover', 'Bent-Arm Dumbbell Pullover', 'Chest', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['chest'], array['lats', 'shoulders', 'triceps'], array['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.', 'Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.', 'While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.', 'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.'], array['Bent-Arm_Dumbbell_Pullover/0.jpg', 'Bent-Arm_Dumbbell_Pullover/1.jpg'], 'free-exercise-db'),
  ('bent-knee-hip-raise', 'Bent-Knee Hip Raise', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Lay flat on the floor with your arms next to your sides.', 'Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.', 'Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.', 'Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.', 'Repeat for the recommended amount of repetitions.'], array['Bent-Knee_Hip_Raise/0.jpg', 'Bent-Knee_Hip_Raise/1.jpg'], 'free-exercise-db'),
  ('bent-over-barbell-row', 'Bent Over Barbell Row', 'Back', false, 'strength', 'barbell', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats', 'shoulders'], array['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.', 'Then inhale and slowly lower the barbell back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Bent_Over_Barbell_Row/0.jpg', 'Bent_Over_Barbell_Row/1.jpg'], 'free-exercise-db'),
  ('bent-over-dumbbell-rear-delt-raise-with-head-on-bench', 'Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['shoulders'], null, array['Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.', 'While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.', 'Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.', 'After a one second contraction at the top, slowly lower the dumbbells back to the starting position.', 'Repeat the recommended amount of repetitions.'], array['Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg', 'Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/1.jpg'], 'free-exercise-db'),
  ('bent-over-low-pulley-side-lateral', 'Bent Over Low-Pulley Side Lateral', 'Shoulders', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['shoulders'], array['lower back', 'middle back', 'traps'], array['Select a weight and hold the handle of the low pulley with your right hand.', 'Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.', 'Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.', 'Slowly lower the weight back to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions and repeat the movement with the other arm.'], array['Bent_Over_Low-Pulley_Side_Lateral/0.jpg', 'Bent_Over_Low-Pulley_Side_Lateral/1.jpg'], 'free-exercise-db'),
  ('bent-over-one-arm-long-bar-row', 'Bent Over One-Arm Long Bar Row', 'Back', false, 'strength', 'barbell', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats', 'lower back', 'traps'], array['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.', 'Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.', 'Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.', 'Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.', 'Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).', 'Repeat for the recommended amount of repetitions and switch arms.'], array['Bent_Over_One-Arm_Long_Bar_Row/0.jpg', 'Bent_Over_One-Arm_Long_Bar_Row/1.jpg'], 'free-exercise-db'),
  ('bent-over-row', 'Bent-over Row', 'Back', false, 'strength', 'barbell', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats', 'shoulders'], array['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.', 'Then inhale and slowly lower the barbell back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Bent_Over_Barbell_Row/0.jpg', 'Bent_Over_Barbell_Row/1.jpg'], 'repple+free-exercise-db'),
  ('bent-over-two-arm-long-bar-row', 'Bent Over Two-Arm Long Bar Row', 'Back', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.', 'Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.', 'Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.', 'Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Use a stirrup or double handle cable attachment by hooking it under the end of the bar.', 'Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).', 'Repeat for the recommended amount of repetitions.'], array['Bent_Over_Two-Arm_Long_Bar_Row/0.jpg', 'Bent_Over_Two-Arm_Long_Bar_Row/1.jpg'], 'free-exercise-db'),
  ('bent-over-two-dumbbell-row', 'Bent Over Two-Dumbbell Row', 'Back', false, 'strength', 'dumbbell', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats', 'shoulders'], array['With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Bent_Over_Two-Dumbbell_Row/0.jpg', 'Bent_Over_Two-Dumbbell_Row/1.jpg'], 'free-exercise-db'),
  ('bent-over-two-dumbbell-row-with-palms-in', 'Bent Over Two-Dumbbell Row With Palms In', 'Back', false, 'strength', 'dumbbell', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg', 'Bent_Over_Two-Dumbbell_Row_With_Palms_In/1.jpg'], 'free-exercise-db'),
  ('bent-press', 'Bent Press', 'Core', false, 'strength', 'kettlebells', 'expert', 'compound', 'pull', array['abdominals'], array['glutes', 'hamstrings', 'lower back', 'quadriceps', 'shoulders', 'triceps'], array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.', 'Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.', 'Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions.'], array['Bent_Press/0.jpg', 'Bent_Press/1.jpg'], 'free-exercise-db'),
  ('bicep-curl', 'Bicep Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Dumbbell_Bicep_Curl/0.jpg', 'Dumbbell_Bicep_Curl/1.jpg'], 'repple+free-exercise-db'),
  ('bicycling', 'Bicycling', 'Legs', true, 'cardio', 'other', 'beginner', null, null, array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, seat yourself on the bike and adjust the seat to your height.'], array['Bicycling/0.jpg', 'Bicycling/1.jpg'], 'free-exercise-db'),
  ('bicycling-stationary', 'Bicycling, Stationary', 'Legs', true, 'cardio', 'machine', 'beginner', null, null, array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, seat yourself on the bike and adjust the seat to your height.', 'Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.'], array['Bicycling_Stationary/0.jpg', 'Bicycling_Stationary/1.jpg'], 'free-exercise-db'),
  ('board-press', 'Board Press', 'Arms', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'forearms', 'lats', 'shoulders'], array['Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.', 'Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', 'You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.', 'Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.'], array['Board_Press/0.jpg', 'Board_Press/1.jpg'], 'free-exercise-db'),
  ('body-tricep-press', 'Body Tricep Press', 'Arms', false, 'strength', 'body only', 'beginner', 'isolation', 'push', array['triceps'], null, array['Position a bar in a rack at chest height.', 'Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.', 'Begin by flexing the elbow, lowering yourself towards the bar.', 'Pause, and then reverse the motion by extending the elbows.', 'Progress from bodyweight by adding chains over your shoulders.'], array['Body_Tricep_Press/0.jpg', 'Body_Tricep_Press/1.jpg'], 'free-exercise-db'),
  ('body-up', 'Body-Up', 'Arms', false, 'strength', 'body only', 'intermediate', 'isolation', 'push', array['triceps'], array['abdominals', 'forearms'], array['Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.', 'Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.', 'Slowly lower your forearms back to the ground by allowing the elbows to flex.', 'Repeat.'], array['Body-Up/0.jpg', 'Body-Up/1.jpg'], 'free-exercise-db'),
  ('bodyweight-flyes', 'Bodyweight Flyes', 'Chest', false, 'strength', 'e-z curl bar', 'intermediate', 'isolation', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.', 'Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.', 'Place your hands on the bars. This will be your starting position.', 'Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.', 'After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement.'], array['Bodyweight_Flyes/0.jpg', 'Bodyweight_Flyes/1.jpg'], 'free-exercise-db'),
  ('bodyweight-mid-row', 'Bodyweight Mid Row', 'Back', false, 'strength', 'other', 'intermediate', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.', 'Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.', 'After a brief pause, return to the starting position.'], array['Bodyweight_Mid_Row/0.jpg', 'Bodyweight_Mid_Row/1.jpg'], 'free-exercise-db'),
  ('bodyweight-squat', 'Bodyweight Squat', 'Legs', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['quadriceps'], array['glutes', 'hamstrings'], array['Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.', 'Begin the movement by flexing your knees and hips, sitting back with your hips.', 'Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.'], array['Bodyweight_Squat/0.jpg', 'Bodyweight_Squat/1.jpg'], 'free-exercise-db'),
  ('bodyweight-walking-lunge', 'Bodyweight Walking Lunge', 'Legs', false, 'strength', null, 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Begin standing with your feet shoulder width apart and your hands on your hips.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.'], array['Bodyweight_Walking_Lunge/0.jpg', 'Bodyweight_Walking_Lunge/1.jpg'], 'free-exercise-db'),
  ('bosu-ball-cable-crunch-with-side-bends', 'Bosu Ball Cable Crunch With Side Bends', 'Core', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Connect a standard handle to each arm of a cable machine, and position them in the most downward position.', 'Grab a Bosu Ball and position it in front and center of the cable machine.', 'Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.', 'With both hands, reach back and grab the handle of each cable.', 'With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.', 'Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.', 'Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.', 'Repeat the same series of movements to failure.', 'Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.', 'Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques.'], array['Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg', 'Bosu_Ball_Cable_Crunch_With_Side_Bends/1.jpg'], 'free-exercise-db'),
  ('bottoms-up', 'Bottoms Up', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.', 'To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.', 'After a brief pause, return to the starting position.'], array['Bottoms_Up/0.jpg', 'Bottoms_Up/1.jpg'], 'free-exercise-db'),
  ('bottoms-up-clean-from-the-hang-position', 'Bottoms-Up Clean From The Hang Position', 'Arms', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['forearms'], array['biceps', 'shoulders'], array['Initiate the exercise by standing upright with a kettlebell in one hand.', 'Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.'], array['Bottoms-Up_Clean_From_The_Hang_Position/0.jpg', 'Bottoms-Up_Clean_From_The_Hang_Position/1.jpg'], 'free-exercise-db'),
  ('box-jump-multiple-response', 'Box Jump (Multiple Response)', 'Hamstrings', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['hamstrings'], array['abductors', 'adductors', 'calves', 'glutes', 'quadriceps'], array['Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent.', 'Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.', 'Immediately drop or jump back down to the original starting place; then repeat the sequence.'], array['Box_Jump_Multiple_Response/0.jpg', 'Box_Jump_Multiple_Response/1.jpg'], 'free-exercise-db'),
  ('box-skip', 'Box Skip', 'Hamstrings', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['hamstrings'], array['abductors', 'adductors', 'calves', 'glutes', 'quadriceps'], array['You will need several boxes lined up about 8 feet apart.', 'Begin facing the first box with one leg slightly behind the other.', 'Drive off the back leg, attempting to gain as much height with the hips as possible.', 'Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.', 'Then, step to the next box and repeat.'], array['Box_Skip/0.jpg', 'Box_Skip/1.jpg'], 'free-exercise-db'),
  ('box-squat', 'Box Squat', 'Legs', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['adductors', 'calves', 'glutes', 'hamstrings', 'lower back'], array['The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.'], array['Box_Squat/0.jpg', 'Box_Squat/1.jpg'], 'free-exercise-db'),
  ('box-squat-with-bands', 'Box Squat with Bands', 'Legs', false, 'powerlifting', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings', 'lower back'], array['Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don''t move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.'], array['Box_Squat_with_Bands/0.jpg', 'Box_Squat_with_Bands/1.jpg'], 'free-exercise-db'),
  ('box-squat-with-chains', 'Box Squat with Chains', 'Legs', false, 'strength', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings', 'lower back'], array['Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.', 'To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.'], array['Box_Squat_with_Chains/0.jpg', 'Box_Squat_with_Chains/1.jpg'], 'free-exercise-db'),
  ('brachialis-smr', 'Brachialis-SMR', 'Arms', false, 'stretching', 'foam roll', 'intermediate', null, 'static', array['biceps'], null, array['Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.', 'Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides.'], array['Brachialis-SMR/0.jpg', 'Brachialis-SMR/1.jpg'], 'free-exercise-db'),
  ('bradford-rocky-presses', 'Bradford/Rocky Presses', 'Shoulders', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position.', 'Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms.', 'Now lower the bar down to the back of the head slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Lower the bar down to the starting position slowly as you inhale. This is one repetition.', 'Alternate in this manner until you complete the recommended amount of repetitions.'], array['Bradford_Rocky_Presses/0.jpg', 'Bradford_Rocky_Presses/1.jpg'], 'free-exercise-db'),
  ('bulgarian-split-squat', 'Bulgarian Split Squat', 'Legs', false, null, null, null, null, null, null, null, null, null, 'repple'),
  ('butt-lift-bridge', 'Butt Lift (Bridge)', 'Glutes', false, 'strength', 'body only', 'beginner', 'isolation', 'push', array['glutes'], array['hamstrings'], array['Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.', 'Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.', 'Slowly go back to the starting position as you breathe in.'], array['Butt_Lift_Bridge/0.jpg', 'Butt_Lift_Bridge/1.jpg'], 'free-exercise-db'),
  ('butt-ups', 'Butt-Ups', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle.', 'Arch your back slightly out rather than keeping your back completely straight.', 'Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of the movement.', 'Lower back down slowly to your starting position as you breathe in. Tip: Don''t let your back sag downwards.', 'Repeat for the recommended amount of repetitions.'], array['Butt-Ups/0.jpg', 'Butt-Ups/1.jpg'], 'free-exercise-db'),
  ('butterfly', 'Butterfly', 'Chest', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['chest'], null, array['Sit on the machine with your back flat on the pad.', 'Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.', 'Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.', 'Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.', 'Repeat for the recommended amount of repetitions.'], array['Butterfly/0.jpg', 'Butterfly/1.jpg'], 'free-exercise-db'),
  ('cable-chest-press', 'Cable Chest Press', 'Chest', false, 'strength', 'cable', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.', 'After pausing at full extension, return to th starting position, keeping tension on the cables.', 'You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands.'], array['Cable_Chest_Press/0.jpg', 'Cable_Chest_Press/1.jpg'], 'free-exercise-db'),
  ('cable-crossover', 'Cable Crossover', 'Chest', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['chest'], array['shoulders'], array['To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.', 'Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.'], array['Cable_Crossover/0.jpg', 'Cable_Crossover/1.jpg'], 'free-exercise-db'),
  ('cable-crunch', 'Cable Crunch', 'Core', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Kneel below a high pulley that contains a rope attachment.', 'Grasp cable rope attachment and lower the rope until your hands are placed next to your face.', 'Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.', 'With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.', 'Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.', 'Repeat for the recommended amount of repetitions.'], array['Cable_Crunch/0.jpg', 'Cable_Crunch/1.jpg'], 'free-exercise-db'),
  ('cable-deadlifts', 'Cable Deadlifts', 'Legs', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['quadriceps'], array['forearms', 'glutes', 'hamstrings', 'lower back'], array['Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.', 'To begin, squat down be flexing your hips and knees until you can reach the handles.', 'After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.', 'After reaching a full standing position, Return to the starting position and repeat.'], array['Cable_Deadlifts/0.jpg', 'Cable_Deadlifts/1.jpg'], 'free-exercise-db'),
  ('cable-hammer-curls-rope-attachment', 'Cable Hammer Curls - Rope Attachment', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.', 'Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.', 'Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.', 'Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.', 'After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.', 'Repeat for the recommended amount of repetitions.'], array['Cable_Hammer_Curls_-_Rope_Attachment/0.jpg', 'Cable_Hammer_Curls_-_Rope_Attachment/1.jpg'], 'free-exercise-db'),
  ('cable-hip-adduction', 'Cable Hip Adduction', 'Legs', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['quadriceps'], null, array['Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.', 'Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.', 'Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.', 'Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.', 'Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg.'], array['Cable_Hip_Adduction/0.jpg', 'Cable_Hip_Adduction/1.jpg'], 'free-exercise-db'),
  ('cable-incline-pushdown', 'Cable Incline Pushdown', 'Back', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['lats'], null, array['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.', 'Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position.', 'Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the movement.', 'Slowly go back to the starting position using your lats and hold the contraction once you reach the starting position. Breathe out during the execution of this movement.', 'Repeat for the recommended amount of repetitions.'], array['Cable_Incline_Pushdown/0.jpg', 'Cable_Incline_Pushdown/1.jpg'], 'free-exercise-db'),
  ('cable-incline-triceps-extension', 'Cable Incline Triceps Extension', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.', 'Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.', 'Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.', 'Slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Cable_Incline_Triceps_Extension/0.jpg', 'Cable_Incline_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('cable-internal-rotation', 'Cable Internal Rotation', 'Shoulders', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['shoulders'], null, array['Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead.', 'Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.', 'Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times.', 'Slowly go back to the initial position.', 'Repeat for the recommended amount of repetitions and then repeat the movement with the next arm.'], array['Cable_Internal_Rotation/0.jpg', 'Cable_Internal_Rotation/1.jpg'], 'free-exercise-db'),
  ('cable-iron-cross', 'Cable Iron Cross', 'Chest', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['chest'], null, array['Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.', 'Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a "T". This will be your starting position.', 'Keeping the elbows extended, pull your arms straight to your sides.', 'Return your arms back to the starting position after a pause at the peak contraction.', 'Continue the movement for the prescribed number of repetitions.'], array['Cable_Iron_Cross/0.jpg', 'Cable_Iron_Cross/1.jpg'], 'free-exercise-db'),
  ('cable-judo-flip', 'Cable Judo Flip', 'Core', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands.', 'Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip.', 'Shift your weight between your feet as you twist and crunch forward, pulling the cable downward.', 'Return to the starting position and repeat until failure.', 'Then, reposition and repeat the same series of movements on the opposite side.'], array['Cable_Judo_Flip/0.jpg', 'Cable_Judo_Flip/1.jpg'], 'free-exercise-db'),
  ('cable-kickback', 'Cable Kickback', 'Glutes', false, 'strength', 'cable', 'intermediate', 'isolation', 'push', array['glutes'], array['hamstrings'], array['Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.', 'Face the weight stack from a distance of about two feet, grasping the steel frame for support.', 'While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.', 'Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.', 'Repeat for the recommended amount of repetitions.', 'Switch legs and repeat the movement for the other side.'], array['One-Legged_Cable_Kickback/0.jpg', 'One-Legged_Cable_Kickback/1.jpg'], 'repple+free-exercise-db'),
  ('cable-lying-triceps-extension', 'Cable Lying Triceps Extension', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.', 'With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.', 'Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.', 'Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.', 'Hold for a second at the contracted position and repeat for the recommended amount of repetitions.'], array['Cable_Lying_Triceps_Extension/0.jpg', 'Cable_Lying_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('cable-machine', 'Cable Machine', 'Full body', false, null, null, null, null, null, null, null, null, null, 'repple'),
  ('cable-one-arm-tricep-extension', 'Cable One Arm Tricep Extension', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.', 'Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.', 'As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.', 'Squeeze the triceps and hold for a second in this contracted position.', 'Slowly return the handle to the starting position.', 'Repeat for the recommended amount of repetitions and then perform the same movement with the other arm.'], array['Cable_One_Arm_Tricep_Extension/0.jpg', 'Cable_One_Arm_Tricep_Extension/1.jpg'], 'free-exercise-db'),
  ('cable-preacher-curl', 'Cable Preacher Curl', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Place a preacher bench about 2 feet in front of a pulley machine.', 'Attach a straight bar to the low pulley.', 'Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.', 'Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.', 'Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.', 'Now slowly lower the weight to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Cable_Preacher_Curl/0.jpg', 'Cable_Preacher_Curl/1.jpg'], 'free-exercise-db'),
  ('cable-rear-delt-fly', 'Cable Rear Delt Fly', 'Shoulders', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['shoulders'], null, array['Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.', 'Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.', 'Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.', 'Pause at the end of the motion before returning the handles to the start position.'], array['Cable_Rear_Delt_Fly/0.jpg', 'Cable_Rear_Delt_Fly/1.jpg'], 'free-exercise-db'),
  ('cable-reverse-crunch', 'Cable Reverse Crunch', 'Core', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.', 'Sit down with your feet toward the pulley and attach the cable to your ankles.', 'Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.', 'With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.', 'Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.', 'Repeat the same movement to failure.'], array['Cable_Reverse_Crunch/0.jpg', 'Cable_Reverse_Crunch/1.jpg'], 'free-exercise-db'),
  ('cable-rope-overhead-triceps-extension', 'Cable Rope Overhead Triceps Extension', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['Attach a rope to the bottom pulley of the pulley machine.', 'Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.', 'Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.', 'Return to the starting position by flexing your triceps as you breathe out.', 'Repeat for the recommended amount of repetitions.'], array['Cable_Rope_Overhead_Triceps_Extension/0.jpg', 'Cable_Rope_Overhead_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('cable-rope-rear-delt-rows', 'Cable Rope Rear-Delt Rows', 'Shoulders', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['shoulders'], array['biceps', 'middle back'], array['Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back.', 'Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out.', 'Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position.', 'Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out to the sides. Continue this motion as you exhale until the elbows travel slightly behind the back. Tip: Keep your upper arms horizontal, perpendicular to the torso and parallel to the floor throughout the motion.', 'Go back to the initial position where the arms are extended and the shoulders are stretched forward. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.'], array['Cable_Rope_Rear-Delt_Rows/0.jpg', 'Cable_Rope_Rear-Delt_Rows/1.jpg'], 'free-exercise-db'),
  ('cable-russian-twists', 'Cable Russian Twists', 'Core', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Connect a standard handle attachment, and position the cable to a middle pulley position.', 'Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.', 'Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.', 'Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.', 'Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.', 'Repeat the same movement to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.'], array['Cable_Russian_Twists/0.jpg', 'Cable_Russian_Twists/1.jpg'], 'free-exercise-db'),
  ('cable-seated-crunch', 'Cable Seated Crunch', 'Core', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Seat on a flat bench with your back facing a high pulley.', 'Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.', 'With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.', 'As you inhale, go back to the initial position slowly.', 'Repeat for the recommended amount of repetitions.'], array['Cable_Seated_Crunch/0.jpg', 'Cable_Seated_Crunch/1.jpg'], 'free-exercise-db'),
  ('cable-seated-lateral-raise', 'Cable Seated Lateral Raise', 'Shoulders', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['shoulders'], array['middle back', 'traps'], array['Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.', 'Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.', 'Bend forward while keeping your back flat and rest your torso on the thighs.', 'Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.', 'While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.', 'Slowly lower your arms to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise.'], array['Cable_Seated_Lateral_Raise/0.jpg', 'Cable_Seated_Lateral_Raise/1.jpg'], 'free-exercise-db'),
  ('cable-shoulder-press', 'Cable Shoulder Press', 'Shoulders', false, 'strength', 'cable', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Move the cables to the bottom of the towers and select an appropriate weight.', 'Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.', 'Keeping your head and chest up, extend through the elbow to press the handles directly over head.', 'After pausing at the top, return to the starting position and repeat.'], array['Cable_Shoulder_Press/0.jpg', 'Cable_Shoulder_Press/1.jpg'], 'free-exercise-db'),
  ('cable-shrugs', 'Cable Shrugs', 'Back', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['traps'], null, array['Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.', 'Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.', 'Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.', 'Lower the bar back to the original position.', 'Repeat for the recommended amount of repetitions.'], array['Cable_Shrugs/0.jpg', 'Cable_Shrugs/1.jpg'], 'free-exercise-db'),
  ('cable-wrist-curl', 'Cable Wrist Curl', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.', 'Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.', 'Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.'], array['Cable_Wrist_Curl/0.jpg', 'Cable_Wrist_Curl/1.jpg'], 'free-exercise-db'),
  ('calf-machine-shoulder-shrug', 'Calf-Machine Shoulder Shrug', 'Back', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['traps'], null, array['Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.', 'Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.', 'Slowly return to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Calf-Machine_Shoulder_Shrug/0.jpg', 'Calf-Machine_Shoulder_Shrug/1.jpg'], 'free-exercise-db'),
  ('calf-press', 'Calf Press', 'Calves', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['calves'], null, array['Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.', 'Select an appropriate weight, and grasp the handles. This will be your starting position.', 'Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible.', 'After a brief pause, reverse the motion and repeat.'], array['Calf_Press/0.jpg', 'Calf_Press/1.jpg'], 'free-exercise-db'),
  ('calf-press-on-the-leg-press-machine', 'Calf Press On The Leg Press Machine', 'Calves', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['calves'], null, array['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.'], array['Calf_Press_On_The_Leg_Press_Machine/0.jpg', 'Calf_Press_On_The_Leg_Press_Machine/1.jpg'], 'free-exercise-db'),
  ('calf-raise', 'Calf Raise', 'Calves', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['calves'], null, array['Adjust the padded lever of the calf raise machine to fit your height.', 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Calf_Raises/0.jpg', 'Standing_Calf_Raises/1.jpg'], 'repple+free-exercise-db'),
  ('calf-raise-on-a-dumbbell', 'Calf Raise On A Dumbbell', 'Calves', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'push', array['calves'], null, array['Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.', 'Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.', 'Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward.', 'Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.', 'Repeat for the recommended amount of repetitions.'], array['Calf_Raise_On_A_Dumbbell/0.jpg', 'Calf_Raise_On_A_Dumbbell/1.jpg'], 'free-exercise-db'),
  ('calf-raises-with-bands', 'Calf Raises - With Bands', 'Calves', false, 'strength', 'bands', 'beginner', 'isolation', 'push', array['calves'], null, array['Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.', 'While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.', 'Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.', 'After a one second contraction, slowly go back down to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Calf_Raises_-_With_Bands/0.jpg', 'Calf_Raises_-_With_Bands/1.jpg'], 'free-exercise-db'),
  ('calf-stretch-elbows-against-wall', 'Calf Stretch Elbows Against Wall', 'Calves', false, 'stretching', null, 'beginner', 'isolation', 'static', array['calves'], null, array['Stand facing a wall from a couple feet away.', 'Lean against the wall, placing your weight on your forearms.', 'Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively.'], array['Calf_Stretch_Elbows_Against_Wall/0.jpg', 'Calf_Stretch_Elbows_Against_Wall/1.jpg'], 'free-exercise-db'),
  ('calf-stretch-hands-against-wall', 'Calf Stretch Hands Against Wall', 'Calves', false, 'stretching', null, 'beginner', 'isolation', 'static', array['calves'], null, array['Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.', 'Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.', 'Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides.'], array['Calf_Stretch_Hands_Against_Wall/0.jpg', 'Calf_Stretch_Hands_Against_Wall/1.jpg'], 'free-exercise-db'),
  ('calves-smr', 'Calves-SMR', 'Calves', false, 'stretching', 'foam roll', 'intermediate', null, 'static', array['calves'], null, array['Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.', 'Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg.'], array['Calves-SMR/0.jpg', 'Calves-SMR/1.jpg'], 'free-exercise-db'),
  ('car-deadlift', 'Car Deadlift', 'Legs', false, 'strongman', 'other', 'intermediate', 'compound', 'pull', array['quadriceps'], array['forearms', 'glutes', 'hamstrings', 'lower back', 'traps'], array['This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs.', 'Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With your feet and your grip set, take a big breath and then lower your hips and flex the knees.', 'Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.', 'Lower the weight by bending at the hips and guiding it to the floor.'], array['Car_Deadlift/0.jpg', 'Car_Deadlift/1.jpg'], 'free-exercise-db'),
  ('car-drivers', 'Car Drivers', 'Shoulders', false, 'strength', 'barbell', 'beginner', 'isolation', 'push', array['shoulders'], array['forearms'], array['While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.', 'Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.', 'Reverse the motion, turning it all the way to the opposite side.', 'Repeat for the recommended amount of repetitions.'], array['Car_Drivers/0.jpg', 'Car_Drivers/1.jpg'], 'free-exercise-db'),
  ('carioca-quick-step', 'Carioca Quick Step', 'Legs', false, 'plyometrics', null, 'beginner', null, null, array['adductors'], array['abdominals', 'abductors', 'calves', 'glutes', 'hamstrings', 'quadriceps'], array['Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.', 'With your right foot, quick step behind and pull the knee up.', 'Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side.'], array['Carioca_Quick_Step/0.jpg', 'Carioca_Quick_Step/1.jpg'], 'free-exercise-db'),
  ('cat-stretch', 'Cat Stretch', 'Lower back', false, 'stretching', null, 'beginner', null, 'static', array['lower back'], array['middle back', 'traps'], array['Position yourself on the floor on your hands and knees.', 'Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.', 'Hold for 15 seconds.'], array['Cat_Stretch/0.jpg', 'Cat_Stretch/1.jpg'], 'free-exercise-db'),
  ('catch-and-overhead-throw', 'Catch and Overhead Throw', 'Back', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'push', array['lats'], array['abdominals', 'chest', 'shoulders'], array['Begin standing while facing a wall or a partner.', 'Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward.', 'Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner.'], array['Catch_and_Overhead_Throw/0.jpg', 'Catch_and_Overhead_Throw/1.jpg'], 'free-exercise-db'),
  ('chain-handle-extension', 'Chain Handle Extension', 'Arms', false, 'powerlifting', 'other', 'intermediate', 'isolation', 'push', array['triceps'], null, array['You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.', 'Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.', 'Pause at the lockout, and reverse the motion to return to the starting position.'], array['Chain_Handle_Extension/0.jpg', 'Chain_Handle_Extension/1.jpg'], 'free-exercise-db'),
  ('chain-press', 'Chain Press', 'Chest', false, 'powerlifting', 'other', 'intermediate', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position.', 'Lower the chains by flexing the elbows, unloading some of the chain onto the floor.', 'Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout.'], array['Chain_Press/0.jpg', 'Chain_Press/1.jpg'], 'free-exercise-db'),
  ('chair-leg-extended-stretch', 'Chair Leg Extended Stretch', 'Hamstrings', false, 'stretching', 'other', 'beginner', 'isolation', 'static', array['hamstrings'], array['adductors'], array['Sit upright in a chair and grip the seat on the sides.', 'Raise one leg, extending the knee, flexing the ankle as you do so.', 'Slowly move that leg outward as far as you can, and then back to the center and down.', 'Repeat for your other leg.'], array['Chair_Leg_Extended_Stretch/0.jpg', 'Chair_Leg_Extended_Stretch/1.jpg'], 'free-exercise-db'),
  ('chair-lower-back-stretch', 'Chair Lower Back Stretch', 'Back', false, 'stretching', null, 'beginner', 'isolation', 'static', array['lats'], array['lower back'], array['Sit upright on a chair.', 'Bend to one side with your arm over your head. You can hold onto the chair with your free hand.', 'Hold for 10 seconds, and repeat for your other side.'], array['Chair_Lower_Back_Stretch/0.jpg', 'Chair_Lower_Back_Stretch/1.jpg'], 'free-exercise-db'),
  ('chair-squat', 'Chair Squat', 'Legs', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders.', 'Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs.', 'Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.', 'Slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees.', 'Begin to raise the bar as you exhale by pushing the floor with the heels of your feet, extending the knees and returning to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Chair_Squat/0.jpg', 'Chair_Squat/1.jpg'], 'free-exercise-db'),
  ('chair-upper-body-stretch', 'Chair Upper Body Stretch', 'Shoulders', false, 'stretching', 'other', 'beginner', null, 'static', array['shoulders'], array['biceps', 'chest'], array['Sit on the edge of a chair, gripping the back of it.', 'Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds.'], array['Chair_Upper_Body_Stretch/0.jpg', 'Chair_Upper_Body_Stretch/1.jpg'], 'free-exercise-db'),
  ('chest-and-front-of-shoulder-stretch', 'Chest And Front Of Shoulder Stretch', 'Chest', false, 'stretching', 'other', 'beginner', 'isolation', 'static', array['chest'], array['shoulders'], array['Start off by standing with your legs together, holding a bodybar or a broomstick.', 'Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down.', 'Carefully lift the pole up and behind your head.'], array['Chest_And_Front_Of_Shoulder_Stretch/0.jpg', 'Chest_And_Front_Of_Shoulder_Stretch/1.jpg'], 'free-exercise-db'),
  ('chest-press', 'Chest Press', 'Chest', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.', 'Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.'], array['Leverage_Chest_Press/0.jpg', 'Leverage_Chest_Press/1.jpg'], 'repple+free-exercise-db'),
  ('chest-push-from-3-point-stance', 'Chest Push from 3 point stance', 'Chest', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you.', 'To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw.', 'As you execute the second step, explosively release the ball forward as hard as possible.'], array['Chest_Push_from_3_point_stance/0.jpg', 'Chest_Push_from_3_point_stance/1.jpg'], 'free-exercise-db'),
  ('chest-push-multiple-response', 'Chest Push (multiple response)', 'Chest', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest.', 'Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible.', 'Follow through by falling forward, catching yourself with your hands.', 'Immediately return to an upright position. Repeat for the desired number of repetitions.'], array['Chest_Push_multiple_response/0.jpg', 'Chest_Push_multiple_response/1.jpg'], 'free-exercise-db'),
  ('chest-push-single-response', 'Chest Push (single response)', 'Chest', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Begin in a kneeling position holding the medicine ball with both hands tightly into the chest.', 'Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible.', 'Follow through by falling forward, catching yourself with your hands.'], array['Chest_Push_single_response/0.jpg', 'Chest_Push_single_response/1.jpg'], 'free-exercise-db'),
  ('chest-push-with-run-release', 'Chest Push with Run Release', 'Chest', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position.', 'While taking your first step draw the medicine ball into your chest.', 'As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!'], array['Chest_Push_with_Run_Release/0.jpg', 'Chest_Push_with_Run_Release/1.jpg'], 'free-exercise-db'),
  ('chest-stretch-on-stability-ball', 'Chest Stretch on Stability Ball', 'Chest', false, 'stretching', 'exercise ball', 'beginner', 'isolation', 'static', array['chest'], null, array['Get on your hands and knees next to an exercise ball.', 'Place your elbows on top of the ball, keeping your arm out to your side. This will be your starting position.', 'Lower your torso towards the floor, keeping your elbow on top of the ball. Hold the stretch for 20-30 seconds, and repeat with the other arm.'], array['Chest_Stretch_on_Stability_Ball/0.jpg', 'Chest_Stretch_on_Stability_Ball/1.jpg'], 'free-exercise-db'),
  ('child-s-pose', 'Child''s Pose', 'Lower back', false, 'stretching', null, 'beginner', null, 'static', array['lower back'], array['glutes', 'middle back'], array['Get on your hands and knees, walk your hands in front of you.', 'Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.', 'Once you settle onto your heels, bring your hands next to your feet and relax. "breathe" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems.'], array['Childs_Pose/0.jpg', 'Childs_Pose/1.jpg'], 'free-exercise-db'),
  ('chin-to-chest-stretch', 'Chin To Chest Stretch', 'Neck', false, 'stretching', null, 'beginner', null, 'static', array['neck'], array['traps'], array['Get into a seated position on the floor.', 'Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds.'], array['Chin_To_Chest_Stretch/0.jpg', 'Chin_To_Chest_Stretch/1.jpg'], 'free-exercise-db'),
  ('chin-up', 'Chin-Up', 'Back', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'forearms', 'middle back'], array['Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.', 'As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.'], array['Chin-Up/0.jpg', 'Chin-Up/1.jpg'], 'free-exercise-db'),
  ('circus-bell', 'Circus Bell', 'Shoulders', false, 'strongman', 'other', 'expert', 'compound', 'push', array['shoulders'], array['forearms', 'glutes', 'hamstrings', 'lower back', 'traps', 'triceps'], array['The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands.', 'Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand.', 'Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip by flexing the knees, and the drive upwards as you extend the dumbbell overhead, leaning slightly away from it as you do so.', 'Carefully guide the bell back to the floor, keeping it under control as much as possible. It is best to perform this event on a thick rubber mat to prevent damage to the floor.'], array['Circus_Bell/0.jpg', 'Circus_Bell/1.jpg'], 'free-exercise-db'),
  ('clean', 'Clean', 'Hamstrings', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps'], array['With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', '', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.'], array['Clean/0.jpg', 'Clean/1.jpg'], 'free-exercise-db'),
  ('clean-and-jerk', 'Clean and Jerk', 'Shoulders', false, 'olympic weightlifting', 'barbell', 'expert', 'compound', 'push', array['shoulders'], array['abdominals', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps', 'triceps'], array['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.', 'The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.', 'Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.', 'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position.'], array['Clean_and_Jerk/0.jpg', 'Clean_and_Jerk/1.jpg'], 'free-exercise-db'),
  ('clean-and-press', 'Clean and Press', 'Shoulders', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['shoulders'], array['abdominals', 'calves', 'glutes', 'hamstrings', 'lower back', 'middle back', 'quadriceps', 'shoulders', 'traps', 'triceps'], array['Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.', 'Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.', 'As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.', 'At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.', 'As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.', 'Stand to full height, holding the bar in the clean position.', 'Without moving your feet, press the bar overhead as you exhale. Lower the bar under control .'], array['Clean_and_Press/0.jpg', 'Clean_and_Press/1.jpg'], 'free-exercise-db'),
  ('clean-deadlift', 'Clean Deadlift', 'Hamstrings', false, 'olympic weightlifting', 'barbell', 'beginner', 'compound', 'pull', array['hamstrings'], array['forearms', 'glutes', 'lower back', 'middle back', 'quadriceps', 'traps'], array['Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.', 'Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.', 'After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended.'], array['Clean_Deadlift/0.jpg', 'Clean_Deadlift/1.jpg'], 'free-exercise-db'),
  ('clean-from-blocks', 'Clean from Blocks', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'shoulders', 'traps'], array['With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out.', 'As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out. Aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position. Return the weight to the boxes for the next rep.'], array['Clean_from_Blocks/0.jpg', 'Clean_from_Blocks/1.jpg'], 'free-exercise-db'),
  ('clean-pull', 'Clean Pull', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['quadriceps'], array['forearms', 'glutes', 'hamstrings', 'lower back', 'traps'], array['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.'], array['Clean_Pull/0.jpg', 'Clean_Pull/1.jpg'], 'free-exercise-db'),
  ('clean-shrug', 'Clean Shrug', 'Back', false, 'olympic weightlifting', 'barbell', 'beginner', 'compound', 'pull', array['traps'], array['forearms', 'shoulders'], array['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.', 'Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.'], array['Clean_Shrug/0.jpg', 'Clean_Shrug/1.jpg'], 'free-exercise-db'),
  ('clock-push-up', 'Clock Push-Up', 'Chest', false, 'strength', 'body only', 'intermediate', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Move into a prone position on the floor, supporting your weight on your hands and toes.', 'Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.', 'Descend by flexing at the elbow, lowering your chest toward the ground.', 'At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side.', 'As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.', 'Return to the starting position and repeat the exercise, working all the way around until you are back where you started.'], array['Clock_Push-Up/0.jpg', 'Clock_Push-Up/1.jpg'], 'free-exercise-db'),
  ('close-grip-barbell-bench-press', 'Close-Grip Barbell Bench Press', 'Arms', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.'], array['Close-Grip_Barbell_Bench_Press/0.jpg', 'Close-Grip_Barbell_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('close-grip-dumbbell-press', 'Close-Grip Dumbbell Press', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.', 'Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.', 'Initiate the movement by lowering the dumbbell to your chest.', 'Return to the starting position by extending the elbows.'], array['Close-Grip_Dumbbell_Press/0.jpg', 'Close-Grip_Dumbbell_Press/1.jpg'], 'free-exercise-db'),
  ('close-grip-ez-bar-curl', 'Close-Grip EZ Bar Curl', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Close-Grip_EZ_Bar_Curl/0.jpg', 'Close-Grip_EZ_Bar_Curl/1.jpg'], 'free-exercise-db'),
  ('close-grip-ez-bar-curl-with-band', 'Close-Grip EZ-Bar Curl with Band', 'Arms', false, 'strength', 'e-z curl bar', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.', 'While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Close-Grip_EZ-Bar_Curl_with_Band/0.jpg', 'Close-Grip_EZ-Bar_Curl_with_Band/1.jpg'], 'free-exercise-db'),
  ('close-grip-ez-bar-press', 'Close-Grip EZ-Bar Press', 'Arms', false, 'strength', 'e-z curl bar', 'beginner', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Lie on a flat bench with an EZ bar loaded to an appropriate weight.', 'Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.', 'Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.', 'Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.', 'Repeat.'], array['Close-Grip_EZ-Bar_Press/0.jpg', 'Close-Grip_EZ-Bar_Press/1.jpg'], 'free-exercise-db'),
  ('close-grip-front-lat-pulldown', 'Close-Grip Front Lat Pulldown', 'Back', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back', 'shoulders'], array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.', 'After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', '6. Repeat this motion for the prescribed amount of repetitions.'], array['Close-Grip_Front_Lat_Pulldown/0.jpg', 'Close-Grip_Front_Lat_Pulldown/1.jpg'], 'free-exercise-db'),
  ('close-grip-push-up-off-of-a-dumbbell', 'Close-Grip Push-Up off of a Dumbbell', 'Arms', false, 'strength', 'body only', 'intermediate', 'compound', 'push', array['triceps'], array['abdominals', 'chest', 'shoulders'], array['Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position.', 'Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag.', 'Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step.', 'After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions.'], array['Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg', 'Close-Grip_Push-Up_off_of_a_Dumbbell/1.jpg'], 'free-exercise-db'),
  ('close-grip-standing-barbell-curl', 'Close-Grip Standing Barbell Curl', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Hold a barbell with both hands, palms up and a few inches apart.', 'Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement.', 'Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip: Avoid bending the back or using swinging motions as you lift the weight. Only the forearms should move.', 'Slowly go back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Close-Grip_Standing_Barbell_Curl/0.jpg', 'Close-Grip_Standing_Barbell_Curl/1.jpg'], 'free-exercise-db'),
  ('cocoons', 'Cocoons', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.', 'To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.', 'After a brief pause, return to the starting position.'], array['Cocoons/0.jpg', 'Cocoons/1.jpg'], 'free-exercise-db'),
  ('conan-s-wheel', 'Conan''s Wheel', 'Legs', false, 'strongman', 'other', 'intermediate', 'compound', null, array['quadriceps'], array['abdominals', 'biceps', 'calves', 'forearms', 'lower back', 'shoulders', 'traps'], array['With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms.', 'Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns.'], array['Conans_Wheel/0.jpg', 'Conans_Wheel/1.jpg'], 'free-exercise-db'),
  ('concentration-curls', 'Concentration Curls', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.', 'Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.', 'Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm.'], array['Concentration_Curls/0.jpg', 'Concentration_Curls/1.jpg'], 'free-exercise-db'),
  ('cross-body-crunch', 'Cross-Body Crunch', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Lie flat on your back and bend your knees about 60 degrees.', 'Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.', 'Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.', 'Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.', 'Continue alternating in this manner until all prescribed repetitions are done.'], array['Cross-Body_Crunch/0.jpg', 'Cross-Body_Crunch/1.jpg'], 'free-exercise-db'),
  ('cross-body-hammer-curl', 'Cross Body Hammer Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.', 'While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.', 'Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.', 'Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.'], array['Cross_Body_Hammer_Curl/0.jpg', 'Cross_Body_Hammer_Curl/1.jpg'], 'free-exercise-db'),
  ('cross-over-with-bands', 'Cross Over - With Bands', 'Chest', false, 'strength', 'bands', 'beginner', 'compound', 'push', array['chest'], array['biceps', 'shoulders'], array['Secure an exercise band around a stationary post.', 'While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.', 'Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.', 'While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.', 'Slowly return to the starting position as you inhale.', 'Perform for the recommended amount of repetitions.'], array['Cross_Over_-_With_Bands/0.jpg', 'Cross_Over_-_With_Bands/1.jpg'], 'free-exercise-db'),
  ('crossover-reverse-lunge', 'Crossover Reverse Lunge', 'Lower back', false, 'stretching', null, 'intermediate', null, 'pull', array['lower back'], array['abdominals', 'abductors', 'glutes', 'hamstrings', 'quadriceps'], array['Stand with your feet shoulder width apart. This will be your starting position.', 'Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.', 'After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion.'], array['Crossover_Reverse_Lunge/0.jpg', 'Crossover_Reverse_Lunge/1.jpg'], 'free-exercise-db'),
  ('crucifix', 'Crucifix', 'Shoulders', false, 'strongman', 'other', 'beginner', 'isolation', 'static', array['shoulders'], array['forearms'], array['In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different.', 'Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be heavy enough that you fail in 30-60 seconds.'], array['Crucifix/0.jpg', 'Crucifix/1.jpg'], 'free-exercise-db'),
  ('crunch-hands-overhead', 'Crunch - Hands Overhead', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.', 'Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position.', 'Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don''t move them forward from that position. Exhale as you perform this portion of the movement and hold the contraction for a second.', 'Slowly lower down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Crunch_-_Hands_Overhead/0.jpg', 'Crunch_-_Hands_Overhead/1.jpg'], 'free-exercise-db'),
  ('crunch-legs-on-exercise-ball', 'Crunch - Legs On Exercise Ball', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.', 'Place your feet three to four inches apart and point your toes inward so they touch.', 'Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.', 'Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.', 'Slowly go back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Crunch_-_Legs_On_Exercise_Ball/0.jpg', 'Crunch_-_Legs_On_Exercise_Ball/1.jpg'], 'free-exercise-db'),
  ('crunches', 'Crunches', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.', 'Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.', 'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.', 'After the one second contraction, begin to come down slowly again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Crunches/0.jpg', 'Crunches/1.jpg'], 'free-exercise-db'),
  ('cuban-press', 'Cuban Press', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['shoulders'], array['traps'], array['Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the "scarecrow" position. This will be your starting position.', 'To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.', 'Now press the dumbbells by extending at the elbows, straightening your arms overhead.', 'Return to the starting position as you breathe in by reversing the steps.', 'Repeat for the recommended amount of repetitions.'], array['Cuban_Press/0.jpg', 'Cuban_Press/1.jpg'], 'free-exercise-db'),
  ('dancer-s-stretch', 'Dancer''s Stretch', 'Lower back', false, 'stretching', null, 'beginner', null, 'static', array['lower back'], array['abductors', 'glutes'], array['Sit up on the floor.', 'Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor.', 'Place your left arm on your right leg and your right hand on the floor.', 'Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides.'], array['Dancers_Stretch/0.jpg', 'Dancers_Stretch/1.jpg'], 'free-exercise-db'),
  ('dead-bug', 'Dead Bug', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Begin lying on your back with your hands extended above you toward the ceiling.', 'Bring your feet, knees, and hips up to 90 degrees.', 'Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.', 'Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.', 'Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.', 'Stay tight and return the working leg to the starting position.', 'Repeat on the opposite side, alternating until the set is complete.'], array['Dead_Bug/0.jpg', 'Dead_Bug/1.jpg'], 'free-exercise-db'),
  ('deadlift', 'Deadlift', 'Back', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['lower back'], array['calves', 'forearms', 'glutes', 'hamstrings', 'lats', 'middle back', 'quadriceps', 'traps'], array['Stand in front of a loaded barbell.', 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.', 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.', 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.', 'Perform the amount of repetitions prescribed in the program.'], array['Barbell_Deadlift/0.jpg', 'Barbell_Deadlift/1.jpg'], 'repple+free-exercise-db'),
  ('deadlift-with-bands', 'Deadlift with Bands', 'Lower back', false, 'powerlifting', 'barbell', 'expert', 'compound', 'pull', array['lower back'], array['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps'], array['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.'], array['Deadlift_with_Bands/0.jpg', 'Deadlift_with_Bands/1.jpg'], 'free-exercise-db'),
  ('deadlift-with-chains', 'Deadlift with Chains', 'Lower back', false, 'powerlifting', 'barbell', 'expert', 'compound', 'pull', array['lower back'], array['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps'], array['You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.', 'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.', 'Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.'], array['Deadlift_with_Chains/0.jpg', 'Deadlift_with_Chains/1.jpg'], 'free-exercise-db'),
  ('decline-barbell-bench-press', 'Decline Barbell Bench Press', 'Chest', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'As you breathe in, come down slowly until you feel the bar on your lower chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.'], array['Decline_Barbell_Bench_Press/0.jpg', 'Decline_Barbell_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('decline-close-grip-bench-to-skull-crusher', 'Decline Close-Grip Bench To Skull Crusher', 'Arms', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.', 'Using the triceps to push the bar back up, press it back to the starting position as you exhale.', 'As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.', 'Lift the bar back to the starting position by contracting the triceps and exhaling.', 'Repeat steps 3-6 until the recommended amount of repetitions is performed.'], array['Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg', 'Decline_Close-Grip_Bench_To_Skull_Crusher/1.jpg'], 'free-exercise-db'),
  ('decline-crunch', 'Decline Crunch', 'Core', false, 'strength', 'body only', 'intermediate', 'isolation', 'pull', array['abdominals'], null, array['Secure your legs at the end of the decline bench and lie down.', 'Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.', 'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.', 'After the one second contraction, begin to come down slowly again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Decline_Crunch/0.jpg', 'Decline_Crunch/1.jpg'], 'free-exercise-db'),
  ('decline-dumbbell-bench-press', 'Decline Dumbbell Bench Press', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..', 'Repeat the movement for the prescribed amount of repetitions of your training program.'], array['Decline_Dumbbell_Bench_Press/0.jpg', 'Decline_Dumbbell_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('decline-dumbbell-flyes', 'Decline Dumbbell Flyes', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['chest'], null, array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.'], array['Decline_Dumbbell_Flyes/0.jpg', 'Decline_Dumbbell_Flyes/1.jpg'], 'free-exercise-db'),
  ('decline-dumbbell-triceps-extension', 'Decline Dumbbell Triceps Extension', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['triceps'], null, array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.', 'As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Breathe in as you perform this portion of the movement.', 'Lift the dumbbells back to the starting position by contracting the triceps and exhaling.', 'Repeat for the recommended amount of repetitions.'], array['Decline_Dumbbell_Triceps_Extension/0.jpg', 'Decline_Dumbbell_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('decline-ez-bar-triceps-extension', 'Decline EZ Bar Triceps Extension', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'push', array['triceps'], null, array['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.', 'Lift the bar back to the starting position by contracting the triceps and exhaling.', 'Repeat until the recommended amount of repetitions is performed.'], array['Decline_EZ_Bar_Triceps_Extension/0.jpg', 'Decline_EZ_Bar_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('decline-oblique-crunch', 'Decline Oblique Crunch', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.', 'Put one hand beside your head and the other on your thigh. This will be your starting position.', 'Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.', 'Lower your body back down slowly to the starting position as you inhale.', 'After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position.'], array['Decline_Oblique_Crunch/0.jpg', 'Decline_Oblique_Crunch/1.jpg'], 'free-exercise-db'),
  ('decline-push-up', 'Decline Push-Up', 'Chest', false, 'strength', null, 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.'], array['Decline_Push-Up/0.jpg', 'Decline_Push-Up/1.jpg'], 'free-exercise-db'),
  ('decline-reverse-crunch', 'Decline Reverse Crunch', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position.', 'Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.', 'While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.', 'Hold the contraction for a second and move your legs back to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.'], array['Decline_Reverse_Crunch/0.jpg', 'Decline_Reverse_Crunch/1.jpg'], 'free-exercise-db'),
  ('decline-smith-press', 'Decline Smith Press', 'Chest', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position.', 'As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso.', 'After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so.', 'Repeat the movement for the prescribed amount of repetitions.', 'When the set is complete, lock the bar back in the rack.'], array['Decline_Smith_Press/0.jpg', 'Decline_Smith_Press/1.jpg'], 'free-exercise-db'),
  ('deficit-deadlift', 'Deficit Deadlift', 'Lower back', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'pull', array['lower back'], array['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps'], array['Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.'], array['Deficit_Deadlift/0.jpg', 'Deficit_Deadlift/1.jpg'], 'free-exercise-db'),
  ('depth-jump-leap', 'Depth Jump Leap', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings'], array['For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.', 'Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer.', 'Begin by dropping off the initial box, landing and simultaneously taking off with both feet.', 'Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact.'], array['Depth_Jump_Leap/0.jpg', 'Depth_Jump_Leap/1.jpg'], 'free-exercise-db'),
  ('dip-machine', 'Dip Machine', 'Arms', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Sit securely in a dip machine, select the weight and firmly grasp the handles.', 'Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.', 'As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.', 'Now slowly let your arms come back up to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Dip_Machine/0.jpg', 'Dip_Machine/1.jpg'], 'free-exercise-db'),
  ('dips-chest-version', 'Dips - Chest Version', 'Chest', false, 'strength', 'other', 'intermediate', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.', 'While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.', 'Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.', 'Repeat the movement for the prescribed amount of repetitions.'], array['Dips_-_Chest_Version/0.jpg', 'Dips_-_Chest_Version/1.jpg'], 'free-exercise-db'),
  ('dips-triceps-version', 'Dips - Triceps Version', 'Arms', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.', 'Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.', 'Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.'], array['Dips_-_Triceps_Version/0.jpg', 'Dips_-_Triceps_Version/1.jpg'], 'free-exercise-db'),
  ('donkey-calf-raises', 'Donkey Calf Raises', 'Calves', false, 'strength', 'other', 'intermediate', 'isolation', 'push', array['calves'], null, array['For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.', 'Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.'], array['Donkey_Calf_Raises/0.jpg', 'Donkey_Calf_Raises/1.jpg'], 'free-exercise-db'),
  ('double-kettlebell-alternating-hang-clean', 'Double Kettlebell Alternating Hang Clean', 'Hamstrings', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['hamstrings'], array['biceps', 'calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'traps'], array['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean one kettlebell to your shoulder and hold on to the other kettlebell.', 'With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up.'], array['Double_Kettlebell_Alternating_Hang_Clean/0.jpg', 'Double_Kettlebell_Alternating_Hang_Clean/1.jpg'], 'free-exercise-db'),
  ('double-kettlebell-jerk', 'Double Kettlebell Jerk', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['calves', 'quadriceps', 'triceps'], array['Hold a kettlebell by the handle in each hand.', 'Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum.', 'As you do so, press the kettlebells overhead to lockout by extending the arms, using your body''s momentum to move the weights.', 'Return your feet to the ground in a split fashion, with one foot forward and one foot back.', 'Keeping the weights overhead, return to a standing position, bringing your feet together. Lower the weights to perform the next repetition.'], array['Double_Kettlebell_Jerk/0.jpg', 'Double_Kettlebell_Jerk/1.jpg'], 'free-exercise-db'),
  ('double-kettlebell-push-press', 'Double Kettlebell Push Press', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['calves', 'quadriceps', 'triceps'], array['Clean two kettlebells to your shoulders.', 'Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead.', 'Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat.'], array['Double_Kettlebell_Push_Press/0.jpg', 'Double_Kettlebell_Push_Press/1.jpg'], 'free-exercise-db'),
  ('double-kettlebell-snatch', 'Double Kettlebell Snatch', 'Shoulders', false, 'strength', 'kettlebells', 'expert', 'compound', 'pull', array['shoulders'], array['glutes', 'hamstrings', 'quadriceps'], array['Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.', 'Swing the kettlebells between your legs forcefully and reverse the direction.', 'Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.'], array['Double_Kettlebell_Snatch/0.jpg', 'Double_Kettlebell_Snatch/1.jpg'], 'free-exercise-db'),
  ('double-kettlebell-windmill', 'Double Kettlebell Windmill', 'Core', false, 'strength', 'kettlebells', 'intermediate', null, 'pull', array['abdominals'], array['glutes', 'hamstrings', 'shoulders', 'triceps'], array['Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.', 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.', 'Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.', 'Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position.'], array['Double_Kettlebell_Windmill/0.jpg', 'Double_Kettlebell_Windmill/1.jpg'], 'free-exercise-db'),
  ('double-leg-butt-kick', 'Double Leg Butt Kick', 'Legs', false, 'plyometrics', 'body only', 'beginner', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings'], array['Begin standing with your knees slightly bent.', 'Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.', 'As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.', 'Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact.'], array['Double_Leg_Butt_Kick/0.jpg', 'Double_Leg_Butt_Kick/1.jpg'], 'free-exercise-db'),
  ('downward-facing-balance', 'Downward Facing Balance', 'Glutes', false, 'strength', 'exercise ball', 'intermediate', 'isolation', 'static', array['glutes'], array['abdominals', 'hamstrings'], array['Lie facedown on top of an exercise ball.', 'While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees.'], array['Downward_Facing_Balance/0.jpg', 'Downward_Facing_Balance/1.jpg'], 'free-exercise-db'),
  ('drag-curl', 'Drag Curl', 'Arms', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['biceps'], array['forearms'], array['Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.', 'As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.', 'Slowly go back to the starting position as you keep the bar in contact with the torso at all times.', 'Repeat for the recommended amount of repetitions.'], array['Drag_Curl/0.jpg', 'Drag_Curl/1.jpg'], 'free-exercise-db'),
  ('drop-push', 'Drop Push', 'Chest', false, 'plyometrics', 'other', 'intermediate', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Position low boxes or other platforms 2-3 feet apart.', 'Move to a pushup position between them, supporting yourself by placing your hands on the boxes.', 'With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm.'], array['Drop_Push/0.jpg', 'Drop_Push/1.jpg'], 'free-exercise-db'),
  ('dumbbell-alternate-bicep-curl', 'Dumbbell Alternate Bicep Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.', 'While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.'], array['Dumbbell_Alternate_Bicep_Curl/0.jpg', 'Dumbbell_Alternate_Bicep_Curl/1.jpg'], 'free-exercise-db'),
  ('dumbbell-bench-press', 'Dumbbell Bench Press', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.', 'Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions of your training program.'], array['Dumbbell_Bench_Press/0.jpg', 'Dumbbell_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('dumbbell-bench-press-with-neutral-grip', 'Dumbbell Bench Press with Neutral Grip', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.', 'Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.', 'Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.', 'Pause, then extend the elbow and return to the starting position.'], array['Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg', 'Dumbbell_Bench_Press_with_Neutral_Grip/1.jpg'], 'free-exercise-db'),
  ('dumbbell-bicep-curl', 'Dumbbell Bicep Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Dumbbell_Bicep_Curl/0.jpg', 'Dumbbell_Bicep_Curl/1.jpg'], 'free-exercise-db'),
  ('dumbbell-clean', 'Dumbbell Clean', 'Hamstrings', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps'], array['Begin standing with a dumbbell in each hand with your feet shoulder width apart.', 'Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.', 'To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.', 'After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.', 'Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders.'], array['Dumbbell_Clean/0.jpg', 'Dumbbell_Clean/1.jpg'], 'free-exercise-db'),
  ('dumbbell-floor-press', 'Dumbbell Floor Press', 'Arms', false, 'powerlifting', 'dumbbell', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.', 'Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.', 'Pause at the bottom, and then bring the weight together at the top by extending through the elbows.'], array['Dumbbell_Floor_Press/0.jpg', 'Dumbbell_Floor_Press/1.jpg'], 'free-exercise-db'),
  ('dumbbell-flyes', 'Dumbbell Flyes', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['chest'], null, array['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.', 'Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.'], array['Dumbbell_Flyes/0.jpg', 'Dumbbell_Flyes/1.jpg'], 'free-exercise-db'),
  ('dumbbell-incline-row', 'Dumbbell Incline Row', 'Back', false, 'strength', 'dumbbell', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'forearms', 'lats', 'shoulders'], array['Using a neutral grip, lean into an incline bench.', 'Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.', 'Retract the shoulder blades and flex the elbows to row the dumbbells to your side.', 'Pause at the top of the motion, and then return to the starting position.'], array['Dumbbell_Incline_Row/0.jpg', 'Dumbbell_Incline_Row/1.jpg'], 'free-exercise-db'),
  ('dumbbell-incline-shoulder-raise', 'Dumbbell Incline Shoulder Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], array['triceps'], array['Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs.', 'Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position.', 'While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe out.', 'Bring back the dumbbells to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Dumbbell_Incline_Shoulder_Raise/0.jpg', 'Dumbbell_Incline_Shoulder_Raise/1.jpg'], 'free-exercise-db'),
  ('dumbbell-lunges', 'Dumbbell Lunges', 'Legs', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.'], array['Dumbbell_Lunges/0.jpg', 'Dumbbell_Lunges/1.jpg'], 'free-exercise-db'),
  ('dumbbell-lying-one-arm-rear-lateral-raise', 'Dumbbell Lying One-Arm Rear Lateral Raise', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['shoulders'], array['middle back'], array['While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. The other hand can be used to hold to the leg of the bench for stability.', 'Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.', 'Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbell to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg', 'Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/1.jpg'], 'free-exercise-db'),
  ('dumbbell-lying-pronation', 'Dumbbell Lying Pronation', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['forearms'], null, array['Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', 'Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.', 'Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.', 'As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.', 'As you breathe in, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Dumbbell_Lying_Pronation/0.jpg', 'Dumbbell_Lying_Pronation/1.jpg'], 'free-exercise-db'),
  ('dumbbell-lying-rear-lateral-raise', 'Dumbbell Lying Rear Lateral Raise', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['shoulders'], null, array['While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench.', 'Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.', 'Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbells to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.'], array['Dumbbell_Lying_Rear_Lateral_Raise/0.jpg', 'Dumbbell_Lying_Rear_Lateral_Raise/1.jpg'], 'free-exercise-db'),
  ('dumbbell-lying-supination', 'Dumbbell Lying Supination', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['forearms'], null, array['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', 'Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.', 'Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.', 'As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.', 'As you breathe in, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.'], array['Dumbbell_Lying_Supination/0.jpg', 'Dumbbell_Lying_Supination/1.jpg'], 'free-exercise-db'),
  ('dumbbell-one-arm-shoulder-press', 'Dumbbell One-Arm Shoulder Press', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.', 'Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.', 'Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.', 'As you exhale, push the dumbbell up until your arm is fully extended.', 'After a second pause, slowly come down back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions and then switch arms.'], array['Dumbbell_One-Arm_Shoulder_Press/0.jpg', 'Dumbbell_One-Arm_Shoulder_Press/1.jpg'], 'free-exercise-db'),
  ('dumbbell-one-arm-triceps-extension', 'Dumbbell One-Arm Triceps Extension', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'push', array['triceps'], null, array['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.', 'Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.', 'Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.', 'Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.', 'Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.', 'Repeat for the recommended amount of repetitions and switch arms.'], array['Dumbbell_One-Arm_Triceps_Extension/0.jpg', 'Dumbbell_One-Arm_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('dumbbell-one-arm-upright-row', 'Dumbbell One-Arm Upright Row', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'pull', array['shoulders'], array['biceps', 'traps'], array['Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs.', 'Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position.', 'Use your side shoulders to lift the dumbbell as you exhale. The dumbbell should be close to the body as you move it up. Continue to lift it until the dumbbell is nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the dumbbell back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions and switch arms.'], array['Dumbbell_One-Arm_Upright_Row/0.jpg', 'Dumbbell_One-Arm_Upright_Row/1.jpg'], 'free-exercise-db'),
  ('dumbbell-prone-incline-curl', 'Dumbbell Prone Incline Curl', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['biceps'], null, array['Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way).', 'Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor.', 'Now keep your elbows in by your side and face the palms forward. This will be your starting position.', 'Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as you perform this portion of the movement and ensure that only the forearms move. The upper arms should remain stationary at all times.', 'Lower the dumbbells until your arms are fully extended.', 'Repeat for the recommended amount of times.'], array['Dumbbell_Prone_Incline_Curl/0.jpg', 'Dumbbell_Prone_Incline_Curl/1.jpg'], 'free-exercise-db'),
  ('dumbbell-raise', 'Dumbbell Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'compound', 'pull', array['shoulders'], array['biceps'], array['Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be next to your thighs with the palm of your hands facing back.', 'Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be to the side of the body as you move them up. Continue to lift it until the dumbbells are nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.'], array['Dumbbell_Raise/0.jpg', 'Dumbbell_Raise/1.jpg'], 'free-exercise-db'),
  ('dumbbell-rear-lunge', 'Dumbbell Rear Lunge', 'Legs', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.', 'Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.', 'Now repeat with the opposite leg.'], array['Dumbbell_Rear_Lunge/0.jpg', 'Dumbbell_Rear_Lunge/1.jpg'], 'free-exercise-db'),
  ('dumbbell-scaption', 'Dumbbell Scaption', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], array['traps'], array['This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.', 'Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.', 'Continue until your arms are parallel to the ground, and then return to the starting position.'], array['Dumbbell_Scaption/0.jpg', 'Dumbbell_Scaption/1.jpg'], 'free-exercise-db'),
  ('dumbbell-seated-box-jump', 'Dumbbell Seated Box Jump', 'Legs', false, 'plyometrics', 'dumbbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.', 'Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward.', 'Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.', 'Step down and return to the starting position.'], array['Dumbbell_Seated_Box_Jump/0.jpg', 'Dumbbell_Seated_Box_Jump/1.jpg'], 'free-exercise-db'),
  ('dumbbell-seated-one-leg-calf-raise', 'Dumbbell Seated One-Leg Calf Raise', 'Calves', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['calves'], null, array['Place a block on the floor about 12 inches from a flat bench.', 'Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.', 'Now place the ball of your left foot on the block. This will be your starting position.', 'Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.', 'Slowly return to the starting position, stretching as far down as possible.', 'Repeat for your prescribed number of repetitions and then repeat with the right leg.'], array['Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg', 'Dumbbell_Seated_One-Leg_Calf_Raise/1.jpg'], 'free-exercise-db'),
  ('dumbbell-shoulder-press', 'Dumbbell Shoulder Press', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.', 'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.', 'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.', 'Now, exhale and push the dumbbells upward until they touch at the top.', 'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.'], array['Dumbbell_Shoulder_Press/0.jpg', 'Dumbbell_Shoulder_Press/1.jpg'], 'free-exercise-db'),
  ('dumbbell-shrug', 'Dumbbell Shrug', 'Back', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['traps'], null, array['Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.', 'Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.', 'Lower the dumbbells back to the original position.', 'Repeat for the recommended amount of repetitions.'], array['Dumbbell_Shrug/0.jpg', 'Dumbbell_Shrug/1.jpg'], 'free-exercise-db'),
  ('dumbbell-side-bend', 'Dumbbell Side Bend', 'Core', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.', 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.', 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.', 'Repeat for the recommended amount of repetitions and then change hands.'], array['Dumbbell_Side_Bend/0.jpg', 'Dumbbell_Side_Bend/1.jpg'], 'free-exercise-db'),
  ('dumbbell-squat', 'Dumbbell Squat', 'Legs', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.', 'Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Dumbbell_Squat/0.jpg', 'Dumbbell_Squat/1.jpg'], 'free-exercise-db'),
  ('dumbbell-squat-to-a-bench', 'Dumbbell Squat To A Bench', 'Legs', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.', 'Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Dumbbell_Squat_To_A_Bench/0.jpg', 'Dumbbell_Squat_To_A_Bench/1.jpg'], 'free-exercise-db'),
  ('dumbbell-step-ups', 'Dumbbell Step Ups', 'Legs', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.'], array['Dumbbell_Step_Ups/0.jpg', 'Dumbbell_Step_Ups/1.jpg'], 'free-exercise-db'),
  ('dumbbell-tricep-extension-pronated-grip', 'Dumbbell Tricep Extension -Pronated Grip', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['triceps'], null, array['Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.', 'The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position.', 'Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in.', 'Then, exhale and use your triceps to return the weight to the starting position.'], array['Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg', 'Dumbbell_Tricep_Extension_-Pronated_Grip/1.jpg'], 'free-exercise-db'),
  ('dynamic-back-stretch', 'Dynamic Back Stretch', 'Back', false, 'stretching', null, 'beginner', null, 'pull', array['lats'], null, array['Stand with your feet shoulder width apart. This will be your starting position.', 'Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head.'], array['Dynamic_Back_Stretch/0.jpg', 'Dynamic_Back_Stretch/1.jpg'], 'free-exercise-db'),
  ('dynamic-chest-stretch', 'Dynamic Chest Stretch', 'Chest', false, 'stretching', null, 'beginner', null, 'pull', array['chest'], array['middle back'], array['Stand with your hands together, arms extended directly in front of you. This will be your starting position.', 'Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so.'], array['Dynamic_Chest_Stretch/0.jpg', 'Dynamic_Chest_Stretch/1.jpg'], 'free-exercise-db'),
  ('elbow-circles', 'Elbow Circles', 'Shoulders', false, 'stretching', null, 'beginner', 'isolation', 'pull', array['shoulders'], array['traps'], array['Sit or stand with your feet slightly apart.', 'Place your hands on your shoulders with your elbows at shoulder level and pointing out.', 'Slowly make a circle with your elbows. Breathe out as you start the circle and breathe in as you complete the circle.'], array['Elbow_Circles/0.jpg', 'Elbow_Circles/1.jpg'], 'free-exercise-db'),
  ('elbow-to-knee', 'Elbow to Knee', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.', 'Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.', 'Return to the starting position and repeat the movement for the desired number of repetitions before switching sides.'], array['Elbow_to_Knee/0.jpg', 'Elbow_to_Knee/1.jpg'], 'free-exercise-db'),
  ('elbows-back', 'Elbows Back', 'Chest', false, 'stretching', null, 'beginner', 'isolation', 'static', array['chest'], array['shoulders'], array['Stand up straight.', 'Place both hands on your lower back, fingers pointing downward and elbows out.', 'Then gently pull your elbows back aiming to touch them together.'], array['Elbows_Back/0.jpg', 'Elbows_Back/1.jpg'], 'free-exercise-db'),
  ('elevated-back-lunge', 'Elevated Back Lunge', 'Legs', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['glutes', 'hamstrings'], array['Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.', 'Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.', 'Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.', 'Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating.'], array['Elevated_Back_Lunge/0.jpg', 'Elevated_Back_Lunge/1.jpg'], 'free-exercise-db'),
  ('elevated-cable-rows', 'Elevated Cable Rows', 'Back', false, 'strength', 'cable', 'intermediate', 'compound', 'pull', array['lats'], array['middle back', 'traps'], array['Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.', 'Place it on the seat of the cable row machine.', 'Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.'], array['Elevated_Cable_Rows/0.jpg', 'Elevated_Cable_Rows/1.jpg'], 'free-exercise-db'),
  ('elliptical', 'Elliptical', 'Full body', true, null, null, null, null, null, null, null, null, null, 'repple'),
  ('elliptical-trainer', 'Elliptical Trainer', 'Legs', true, 'cardio', 'machine', 'intermediate', null, null, array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.'], array['Elliptical_Trainer/0.jpg', 'Elliptical_Trainer/1.jpg'], 'free-exercise-db'),
  ('exercise-ball-crunch', 'Exercise Ball Crunch', 'Core', false, 'strength', 'exercise ball', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).', 'Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.', 'With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.', 'As you inhale, go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Exercise_Ball_Crunch/0.jpg', 'Exercise_Ball_Crunch/1.jpg'], 'free-exercise-db'),
  ('exercise-ball-pull-in', 'Exercise Ball Pull-In', 'Core', false, 'strength', 'exercise ball', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.', 'Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.', 'While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.', 'Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Exercise_Ball_Pull-In/0.jpg', 'Exercise_Ball_Pull-In/1.jpg'], 'free-exercise-db'),
  ('extended-range-one-arm-kettlebell-floor-press', 'Extended Range One-Arm Kettlebell Floor Press', 'Chest', false, 'strength', 'kettlebells', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body.', 'Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position.'], array['Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg', 'Extended_Range_One-Arm_Kettlebell_Floor_Press/1.jpg'], 'free-exercise-db'),
  ('external-rotation', 'External Rotation', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['shoulders'], null, array['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', 'Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso.', 'Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.', 'As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.', 'As you breathe in, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.'], array['External_Rotation/0.jpg', 'External_Rotation/1.jpg'], 'free-exercise-db'),
  ('external-rotation-with-band', 'External Rotation with Band', 'Shoulders', false, 'strength', 'bands', 'beginner', 'compound', 'pull', array['shoulders'], null, array['Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.', 'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.', 'Continue as far as you are able, pause, and then return to the starting position.'], array['External_Rotation_with_Band/0.jpg', 'External_Rotation_with_Band/1.jpg'], 'free-exercise-db'),
  ('external-rotation-with-cable', 'External Rotation with Cable', 'Shoulders', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['shoulders'], null, array['Adjust the cable to the same height as your elbow. Stand with your left side to the band a couple of feet away.', 'Grasp the handle with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.'], array['External_Rotation_with_Cable/0.jpg', 'External_Rotation_with_Cable/1.jpg'], 'free-exercise-db'),
  ('ez-bar-curl', 'EZ-Bar Curl', 'Arms', false, 'strength', 'e-z curl bar', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.', 'Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.', 'Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.', 'Then inhale and slowly lower the bar back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['EZ-Bar_Curl/0.jpg', 'EZ-Bar_Curl/1.jpg'], 'free-exercise-db'),
  ('ez-bar-skullcrusher', 'EZ-Bar Skullcrusher', 'Arms', false, 'strength', 'e-z curl bar', 'beginner', 'isolation', 'push', array['triceps'], array['forearms'], array['Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.', 'Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.', 'Lift the bar back to the starting position by extending the elbow and exhaling.', 'Repeat.'], array['EZ-Bar_Skullcrusher/0.jpg', 'EZ-Bar_Skullcrusher/1.jpg'], 'free-exercise-db'),
  ('face-pull', 'Face Pull', 'Shoulders', false, 'strength', 'cable', 'intermediate', 'compound', 'pull', array['shoulders'], array['middle back'], array['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.'], array['Face_Pull/0.jpg', 'Face_Pull/1.jpg'], 'free-exercise-db'),
  ('farmer-s-walk', 'Farmer''s Walk', 'Arms', false, 'strongman', 'other', 'intermediate', 'compound', null, array['forearms'], array['abdominals', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps'], array['There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.', 'After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.', 'Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.'], array['Farmers_Walk/0.jpg', 'Farmers_Walk/1.jpg'], 'free-exercise-db'),
  ('fast-skipping', 'Fast Skipping', 'Legs', false, 'plyometrics', 'body only', 'beginner', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings'], array['Start in a relaxed position with one leg slightly forward. This will be your starting position.', 'Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.', 'Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.'], array['Fast_Skipping/0.jpg', 'Fast_Skipping/1.jpg'], 'free-exercise-db'),
  ('finger-curls', 'Finger Curls', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.', 'Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.', 'Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top.'], array['Finger_Curls/0.jpg', 'Finger_Curls/1.jpg'], 'free-exercise-db'),
  ('flat-bench-cable-flyes', 'Flat Bench Cable Flyes', 'Chest', false, 'strength', 'cable', 'intermediate', 'isolation', 'push', array['chest'], null, array['Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.', 'Lay flat on the bench and keep your feet on the ground.', 'Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.', 'Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.', 'Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.', 'Slowly come back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Flat_Bench_Cable_Flyes/0.jpg', 'Flat_Bench_Cable_Flyes/1.jpg'], 'free-exercise-db'),
  ('flat-bench-leg-pull-in', 'Flat Bench Leg Pull-In', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Lie on an exercise mat or a flat bench with your legs off the end.', 'Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.', 'Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.', 'As you breathe in, slowly return to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Flat_Bench_Leg_Pull-In/0.jpg', 'Flat_Bench_Leg_Pull-In/1.jpg'], 'free-exercise-db'),
  ('flat-bench-lying-leg-raise', 'Flat Bench Lying Leg Raise', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Lie with your back flat on a bench and your legs extended in front of you off the end.', 'Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.', 'As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.', 'Now, as you inhale, slowly lower your legs back down to the starting position.'], array['Flat_Bench_Lying_Leg_Raise/0.jpg', 'Flat_Bench_Lying_Leg_Raise/1.jpg'], 'free-exercise-db'),
  ('flexor-incline-dumbbell-curls', 'Flexor Incline Dumbbell Curls', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.', 'Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.', 'Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.', 'Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.', 'As you inhale, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Flexor_Incline_Dumbbell_Curls/0.jpg', 'Flexor_Incline_Dumbbell_Curls/1.jpg'], 'free-exercise-db'),
  ('floor-glute-ham-raise', 'Floor Glute-Ham Raise', 'Hamstrings', false, 'strength', null, 'intermediate', 'isolation', 'pull', array['hamstrings'], array['calves', 'glutes'], array['You can use a partner for this exercise or brace your feet under something stable.', 'Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.', 'Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.', 'Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position.'], array['Floor_Glute-Ham_Raise/0.jpg', 'Floor_Glute-Ham_Raise/1.jpg'], 'free-exercise-db'),
  ('floor-press', 'Floor Press', 'Arms', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.', 'Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.', 'Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.'], array['Floor_Press/0.jpg', 'Floor_Press/1.jpg'], 'free-exercise-db'),
  ('floor-press-with-chains', 'Floor Press with Chains', 'Arms', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates.', 'Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks.', 'Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.', 'Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.'], array['Floor_Press_with_Chains/0.jpg', 'Floor_Press_with_Chains/1.jpg'], 'free-exercise-db'),
  ('flutter-kicks', 'Flutter Kicks', 'Glutes', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['glutes'], array['hamstrings'], array['On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.', 'Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.', 'Start the movement by lifting the left leg higher than the right leg.', 'Then lower the left leg as you lift the right leg.', 'Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement.'], array['Flutter_Kicks/0.jpg', 'Flutter_Kicks/1.jpg'], 'free-exercise-db'),
  ('foot-smr', 'Foot-SMR', 'Calves', false, 'stretching', 'other', 'intermediate', null, 'static', array['calves'], null, array['This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position.', 'Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet.'], array['Foot-SMR/0.jpg', 'Foot-SMR/1.jpg'], 'free-exercise-db'),
  ('forward-drag-with-press', 'Forward Drag with Press', 'Chest', false, 'strongman', 'other', 'intermediate', 'compound', 'push', array['chest'], array['calves', 'glutes', 'hamstrings', 'quadriceps', 'shoulders', 'triceps'], array['Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand.', 'Begin the movement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the elbows, pressing your hands forward. Step forward until you return to the start position prepared to press.'], array['Forward_Drag_with_Press/0.jpg', 'Forward_Drag_with_Press/1.jpg'], 'free-exercise-db'),
  ('frankenstein-squat', 'Frankenstein Squat', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['abdominals', 'calves', 'glutes', 'hamstrings'], array['This drill teaches you the proper positioning of both the bar and your body during the clean and front squat.', 'Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don''t round the thoracic spine.', 'Squat by flexing the knees and hips, sitting in between your legs. Keep the torso upright, the arms up, and the shoulders forward, and the bar should stay in place. Go to the bottom of the squat, until your hamstrings contact your calves.', 'Return to the upright position by driving through the front of the heel and extending the knees and hips.'], array['Frankenstein_Squat/0.jpg', 'Frankenstein_Squat/1.jpg'], 'free-exercise-db'),
  ('freehand-jump-squat', 'Freehand Jump Squat', 'Legs', false, 'strength', 'body only', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Cross your arms over your chest.', 'With your head up and your back straight, position your feet at shoulder width.', 'Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.', 'Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.', 'When you touch the floor again, immediately squat down and jump again.', 'Repeat for the recommended amount of repetitions.'], array['Freehand_Jump_Squat/0.jpg', 'Freehand_Jump_Squat/1.jpg'], 'free-exercise-db'),
  ('frog-hops', 'Frog Hops', 'Legs', false, 'stretching', null, 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.', 'Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times.'], array['Frog_Hops/0.jpg', 'Frog_Hops/1.jpg'], 'free-exercise-db'),
  ('frog-sit-ups', 'Frog Sit-Ups', 'Core', false, 'strength', 'body only', 'intermediate', 'isolation', 'pull', array['abdominals'], null, array['Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.', 'Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.', 'Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.', 'Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.', 'As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.', 'As you inhale, slowly lower back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Frog_Sit-Ups/0.jpg', 'Frog_Sit-Ups/1.jpg'], 'free-exercise-db'),
  ('front-barbell-squat', 'Front Barbell Squat', 'Legs', false, 'strength', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Front_Barbell_Squat/0.jpg', 'Front_Barbell_Squat/1.jpg'], 'free-exercise-db'),
  ('front-barbell-squat-to-a-bench', 'Front Barbell Squat To A Bench', 'Legs', false, 'strength', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat bench behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until you touch the bench with your glutes. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Front_Barbell_Squat_To_A_Bench/0.jpg', 'Front_Barbell_Squat_To_A_Bench/1.jpg'], 'free-exercise-db'),
  ('front-box-jump', 'Front Box Jump', 'Hamstrings', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['hamstrings'], array['abductors', 'adductors', 'calves', 'glutes', 'quadriceps'], array['Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.', 'Perform a short squat in preparation for jumping, swinging your arms behind you.', 'Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.', 'Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time.'], array['Front_Box_Jump/0.jpg', 'Front_Box_Jump/1.jpg'], 'free-exercise-db'),
  ('front-cable-raise', 'Front Cable Raise', 'Shoulders', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['shoulders'], null, array['Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.', 'Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms'' length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.', 'Now as you inhale lower the arm back down slowly to the starting position.', 'Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one.'], array['Front_Cable_Raise/0.jpg', 'Front_Cable_Raise/1.jpg'], 'free-exercise-db'),
  ('front-cone-hops-or-hurdle-hops', 'Front Cone Hops (or hurdle hops)', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings'], array['Set up a row of cones or other small barriers, placing them a few feet apart.', 'Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.', 'Begin by jumping with both feet over the first cone, swinging both arms as you jump.', 'Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.', 'Continue until you have jumped over all of the cones.'], array['Front_Cone_Hops_or_hurdle_hops/0.jpg', 'Front_Cone_Hops_or_hurdle_hops/1.jpg'], 'free-exercise-db'),
  ('front-dumbbell-raise', 'Front Dumbbell Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], null, array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.', 'Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.', 'Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.'], array['Front_Dumbbell_Raise/0.jpg', 'Front_Dumbbell_Raise/1.jpg'], 'free-exercise-db'),
  ('front-incline-dumbbell-raise', 'Front Incline Dumbbell Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], null, array['Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand. Tip: You can change the angle to hit the muscle a little differently each time.', 'Extend your arms straight in front of you and have your palms facing down with the dumbbells raised about 1 inch above your thighs. This will be your starting position.', 'Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked. Squeeze at the top for a second and make sure you breathe out during this portion of the movement. Tip: Keep your head resting down against the bench and your legs on the floor at all times.', 'Lower the arms back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Front_Incline_Dumbbell_Raise/0.jpg', 'Front_Incline_Dumbbell_Raise/1.jpg'], 'free-exercise-db'),
  ('front-leg-raises', 'Front Leg Raises', 'Hamstrings', false, 'stretching', 'body only', 'beginner', null, 'pull', array['hamstrings'], null, array['Stand next to a chair or other support, holding on with one hand.', 'Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs.'], array['Front_Leg_Raises/0.jpg', 'Front_Leg_Raises/1.jpg'], 'free-exercise-db'),
  ('front-plate-raise', 'Front Plate Raise', 'Shoulders', false, 'strength', 'other', 'intermediate', 'isolation', 'push', array['shoulders'], null, array['While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.', 'Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. Tip: make sure that you do not swing the weight or bend at the elbows. Your torso should remain stationary throughout the movement as well.', 'As you inhale, slowly lower the plate back down to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Front_Plate_Raise/0.jpg', 'Front_Plate_Raise/1.jpg'], 'free-exercise-db'),
  ('front-raise-and-pullover', 'Front Raise And Pullover', 'Chest', false, 'strength', 'barbell', 'beginner', 'compound', 'pull', array['chest'], array['lats', 'shoulders', 'triceps'], array['Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.', 'Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position.', 'Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms should be parallel to the floor with the palms of your hands facing the ceiling.', 'Now return the barbell to the starting position by reversing the motion as you exhale.', 'Repeat for the recommended amount of repetitions.'], array['Front_Raise_And_Pullover/0.jpg', 'Front_Raise_And_Pullover/1.jpg'], 'free-exercise-db'),
  ('front-squat', 'Front Squat', 'Legs', false, 'strength', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Front_Barbell_Squat/0.jpg', 'Front_Barbell_Squat/1.jpg'], 'repple+free-exercise-db'),
  ('front-squat-clean-grip', 'Front Squat (Clean Grip)', 'Legs', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['abdominals', 'glutes', 'hamstrings'], array['To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.', 'Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position.'], array['Front_Squat_Clean_Grip/0.jpg', 'Front_Squat_Clean_Grip/1.jpg'], 'free-exercise-db'),
  ('front-squats-with-two-kettlebells', 'Front Squats With Two Kettlebells', 'Legs', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes'], array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.', 'Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.', 'Rise back up by driving through your heels and repeat.'], array['Front_Squats_With_Two_Kettlebells/0.jpg', 'Front_Squats_With_Two_Kettlebells/1.jpg'], 'free-exercise-db'),
  ('front-two-dumbbell-raise', 'Front Two-Dumbbell Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], null, array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arms are slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.', 'As you inhale, lower the dumbbells back down slowly to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Front_Two-Dumbbell_Raise/0.jpg', 'Front_Two-Dumbbell_Raise/1.jpg'], 'free-exercise-db'),
  ('full-range-of-motion-lat-pulldown', 'Full Range-Of-Motion Lat Pulldown', 'Back', false, 'strength', 'cable', 'intermediate', 'compound', 'pull', array['lats'], array['biceps', 'middle back', 'shoulders'], array['Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward.', 'Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat.'], array['Full_Range-Of-Motion_Lat_Pulldown/0.jpg', 'Full_Range-Of-Motion_Lat_Pulldown/1.jpg'], 'free-exercise-db'),
  ('gironda-sternum-chins', 'Gironda Sternum Chins', 'Back', false, 'strength', 'other', 'intermediate', 'compound', 'pull', array['lats'], array['biceps', 'middle back'], array['Grasp the pull-up bar with a shoulder width underhand grip.', 'Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position.', 'Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs will be at about a 45-degree angle to the floor.', 'Keep pulling until your collarbone passes the bar and your lower chest or sternum area touches it. Hold that contraction for a second. Tip: By the time you''ve completed this portion of the movement; your head will be parallel to the floor.', 'Slowly start going back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Gironda_Sternum_Chins/0.jpg', 'Gironda_Sternum_Chins/1.jpg'], 'free-exercise-db'),
  ('glute-bridge', 'Glute Bridge', 'Glutes', false, 'strength', 'body only', 'beginner', 'isolation', 'push', array['glutes'], array['hamstrings'], array['Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.', 'Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.', 'Slowly go back to the starting position as you breathe in.'], array['Butt_Lift_Bridge/0.jpg', 'Butt_Lift_Bridge/1.jpg'], 'repple+free-exercise-db'),
  ('glute-ham-raise', 'Glute Ham Raise', 'Hamstrings', false, 'powerlifting', 'machine', 'intermediate', 'compound', 'pull', array['hamstrings'], array['calves', 'glutes'], array['Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.', 'Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.', 'Return to the starting position, keeping your descent under control.'], array['Glute_Ham_Raise/0.jpg', 'Glute_Ham_Raise/1.jpg'], 'free-exercise-db'),
  ('glute-kickback', 'Glute Kickback', 'Glutes', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['glutes'], array['hamstrings'], array['Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.', 'As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.', 'Go back to the initial position as you inhale and now repeat with the left leg.', 'Continue to alternate legs until all of the recommended repetitions have been performed.'], array['Glute_Kickback/0.jpg', 'Glute_Kickback/1.jpg'], 'free-exercise-db'),
  ('goblet-squat', 'Goblet Squat', 'Legs', false, 'strength', 'kettlebells', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'shoulders'], array['Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.', 'Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.', 'At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.'], array['Goblet_Squat/0.jpg', 'Goblet_Squat/1.jpg'], 'free-exercise-db'),
  ('good-morning', 'Good Morning', 'Hamstrings', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['hamstrings'], array['abdominals', 'glutes', 'lower back'], array['Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.', 'Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.', 'Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.'], array['Good_Morning/0.jpg', 'Good_Morning/1.jpg'], 'free-exercise-db'),
  ('good-morning-off-pins', 'Good Morning off Pins', 'Hamstrings', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['hamstrings'], array['abdominals', 'glutes', 'lower back'], array['Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.', 'Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position.'], array['Good_Morning_off_Pins/0.jpg', 'Good_Morning_off_Pins/1.jpg'], 'free-exercise-db'),
  ('gorilla-chin-crunch', 'Gorilla Chin/Crunch', 'Core', false, 'strength', 'body only', 'intermediate', 'compound', 'pull', array['abdominals'], array['biceps', 'lats'], array['Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.', 'Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.', 'As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.', 'Slowly start to inhale as you return to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Gorilla_Chin_Crunch/0.jpg', 'Gorilla_Chin_Crunch/1.jpg'], 'free-exercise-db'),
  ('groin-and-back-stretch', 'Groin and Back Stretch', 'Legs', false, 'stretching', null, 'intermediate', 'compound', 'static', array['adductors'], null, array['Sit on the floor with your knees bent and feet together.', 'Interlock your fingers behind your head. This will be your starting position.', 'Curl downwards, bringing your elbows to the inside of your thighs. After a brief pause, return to the starting position with your head up and your back straight. Repeat for 10-20 repetitions.'], array['Groin_and_Back_Stretch/0.jpg', 'Groin_and_Back_Stretch/1.jpg'], 'free-exercise-db'),
  ('groiners', 'Groiners', 'Legs', false, 'stretching', 'body only', 'intermediate', 'compound', 'pull', array['adductors'], null, array['Begin in a pushup position on the floor. This will be your starting position.', 'Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.', 'Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions.'], array['Groiners/0.jpg', 'Groiners/1.jpg'], 'free-exercise-db'),
  ('hack-squat', 'Hack Squat', 'Legs', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.', 'Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).', 'Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Hack_Squat/0.jpg', 'Hack_Squat/1.jpg'], 'free-exercise-db'),
  ('hammer-curl', 'Hammer Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.', 'After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Hammer_Curls/0.jpg', 'Hammer_Curls/1.jpg'], 'repple+free-exercise-db'),
  ('hammer-curls', 'Hammer Curls', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.', 'After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Hammer_Curls/0.jpg', 'Hammer_Curls/1.jpg'], 'free-exercise-db'),
  ('hammer-grip-incline-db-bench-press', 'Hammer Grip Incline DB Bench Press', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.', 'Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.', 'Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells.'], array['Hammer_Grip_Incline_DB_Bench_Press/0.jpg', 'Hammer_Grip_Incline_DB_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('hamstring-smr', 'Hamstring-SMR', 'Hamstrings', false, 'stretching', 'foam roll', 'beginner', 'isolation', 'static', array['hamstrings'], null, array['In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position.', 'Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching.', 'Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for the other leg.'], array['Hamstring-SMR/0.jpg', 'Hamstring-SMR/1.jpg'], 'free-exercise-db'),
  ('hamstring-stretch', 'Hamstring Stretch', 'Hamstrings', false, 'stretching', null, 'beginner', 'isolation', 'static', array['hamstrings'], null, array['Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor.', 'Loop a belt, band, or rope over the ball of your foot. This will be your starting position.', 'Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg.'], array['Hamstring_Stretch/0.jpg', 'Hamstring_Stretch/1.jpg'], 'free-exercise-db'),
  ('handstand-push-ups', 'Handstand Push-Ups', 'Shoulders', false, 'strength', 'body only', 'expert', 'compound', 'push', array['shoulders'], array['triceps'], array['With your back to the wall bend at the waist and place both hands on the floor at shoulder width.', 'Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down.', 'Slowly lower yourself to the ground as you inhale until your head almost touches the floor. Tip: It is of utmost importance that you come down slow in order to avoid head injury.', 'Push yourself back up slowly as you exhale until your elbows are nearly locked.', 'Repeat for the recommended amount of repetitions.'], array['Handstand_Push-Ups/0.jpg', 'Handstand_Push-Ups/1.jpg'], 'free-exercise-db'),
  ('hang-clean', 'Hang Clean', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['quadriceps'], array['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps'], array['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.', 'Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.'], array['Hang_Clean/0.jpg', 'Hang_Clean/1.jpg'], 'free-exercise-db'),
  ('hang-clean-below-the-knees', 'Hang Clean - Below the Knees', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['quadriceps'], array['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps'], array['Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward.', 'Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out.', 'At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.'], array['Hang_Clean_-_Below_the_Knees/0.jpg', 'Hang_Clean_-_Below_the_Knees/1.jpg'], 'free-exercise-db'),
  ('hang-snatch', 'Hang Snatch', 'Hamstrings', false, 'olympic weightlifting', 'barbell', 'expert', 'compound', 'pull', array['hamstrings'], array['abdominals', 'calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps'], array['Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.', 'Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control.'], array['Hang_Snatch/0.jpg', 'Hang_Snatch/1.jpg'], 'free-exercise-db'),
  ('hang-snatch-below-knees', 'Hang Snatch - Below Knees', 'Hamstrings', false, 'olympic weightlifting', 'barbell', 'expert', 'compound', 'pull', array['hamstrings'], array['abdominals', 'calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps'], array['Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position.', 'Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Return to a standing position with the weight overhead, and then return the weight to the floor under control.'], array['Hang_Snatch_-_Below_Knees/0.jpg', 'Hang_Snatch_-_Below_Knees/1.jpg'], 'free-exercise-db'),
  ('hanging-bar-good-morning', 'Hanging Bar Good Morning', 'Hamstrings', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['hamstrings'], array['abdominals', 'glutes', 'lower back'], array['Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps.', 'Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.', 'Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight.', 'Slowly lower the weight back to the starting position, where it is supported by the chains.'], array['Hanging_Bar_Good_Morning/0.jpg', 'Hanging_Bar_Good_Morning/1.jpg'], 'free-exercise-db'),
  ('hanging-leg-raise', 'Hanging Leg Raise', 'Core', false, 'strength', 'body only', 'expert', 'isolation', 'pull', array['abdominals'], null, array['Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.', 'Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.', 'Go back slowly to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Hanging_Leg_Raise/0.jpg', 'Hanging_Leg_Raise/1.jpg'], 'free-exercise-db'),
  ('hanging-pike', 'Hanging Pike', 'Core', false, 'strength', 'body only', 'expert', 'compound', 'pull', array['abdominals'], null, array['Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar.', 'Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your starting position.', 'Pull your legs up as you exhale until you almost touch your shins with the bar above you. Tip: Try to straighten your legs as much as possible while at the top.', 'Lower your legs as slowly as possible until you reach the starting position. Tip: Avoid swinging and using momentum at all times.', 'Repeat for the recommended amount of repetitions.'], array['Hanging_Pike/0.jpg', 'Hanging_Pike/1.jpg'], 'free-exercise-db'),
  ('heaving-snatch-balance', 'Heaving Snatch Balance', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['abdominals', 'forearms', 'glutes', 'hamstrings', 'shoulders', 'triceps'], array['This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with.', 'Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat.', 'Return to a standing position.'], array['Heaving_Snatch_Balance/0.jpg', 'Heaving_Snatch_Balance/1.jpg'], 'free-exercise-db'),
  ('heavy-bag-thrust', 'Heavy Bag Thrust', 'Chest', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position.', 'Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body.', 'Receive the bag as it swings back by reversing these steps.'], array['Heavy_Bag_Thrust/0.jpg', 'Heavy_Bag_Thrust/1.jpg'], 'free-exercise-db'),
  ('high-cable-curls', 'High Cable Curls', 'Arms', false, 'strength', 'cable', 'intermediate', 'compound', 'pull', array['biceps'], null, array['Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.', 'Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.', 'Slowly bring back the arms to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['High_Cable_Curls/0.jpg', 'High_Cable_Curls/1.jpg'], 'free-exercise-db'),
  ('hip-abduction', 'Hip Abduction', 'Glutes', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['abductors'], array['glutes'], array['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them away from each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.'], array['Thigh_Abductor/0.jpg', 'Thigh_Abductor/1.jpg'], 'repple+free-exercise-db'),
  ('hip-circles-prone', 'Hip Circles (prone)', 'Glutes', false, 'stretching', 'body only', 'beginner', 'isolation', 'pull', array['abductors'], array['adductors'], array['Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.', 'Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.', 'Perform this slowly for a number of repetitions, and repeat on the other side.'], array['Hip_Circles_prone/0.jpg', 'Hip_Circles_prone/1.jpg'], 'free-exercise-db'),
  ('hip-extension-with-bands', 'Hip Extension with Bands', 'Glutes', false, 'strength', 'bands', 'beginner', 'compound', 'push', array['glutes'], array['hamstrings'], array['Secure one end of the band to the lower portion of a post and attach the other to one ankle.', 'Facing the attachment point of the band, hold on to the column to stabilize yourself.', 'Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.', 'Return the leg to the starting position.'], array['Hip_Extension_with_Bands/0.jpg', 'Hip_Extension_with_Bands/1.jpg'], 'free-exercise-db'),
  ('hip-flexion-with-band', 'Hip Flexion with Band', 'Legs', false, 'strength', 'bands', 'beginner', 'compound', 'pull', array['quadriceps'], null, array['Secure one end of the band to the lower portion of a post and attach the other to one ankle.', 'Face away from the attachment point of the band.', 'Keeping your head and your chest up, raise your knee up to 90 degrees and pause.', 'Return the leg to the starting position.'], array['Hip_Flexion_with_Band/0.jpg', 'Hip_Flexion_with_Band/1.jpg'], 'free-exercise-db'),
  ('hip-lift-with-band', 'Hip Lift with Band', 'Glutes', false, 'powerlifting', 'bands', 'beginner', 'compound', 'push', array['glutes'], array['calves', 'hamstrings'], array['After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move.', 'Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.', 'Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.', 'Pause at the top of the motion, and return to the starting position.'], array['Hip_Lift_with_Band/0.jpg', 'Hip_Lift_with_Band/1.jpg'], 'free-exercise-db'),
  ('hip-thrust', 'Hip Thrust', 'Glutes', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['glutes'], array['calves', 'hamstrings'], array['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.', 'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.', 'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.'], array['Barbell_Hip_Thrust/0.jpg', 'Barbell_Hip_Thrust/1.jpg'], 'repple+free-exercise-db'),
  ('hug-a-ball', 'Hug A Ball', 'Lower back', false, 'stretching', 'exercise ball', 'beginner', 'isolation', 'static', array['lower back'], array['calves', 'glutes'], array['Seat yourself on the floor.', 'Straddle an exercise ball between both legs and lower your hips down toward the floor.', 'Hug your arms around the ball to support your body. Adjust your legs so that your feet are flat on the floor and your knees line up over your ankles. Keep a good grip on the ball so it doesn''t roll away from you and send you back onto your buttocks.'], array['Hug_A_Ball/0.jpg', 'Hug_A_Ball/1.jpg'], 'free-exercise-db'),
  ('hug-knees-to-chest', 'Hug Knees To Chest', 'Lower back', false, 'stretching', null, 'beginner', null, 'static', array['lower back'], array['glutes'], array['Lie down on your back and pull both knees up to your chest.', 'Hold your arms under the knees, not over (that would put to much pressure on your knee joints).', 'Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles.'], array['Hug_Knees_To_Chest/0.jpg', 'Hug_Knees_To_Chest/1.jpg'], 'free-exercise-db'),
  ('hurdle-hops', 'Hurdle Hops', 'Hamstrings', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['hamstrings'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings'], array['Set up a row of hurdles or other small barriers, placing them a few feet apart.', 'Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position.', 'Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.', 'Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles.'], array['Hurdle_Hops/0.jpg', 'Hurdle_Hops/1.jpg'], 'free-exercise-db'),
  ('hyperextensions-back-extensions', 'Hyperextensions (Back Extensions)', 'Lower back', false, 'strength', 'other', 'beginner', 'isolation', 'pull', array['lower back'], array['glutes', 'hamstrings'], array['Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.', 'Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.', 'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.', 'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.', 'Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.', 'Repeat for the recommended amount of repetitions.'], array['Hyperextensions_Back_Extensions/0.jpg', 'Hyperextensions_Back_Extensions/1.jpg'], 'free-exercise-db'),
  ('hyperextensions-with-no-hyperextension-bench', 'Hyperextensions With No Hyperextension Bench', 'Lower back', false, 'strength', 'body only', 'intermediate', 'compound', 'pull', array['lower back'], array['glutes', 'hamstrings'], array['With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.', 'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.', 'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first). Tip: Never round the back as you perform this exercise.', 'Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.', 'Repeat for the recommended amount of repetitions.'], array['Hyperextensions_With_No_Hyperextension_Bench/0.jpg', 'Hyperextensions_With_No_Hyperextension_Bench/1.jpg'], 'free-exercise-db'),
  ('iliotibial-tract-smr', 'Iliotibial Tract-SMR', 'Glutes', false, 'stretching', 'foam roll', 'intermediate', 'isolation', 'static', array['abductors'], null, array['Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.', 'Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.', 'Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg.'], array['Iliotibial_Tract-SMR/0.jpg', 'Iliotibial_Tract-SMR/1.jpg'], 'free-exercise-db'),
  ('inchworm', 'Inchworm', 'Hamstrings', false, 'stretching', 'body only', 'beginner', 'compound', null, array['hamstrings'], null, array['Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position.', 'Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.', 'Keep going until your body is parallel to the ground in a pushup position.', 'Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.', 'Continue walking until your feet are by hour hands, keeping your legs straight as you do so.'], array['Inchworm/0.jpg', 'Inchworm/1.jpg'], 'free-exercise-db'),
  ('incline-barbell-triceps-extension', 'Incline Barbell Triceps Extension', 'Arms', false, 'strength', 'barbell', 'intermediate', 'isolation', 'push', array['triceps'], array['forearms'], array['Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.', 'Lie back on an incline bench set at any angle between 45-75-degrees.', 'Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position.', 'Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.', 'Return to the starting position as you breathe out and you contract the triceps. Hold the contraction for a second.', 'Repeat for the recommended amount of repetitions.'], array['Incline_Barbell_Triceps_Extension/0.jpg', 'Incline_Barbell_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('incline-bench-pull', 'Incline Bench Pull', 'Back', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['middle back'], array['lats', 'shoulders'], array['Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.', 'Let the arms hang to your sides fully extended as they point to the floor.', 'Turn the wrists until your hands have a pronated (palms down) grip.', 'Now flare the elbows out. This will be your starting position.', 'As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as your back. Tip: The elbows will come out to the side and your upper arms and torso should make the letter "T" at the top of the movement. Hold the contraction at the top for a second.', 'Slowly go back down to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Incline_Bench_Pull/0.jpg', 'Incline_Bench_Pull/1.jpg'], 'free-exercise-db'),
  ('incline-cable-chest-press', 'Incline Cable Chest Press', 'Chest', false, 'strength', 'cable', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.', 'After pausing at full extension, return to the starting position, keeping tension on the cables.'], array['Incline_Cable_Chest_Press/0.jpg', 'Incline_Cable_Chest_Press/1.jpg'], 'free-exercise-db'),
  ('incline-cable-flye', 'Incline Cable Flye', 'Chest', false, 'strength', 'cable', 'intermediate', 'isolation', 'push', array['chest'], array['shoulders'], array['To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).', 'Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.', 'With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.', 'With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Repeat the movement for the prescribed amount of repetitions.'], array['Incline_Cable_Flye/0.jpg', 'Incline_Cable_Flye/1.jpg'], 'free-exercise-db'),
  ('incline-dumbbell-bench-with-palms-facing-in', 'Incline Dumbbell Bench With Palms Facing In', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.', 'Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.', 'Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells.'], array['Incline_Dumbbell_Bench_With_Palms_Facing_In/0.jpg', 'Incline_Dumbbell_Bench_With_Palms_Facing_In/1.jpg'], 'free-exercise-db'),
  ('incline-dumbbell-curl', 'Incline Dumbbell Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Incline_Dumbbell_Curl/0.jpg', 'Incline_Dumbbell_Curl/1.jpg'], 'free-exercise-db'),
  ('incline-dumbbell-flyes', 'Incline Dumbbell Flyes', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders'], array['Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.', 'Extend your arms above you with a slight bend at the elbows.', 'Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.', 'As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.', 'As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.', 'Repeat for the recommended amount of repetitions.'], array['Incline_Dumbbell_Flyes/0.jpg', 'Incline_Dumbbell_Flyes/1.jpg'], 'free-exercise-db'),
  ('incline-dumbbell-flyes-with-a-twist', 'Incline Dumbbell Flyes - With A Twist', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders'], array['Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.', 'Extend your arms above you with a slight bend at the elbows.', 'Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.', 'As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.', 'As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.', 'Repeat for the recommended amount of repetitions.'], array['Incline_Dumbbell_Flyes_-_With_A_Twist/0.jpg', 'Incline_Dumbbell_Flyes_-_With_A_Twist/1.jpg'], 'free-exercise-db'),
  ('incline-dumbbell-press', 'Incline Dumbbell Press', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.', 'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.', 'Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.'], array['Incline_Dumbbell_Press/0.jpg', 'Incline_Dumbbell_Press/1.jpg'], 'free-exercise-db'),
  ('incline-hammer-curls', 'Incline Hammer Curls', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.', 'Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.', 'Continue to the top of the movement and pause, then slowly return to the start position.'], array['Incline_Hammer_Curls/0.jpg', 'Incline_Hammer_Curls/1.jpg'], 'free-exercise-db'),
  ('incline-inner-biceps-curl', 'Incline Inner Biceps Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', null, array['biceps'], null, array['Hold a dumbbell in each hand and lie back on an incline bench.', 'The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position.', 'Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.', 'After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up.', 'Repeat for the recommended amount of repetitions.'], array['Incline_Inner_Biceps_Curl/0.jpg', 'Incline_Inner_Biceps_Curl/1.jpg'], 'free-exercise-db'),
  ('incline-push-up', 'Incline Push-Up', 'Chest', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.', 'Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.', 'Push body up until arms are extended. Repeat.'], array['Incline_Push-Up/0.jpg', 'Incline_Push-Up/1.jpg'], 'free-exercise-db'),
  ('incline-push-up-close-grip', 'Incline Push-Up Close-Grip', 'Arms', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands next to one another on the bar.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.'], array['Incline_Push-Up_Close-Grip/0.jpg', 'Incline_Push-Up_Close-Grip/1.jpg'], 'free-exercise-db'),
  ('incline-push-up-depth-jump', 'Incline Push-Up Depth Jump', 'Chest', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps.', 'Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps. This will be your starting position.', 'Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground. As you leave the ground, move your hands onto the steps, bending your elbows to absorb the impact.', 'Repeat the motion to return to the starting position.'], array['Incline_Push-Up_Depth_Jump/0.jpg', 'Incline_Push-Up_Depth_Jump/1.jpg'], 'free-exercise-db'),
  ('incline-push-up-medium', 'Incline Push-Up Medium', 'Chest', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar, with your hands about shoulder width apart.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.'], array['Incline_Push-Up_Medium/0.jpg', 'Incline_Push-Up_Medium/1.jpg'], 'free-exercise-db'),
  ('incline-push-up-reverse-grip', 'Incline Push-Up Reverse Grip', 'Chest', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar palms up, with your hands about shoulder width apart.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.'], array['Incline_Push-Up_Reverse_Grip/0.jpg', 'Incline_Push-Up_Reverse_Grip/1.jpg'], 'free-exercise-db'),
  ('incline-push-up-wide', 'Incline Push-Up Wide', 'Chest', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar, with your hands wider than shoulder width.', 'Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.'], array['Incline_Push-Up_Wide/0.jpg', 'Incline_Push-Up_Wide/1.jpg'], 'free-exercise-db'),
  ('intermediate-groin-stretch', 'Intermediate Groin Stretch', 'Hamstrings', false, 'stretching', 'other', 'intermediate', 'isolation', 'static', array['hamstrings'], null, array['Lie on your back with your legs extended. Loop a belt, rope, or band around one of your feet, and swing that leg as far to the side as you can. This will be your starting position.', 'Pull gently on the belt to create tension in your groin and hamstring muscles. Hold for 10-20 seconds, and repeat on the other side.'], array['Intermediate_Groin_Stretch/0.jpg', 'Intermediate_Groin_Stretch/1.jpg'], 'free-exercise-db'),
  ('intermediate-hip-flexor-and-quad-stretch', 'Intermediate Hip Flexor and Quad Stretch', 'Legs', false, 'stretching', 'other', 'intermediate', 'compound', 'static', array['quadriceps'], null, array['Lie face down on the floor, with a rope, belt, or band looped around one foot.', 'Flex the knee and extend the hip of the leg to be stretched, using both hands to pull on the belt. Your knee and your hip should come off of the floor, creating tension in the hip flexors and quadriceps. Hold the stretch for 10-20 seconds, and repeat on the other leg.'], array['Intermediate_Hip_Flexor_and_Quad_Stretch/0.jpg', 'Intermediate_Hip_Flexor_and_Quad_Stretch/1.jpg'], 'free-exercise-db'),
  ('internal-rotation-with-band', 'Internal Rotation with Band', 'Shoulders', false, 'strength', 'bands', 'beginner', 'isolation', null, array['shoulders'], null, array['Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.', 'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.', 'Continue as far as you are able, pause, and then return to the starting position.'], array['Internal_Rotation_with_Band/0.jpg', 'Internal_Rotation_with_Band/1.jpg'], 'free-exercise-db'),
  ('inverted-row', 'Inverted Row', 'Back', false, 'strength', null, 'beginner', 'compound', 'pull', array['middle back'], array['lats'], array['Position a bar in a rack to about waist height. You can also use a smith machine.', 'Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.', 'Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.', 'Pause at the top of the motion, and return yourself to the start position.', 'Repeat for the desired number of repetitions.'], array['Inverted_Row/0.jpg', 'Inverted_Row/1.jpg'], 'free-exercise-db'),
  ('inverted-row-with-straps', 'Inverted Row with Straps', 'Back', false, 'strength', 'other', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.', 'Begin by flexing the elbow, pulling your chest to your hands. Retract your shoulder blades as you perform the movement.', 'Pause at the top of the motion, and return yourself to the start position.', 'Repeat for the desired number of repetitions.'], array['Inverted_Row_with_Straps/0.jpg', 'Inverted_Row_with_Straps/1.jpg'], 'free-exercise-db'),
  ('iron-cross', 'Iron Cross', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['shoulders'], array['chest', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps'], null, array['Iron_Cross/0.jpg', 'Iron_Cross/1.jpg'], 'free-exercise-db'),
  ('iron-crosses-stretch', 'Iron Crosses (stretch)', 'Legs', false, 'stretching', null, 'intermediate', 'compound', 'pull', array['quadriceps'], null, array['Lie face down on the floor, with your arms extended out to your side, palms pressed to the floor. This will be your starting position.', 'To begin, flex one knee and bring that leg across the back of your body, attempting to touch it to the ground near the opposite hand.', 'Promptly return the leg to the starting postion, and quickly repeat with the other leg. Continue alternating for 10-20 repetitions.'], array['Iron_Crosses_stretch/0.jpg', 'Iron_Crosses_stretch/1.jpg'], 'free-exercise-db'),
  ('isometric-chest-squeezes', 'Isometric Chest Squeezes', 'Chest', false, 'plyometrics', 'body only', 'beginner', 'compound', 'static', array['chest'], array['shoulders', 'triceps'], array['While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso).', 'Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.', 'Hold for the recommended number of seconds.', 'Now release the tension slowly.', 'Rest for the recommended amount of time and repeat.'], array['Isometric_Chest_Squeezes/0.jpg', 'Isometric_Chest_Squeezes/1.jpg'], 'free-exercise-db'),
  ('isometric-neck-exercise-front-and-back', 'Isometric Neck Exercise - Front And Back', 'Neck', false, 'strength', 'body only', 'beginner', 'isolation', 'static', array['neck'], null, array['With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.', 'Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.', 'Hold for the recommended number of seconds.', 'Now release the tension slowly.', 'Rest for the recommended amount of time and repeat with your hands placed on the back side of your head.'], array['Isometric_Neck_Exercise_-_Front_And_Back/0.jpg', 'Isometric_Neck_Exercise_-_Front_And_Back/1.jpg'], 'free-exercise-db'),
  ('isometric-neck-exercise-sides', 'Isometric Neck Exercise - Sides', 'Neck', false, 'strength', 'body only', 'beginner', 'isolation', 'static', array['neck'], null, array['With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head.', 'Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.', 'Hold for the recommended number of seconds.', 'Now release the tension slowly.', 'Rest for the recommended amount of time and repeat with your right hand placed on the right side of your head.'], array['Isometric_Neck_Exercise_-_Sides/0.jpg', 'Isometric_Neck_Exercise_-_Sides/1.jpg'], 'free-exercise-db'),
  ('isometric-wipers', 'Isometric Wipers', 'Chest', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight. Your hands should be just outside of shoulder width. This will be your starting position.', 'Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body.', 'Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side.', 'Repeat for the desired number of repetitions.'], array['Isometric_Wipers/0.jpg', 'Isometric_Wipers/1.jpg'], 'free-exercise-db'),
  ('it-band-and-glute-stretch', 'IT Band and Glute Stretch', 'Glutes', false, 'stretching', 'other', 'intermediate', null, 'static', array['abductors'], null, array['Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground. This will be your starting position.', 'Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and repeat on the other side.'], array['IT_Band_and_Glute_Stretch/0.jpg', 'IT_Band_and_Glute_Stretch/1.jpg'], 'free-exercise-db'),
  ('jackknife-sit-up', 'Jackknife Sit-Up', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.', 'As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.', 'While inhaling, lower your arms and legs back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Jackknife_Sit-Up/0.jpg', 'Jackknife_Sit-Up/1.jpg'], 'free-exercise-db'),
  ('janda-sit-up', 'Janda Sit-Up', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides. This will be your starting position.', 'As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings as this will cause the hip flexors to be inactivated in a process called reciprocal inhibition, which basically means that opposite muscles to the contracted ones will relax.', 'As you inhale, slowly go back in a controlled manner to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Janda_Sit-Up/0.jpg', 'Janda_Sit-Up/1.jpg'], 'free-exercise-db'),
  ('jefferson-squats', 'Jefferson Squats', 'Legs', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back', 'traps'], array['Place a barbell on the floor.', 'Stand in the middle of the bar length wise.', 'Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side.', 'Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Tip: Ensure that your grip is even on the bar. Your torso should be positioned right in the middle of the bar and the distance between your torso and your right hand (which should be at the front) should be the same as the distance between your torso and your left hand (which should be to your back).', 'Now stand straight up with the weight. Tip: Your feet should be shoulder width apart and your toes slightly pointed out.', 'Squat down by bending at the knees and keeping your back straight until your upper thighs are parallel with the floor. Tip: Keep your back as vertical as possible with the floor and your head up. Also remember to not let your knees go past your toes. Inhale during this portion of the movement.', 'Now drive yourself back up to the starting position by pushing with the feet . Tip: Keep the bar hanging at arm''s length and your elbows locked with a slight bend. The arms only serve as hooks. Avoid doing any lifting with them. Do the lifting with your thighs; not your arms.'], array['Jefferson_Squats/0.jpg', 'Jefferson_Squats/1.jpg'], 'free-exercise-db'),
  ('jerk-balance', 'Jerk Balance', 'Shoulders', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'push', array['shoulders'], array['glutes', 'hamstrings', 'quadriceps', 'triceps'], array['This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.', 'Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.', 'Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead.'], array['Jerk_Balance/0.jpg', 'Jerk_Balance/1.jpg'], 'free-exercise-db'),
  ('jerk-dip-squat', 'Jerk Dip Squat', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['abdominals', 'calves'], array['This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable.', 'Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the weight to the starting position by driving forcefully though the feet.'], array['Jerk_Dip_Squat/0.jpg', 'Jerk_Dip_Squat/1.jpg'], 'free-exercise-db'),
  ('jm-press', 'JM Press', 'Arms', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.', 'Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.', 'As you exhale, press the bar back up by using the triceps to perform a close grip bench press.', 'Now go back to the starting position and start over.', 'Repeat for the recommended amount of repetitions.'], array['JM_Press/0.jpg', 'JM_Press/1.jpg'], 'free-exercise-db'),
  ('jogging-treadmill', 'Jogging, Treadmill', 'Legs', true, 'cardio', 'machine', 'beginner', null, null, array['quadriceps'], array['glutes', 'hamstrings'], array['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.'], array['Jogging_Treadmill/0.jpg', 'Jogging_Treadmill/1.jpg'], 'free-exercise-db'),
  ('keg-load', 'Keg Load', 'Lower back', false, 'strongman', 'other', 'intermediate', 'compound', 'pull', array['lower back'], array['abdominals', 'biceps', 'calves', 'forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'shoulders', 'traps'], array['To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet.', 'Begin by grabbing the close handle of the first keg, tilting it onto its side to grab the opposite edge of the bottom of the keg. Lift the keg up to your chest.', 'The higher you can place the keg, the faster you should be able to move to the platform. Shouldering is usually not allowed. Be sure to keep a firm hold on the keg. Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible.', 'Return to the starting position to retrieve the next keg, and repeat until the event is completed.'], array['Keg_Load/0.jpg', 'Keg_Load/1.jpg'], 'free-exercise-db'),
  ('kettlebell-arnold-press', 'Kettlebell Arnold Press', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward.', 'Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion.', 'Return the kettlebell to the starting position, with the palm facing in.'], array['Kettlebell_Arnold_Press/0.jpg', 'Kettlebell_Arnold_Press/1.jpg'], 'free-exercise-db'),
  ('kettlebell-dead-clean', 'Kettlebell Dead Clean', 'Hamstrings', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['hamstrings'], array['calves', 'glutes', 'lower back', 'quadriceps', 'traps'], array['Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.', 'Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out.'], array['Kettlebell_Dead_Clean/0.jpg', 'Kettlebell_Dead_Clean/1.jpg'], 'free-exercise-db'),
  ('kettlebell-figure-8', 'Kettlebell Figure 8', 'Core', false, 'strength', 'kettlebells', 'intermediate', null, 'pull', array['abdominals'], array['hamstrings', 'shoulders'], array['Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.', 'Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions.'], array['Kettlebell_Figure_8/0.jpg', 'Kettlebell_Figure_8/1.jpg'], 'free-exercise-db'),
  ('kettlebell-halo', 'Kettlebell Halo', 'Shoulders', false, 'strength', 'kettlebells', 'beginner', 'compound', null, array['shoulders'], array['traps', 'middle back', 'abdominals', 'triceps'], array['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.', 'Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.', 'Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.', 'Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.', 'Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight.'], null, 'free-exercise-db'),
  ('kettlebell-halo-with-overhead-extension', 'Kettlebell Halo with Overhead Extension', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders', 'triceps'], array['traps', 'middle back', 'abdominals'], array['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.', 'Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here.', 'From this position, extend your elbows to press the kettlebell up and overhead until your arms are straight, keeping your upper arms alongside your head.', 'Bend your elbows to lower the kettlebell back to the pause position behind your head, under control.', 'Continue the circle past the opposite ear and back down to the starting position in front of your chest to complete one repetition.', 'Alternate the direction of the circle on each repetition. Keep your head, hips and lower back still throughout; if your lower back arches or you cannot reach the overhead position without leaning back, use a lighter weight or perform the halo and the extension as separate exercises.'], null, 'free-exercise-db'),
  ('kettlebell-hang-clean', 'Kettlebell Hang Clean', 'Hamstrings', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['hamstrings'], array['calves', 'glutes', 'lower back', 'shoulders', 'traps'], array['Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.', 'Lower kettlebell to a hanging position between your legs while keeping the hamstrings loaded. Keep your head up at all times.'], array['Kettlebell_Hang_Clean/0.jpg', 'Kettlebell_Hang_Clean/1.jpg'], 'free-exercise-db'),
  ('kettlebell-one-legged-deadlift', 'Kettlebell One-Legged Deadlift', 'Hamstrings', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['hamstrings'], array['glutes', 'lower back'], array['Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.', 'Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.', 'Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position.'], array['Kettlebell_One-Legged_Deadlift/0.jpg', 'Kettlebell_One-Legged_Deadlift/1.jpg'], 'free-exercise-db'),
  ('kettlebell-overhead-triceps-extension', 'Kettlebell Overhead Triceps Extension', 'Arms', false, 'strength', 'kettlebells', 'beginner', 'isolation', 'push', array['triceps'], array['shoulders', 'abdominals'], array['Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands. Press it overhead until your arms are extended, with the bell hanging behind your hands.', 'Brace your abdominals and keep your upper arms vertical and close to your head. This is your starting position.', 'Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows flaring outward.', 'Extend your elbows to press the kettlebell back to the starting position, keeping your upper arms still throughout.', 'Keep your ribcage down and avoid arching your lower back as you extend.'], null, 'free-exercise-db'),
  ('kettlebell-pass-between-the-legs', 'Kettlebell Pass Between The Legs', 'Core', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['abdominals'], array['glutes', 'hamstrings', 'shoulders'], array['Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.', 'Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a "W". Go back and forth for several repetitions.'], array['Kettlebell_Pass_Between_The_Legs/0.jpg', 'Kettlebell_Pass_Between_The_Legs/1.jpg'], 'free-exercise-db'),
  ('kettlebell-pirate-ships', 'Kettlebell Pirate Ships', 'Shoulders', false, 'strength', 'kettlebells', 'beginner', 'compound', 'push', array['shoulders'], array['abdominals'], array['With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.', 'Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion.', 'Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.', 'Repeat for the desired amount of repetitions.'], array['Kettlebell_Pirate_Ships/0.jpg', 'Kettlebell_Pirate_Ships/1.jpg'], 'free-exercise-db'),
  ('kettlebell-pistol-squat', 'Kettlebell Pistol Squat', 'Legs', false, 'strength', 'kettlebells', 'expert', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'shoulders'], array['Pick up a kettlebell with two hands and hold it by the horns. Hold one leg off of the floor and squat down on the other.', 'Squat down by flexing the knee and sitting back with the hips, holding the kettlebell up in front of you.', 'Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up.', 'Lower yourself again and repeat.'], array['Kettlebell_Pistol_Squat/0.jpg', 'Kettlebell_Pistol_Squat/1.jpg'], 'free-exercise-db'),
  ('kettlebell-seated-press', 'Kettlebell Seated Press', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['Sit on the floor and spread your legs out comfortably.', 'Clean one kettlebell to your shoulder.', 'Press the kettlebell up and out until it is locked out overhead. Return to the starting position.'], array['Kettlebell_Seated_Press/0.jpg', 'Kettlebell_Seated_Press/1.jpg'], 'free-exercise-db'),
  ('kettlebell-seesaw-press', 'Kettlebell Seesaw Press', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['Clean two kettlebells two your shoulders.', 'Press one kettlebell.', 'Lower the kettlebell and immediately press the other kettlebell. Make sure to do the same amount of reps on both sides.'], array['Kettlebell_Seesaw_Press/0.jpg', 'Kettlebell_Seesaw_Press/1.jpg'], 'free-exercise-db'),
  ('kettlebell-sumo-high-pull', 'Kettlebell Sumo High Pull', 'Back', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['traps'], array['adductors', 'glutes', 'hamstrings', 'quadriceps', 'shoulders'], array['Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.', 'Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position.'], array['Kettlebell_Sumo_High_Pull/0.jpg', 'Kettlebell_Sumo_High_Pull/1.jpg'], 'free-exercise-db'),
  ('kettlebell-thruster', 'Kettlebell Thruster', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['quadriceps', 'triceps'], array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.', 'Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.', 'At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward.', 'As you begin the next repetition, return the weights to the shoulders.'], array['Kettlebell_Thruster/0.jpg', 'Kettlebell_Thruster/1.jpg'], 'free-exercise-db'),
  ('kettlebell-turkish-get-up-lunge-style', 'Kettlebell Turkish Get-Up (Lunge style)', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['abdominals', 'hamstrings', 'quadriceps', 'triceps'], array['Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.', 'Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.', 'While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.'], array['Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg', 'Kettlebell_Turkish_Get-Up_Lunge_style/1.jpg'], 'free-exercise-db'),
  ('kettlebell-turkish-get-up-squat-style', 'Kettlebell Turkish Get-Up (Squat style)', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['abdominals', 'calves', 'hamstrings', 'quadriceps', 'triceps'], array['Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.', 'Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position.', 'Using your free hand, push yourself to a seated position, then progressing to your feet. While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.'], array['Kettlebell_Turkish_Get-Up_Squat_style/0.jpg', 'Kettlebell_Turkish_Get-Up_Squat_style/1.jpg'], 'free-exercise-db'),
  ('kettlebell-windmill', 'Kettlebell Windmill', 'Core', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['abdominals'], array['glutes', 'hamstrings', 'shoulders', 'triceps'], array['Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.', 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times.', 'Pause for a second after reaching the ground and reverse the motion back to the starting position.'], array['Kettlebell_Windmill/0.jpg', 'Kettlebell_Windmill/1.jpg'], 'free-exercise-db'),
  ('kipping-muscle-up', 'Kipping Muscle Up', 'Back', false, 'strength', 'other', 'intermediate', 'compound', 'pull', array['lats'], array['abdominals', 'biceps', 'forearms', 'middle back', 'shoulders', 'traps', 'triceps'], array['Grip the rings using a false grip, with the base of your palms on top of the rings.', 'Begin with a movement swinging your legs backward slightly.', 'Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.', 'Maintaining control and stability, extend through the elbow to complete the motion.', 'Use care when lowering yourself to the ground.'], array['Kipping_Muscle_Up/0.jpg', 'Kipping_Muscle_Up/1.jpg'], 'free-exercise-db'),
  ('knee-across-the-body', 'Knee Across The Body', 'Glutes', false, 'stretching', null, 'beginner', null, 'static', array['glutes'], array['abductors', 'lower back'], array['Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn''t need to touch the floor if you''re tight.)', 'Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides.'], array['Knee_Across_The_Body/0.jpg', 'Knee_Across_The_Body/1.jpg'], 'free-exercise-db'),
  ('knee-circles', 'Knee Circles', 'Calves', false, 'stretching', 'body only', 'beginner', 'compound', 'pull', array['calves'], array['hamstrings', 'quadriceps'], array['Stand with your legs together and hands by your waist.', 'Now move your knees in a circular motion as you breathe normally.', 'Repeat for the recommended amount of repetitions.'], array['Knee_Circles/0.jpg', 'Knee_Circles/1.jpg'], 'free-exercise-db'),
  ('knee-hip-raise-on-parallel-bars', 'Knee/Hip Raise On Parallel Bars', 'Core', false, 'strength', 'other', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle.', 'The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position.', 'Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to the floor and then hold the contraction for a second. Tip: Do not use any momentum or swinging as you perform this exercise.', 'Slowly go back to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Knee_Hip_Raise_On_Parallel_Bars/0.jpg', 'Knee_Hip_Raise_On_Parallel_Bars/1.jpg'], 'free-exercise-db'),
  ('knee-tuck-jump', 'Knee Tuck Jump', 'Hamstrings', false, 'plyometrics', 'body only', 'beginner', 'compound', 'push', array['hamstrings'], array['abductors', 'adductors', 'calves', 'glutes', 'quadriceps'], array['Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.', 'Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands.', 'Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend.'], array['Knee_Tuck_Jump/0.jpg', 'Knee_Tuck_Jump/1.jpg'], 'free-exercise-db'),
  ('kneeling-arm-drill', 'Kneeling Arm Drill', 'Shoulders', false, 'plyometrics', null, 'beginner', null, 'pull', array['shoulders'], array['abdominals'], array['This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated.', 'Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint.', 'As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible.', 'Switch knees and repeat.'], array['Kneeling_Arm_Drill/0.jpg', 'Kneeling_Arm_Drill/1.jpg'], 'free-exercise-db'),
  ('kneeling-cable-crunch-with-alternating-oblique-twists', 'Kneeling Cable Crunch With Alternating Oblique Twists', 'Core', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.', 'Grab the rope with both hands and kneel approximately two feet back from the tower.', 'Position the rope behind your head with your hands by your ears.', 'Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.', 'Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.', 'Repeat the same downward movement until you''re halfway down, at which time you''ll begin rotating one of your elbows to the opposite knee.', 'Again, pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.', 'Repeat the same movement as before, but alternate the other elbow to the opposite knee.', 'Continue this series of movements to failure.'], array['Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/0.jpg', 'Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/1.jpg'], 'free-exercise-db'),
  ('kneeling-cable-triceps-extension', 'Kneeling Cable Triceps Extension', 'Arms', false, 'strength', 'cable', 'intermediate', 'isolation', 'push', array['triceps'], null, array['Place a bench sideways in front of a high pulley machine.', 'Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down.', 'Face away from the machine and kneel.', 'Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position.', 'While keeping your upper arms close to your head at all times with the elbows in, press the bar out in a semicircular motion until the elbows are locked and your arms are parallel to the floor. Contract the triceps hard and keep this position for a second. Exhale as you perform this movement.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Kneeling_Cable_Triceps_Extension/0.jpg', 'Kneeling_Cable_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('kneeling-forearm-stretch', 'Kneeling Forearm Stretch', 'Arms', false, 'stretching', null, 'beginner', 'isolation', 'static', array['forearms'], null, array['Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.', 'Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds.'], array['Kneeling_Forearm_Stretch/0.jpg', 'Kneeling_Forearm_Stretch/1.jpg'], 'free-exercise-db'),
  ('kneeling-high-pulley-row', 'Kneeling High Pulley Row', 'Back', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back'], array['Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position.', 'Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out.', 'After pausing briefly, slowly return to the starting position.'], array['Kneeling_High_Pulley_Row/0.jpg', 'Kneeling_High_Pulley_Row/1.jpg'], 'free-exercise-db'),
  ('kneeling-hip-flexor', 'Kneeling Hip Flexor', 'Legs', false, 'stretching', null, 'beginner', 'isolation', 'static', array['quadriceps'], array['quadriceps'], array['Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.', 'Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side.'], array['Kneeling_Hip_Flexor/0.jpg', 'Kneeling_Hip_Flexor/1.jpg'], 'free-exercise-db'),
  ('kneeling-jump-squat', 'Kneeling Jump Squat', 'Glutes', false, 'olympic weightlifting', 'barbell', 'expert', 'compound', 'push', array['glutes'], array['calves', 'hamstrings', 'quadriceps'], array['Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier.', 'Sit back with your hips until your glutes touch your feet, keeping your head and chest up.', 'Explode up with your hips, generating enough power to land with your feet flat on the floor.', 'Continue with the squat by driving through your heels and extending the knees to come to a standing position.'], array['Kneeling_Jump_Squat/0.jpg', 'Kneeling_Jump_Squat/1.jpg'], 'free-exercise-db'),
  ('kneeling-single-arm-high-pulley-row', 'Kneeling Single-Arm High Pulley Row', 'Back', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back'], array['Attach a single handle to a high pulley and make your weight selection.', 'Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position.', 'Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you.', 'After a brief pause, return to the starting position.'], array['Kneeling_Single-Arm_High_Pulley_Row/0.jpg', 'Kneeling_Single-Arm_High_Pulley_Row/1.jpg'], 'free-exercise-db'),
  ('kneeling-squat', 'Kneeling Squat', 'Glutes', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['glutes'], array['abdominals', 'hamstrings', 'lower back'], array['Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight.', 'With your head looking forward, sit back with your butt until you touch your calves.', 'Reverse the motion, returning the torso to an upright position.'], array['Kneeling_Squat/0.jpg', 'Kneeling_Squat/1.jpg'], 'free-exercise-db'),
  ('landmine-180-s', 'Landmine 180''s', 'Core', false, 'strength', 'barbell', 'beginner', 'compound', 'pull', array['abdominals'], array['glutes', 'lower back', 'shoulders'], array['Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.', 'Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.', 'Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.', 'Reverse the motion to swing the weight all the way to the opposite side.', 'Continue alternating the movement until the set is complete.'], array['Landmine_180s/0.jpg', 'Landmine_180s/1.jpg'], 'free-exercise-db'),
  ('landmine-linear-jammer', 'Landmine Linear Jammer', 'Shoulders', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['shoulders'], array['abdominals', 'calves', 'chest', 'hamstrings', 'quadriceps', 'triceps'], array['Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.', 'Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position.', 'In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.', 'Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible.', 'Return to the starting position.'], array['Landmine_Linear_Jammer/0.jpg', 'Landmine_Linear_Jammer/1.jpg'], 'free-exercise-db'),
  ('lat-pulldown', 'Lat Pulldown', 'Back', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back', 'shoulders'], array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.'], array['Wide-Grip_Lat_Pulldown/0.jpg', 'Wide-Grip_Lat_Pulldown/1.jpg'], 'repple+free-exercise-db'),
  ('lateral-bound', 'Lateral Bound', 'Legs', false, 'plyometrics', 'body only', 'beginner', 'compound', 'push', array['adductors'], array['abductors', 'calves', 'glutes', 'hamstrings', 'quadriceps'], array['Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position.', 'Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg.', 'Immediately push off and extend, attempting to bound to the side as far as possible.', 'Upon landing, immediately push off in the opposite direction, returning to your original start position.', 'Continue back and forth for several repetitions.'], array['Lateral_Bound/0.jpg', 'Lateral_Bound/1.jpg'], 'free-exercise-db'),
  ('lateral-box-jump', 'Lateral Box Jump', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['adductors'], array['abductors', 'calves', 'glutes', 'hamstrings', 'quadriceps'], array['Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position.', 'Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side.', 'Bring your knees high enough to ensure your feet have good clearance over the box.', 'Land on the center of the box, using your legs to absorb the impact.', 'Carefully jump down to the other side of the box, and continue going back and forth for several repetitions.'], array['Lateral_Box_Jump/0.jpg', 'Lateral_Box_Jump/1.jpg'], 'free-exercise-db'),
  ('lateral-cone-hops', 'Lateral Cone Hops', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['adductors'], array['abductors', 'calves', 'glutes', 'hamstrings', 'quadriceps'], array['Position a number of cones in a row several feet apart.', 'Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position.', 'Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone.', 'Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones.'], array['Lateral_Cone_Hops/0.jpg', 'Lateral_Cone_Hops/1.jpg'], 'free-exercise-db'),
  ('lateral-raise', 'Lateral Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], null, array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.', 'While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Side_Lateral_Raise/0.jpg', 'Side_Lateral_Raise/1.jpg'], 'repple+free-exercise-db'),
  ('lateral-raise-with-bands', 'Lateral Raise - With Bands', 'Shoulders', false, 'strength', 'bands', 'beginner', 'isolation', 'push', array['shoulders'], null, array['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.'], array['Lateral_Raise_-_With_Bands/0.jpg', 'Lateral_Raise_-_With_Bands/1.jpg'], 'free-exercise-db'),
  ('latissimus-dorsi-smr', 'Latissimus Dorsi-SMR', 'Back', false, 'stretching', 'foam roll', 'beginner', 'isolation', 'static', array['lats'], null, array['While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit. This will be your starting position.', 'Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides.'], array['Latissimus_Dorsi-SMR/0.jpg', 'Latissimus_Dorsi-SMR/1.jpg'], 'free-exercise-db'),
  ('leg-curl', 'Leg Curl', 'Hamstrings', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['hamstrings'], null, array['Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.', 'Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.', 'As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.'], array['Lying_Leg_Curls/0.jpg', 'Lying_Leg_Curls/1.jpg'], 'repple+free-exercise-db'),
  ('leg-extension', 'Leg Extension', 'Legs', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['quadriceps'], null, array['For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.', 'Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.', 'Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.', 'Repeat for the recommended amount of times.'], array['Leg_Extensions/0.jpg', 'Leg_Extensions/1.jpg'], 'repple+free-exercise-db'),
  ('leg-extensions', 'Leg Extensions', 'Legs', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['quadriceps'], null, array['For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.', 'Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.', 'Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.', 'Repeat for the recommended amount of times.'], array['Leg_Extensions/0.jpg', 'Leg_Extensions/1.jpg'], 'free-exercise-db'),
  ('leg-lift', 'Leg Lift', 'Glutes', false, 'strength', 'body only', 'beginner', 'isolation', 'push', array['glutes'], array['hamstrings'], array['While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.', 'With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement.', 'Slowly bring the raised leg back to the floor as you breathe in.', 'Repeat for the recommended amount of repetitions.', 'Repeat the movement with the opposite leg.'], array['Leg_Lift/0.jpg', 'Leg_Lift/1.jpg'], 'free-exercise-db'),
  ('leg-over-floor-press', 'Leg-Over Floor Press', 'Chest', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support.', 'Press the kettlebll into a locked out position.', 'Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions.'], array['Leg-Over_Floor_Press/0.jpg', 'Leg-Over_Floor_Press/1.jpg'], 'free-exercise-db'),
  ('leg-press', 'Leg Press', 'Legs', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.', 'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.', 'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.'], array['Leg_Press/0.jpg', 'Leg_Press/1.jpg'], 'free-exercise-db'),
  ('leg-pull-in', 'Leg Pull-In', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.', 'Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.', 'Return to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Leg_Pull-In/0.jpg', 'Leg_Pull-In/1.jpg'], 'free-exercise-db'),
  ('leg-up-hamstring-stretch', 'Leg-Up Hamstring Stretch', 'Hamstrings', false, 'stretching', null, 'beginner', 'isolation', 'push', array['hamstrings'], null, array['Lie flat on your back, bend one knee, and put that foot flat on the floor to stabilize your spine.', 'Extend the other leg in the air. If you''re tight, you wont be able to straighten it. That''s okay. Extend the knee so that the sole of the lifted foot faces the ceiling (or as close as you can get it).', 'Slowly straighten the legs as much as possible and then pull the leg toward your nose. Switch sides.'], array['Leg-Up_Hamstring_Stretch/0.jpg', 'Leg-Up_Hamstring_Stretch/1.jpg'], 'free-exercise-db'),
  ('leverage-chest-press', 'Leverage Chest Press', 'Chest', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.', 'Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.'], array['Leverage_Chest_Press/0.jpg', 'Leverage_Chest_Press/1.jpg'], 'free-exercise-db'),
  ('leverage-deadlift', 'Leverage Deadlift', 'Legs', false, 'strength', 'machine', 'beginner', 'compound', 'pull', array['quadriceps'], array['glutes', 'hamstrings'], array['Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position.', 'Return the weight to the starting position.'], array['Leverage_Deadlift/0.jpg', 'Leverage_Deadlift/1.jpg'], 'free-exercise-db'),
  ('leverage-decline-chest-press', 'Leverage Decline Chest Press', 'Chest', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.'], array['Leverage_Decline_Chest_Press/0.jpg', 'Leverage_Decline_Chest_Press/1.jpg'], 'free-exercise-db'),
  ('leverage-high-row', 'Leverage High Row', 'Back', false, 'strength', 'machine', 'beginner', 'compound', 'pull', array['middle back'], array['lats'], array['Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.', 'Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handles to the starting position.', 'For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.'], array['Leverage_High_Row/0.jpg', 'Leverage_High_Row/1.jpg'], 'free-exercise-db'),
  ('leverage-incline-chest-press', 'Leverage Incline Chest Press', 'Chest', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.'], array['Leverage_Incline_Chest_Press/0.jpg', 'Leverage_Incline_Chest_Press/1.jpg'], 'free-exercise-db'),
  ('leverage-iso-row', 'Leverage Iso Row', 'Back', false, 'strength', 'machine', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back'], array['Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.', 'Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.'], array['Leverage_Iso_Row/0.jpg', 'Leverage_Iso_Row/1.jpg'], 'free-exercise-db'),
  ('leverage-shoulder-press', 'Leverage Shoulder Press', 'Shoulders', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.', 'Press the handles upward by extending through the elbow.', 'After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.'], array['Leverage_Shoulder_Press/0.jpg', 'Leverage_Shoulder_Press/1.jpg'], 'free-exercise-db'),
  ('leverage-shrug', 'Leverage Shrug', 'Back', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['traps'], array['forearms'], array['Load the pins to an appropriate weight. Position yourself directly between the handles.', 'Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up.', 'Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position.', 'Raise the weight by shrugging the shoulders towards your ears, moving straight up and down.', 'Pause at the top of the motion, and then return the weight to the starting position.'], array['Leverage_Shrug/0.jpg', 'Leverage_Shrug/1.jpg'], 'free-exercise-db'),
  ('linear-3-part-start-technique', 'Linear 3-Part Start Technique', 'Hamstrings', false, 'plyometrics', null, 'beginner', 'compound', 'push', array['hamstrings'], array['calves', 'quadriceps'], array['This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.', 'Place your right hand onto the line, and thing bring your nose close to your left knee.', 'Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position.', 'Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready.'], array['Linear_3-Part_Start_Technique/0.jpg', 'Linear_3-Part_Start_Technique/1.jpg'], 'free-exercise-db'),
  ('linear-acceleration-wall-drill', 'Linear Acceleration Wall Drill', 'Hamstrings', false, 'plyometrics', null, 'beginner', 'compound', null, array['hamstrings'], array['calves', 'glutes', 'quadriceps'], array['Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.', 'Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.', 'Switch legs, raising the opposite knee, and then attacking the ground straight down.', 'Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can.'], array['Linear_Acceleration_Wall_Drill/0.jpg', 'Linear_Acceleration_Wall_Drill/1.jpg'], 'free-exercise-db'),
  ('linear-depth-jump', 'Linear Depth Jump', 'Legs', false, 'plyometrics', 'other', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.', 'To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex.', 'Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.', 'Land softly, asborbing the impact through the legs.'], array['Linear_Depth_Jump/0.jpg', 'Linear_Depth_Jump/1.jpg'], 'free-exercise-db'),
  ('log-lift', 'Log Lift', 'Shoulders', false, 'strongman', 'other', 'intermediate', 'compound', 'push', array['shoulders'], array['abdominals', 'chest', 'glutes', 'hamstrings', 'lower back', 'middle back', 'quadriceps', 'traps', 'triceps'], array['Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your chest. Extend through the hips and knees to bring it up to complete the clean.', 'Push your head back and look up, creating a shelf on your chest to rest the log. Begin the press by dipping, flexing slightly through the knees and reversing the motion. This push press will generate momentum to start the log moving vertically. Continue by extending through the elbows to press the log above your head. There are no strict rules on form, so use whatever techniques you are most efficient with. As the log is pressed, ensure that you push your head through on each repetition, looking forward.', 'Repeat as many times as possible. Attempt to control the descent of the log as it is returned to the ground.'], array['Log_Lift/0.jpg', 'Log_Lift/1.jpg'], 'free-exercise-db'),
  ('london-bridges', 'London Bridges', 'Back', false, 'strength', 'other', 'intermediate', 'compound', 'pull', array['lats'], array['biceps', 'forearms', 'middle back'], array['Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized.', 'Stand on the bar, using the rope to balance yourself. This will be your starting position.', 'Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until you are perpendicular to the ground.', 'Keeping your body straight, reverse the motion, going hand over hand back to the starting position.'], array['London_Bridges/0.jpg', 'London_Bridges/1.jpg'], 'free-exercise-db'),
  ('looking-at-ceiling', 'Looking At Ceiling', 'Legs', false, 'stretching', null, 'beginner', 'isolation', 'static', array['quadriceps'], null, array['Kneel on the floor, holding your heels with both hands.', 'Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back.'], array['Looking_At_Ceiling/0.jpg', 'Looking_At_Ceiling/1.jpg'], 'free-exercise-db'),
  ('low-cable-crossover', 'Low Cable Crossover', 'Chest', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['chest'], array['shoulders'], array['To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.', 'Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.', 'With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.', 'Return your arms back to the starting position after a brief pause.'], array['Low_Cable_Crossover/0.jpg', 'Low_Cable_Crossover/1.jpg'], 'free-exercise-db'),
  ('low-cable-triceps-extension', 'Low Cable Triceps Extension', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.', 'Grab the outside of the rope ends with your palms facing each other (neutral grip).', 'Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position.', 'As you breathe out, extend your lower arms until they are straight and vertical. The upper arms and elbows remain stationary throughout the movement. Only the forearms should move. Contract the triceps hard for a second.', 'As you breathe in slowly return to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Low_Cable_Triceps_Extension/0.jpg', 'Low_Cable_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('low-pulley-row-to-neck', 'Low Pulley Row To Neck', 'Shoulders', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['shoulders'], array['biceps', 'middle back', 'traps'], array['Sit on a low pulley row machine with a rope attachment.', 'Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position.', 'While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the floor. Tip: Continue this motion until your hands are almost next to your ears (the forearms will not be parallel to the floor at the end of the movement as they will be angled a bit upwards) and your elbows are out away from your sides.', 'After holding for a second or so at the contracted position, come back slowly to the starting position as you inhale. Tip: Again, during no part of the movement should the torso move.', 'Repeat for the recommended amount of repetitions.'], array['Low_Pulley_Row_To_Neck/0.jpg', 'Low_Pulley_Row_To_Neck/1.jpg'], 'free-exercise-db'),
  ('lower-back-curl', 'Lower Back Curl', 'Core', false, 'stretching', 'body only', 'beginner', null, 'static', array['abdominals'], null, array['Lie on your stomach with your arms out to your sides. This will be your starting position.', 'Using your lower back muscles, extend your spine lifting your chest off of the ground. Do not use your arms to push yourself up. Keep your head up during the movement. Repeat for 10-20 repetitions.'], array['Lower_Back_Curl/0.jpg', 'Lower_Back_Curl/1.jpg'], 'free-exercise-db'),
  ('lower-back-smr', 'Lower Back-SMR', 'Lower back', false, 'stretching', 'foam roll', 'beginner', null, 'static', array['lower back'], null, array['In a seated position, place a foam roll under your lower back. Cross your arms in front of you and protract your shoulders. This will be your starting position.', 'Raise your hips off of the floor and lean back, keeping your weight on your lower back. Now shift your weight slightly to one side, keeping your weight off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repeat on the other side.'], array['Lower_Back-SMR/0.jpg', 'Lower_Back-SMR/1.jpg'], 'free-exercise-db'),
  ('lunge-pass-through', 'Lunge Pass Through', 'Hamstrings', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['hamstrings'], array['calves', 'glutes', 'quadriceps'], array['Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.', 'Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.', 'As you lunge, pass the kettlebell under your front leg to your opposite hand.', 'Pressing through the heel of your foot, return to the starting position.', 'Repeat the movement for the recommended amount of repetitions, alternating legs.'], array['Lunge_Pass_Through/0.jpg', 'Lunge_Pass_Through/1.jpg'], 'free-exercise-db'),
  ('lunge-sprint', 'Lunge Sprint', 'Legs', false, 'strength', 'machine', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position.', 'Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so.', 'At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from your back foot. Jump up and reverse the position of your legs.', 'Repeat for the recommended amount of repetitions.'], array['Lunge_Sprint/0.jpg', 'Lunge_Sprint/1.jpg'], 'free-exercise-db'),
  ('lying-bent-leg-groin', 'Lying Bent Leg Groin', 'Legs', false, 'stretching', 'other', 'expert', null, 'static', array['adductors'], null, array['Lie on your back with your knees bent and the soles of the feet pressed together. Have your partner hold your knees. This will be your starting position.', 'Attempt to squeeze your knees together, while your partner prevents any movement from occurring.', 'After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.'], array['Lying_Bent_Leg_Groin/0.jpg', 'Lying_Bent_Leg_Groin/1.jpg'], 'free-exercise-db'),
  ('lying-cable-curl', 'Lying Cable Curl', 'Arms', false, 'strength', 'cable', 'intermediate', 'isolation', 'pull', array['biceps'], null, array['Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.', 'Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.', 'With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.', 'While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.', 'After a second squeeze at the top of the movement, slowly return to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Lying_Cable_Curl/0.jpg', 'Lying_Cable_Curl/1.jpg'], 'free-exercise-db'),
  ('lying-cambered-barbell-row', 'Lying Cambered Barbell Row', 'Back', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['middle back'], array['biceps', 'lats', 'traps'], array['Place a cambered bar underneath an exercise bench.', 'Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position.', 'As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal.', 'After a second hold at the top, lower back down to the starting position slowly as you inhale.'], array['Lying_Cambered_Barbell_Row/0.jpg', 'Lying_Cambered_Barbell_Row/1.jpg'], 'free-exercise-db'),
  ('lying-close-grip-bar-curl-on-high-pulley', 'Lying Close-Grip Bar Curl On High Pulley', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Place a flat bench in front of a high pulley or lat pulldown machine.', 'Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width.', 'Lie on your back with your head over the end of the bench.', 'Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position.', 'As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Tip: As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout the movement.', 'Return to starting position slowly.', 'Repeat for the recommended amount of repetitions.'], array['Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg', 'Lying_Close-Grip_Bar_Curl_On_High_Pulley/1.jpg'], 'free-exercise-db'),
  ('lying-close-grip-barbell-triceps-extension-behind-the-head', 'Lying Close-Grip Barbell Triceps Extension Behind The Head', 'Arms', false, 'strength', 'barbell', 'intermediate', 'isolation', 'push', array['triceps'], null, array['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.', 'Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead and parallel to the floor. This will be your starting position. Tip: Keep your elbows in at all times.', 'As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to the floor.', 'As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion until the lower arms are also parallel to the floor. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.', 'Repeat for the recommended amount of repetitions.'], array['Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg', 'Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/1.jpg'], 'free-exercise-db'),
  ('lying-close-grip-barbell-triceps-press-to-chin', 'Lying Close-Grip Barbell Triceps Press To Chin', 'Arms', false, 'strength', 'e-z curl bar', 'intermediate', 'isolation', 'push', array['triceps'], null, array['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.', 'Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position.', 'As you inhale, lower the bar in a semi-circular motion by bending at the elbows and while keeping the upper arm stationary and elbows in. Keep lowering the bar until it lightly touches your chin.', 'As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.', 'Repeat for the recommended amount of repetitions.'], array['Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg', 'Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/1.jpg'], 'free-exercise-db'),
  ('lying-crossover', 'Lying Crossover', 'Glutes', false, 'stretching', 'body only', 'expert', null, 'static', array['abductors'], null, array['Lie on your back with your legs extended.', 'Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position.', 'Attempt to raise the bent knee off of the ground as your partner prevents any actual movement.', 'After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with the other side.'], array['Lying_Crossover/0.jpg', 'Lying_Crossover/1.jpg'], 'free-exercise-db'),
  ('lying-dumbbell-tricep-extension', 'Lying Dumbbell Tricep Extension', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'push', array['triceps'], array['chest', 'shoulders'], array['Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position.', 'As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears.', 'At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out.', 'Repeat for the recommended amount of repetitions.'], array['Lying_Dumbbell_Tricep_Extension/0.jpg', 'Lying_Dumbbell_Tricep_Extension/1.jpg'], 'free-exercise-db'),
  ('lying-face-down-plate-neck-resistance', 'Lying Face Down Plate Neck Resistance', 'Neck', false, 'strength', 'other', 'intermediate', 'isolation', 'pull', array['neck'], null, array['Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position.', 'While keeping the plate secure on the back of your head slowly lower your head (as in saying "yes") as you breathe in.', 'Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.', 'Repeat for the recommended amount of repetitions.'], array['Lying_Face_Down_Plate_Neck_Resistance/0.jpg', 'Lying_Face_Down_Plate_Neck_Resistance/1.jpg'], 'free-exercise-db'),
  ('lying-face-up-plate-neck-resistance', 'Lying Face Up Plate Neck Resistance', 'Neck', false, 'strength', 'other', 'intermediate', 'isolation', 'pull', array['neck'], null, array['Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the traps, neck and head to be off the bench. This will be your starting position.', 'While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion as you breathe in.', 'Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.', 'Repeat for the recommended amount of repetitions.'], array['Lying_Face_Up_Plate_Neck_Resistance/0.jpg', 'Lying_Face_Up_Plate_Neck_Resistance/1.jpg'], 'free-exercise-db'),
  ('lying-glute', 'Lying Glute', 'Glutes', false, 'stretching', 'body only', 'expert', null, 'static', array['glutes'], array['abductors'], array['Lie on your back with your partner kneeling beside you.', 'Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position.', 'Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.', 'After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.'], array['Lying_Glute/0.jpg', 'Lying_Glute/1.jpg'], 'free-exercise-db'),
  ('lying-hamstring', 'Lying Hamstring', 'Hamstrings', false, 'stretching', 'other', 'expert', null, 'static', array['hamstrings'], array['calves'], array['Lie on your back with your legs extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their shoulder to brace your leg if necessary. This will be your starting position.', 'With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds.', 'Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching. Switch sides once complete.'], array['Lying_Hamstring/0.jpg', 'Lying_Hamstring/1.jpg'], 'free-exercise-db'),
  ('lying-high-bench-barbell-curl', 'Lying High Bench Barbell Curl', 'Arms', false, 'strength', 'barbell', 'intermediate', 'isolation', 'pull', array['biceps'], null, array['Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position.', 'While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second.', 'As you inhale, slowly go back to the starting position. Tip: Maintain full control of the weight at all times and avoid any swinging. Remember, only the forearms should move throughout the movement.', 'Repeat for the recommended amount of repetitions.'], array['Lying_High_Bench_Barbell_Curl/0.jpg', 'Lying_High_Bench_Barbell_Curl/1.jpg'], 'free-exercise-db'),
  ('lying-leg-curls', 'Lying Leg Curls', 'Hamstrings', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['hamstrings'], null, array['Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.', 'Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.', 'As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.'], array['Lying_Leg_Curls/0.jpg', 'Lying_Leg_Curls/1.jpg'], 'free-exercise-db'),
  ('lying-machine-squat', 'Lying Machine Squat', 'Legs', false, 'strength', 'machine', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.', 'Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly below parallel). Your back and your head should be resting on the machine while your shoulders are pressed under the shoulder pads.', 'Place your hands by the handles and position your feet slightly pointing out at a shoulder width position. This will be your starting position.', 'While pressing with the balls of the feet as you breathe out, make your whole body erect as you squeeze the quads. Hold the contracted position for a second. Tip: Since you are starting below parallel, you can opt to use your hands to help you up by pressing on your thighs only on the first repetition.', 'Slowly squat down as you inhale but instead of going all the way down to the starting position, just stop once your thighs are parallel to the platform. The angle between your hamstrings and calves should be a 90-degree angle.', 'Repeat for the recommended amount of repetitions.'], array['Lying_Machine_Squat/0.jpg', 'Lying_Machine_Squat/1.jpg'], 'free-exercise-db'),
  ('lying-one-arm-lateral-raise', 'Lying One-Arm Lateral Raise', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['shoulders'], null, array['While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability.', 'Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.', 'Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbell to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Lying_One-Arm_Lateral_Raise/0.jpg', 'Lying_One-Arm_Lateral_Raise/1.jpg'], 'free-exercise-db'),
  ('lying-prone-quadriceps', 'Lying Prone Quadriceps', 'Legs', false, 'stretching', 'body only', 'expert', null, null, array['quadriceps'], null, array['Lay face down on the floor with your partner kneeling beside you. Flex one knee and raise that leg off the ground, attempting to touch your glutes with your foot. Your partner should hold the knee and ankle. This will be your starting position.', 'Attempt to extend your knee while your partner prevents any actual movement.', 'After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your glutes, further stretching the quadriceps and hip flexors.', 'After 10-20 seconds, switch sides.'], array['Lying_Prone_Quadriceps/0.jpg', 'Lying_Prone_Quadriceps/1.jpg'], 'free-exercise-db'),
  ('lying-rear-delt-raise', 'Lying Rear Delt Raise', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['shoulders'], null, array['While holding a dumbbell in each hand, lay with your chest down on a flat bench.', 'Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.', 'Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbells to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.'], array['Lying_Rear_Delt_Raise/0.jpg', 'Lying_Rear_Delt_Raise/1.jpg'], 'free-exercise-db'),
  ('lying-supine-dumbbell-curl', 'Lying Supine Dumbbell Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs.', 'Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip).', 'While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your starting position.', 'As you breathe out, slowly begin to curl the weights up as you simultaneously rotate your wrists so that the palms of the hands face up. Continue curling the weight until your biceps are fully contracted and squeeze hard at the top position for a second. Tip: Only the forearms should move. Upper arms should remain stationary and elbows should stay in throughout the movement.', 'Return back to the starting position very slowly.'], array['Lying_Supine_Dumbbell_Curl/0.jpg', 'Lying_Supine_Dumbbell_Curl/1.jpg'], 'free-exercise-db'),
  ('lying-t-bar-row', 'Lying T-Bar Row', 'Back', false, 'strength', 'machine', 'intermediate', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.', 'Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.', 'Lift the bar off the rack and extend your arms in front of you. This will be your starting position.', 'As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.', 'After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Lying_T-Bar_Row/0.jpg', 'Lying_T-Bar_Row/1.jpg'], 'free-exercise-db'),
  ('lying-triceps-press', 'Lying Triceps Press', 'Arms', false, 'strength', 'e-z curl bar', 'intermediate', 'isolation', 'push', array['triceps'], null, array['Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.', 'Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.', 'As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.', 'At that point, use the triceps to bring the weight back up to the starting position as you breathe out.', 'Repeat for the recommended amount of repetitions.'], array['Lying_Triceps_Press/0.jpg', 'Lying_Triceps_Press/1.jpg'], 'free-exercise-db'),
  ('machine-bench-press', 'Machine Bench Press', 'Chest', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Sit down on the Chest Press Machine and select the weight.', 'Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.', 'Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.', 'Now bring the handles back towards you as you breathe in.', 'Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.', 'Repeat for the recommended amount of reps.', 'When finished step on the lever again and slowly get the handles back to their original place.'], array['Machine_Bench_Press/0.jpg', 'Machine_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('machine-bicep-curl', 'Machine Bicep Curl', 'Arms', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.', 'Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.', 'Pause at the top of the movement, and then slowly return the weight to the starting position.', 'Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.'], array['Machine_Bicep_Curl/0.jpg', 'Machine_Bicep_Curl/1.jpg'], 'free-exercise-db'),
  ('machine-preacher-curls', 'Machine Preacher Curls', 'Arms', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Sit down on the Preacher Curl Machine and select the weight.', 'Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.', 'Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.', 'Lower the handles slowly back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Machine_Preacher_Curls/0.jpg', 'Machine_Preacher_Curls/1.jpg'], 'free-exercise-db'),
  ('machine-shoulder-military-press', 'Machine Shoulder (Military) Press', 'Shoulders', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Sit down on the Shoulder Press Machine and select the weight.', 'Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.', 'Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.', 'Lower the handles slowly back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Machine_Shoulder_Military_Press/0.jpg', 'Machine_Shoulder_Military_Press/1.jpg'], 'free-exercise-db'),
  ('machine-triceps-extension', 'Machine Triceps Extension', 'Arms', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['triceps'], null, array['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.', 'Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.', 'Pause at the completion of the movement, and then slowly return the weight to the starting position.', 'Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.'], array['Machine_Triceps_Extension/0.jpg', 'Machine_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('medicine-ball-chest-pass', 'Medicine Ball Chest Pass', 'Chest', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['You will need a partner for this exercise. Lacking one, this movement can be performed against a wall.', 'Begin facing your partner holding the medicine ball at your torso with both hands.', 'Pull the ball to your chest, and reverse the motion by extending through the elbows. For sports applications, you can take a step as you throw.', 'Your partner should catch the ball, and throw it back to you.', 'Receive the throw with both hands at chest height.'], array['Medicine_Ball_Chest_Pass/0.jpg', 'Medicine_Ball_Chest_Pass/1.jpg'], 'free-exercise-db'),
  ('medicine-ball-full-twist', 'Medicine Ball Full Twist', 'Core', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'pull', array['abdominals'], array['shoulders'], array['For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position.', 'Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner.', 'For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise.', 'Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure.'], array['Medicine_Ball_Full_Twist/0.jpg', 'Medicine_Ball_Full_Twist/1.jpg'], 'free-exercise-db'),
  ('medicine-ball-scoop-throw', 'Medicine Ball Scoop Throw', 'Shoulders', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'push', array['shoulders'], array['abdominals', 'hamstrings', 'quadriceps'], array['Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet.', 'Begin by thrusting the hips forward as you extend through the legs, jumping up.', 'As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you.'], array['Medicine_Ball_Scoop_Throw/0.jpg', 'Medicine_Ball_Scoop_Throw/1.jpg'], 'free-exercise-db'),
  ('middle-back-shrug', 'Middle Back Shrug', 'Back', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['middle back'], null, array['Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.', 'As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms.', 'As you inhale go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Middle_Back_Shrug/0.jpg', 'Middle_Back_Shrug/1.jpg'], 'free-exercise-db'),
  ('middle-back-stretch', 'Middle Back Stretch', 'Back', false, 'stretching', null, 'beginner', 'isolation', 'static', array['middle back'], array['abdominals', 'lats', 'lower back'], array['Stand so your feet are shoulder width apart and your hands are on your hips.', 'Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side.'], array['Middle_Back_Stretch/0.jpg', 'Middle_Back_Stretch/1.jpg'], 'free-exercise-db'),
  ('mixed-grip-chin', 'Mixed Grip Chin', 'Back', false, 'strength', 'other', 'expert', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position.', 'Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elbows will be away but in line with the torso. You will concentrate on using the lats to pull your body up.', 'After a second contraction at the top, start to slowly come down as you inhale.', 'Repeat for the recommended amount of repetitions.', 'On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left.'], array['Mixed_Grip_Chin/0.jpg', 'Mixed_Grip_Chin/1.jpg'], 'free-exercise-db'),
  ('monster-walk', 'Monster Walk', 'Glutes', false, 'strength', 'bands', 'beginner', 'compound', 'pull', array['abductors'], null, array['Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.', 'To begin, take short steps forward alternating your left and right foot.', 'After several steps, do just the opposite and walk backward to where you started.'], array['Monster_Walk/0.jpg', 'Monster_Walk/1.jpg'], 'free-exercise-db'),
  ('mountain-climbers', 'Mountain Climbers', 'Legs', false, 'plyometrics', null, 'beginner', 'compound', 'pull', array['quadriceps'], array['chest', 'hamstrings', 'shoulders'], array['Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.', 'Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.'], array['Mountain_Climbers/0.jpg', 'Mountain_Climbers/1.jpg'], 'free-exercise-db'),
  ('moving-claw-series', 'Moving Claw Series', 'Hamstrings', false, 'plyometrics', null, 'beginner', 'compound', null, array['hamstrings'], array['calves', 'quadriceps'], array['This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.', 'Reload the quad as the leg moves back forward, attacking the ground on the next step.', 'Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.'], array['Moving_Claw_Series/0.jpg', 'Moving_Claw_Series/1.jpg'], 'free-exercise-db'),
  ('muscle-snatch', 'Muscle Snatch', 'Hamstrings', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['glutes', 'lower back', 'quadriceps', 'shoulders', 'triceps'], array['Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.', 'Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body.', 'Continue raising the bar to the overhead position, without rebending the knees.'], array['Muscle_Snatch/0.jpg', 'Muscle_Snatch/1.jpg'], 'free-exercise-db'),
  ('muscle-up', 'Muscle Up', 'Back', false, 'strength', 'other', 'intermediate', 'compound', 'pull', array['lats'], array['abdominals', 'biceps', 'forearms', 'middle back', 'shoulders', 'traps', 'triceps'], array['Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.', 'As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.', 'Maintaining control and stability, extend through the elbow to complete the motion.', 'Use care when lowering yourself to the ground.'], array['Muscle_Up/0.jpg', 'Muscle_Up/1.jpg'], 'free-exercise-db'),
  ('narrow-stance-hack-squats', 'Narrow Stance Hack Squats', 'Legs', false, 'strength', 'machine', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.', 'Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).', 'Now straighten your legs without locking the knees. This will be your starting position.', 'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.', 'Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Narrow_Stance_Hack_Squats/0.jpg', 'Narrow_Stance_Hack_Squats/1.jpg'], 'free-exercise-db'),
  ('narrow-stance-leg-press', 'Narrow Stance Leg Press', 'Legs', false, 'strength', 'machine', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.', 'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.', 'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.'], array['Narrow_Stance_Leg_Press/0.jpg', 'Narrow_Stance_Leg_Press/1.jpg'], 'free-exercise-db'),
  ('narrow-stance-squats', 'Narrow Stance Squats', 'Legs', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a less-than-shoulder-width narrow stance with the toes slightly pointed out. Feet should be around 3-6 inches apart. Keep your head up at all times (looking down will get you off balance) and maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Narrow_Stance_Squats/0.jpg', 'Narrow_Stance_Squats/1.jpg'], 'free-exercise-db'),
  ('natural-glute-ham-raise', 'Natural Glute Ham Raise', 'Hamstrings', false, 'strength', 'body only', 'intermediate', 'compound', 'pull', array['hamstrings'], array['calves', 'glutes', 'lower back'], array['Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.', 'This will be your starting position. Lower yourself under control until your knees are almost completely straight.', 'Remaining in control, raise yourself back up to the starting position.', 'If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition.'], array['Natural_Glute_Ham_Raise/0.jpg', 'Natural_Glute_Ham_Raise/1.jpg'], 'free-exercise-db'),
  ('neck-press', 'Neck Press', 'Chest', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your neck.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.'], array['Neck_Press/0.jpg', 'Neck_Press/1.jpg'], 'free-exercise-db'),
  ('neck-smr', 'Neck-SMR', 'Neck', false, 'stretching', 'other', 'intermediate', null, 'static', array['neck'], null, array['Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. This will be your starting position.', 'Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds.'], array['Neck-SMR/0.jpg', 'Neck-SMR/1.jpg'], 'free-exercise-db'),
  ('nordic-curl', 'Nordic Curl', 'Hamstrings', false, null, null, null, null, null, null, null, null, null, 'repple'),
  ('oblique-crunches', 'Oblique Crunches', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.', 'Make sure your feet are elevated and resting on a flat surface.', 'Now lift the shoulder in which your hand is touching your head.', 'Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.', 'After your knee touches your elbow, lower your body until you have reached the starting position.', 'Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (upward) part of the exercise.', 'Continue alternating in this manner until all of the recommended repetitions for each side have been completed.'], array['Oblique_Crunches/0.jpg', 'Oblique_Crunches/1.jpg'], 'free-exercise-db'),
  ('oblique-crunches-on-the-floor', 'Oblique Crunches - On The Floor', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.', 'Place your left hand behind your head.', 'Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.', 'Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position.', 'Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise.'], array['Oblique_Crunches_-_On_The_Floor/0.jpg', 'Oblique_Crunches_-_On_The_Floor/1.jpg'], 'free-exercise-db'),
  ('olympic-squat', 'Olympic Squat', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed.', 'Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel.', 'At the moment the upper legs contact the lower, reverse the motion, driving the weight upward.'], array['Olympic_Squat/0.jpg', 'Olympic_Squat/1.jpg'], 'free-exercise-db'),
  ('on-your-back-quad-stretch', 'On-Your-Back Quad Stretch', 'Legs', false, 'stretching', 'other', 'beginner', 'isolation', 'static', array['quadriceps'], null, array['Lie on a flat bench or step, and hang one leg and arm over the side.', 'Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back.', 'Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you''re holding up toward the ceiling.', 'Switch sides.'], array['On-Your-Back_Quad_Stretch/0.jpg', 'On-Your-Back_Quad_Stretch/1.jpg'], 'free-exercise-db'),
  ('on-your-side-quad-stretch', 'On Your Side Quad Stretch', 'Legs', false, 'stretching', null, 'beginner', 'isolation', 'static', array['quadriceps'], null, array['Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).', 'Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides.'], array['On_Your_Side_Quad_Stretch/0.jpg', 'On_Your_Side_Quad_Stretch/1.jpg'], 'free-exercise-db'),
  ('one-arm-against-wall', 'One Arm Against Wall', 'Back', false, 'stretching', null, 'beginner', 'isolation', 'static', array['lats'], null, array['From a standing position, place a bent arm against a wall or doorway.', 'Slowly lean toward your arm until you feel a stretch in your lats.'], array['One_Arm_Against_Wall/0.jpg', 'One_Arm_Against_Wall/1.jpg'], 'free-exercise-db'),
  ('one-arm-chin-up', 'One Arm Chin-Up', 'Back', false, 'strength', 'other', 'expert', 'compound', 'pull', array['middle back'], array['biceps', 'forearms', 'lats'], array['For this exercise, start out by placing a towel around a chin up bar.', 'Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel.', 'Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.', 'Switch arms and repeat the movement.'], array['One_Arm_Chin-Up/0.jpg', 'One_Arm_Chin-Up/1.jpg'], 'free-exercise-db'),
  ('one-arm-dumbbell-bench-press', 'One Arm Dumbbell Bench Press', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie down on a flat bench with a dumbbell in one hand on top of your thigh.', 'By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.', 'Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position.', 'Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times. Tip: Use the hand that you are not lifting with to help keep the dumbbell balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.', 'Switch arms and repeat the movement.'], array['One_Arm_Dumbbell_Bench_Press/0.jpg', 'One_Arm_Dumbbell_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('one-arm-dumbbell-preacher-curl', 'One Arm Dumbbell Preacher Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.', 'Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.', 'Switch arms and repeat the movement.'], array['One_Arm_Dumbbell_Preacher_Curl/0.jpg', 'One_Arm_Dumbbell_Preacher_Curl/1.jpg'], 'free-exercise-db'),
  ('one-arm-dumbbell-row', 'One-Arm Dumbbell Row', 'Back', false, 'strength', 'dumbbell', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats', 'shoulders'], array['Choose a flat bench and place a dumbbell on each side of it.', 'Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.', 'Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.', 'Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.', 'Lower the resistance straight down to the starting position. Breathe in as you perform this step.', 'Repeat the movement for the specified amount of repetitions.', 'Switch sides and repeat again with the other arm.'], array['One-Arm_Dumbbell_Row/0.jpg', 'One-Arm_Dumbbell_Row/1.jpg'], 'free-exercise-db'),
  ('one-arm-flat-bench-dumbbell-flye', 'One-Arm Flat Bench Dumbbell Flye', 'Chest', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['chest'], null, array['Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip.', 'By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position.', 'Your arm with the weight should have a slight bend on your elbow in order to prevent stress at the biceps tendon. Begin by lowering your arm with the weight in it out in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, your lifting arm should remain stationary; the movement should only occur at the shoulder joint.', 'Return your lifting arm back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the exercise.'], array['One-Arm_Flat_Bench_Dumbbell_Flye/0.jpg', 'One-Arm_Flat_Bench_Dumbbell_Flye/1.jpg'], 'free-exercise-db'),
  ('one-arm-floor-press', 'One Arm Floor Press', 'Arms', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent.', 'Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso).', 'Make sure the hand you are not using to lift the weight is placed by your side.', 'Begin the exercise by lowering the barbell until your elbow touches the ground. Make sure to breathe in as this is the eccentric (lowering part of the exercise).', 'Then start lifting the barbell back up to the original starting position. Remember to breathe out during the concentric (lifting part of the exercise).', 'Repeat until you have performed your recommended repetitions.', 'Switch arms and repeat the movement.'], array['One_Arm_Floor_Press/0.jpg', 'One_Arm_Floor_Press/1.jpg'], 'free-exercise-db'),
  ('one-arm-high-pulley-cable-side-bends', 'One-Arm High-Pulley Cable Side Bends', 'Core', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Connect a standard handle to a tower. Move cable to highest pulley position.', 'Stand with side to cable. With one hand, reach up and grab handle with underhand grip.', 'Pull down cable until elbow touches your side and the handle is by your shoulder.', 'Position feet hip-width apart. Place free hand on hip to help gauge pivot point.', 'Keep arm in static position. Contract oblique to bring the weight down in a side crunch.', 'Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position. The aim is constant tension during the set.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.'], array['One-Arm_High-Pulley_Cable_Side_Bends/0.jpg', 'One-Arm_High-Pulley_Cable_Side_Bends/1.jpg'], 'free-exercise-db'),
  ('one-arm-incline-lateral-raise', 'One-Arm Incline Lateral Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], null, array['Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel.', 'Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position.', 'While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Tip: Exhale as you perform this movement. Hold the dumbbell in the position and feel the contraction in the shoulders for a second.', 'While inhaling lower the weight across your body back into the starting position.', 'Repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the movement.'], array['One-Arm_Incline_Lateral_Raise/0.jpg', 'One-Arm_Incline_Lateral_Raise/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-clean', 'One-Arm Kettlebell Clean', 'Hamstrings', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['hamstrings'], array['glutes', 'lower back', 'shoulders', 'traps'], array['Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.', 'Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.', 'Return the weight to the starting position.'], array['One-Arm_Kettlebell_Clean/0.jpg', 'One-Arm_Kettlebell_Clean/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-clean-and-jerk', 'One-Arm Kettlebell Clean and Jerk', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], null, array['Hold a kettlebell by the handle.', 'Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.', 'Receive the weight overhead by returning to a squat position underneath the weight.', 'Keeping the weight overhead, return to a standing position. Lower the weight to the floor to perform the next repetition.'], array['One-Arm_Kettlebell_Clean_and_Jerk/0.jpg', 'One-Arm_Kettlebell_Clean_and_Jerk/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-floor-press', 'One-Arm Kettlebell Floor Press', 'Chest', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['chest'], array['triceps'], array['Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.', 'Press the kettlebell straight up toward the ceiling, rotating your wrist.', 'Lower the kettlebell back to the starting position and repeat.'], array['One-Arm_Kettlebell_Floor_Press/0.jpg', 'One-Arm_Kettlebell_Floor_Press/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-jerk', 'One-Arm Kettlebell Jerk', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['calves', 'quadriceps', 'triceps'], array['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Receive the weight overhead by returning to a squat position underneath the weight. Keeping the weight overhead, return to a standing position.', 'Lower the weight to perform the next repetition.'], array['One-Arm_Kettlebell_Jerk/0.jpg', 'One-Arm_Kettlebell_Jerk/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-military-press-to-the-side', 'One-Arm Kettlebell Military Press To The Side', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position.', 'Look at the kettlebell and press it up and out until it is locked out overhead.', 'Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.'], array['One-Arm_Kettlebell_Military_Press_To_The_Side/0.jpg', 'One-Arm_Kettlebell_Military_Press_To_The_Side/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-para-press', 'One-Arm Kettlebell Para Press', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead.', 'Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.'], array['One-Arm_Kettlebell_Para_Press/0.jpg', 'One-Arm_Kettlebell_Para_Press/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-push-press', 'One-Arm Kettlebell Push Press', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['calves', 'quadriceps', 'triceps'], array['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Lower the weight to perform the next repetition.'], array['One-Arm_Kettlebell_Push_Press/0.jpg', 'One-Arm_Kettlebell_Push_Press/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-row', 'One-Arm Kettlebell Row', 'Back', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat.'], array['One-Arm_Kettlebell_Row/0.jpg', 'One-Arm_Kettlebell_Row/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-snatch', 'One-Arm Kettlebell Snatch', 'Shoulders', false, 'strength', 'kettlebells', 'expert', 'compound', 'pull', array['shoulders'], array['calves', 'glutes', 'hamstrings', 'lower back', 'traps', 'triceps'], array['Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position.', 'Look straight ahead and swing the kettlebell back between your legs.', 'Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead.'], array['One-Arm_Kettlebell_Snatch/0.jpg', 'One-Arm_Kettlebell_Snatch/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-split-jerk', 'One-Arm Kettlebell Split Jerk', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['glutes', 'hamstrings', 'quadriceps', 'triceps'], array['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.', 'Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.', 'Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition.'], array['One-Arm_Kettlebell_Split_Jerk/0.jpg', 'One-Arm_Kettlebell_Split_Jerk/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-split-snatch', 'One-Arm Kettlebell Split Snatch', 'Shoulders', false, 'strength', 'kettlebells', 'expert', 'compound', 'pull', array['shoulders'], array['hamstrings', 'quadriceps'], array['Hold a kettlebell in one hand by the handle.', 'Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead.', 'After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.', 'Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position.'], array['One-Arm_Kettlebell_Split_Snatch/0.jpg', 'One-Arm_Kettlebell_Split_Snatch/1.jpg'], 'free-exercise-db'),
  ('one-arm-kettlebell-swings', 'One-Arm Kettlebell Swings', 'Hamstrings', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['hamstrings'], array['calves', 'glutes', 'lower back', 'shoulders'], null, array['One-Arm_Kettlebell_Swings/0.jpg', 'One-Arm_Kettlebell_Swings/1.jpg'], 'free-exercise-db'),
  ('one-arm-lat-pulldown', 'One Arm Lat Pulldown', 'Back', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back'], array['Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.', 'Pull the handle down, squeezing your elbow to your side as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handle to the starting position.', 'For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.'], array['One_Arm_Lat_Pulldown/0.jpg', 'One_Arm_Lat_Pulldown/1.jpg'], 'free-exercise-db'),
  ('one-arm-long-bar-row', 'One-Arm Long Bar Row', 'Back', false, 'strength', 'barbell', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.', 'Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position.', 'Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position.', 'Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the movement.', 'After a brief pause, return to the starting position.'], array['One-Arm_Long_Bar_Row/0.jpg', 'One-Arm_Long_Bar_Row/1.jpg'], 'free-exercise-db'),
  ('one-arm-medicine-ball-slam', 'One-Arm Medicine Ball Slam', 'Core', false, 'strength', 'medicine ball', 'beginner', 'compound', 'pull', array['abdominals'], array['lats', 'shoulders'], array['Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position.', 'Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam.', 'At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you.', 'Catch the ball on the bounce and continue for the desired number of repetitions.'], array['One-Arm_Medicine_Ball_Slam/0.jpg', 'One-Arm_Medicine_Ball_Slam/1.jpg'], 'free-exercise-db'),
  ('one-arm-open-palm-kettlebell-clean', 'One-Arm Open Palm Kettlebell Clean', 'Hamstrings', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['hamstrings'], array['forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders'], array['Place one kettlebell between your feet.', 'Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand.', 'Throw the kettlebell out in front of you and catch the handle with one hand.', 'Take the kettlebell to the floor and repeat. Make sure to work both arms.'], array['One-Arm_Open_Palm_Kettlebell_Clean/0.jpg', 'One-Arm_Open_Palm_Kettlebell_Clean/1.jpg'], 'free-exercise-db'),
  ('one-arm-overhead-kettlebell-squats', 'One-Arm Overhead Kettlebell Squats', 'Legs', false, 'strength', 'kettlebells', 'expert', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'shoulders'], array['Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position.', 'Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up.', 'Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet.'], array['One-Arm_Overhead_Kettlebell_Squats/0.jpg', 'One-Arm_Overhead_Kettlebell_Squats/1.jpg'], 'free-exercise-db'),
  ('one-arm-pronated-dumbbell-triceps-extension', 'One Arm Pronated Dumbbell Triceps Extension', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['triceps'], null, array['Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise.', 'Place your non lifting hand on your bicep for support.', 'Slowly begin to lower the dumbbell down as you breathe in.', 'Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).', 'Repeat until you have performed your set repetitions.', 'Switch arms and repeat the movement.'], array['One_Arm_Pronated_Dumbbell_Triceps_Extension/0.jpg', 'One_Arm_Pronated_Dumbbell_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('one-arm-side-deadlift', 'One-Arm Side Deadlift', 'Legs', false, 'strength', 'barbell', 'expert', 'compound', 'pull', array['quadriceps'], array['abdominals', 'calves', 'glutes', 'hamstrings', 'lower back', 'traps'], array['Stand to the side of a barbell next to its center. Bend your knees and lower your body until you are able to reach the barbell.', 'Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a wrist wrap if you are using a significant amount of weight. This is your starting position.', 'Use your legs to help lift the barbell up while exhaling. Your arms should extend fully as bring the barbell up until you are in a standing position.', 'Slowly bring the barbell back down while inhaling. Tip: Make sure to bend your knees while lowering the weight to avoid any injury from occurring.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the movement.'], array['One-Arm_Side_Deadlift/0.jpg', 'One-Arm_Side_Deadlift/1.jpg'], 'free-exercise-db'),
  ('one-arm-side-laterals', 'One-Arm Side Laterals', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], null, array['Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance.', 'Stand with a straight torso and have the dumbbell by your side at arm''s length with the palm of the hand facing you. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbell back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.'], array['One-Arm_Side_Laterals/0.jpg', 'One-Arm_Side_Laterals/1.jpg'], 'free-exercise-db'),
  ('one-arm-supinated-dumbbell-triceps-extension', 'One Arm Supinated Dumbbell Triceps Extension', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['triceps'], null, array['Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise.', 'Place your non lifting hand on your bicep for support.', 'Slowly begin to lower the dumbbell down as you breathe in.', 'Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).', 'Repeat until you have performed your set repetitions.', 'Switch arms and repeat the movement.', 'Switch arms again and repeat the movement.'], array['One_Arm_Supinated_Dumbbell_Triceps_Extension/0.jpg', 'One_Arm_Supinated_Dumbbell_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('one-half-locust', 'One Half Locust', 'Legs', false, 'stretching', null, 'beginner', null, 'static', array['quadriceps'], array['abdominals', 'biceps', 'chest'], array['Lie facedown on the floor.', 'Put your left hand under your left hipbone to pad your hip and pubic bone.', 'Bend your right knee so you can hold the foot in your right hand.', 'Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn''t bother your back, you can try it with both arms and legs at the same time.'], array['One_Half_Locust/0.jpg', 'One_Half_Locust/1.jpg'], 'free-exercise-db'),
  ('one-handed-hang', 'One Handed Hang', 'Back', false, 'stretching', 'other', 'beginner', null, 'static', array['lats'], array['biceps'], array['Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides.'], array['One_Handed_Hang/0.jpg', 'One_Handed_Hang/1.jpg'], 'free-exercise-db'),
  ('one-knee-to-chest', 'One Knee To Chest', 'Glutes', false, 'stretching', null, 'beginner', 'compound', 'static', array['glutes'], array['hamstrings', 'lower back'], array['Start off by lying on the floor.', 'Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.', 'Gently tug that knee toward your nose.', 'Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg.'], array['One_Knee_To_Chest/0.jpg', 'One_Knee_To_Chest/1.jpg'], 'free-exercise-db'),
  ('one-leg-barbell-squat', 'One Leg Barbell Squat', 'Legs', false, 'strength', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other.', 'Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest.', 'Then lift the barbell over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the flat bench. Your other foot should be stationary in front of you. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. Tip: Make sure your back is straight and chest is out while performing this exercise.', 'As you inhale, slowly lower your leg until your thigh is parallel to the floor. At this point, your knee should be over your toes. Your chest should be directly above the middle of your thigh.', 'Leading with the chest and hips and contracting the quadriceps, elevate your leg back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.', 'Switch legs and repeat the movement.'], array['One_Leg_Barbell_Squat/0.jpg', 'One_Leg_Barbell_Squat/1.jpg'], 'free-exercise-db'),
  ('one-legged-cable-kickback', 'One-Legged Cable Kickback', 'Glutes', false, 'strength', 'cable', 'intermediate', 'isolation', 'push', array['glutes'], array['hamstrings'], array['Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.', 'Face the weight stack from a distance of about two feet, grasping the steel frame for support.', 'While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.', 'Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.', 'Repeat for the recommended amount of repetitions.', 'Switch legs and repeat the movement for the other side.'], array['One-Legged_Cable_Kickback/0.jpg', 'One-Legged_Cable_Kickback/1.jpg'], 'free-exercise-db'),
  ('open-palm-kettlebell-clean', 'Open Palm Kettlebell Clean', 'Hamstrings', false, 'strength', 'kettlebells', 'expert', 'compound', 'pull', array['hamstrings'], array['glutes', 'lower back', 'quadriceps', 'shoulders'], array['Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders.', 'Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands.', 'Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat.'], array['Open_Palm_Kettlebell_Clean/0.jpg', 'Open_Palm_Kettlebell_Clean/1.jpg'], 'free-exercise-db'),
  ('otis-up', 'Otis-Up', 'Core', false, 'strength', 'other', 'beginner', 'compound', 'pull', array['abdominals'], array['chest', 'shoulders', 'triceps'], array['Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position.', 'Initiate the movement by flexing the hips and spine to raise your torso up from the ground.', 'As you move up, press the weight up so that it is above your head at the top of the movement.', 'Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor.'], array['Otis-Up/0.jpg', 'Otis-Up/1.jpg'], 'free-exercise-db'),
  ('overhead-cable-curl', 'Overhead Cable Curl', 'Arms', false, 'strength', 'cable', 'intermediate', 'isolation', 'pull', array['biceps'], null, array['To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.', 'Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.', 'Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.', 'While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.', 'While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.', 'Repeat for the recommended amount of repetitions prescribed in your program.'], array['Overhead_Cable_Curl/0.jpg', 'Overhead_Cable_Curl/1.jpg'], 'free-exercise-db'),
  ('overhead-lat', 'Overhead Lat', 'Back', false, 'stretching', 'other', 'expert', null, 'static', array['lats'], array['triceps'], array['Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position.', 'Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.', 'After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch sides.'], array['Overhead_Lat/0.jpg', 'Overhead_Lat/1.jpg'], 'free-exercise-db'),
  ('overhead-press', 'Overhead Press', 'Shoulders', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.', 'Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Military_Press/0.jpg', 'Standing_Military_Press/1.jpg'], 'repple+free-exercise-db'),
  ('overhead-slam', 'Overhead Slam', 'Back', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'pull', array['lats'], null, array['Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.', 'Initiate the countermovement by raising the ball above your head and fully extending your body.', 'Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.', 'Receive the ball with both hands on the bounce and repeat the movement.'], array['Overhead_Slam/0.jpg', 'Overhead_Slam/1.jpg'], 'free-exercise-db'),
  ('overhead-squat', 'Overhead Squat', 'Legs', false, 'olympic weightlifting', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['abdominals', 'calves', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'triceps'], array['Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.', 'Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.', 'Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.', 'Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.', 'Now use your feet and legs to help bring the weight back up to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.'], array['Overhead_Squat/0.jpg', 'Overhead_Squat/1.jpg'], 'free-exercise-db'),
  ('overhead-stretch', 'Overhead Stretch', 'Core', false, 'stretching', null, 'beginner', 'compound', 'static', array['abdominals'], array['chest', 'forearms', 'lats', 'triceps'], array['Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your shoulders down as you extend your arms up.', 'To create a full torso stretch, pull your tailbone down and stabilize your torso as you do this. Stretch the muscles on both the front and the back of the torso.'], array['Overhead_Stretch/0.jpg', 'Overhead_Stretch/1.jpg'], 'free-exercise-db'),
  ('overhead-tricep-extension', 'Overhead Tricep Extension', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['Attach a rope to the bottom pulley of the pulley machine.', 'Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.', 'Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.', 'Return to the starting position by flexing your triceps as you breathe out.', 'Repeat for the recommended amount of repetitions.'], array['Cable_Rope_Overhead_Triceps_Extension/0.jpg', 'Cable_Rope_Overhead_Triceps_Extension/1.jpg'], 'repple+free-exercise-db'),
  ('overhead-triceps', 'Overhead Triceps', 'Arms', false, 'stretching', 'body only', 'expert', null, 'static', array['triceps'], array['lats'], array['Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your elbow and wrist. This will be your starting position.', 'Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so.', 'After 10-20 seconds, relax the arm and allow your partner to further stretch the tricep by applying gentle pressure to the wrist. Hold for 10-20 seconds, and then switch sides.'], array['Overhead_Triceps/0.jpg', 'Overhead_Triceps/1.jpg'], 'free-exercise-db'),
  ('pallof-press', 'Pallof Press', 'Core', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['abdominals'], array['chest', 'shoulders', 'triceps'], array['Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.', 'With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.', 'With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.', 'Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.', 'Hold the repetition for several seconds before returning to the starting position.', 'At the conclusion of the set, repeat facing the other direction.'], array['Pallof_Press/0.jpg', 'Pallof_Press/1.jpg'], 'free-exercise-db'),
  ('pallof-press-with-rotation', 'Pallof Press With Rotation', 'Core', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['abdominals'], array['chest', 'shoulders', 'triceps'], array['Connect a standard handle to a tower, and position the cable to shoulder height.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.', 'With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.', 'Facing forward, press the cable away from your chest. You core should be tight and engaged.', 'Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.', 'Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.', 'With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.'], array['Pallof_Press_With_Rotation/0.jpg', 'Pallof_Press_With_Rotation/1.jpg'], 'free-exercise-db'),
  ('palms-down-dumbbell-wrist-curl-over-a-bench', 'Palms-Down Dumbbell Wrist Curl Over A Bench', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Start out by placing two dumbbells on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.'], array['Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg', 'Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg'], 'free-exercise-db'),
  ('palms-down-wrist-curl-over-a-bench', 'Palms-Down Wrist Curl Over A Bench', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Start out by placing a barbell on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.'], array['Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg', 'Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg'], 'free-exercise-db'),
  ('palms-up-barbell-wrist-curl-over-a-bench', 'Palms-Up Barbell Wrist Curl Over A Bench', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Start out by placing a barbell on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.'], array['Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg', 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg'], 'free-exercise-db'),
  ('palms-up-dumbbell-wrist-curl-over-a-bench', 'Palms-Up Dumbbell Wrist Curl Over A Bench', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Start out by placing two dumbbells on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.'], array['Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg', 'Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg'], 'free-exercise-db'),
  ('parallel-bar-dip', 'Parallel Bar Dip', 'Arms', false, 'strength', 'other', 'beginner', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.', 'Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.', 'Reverse the motion by extending the elbow, pushing yourself back up into the starting position.', 'Repeat for the desired number of repetitions.'], array['Parallel_Bar_Dip/0.jpg', 'Parallel_Bar_Dip/1.jpg'], 'free-exercise-db'),
  ('pec-deck', 'Pec Deck', 'Chest', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['chest'], null, array['Sit on the machine with your back flat on the pad.', 'Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.', 'Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.', 'Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.', 'Repeat for the recommended amount of repetitions.'], array['Butterfly/0.jpg', 'Butterfly/1.jpg'], 'repple+free-exercise-db'),
  ('pelvic-tilt-into-bridge', 'Pelvic Tilt Into Bridge', 'Lower back', false, 'stretching', null, 'intermediate', 'compound', 'static', array['lower back'], null, array['Lie down with your feet on the floor, heels directly under your knees.', 'Lift only your tailbone to the ceiling to stretch your lower back. (Don''t lift the entire spine yet.) Pull in your stomach.', 'To go into a bridge, lift the entire spine except the neck.'], array['Pelvic_Tilt_Into_Bridge/0.jpg', 'Pelvic_Tilt_Into_Bridge/1.jpg'], 'free-exercise-db'),
  ('peroneals-smr', 'Peroneals-SMR', 'Calves', false, 'stretching', 'foam roll', 'intermediate', null, 'static', array['calves'], null, array['Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position.', 'Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg.'], array['Peroneals-SMR/0.jpg', 'Peroneals-SMR/1.jpg'], 'free-exercise-db'),
  ('peroneals-stretch', 'Peroneals Stretch', 'Calves', false, 'stretching', 'other', 'intermediate', null, 'static', array['calves'], null, array['In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.', 'With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.'], array['Peroneals_Stretch/0.jpg', 'Peroneals_Stretch/1.jpg'], 'free-exercise-db'),
  ('physioball-hip-bridge', 'Physioball Hip Bridge', 'Glutes', false, 'strength', 'exercise ball', 'beginner', 'compound', 'push', array['glutes'], array['hamstrings'], array['Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position.', 'Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge.', 'Pause at the top of the motion and return to the starting position.'], array['Physioball_Hip_Bridge/0.jpg', 'Physioball_Hip_Bridge/1.jpg'], 'free-exercise-db'),
  ('pin-presses', 'Pin Presses', 'Arms', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'forearms', 'lats', 'middle back', 'shoulders'], array['Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion.', 'The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting.', 'Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', 'You can take a standard bench grip, or shoulder width to focus on the triceps. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.', 'Drive the bar up with as much force as possible. The elbows should be tucked in until lockout.', 'Return the bar to the pins, pausing before beginning the next repetition.'], array['Pin_Presses/0.jpg', 'Pin_Presses/1.jpg'], 'free-exercise-db'),
  ('piriformis-smr', 'Piriformis-SMR', 'Glutes', false, 'stretching', 'foam roll', 'intermediate', 'isolation', 'static', array['glutes'], null, array['Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.', 'Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides.'], array['Piriformis-SMR/0.jpg', 'Piriformis-SMR/1.jpg'], 'free-exercise-db'),
  ('plank', 'Plank', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'static', array['abdominals'], null, array['Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.', 'Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.'], array['Plank/0.jpg', 'Plank/1.jpg'], 'free-exercise-db'),
  ('plate-pinch', 'Plate Pinch', 'Arms', false, 'strength', 'other', 'intermediate', 'isolation', 'static', array['forearms'], null, array['Grab two wide-rimmed plates and put them together with the smooth sides facing outward', 'Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.', 'Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.', 'Repeat for the recommended amount of sets prescribed in your program.', 'Switch arms and repeat the movements.'], array['Plate_Pinch/0.jpg', 'Plate_Pinch/1.jpg'], 'free-exercise-db'),
  ('plate-twist', 'Plate Twist', 'Core', false, 'strength', 'other', 'intermediate', 'compound', 'pull', array['abdominals'], null, array['Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.', 'Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position.', 'Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement.', 'Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times. Jerking motions can injure the back.', 'Repeat for the recommended amount of repetitions.'], array['Plate_Twist/0.jpg', 'Plate_Twist/1.jpg'], 'free-exercise-db'),
  ('platform-hamstring-slides', 'Platform Hamstring Slides', 'Hamstrings', false, 'strength', 'other', 'beginner', 'isolation', 'pull', array['hamstrings'], array['glutes'], array['For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.', 'Begin the movement by flexing the knee, keeping your other leg straight.', 'Continue bringing the heel closer to you, sliding it on the floor.', 'At full knee flexion, reverse the movement to return to the starting position.'], array['Platform_Hamstring_Slides/0.jpg', 'Platform_Hamstring_Slides/1.jpg'], 'free-exercise-db'),
  ('plie-dumbbell-squat', 'Plie Dumbbell Squat', 'Legs', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['quadriceps'], array['abdominals', 'calves', 'glutes', 'hamstrings'], array['Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.', 'Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.', 'Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.', 'Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.'], array['Plie_Dumbbell_Squat/0.jpg', 'Plie_Dumbbell_Squat/1.jpg'], 'free-exercise-db'),
  ('plyo-kettlebell-pushups', 'Plyo Kettlebell Pushups', 'Chest', false, 'strength', 'kettlebells', 'expert', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position.', 'Begin by lowering yourself as low as you can, keeping your back straight.', 'Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth.'], array['Plyo_Kettlebell_Pushups/0.jpg', 'Plyo_Kettlebell_Pushups/1.jpg'], 'free-exercise-db'),
  ('plyo-push-up', 'Plyo Push-up', 'Chest', false, 'plyometrics', 'body only', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Move into a prone position on the floor, supporting your weight on your hands and toes.', 'Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.', 'Descend by flexing at the elbow, lowering your chest towards the ground.', 'At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground.', 'Return to the starting position and repeat the exercise.', 'For added difficulty, add claps into the movement while you are air borne.'], array['Plyo_Push-up/0.jpg', 'Plyo_Push-up/1.jpg'], 'free-exercise-db'),
  ('posterior-tibialis-stretch', 'Posterior Tibialis Stretch', 'Calves', false, 'stretching', 'other', 'intermediate', null, 'static', array['calves'], null, array['In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.', 'With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.'], array['Posterior_Tibialis_Stretch/0.jpg', 'Posterior_Tibialis_Stretch/1.jpg'], 'free-exercise-db'),
  ('power-clean', 'Power Clean', 'Hamstrings', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['calves', 'forearms', 'glutes', 'lower back', 'middle back', 'quadriceps', 'shoulders', 'traps', 'triceps'], array['Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.', 'Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.', 'Place the bar about 1 inch in front of your shins and over the balls of your feet.', 'Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.', 'Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.', 'Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.', 'Keep elbows fully extended with the head in a neutral position and the shoulders over the bar.', 'As the bar raises keep it as close to the shins as possible.', 'As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Tip: At this point your thighs should be against the bar.', 'Keep the back flat or slightly arched, elbows fully extended and your head neutral. Tip: You will hold your breath until the next phase.', 'Inhale and then forcefully and quickly extend your hips and knees and stand on your toes.', 'Keep the bar as close to your body as possible. Tip: Your back should be flat with the elbows pointed out to the sides and your head in a neutral position. Also, keep your shoulders over the bar and arms straight as long as possible.', 'When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet. Exhale during this portion of the movement.', 'As the shoulders reach their highest elevation flex your elbows to begin pulling your body under the bar.', 'Continue to pull the arms as high and as long as possible. Tip: Due to the explosive nature of this phase, your torso will be erect or with an arched back, your head will be tilted back slightly and your feet may lose contact with the floor.', 'After the lower body has fully extended and the bar reaches near maximal height, pull your body under the bar and rotate the arms around and under the bar.', 'Simultaneously, flex the hips and knees into a quarter squat position.', 'Once the arms are under the bar, inhale and then lift your elbows to position the upper arms parallel to the floor. Rack the bar across the front of your collar bones and front shoulder muscles.', 'Catch the bar with an erect and tight torso, a neutral head position and flat feet. Exhale during this movement.', 'Stand up by extending the hips and knees to a fully erect position.', 'Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the thighs. Inhale during this movement.', 'Simultaneously flex the hips and knees to cushion the impact of the bar on the thighs.', 'Squat down with the elbows fully extended until the bar touches the floor.', 'Start over at Phase 1 and repeat for the recommended amount of repetitions.'], array['Power_Clean/0.jpg', 'Power_Clean/1.jpg'], 'free-exercise-db'),
  ('power-clean-from-blocks', 'Power Clean from Blocks', 'Hamstrings', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['quadriceps'], array['With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips.', 'In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight. At the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, pull yourself under the bar far enough that it can be racked onto the shoulders, rotating your elbows under the bar as you do so. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position, and complete the repetition by returning the weight to the boxes.'], array['Power_Clean_from_Blocks/0.jpg', 'Power_Clean_from_Blocks/1.jpg'], 'free-exercise-db'),
  ('power-jerk', 'Power Jerk', 'Legs', false, 'olympic weightlifting', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['abdominals', 'calves', 'glutes', 'hamstrings', 'shoulders', 'triceps'], array['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.', 'Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.', 'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the knees partially bent.', 'Receive the bar with the arms locked out overhead.', 'Return to a standing position.'], array['Power_Jerk/0.jpg', 'Power_Jerk/1.jpg'], 'free-exercise-db'),
  ('power-partials', 'Power Partials', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], null, array['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position.', 'Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling.', 'Feel the contraction for a second and begin to lower the weights back down to the starting position while inhaling. Tip: Keep the palms facing down with the little finger slightly higher while lifting and lowering the weights as it will concentrate the stress on your shoulders mainly.', 'Repeat for the recommended amount of repetitions.'], array['Power_Partials/0.jpg', 'Power_Partials/1.jpg'], 'free-exercise-db'),
  ('power-snatch', 'Power Snatch', 'Hamstrings', false, 'olympic weightlifting', 'barbell', 'expert', 'compound', 'pull', array['hamstrings'], array['calves', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps', 'triceps'], array['Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.', 'Return to a standing position with the weight over head.'], array['Power_Snatch/0.jpg', 'Power_Snatch/1.jpg'], 'free-exercise-db'),
  ('power-snatch-from-blocks', 'Power Snatch from Blocks', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['quadriceps'], array['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps', 'triceps'], array['Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the boxes.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar above a full squat and with the arms fully extended overhead.', 'Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes.'], array['Power_Snatch_from_Blocks/0.jpg', 'Power_Snatch_from_Blocks/1.jpg'], 'free-exercise-db'),
  ('power-stairs', 'Power Stairs', 'Hamstrings', false, 'strongman', 'other', 'intermediate', 'compound', 'pull', array['hamstrings'], array['adductors', 'calves', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps'], array['In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box.', 'Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground.', 'As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18" high. You can use your legs to help push the weight onto the stair.', 'Repeat for 3-5 repetitions, and continue with a heavier weight, moving as fast as possible.'], array['Power_Stairs/0.jpg', 'Power_Stairs/1.jpg'], 'free-exercise-db'),
  ('preacher-curl', 'Preacher Curl', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.', 'With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.', 'Repeat for the recommended amount of repetitions.'], array['Preacher_Curl/0.jpg', 'Preacher_Curl/1.jpg'], 'free-exercise-db'),
  ('preacher-hammer-dumbbell-curl', 'Preacher Hammer Dumbbell Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip).', 'As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height.', 'Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.'], array['Preacher_Hammer_Dumbbell_Curl/0.jpg', 'Preacher_Hammer_Dumbbell_Curl/1.jpg'], 'free-exercise-db'),
  ('press-sit-up', 'Press Sit-Up', 'Core', false, 'strength', 'barbell', 'expert', 'compound', 'push', array['abdominals'], array['chest', 'shoulders', 'triceps'], array['To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position.', 'While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles.', 'Lower your upper body back down to the starting position while bringing the barbell back down to your torso. Remember to breathe in while lowering the body.', 'Repeat for the recommended amount of repetitions.'], array['Press_Sit-Up/0.jpg', 'Press_Sit-Up/1.jpg'], 'free-exercise-db'),
  ('prone-manual-hamstring', 'Prone Manual Hamstring', 'Hamstrings', false, 'strength', null, 'beginner', 'isolation', 'static', array['hamstrings'], null, array['You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel.', 'To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels.', 'Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction.'], array['Prone_Manual_Hamstring/0.jpg', 'Prone_Manual_Hamstring/1.jpg'], 'free-exercise-db'),
  ('prowler-sprint', 'Prowler Sprint', 'Hamstrings', true, 'cardio', 'other', 'beginner', 'compound', 'push', array['hamstrings'], array['calves', 'chest', 'glutes', 'quadriceps', 'shoulders'], array['Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.', 'You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement.', 'With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.'], array['Prowler_Sprint/0.jpg', 'Prowler_Sprint/1.jpg'], 'free-exercise-db'),
  ('pull-through', 'Pull Through', 'Glutes', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['glutes'], array['hamstrings', 'lower back'], array['Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.', 'Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.'], array['Pull_Through/0.jpg', 'Pull_Through/1.jpg'], 'free-exercise-db'),
  ('pull-up', 'Pull-up', 'Back', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back'], array['Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.'], array['Pullups/0.jpg', 'Pullups/1.jpg'], 'repple+free-exercise-db'),
  ('pullups', 'Pullups', 'Back', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back'], array['Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.'], array['Pullups/0.jpg', 'Pullups/1.jpg'], 'free-exercise-db'),
  ('push-press', 'Push Press', 'Shoulders', false, 'olympic weightlifting', 'barbell', 'expert', 'compound', 'push', array['shoulders'], array['quadriceps', 'triceps'], null, array['Push_Press/0.jpg', 'Push_Press/1.jpg'], 'free-exercise-db'),
  ('push-press-behind-the-neck', 'Push Press - Behind the Neck', 'Shoulders', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'push', array['shoulders'], array['calves', 'quadriceps', 'triceps'], array['Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path.', 'Using the momentum generated, finish pressing the weight overhead be extending through the arms.', 'Return to the starting position, using your legs to absorb the impact.'], array['Push_Press_-_Behind_the_Neck/0.jpg', 'Push_Press_-_Behind_the_Neck/1.jpg'], 'free-exercise-db'),
  ('push-up', 'Push-up', 'Chest', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.'], array['Pushups/0.jpg', 'Pushups/1.jpg'], 'repple+free-exercise-db'),
  ('push-up-to-side-plank', 'Push Up to Side Plank', 'Chest', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['chest'], array['abdominals', 'shoulders', 'triceps'], array['Get into pushup position on the toes with your hands just outside of shoulder width.', 'Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.', 'Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.', 'Lower the arm back to the floor for another pushup and then twist to the other side.', 'Repeat the series, alternating each side, for 10 or more reps.'], array['Push_Up_to_Side_Plank/0.jpg', 'Push_Up_to_Side_Plank/1.jpg'], 'free-exercise-db'),
  ('push-up-wide', 'Push-Up Wide', 'Chest', false, 'strength', 'body only', 'beginner', 'compound', null, array['chest'], array['abdominals', 'shoulders', 'triceps'], array['With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.', 'To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.', 'After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions.'], array['Push-Up_Wide/0.jpg', 'Push-Up_Wide/1.jpg'], 'free-exercise-db'),
  ('push-ups-close-triceps-position', 'Push-Ups - Close Triceps Position', 'Arms', false, 'strength', 'body only', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.'], array['Push-Ups_-_Close_Triceps_Position/0.jpg', 'Push-Ups_-_Close_Triceps_Position/1.jpg'], 'free-exercise-db'),
  ('push-ups-with-feet-elevated', 'Push-Ups With Feet Elevated', 'Chest', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.', 'Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.'], array['Push-Ups_With_Feet_Elevated/0.jpg', 'Push-Ups_With_Feet_Elevated/1.jpg'], 'free-exercise-db'),
  ('push-ups-with-feet-on-an-exercise-ball', 'Push-Ups With Feet On An Exercise Ball', 'Chest', false, 'strength', 'exercise ball', 'intermediate', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.', 'Place your toes on top of an exercise ball. This will allow your body to be elevated.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.'], array['Push-Ups_With_Feet_On_An_Exercise_Ball/0.jpg', 'Push-Ups_With_Feet_On_An_Exercise_Ball/1.jpg'], 'free-exercise-db'),
  ('pushups', 'Pushups', 'Chest', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.'], array['Pushups/0.jpg', 'Pushups/1.jpg'], 'free-exercise-db'),
  ('pushups-close-and-wide-hand-positions', 'Pushups (Close and Wide Hand Positions)', 'Chest', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.'], array['Pushups_Close_and_Wide_Hand_Positions/0.jpg', 'Pushups_Close_and_Wide_Hand_Positions/1.jpg'], 'free-exercise-db'),
  ('pyramid', 'Pyramid', 'Lower back', false, 'stretching', 'exercise ball', 'beginner', null, 'static', array['lower back'], array['shoulders'], array['Start off by rolling your torso forward onto the ball so your hips rest on top of the ball and become the highest point of your body.', 'Rest your hands and feet on the floor. Your arms and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torso and shoulders.'], array['Pyramid/0.jpg', 'Pyramid/1.jpg'], 'free-exercise-db'),
  ('quad-stretch', 'Quad Stretch', 'Legs', false, 'stretching', 'other', 'intermediate', null, 'static', array['quadriceps'], null, array['Lay on your side. Loop a belt, rope, or band around your top foot. Flex the knee and extend your hip, attempting to touch your glutes with your foot, and holding the belt with your hands. This will be your starting position.', 'With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides.'], array['Quad_Stretch/0.jpg', 'Quad_Stretch/1.jpg'], 'free-exercise-db'),
  ('quadriceps-smr', 'Quadriceps-SMR', 'Legs', false, 'stretching', 'foam roll', 'intermediate', 'isolation', 'static', array['quadriceps'], null, array['Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position.', 'Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides.'], array['Quadriceps-SMR/0.jpg', 'Quadriceps-SMR/1.jpg'], 'free-exercise-db'),
  ('quick-leap', 'Quick Leap', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'hamstrings'], array['You will need a box for this exerise.', 'Begin facing the box standing 1-2 feet from its edge.', 'By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat.', 'Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing.'], array['Quick_Leap/0.jpg', 'Quick_Leap/1.jpg'], 'free-exercise-db'),
  ('rack-delivery', 'Rack Delivery', 'Shoulders', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['shoulders'], array['forearms', 'traps'], array['This drill teaches the delivery of the barbell to the rack position on the shoulders. Begin holding a bar in the scarecrow position, with the upper arms parallel to the floor, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs.', 'Begin by rotating the elbows around the bar, delivering the bar to the shoulders. As your elbows come forward, relax your grip. The shoulders should be protracted, providing a shelf for the bar, which should lightly contact the throat.', 'It is important that the bar stay close to the body at all times, as with a heavier load any distance will result in an unwanted collision. As the movement becomes smoother, speed and load can be increased before progressing further.'], array['Rack_Delivery/0.jpg', 'Rack_Delivery/1.jpg'], 'free-exercise-db'),
  ('rack-pull-with-bands', 'Rack Pull with Bands', 'Lower back', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'pull', array['lower back'], array['forearms', 'glutes', 'hamstrings', 'quadriceps', 'traps'], array['Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Attach bands to the base of the rack, or secure them with dumbbells. Attach the other end to the bar. You may need to choke the bands to provide tension.', 'Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.', 'With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement. Return the weight to the pins and repeat.'], array['Rack_Pull_with_Bands/0.jpg', 'Rack_Pull_with_Bands/1.jpg'], 'free-exercise-db'),
  ('rack-pulls', 'Rack Pulls', 'Lower back', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'pull', array['lower back'], array['forearms', 'glutes', 'hamstrings', 'traps'], array['Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.', 'With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.', 'Return the weight to the pins and repeat.'], array['Rack_Pulls/0.jpg', 'Rack_Pulls/1.jpg'], 'free-exercise-db'),
  ('rear-delt-fly', 'Rear Delt Fly', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['shoulders'], null, array['To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).', 'Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.', 'Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.', 'The arms should be elevated until they are parallel to the floor.', 'Feel the contraction and slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.'], array['Reverse_Flyes/0.jpg', 'Reverse_Flyes/1.jpg'], 'repple+free-exercise-db'),
  ('rear-leg-raises', 'Rear Leg Raises', 'Legs', false, 'stretching', 'body only', 'beginner', null, 'push', array['quadriceps'], null, array['Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.', 'Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides.'], array['Rear_Leg_Raises/0.jpg', 'Rear_Leg_Raises/1.jpg'], 'free-exercise-db'),
  ('recumbent-bike', 'Recumbent Bike', 'Legs', true, 'cardio', 'machine', 'beginner', null, null, array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, seat yourself on the bike and adjust the seat to your height.', 'Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.', 'Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities. A 150 lb person will burn about 230 calories cycling at a moderate rate for 30 minutes, compared to 450 calories or more running.'], array['Recumbent_Bike/0.jpg', 'Recumbent_Bike/1.jpg'], 'free-exercise-db'),
  ('return-push-from-stance', 'Return Push from Stance', 'Shoulders', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'push', array['shoulders'], array['chest', 'triceps'], array['You will need a partner for this drill.', 'Begin in an athletic 2 or 3 point stance.', 'At the signal, move into a position to receive the pass from your partner.', 'Catch the medicine ball with both hands and immediately throw it back to your partner.', 'You can modify this drill by running different routes.'], array['Return_Push_from_Stance/0.jpg', 'Return_Push_from_Stance/1.jpg'], 'free-exercise-db'),
  ('reverse-band-bench-press', 'Reverse Band Bench Press', 'Arms', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'forearms', 'lats', 'middle back', 'shoulders'], array['Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell.', 'Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.', 'Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.', 'Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.'], array['Reverse_Band_Bench_Press/0.jpg', 'Reverse_Band_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('reverse-band-box-squat', 'Reverse Band Box Squat', 'Legs', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'forearms', 'glutes', 'hamstrings', 'lower back'], array['Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.'], array['Reverse_Band_Box_Squat/0.jpg', 'Reverse_Band_Box_Squat/1.jpg'], 'free-exercise-db'),
  ('reverse-band-deadlift', 'Reverse Band Deadlift', 'Lower back', false, 'powerlifting', 'barbell', 'expert', 'compound', 'pull', array['lower back'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings', 'quadriceps'], array['Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar.', 'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.', 'After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.'], array['Reverse_Band_Deadlift/0.jpg', 'Reverse_Band_Deadlift/1.jpg'], 'free-exercise-db'),
  ('reverse-band-power-squat', 'Reverse Band Power Squat', 'Legs', false, 'powerlifting', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['adductors', 'calves', 'glutes', 'hamstrings', 'lower back'], array['Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings.', 'Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.'], array['Reverse_Band_Power_Squat/0.jpg', 'Reverse_Band_Power_Squat/1.jpg'], 'free-exercise-db'),
  ('reverse-band-sumo-deadlift', 'Reverse Band Sumo Deadlift', 'Hamstrings', false, 'powerlifting', 'barbell', 'expert', 'compound', 'pull', array['hamstrings'], array['abductors', 'adductors', 'calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'traps'], array['Begin with a bar loaded on the floor inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barbell.', 'Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.'], array['Reverse_Band_Sumo_Deadlift/0.jpg', 'Reverse_Band_Sumo_Deadlift/1.jpg'], 'free-exercise-db'),
  ('reverse-barbell-curl', 'Reverse Barbell Curl', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Reverse_Barbell_Curl/0.jpg', 'Reverse_Barbell_Curl/1.jpg'], 'free-exercise-db'),
  ('reverse-barbell-preacher-curls', 'Reverse Barbell Preacher Curls', 'Arms', false, 'strength', 'e-z curl bar', 'intermediate', 'isolation', 'pull', array['biceps'], array['forearms'], array['Grab an EZ-bar using a shoulder width and palms down (pronated) grip.', 'Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position.', 'As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position.', 'As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched.', 'Repeat for the recommended amount of repetitions.'], array['Reverse_Barbell_Preacher_Curls/0.jpg', 'Reverse_Barbell_Preacher_Curls/1.jpg'], 'free-exercise-db'),
  ('reverse-cable-curl', 'Reverse Cable Curl', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Reverse_Cable_Curl/0.jpg', 'Reverse_Cable_Curl/1.jpg'], 'free-exercise-db'),
  ('reverse-crunch', 'Reverse Crunch', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.', 'Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.', 'While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.', 'Hold the contraction for a second and move your legs back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.'], array['Reverse_Crunch/0.jpg', 'Reverse_Crunch/1.jpg'], 'free-exercise-db'),
  ('reverse-flyes', 'Reverse Flyes', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['shoulders'], null, array['To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).', 'Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.', 'Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.', 'The arms should be elevated until they are parallel to the floor.', 'Feel the contraction and slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.'], array['Reverse_Flyes/0.jpg', 'Reverse_Flyes/1.jpg'], 'free-exercise-db'),
  ('reverse-flyes-with-external-rotation', 'Reverse Flyes With External Rotation', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['shoulders'], null, array['To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline.', 'Have the dumbbells in each hand with the palms facing down to the floor. Your arms should be in front of you so that they are perpendicular to the angle of the bench. Tip: Your elbows should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching the floor). This is the starting position.', 'Maintaining the slight bend of the elbows, move the weights out and away from each other in an arc motion while exhaling.', 'As you lift the weight, your wrist should externally rotate by 90-degrees so that you go from a palms down (pronated) grip to a palms facing each other (neutral) grip. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.', 'The arms should be elevated until they are level with the head.', 'Feel the contraction and slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.'], array['Reverse_Flyes_With_External_Rotation/0.jpg', 'Reverse_Flyes_With_External_Rotation/1.jpg'], 'free-exercise-db'),
  ('reverse-grip-bent-over-rows', 'Reverse Grip Bent-Over Rows', 'Back', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['middle back'], array['biceps', 'lats', 'shoulders'], array['Stand erect while holding a barbell with a supinated grip (palms facing up).', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Reverse_Grip_Bent-Over_Rows/0.jpg', 'Reverse_Grip_Bent-Over_Rows/1.jpg'], 'free-exercise-db'),
  ('reverse-grip-triceps-pushdown', 'Reverse Grip Triceps Pushdown', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['Start by setting a bar attachment (straight or e-z) on a high pulley machine.', 'Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position.', 'Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.', 'Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.', 'Repeat for the recommended amount of repetitions.'], array['Reverse_Grip_Triceps_Pushdown/0.jpg', 'Reverse_Grip_Triceps_Pushdown/1.jpg'], 'free-exercise-db'),
  ('reverse-hyperextension', 'Reverse Hyperextension', 'Hamstrings', false, 'strength', 'machine', 'intermediate', null, 'pull', array['hamstrings'], array['calves', 'glutes'], array['Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.', 'To begin the movement, flex the hips, pulling the legs forward.', 'Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.', 'Return by again flexing the hip, pulling the carriage forward as far as you can.', 'Repeat for the desired number of repetitions.'], array['Reverse_Hyperextension/0.jpg', 'Reverse_Hyperextension/1.jpg'], 'free-exercise-db'),
  ('reverse-machine-flyes', 'Reverse Machine Flyes', 'Shoulders', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['shoulders'], null, array['Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.', 'In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.', 'Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.', 'Pause at the rear of the movement, and slowly return the weight to the starting position.'], array['Reverse_Machine_Flyes/0.jpg', 'Reverse_Machine_Flyes/1.jpg'], 'free-exercise-db'),
  ('reverse-plate-curls', 'Reverse Plate Curls', 'Arms', false, 'strength', 'other', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o''clock position.', 'Your feet should be shoulder width apart from each other and the weighted plate should be near the groin area. This is the starting position.', 'Slowly lift the plate up while keeping the elbows in and the upper arms stationary until your biceps and forearms touch while exhaling. The plate should be evenly aligned with your torso at this point.', 'Feel the contraction for a second and begin to lower the weight back down to the starting position while inhaling', 'Repeat for the recommended amount of repetitions.'], array['Reverse_Plate_Curls/0.jpg', 'Reverse_Plate_Curls/1.jpg'], 'free-exercise-db'),
  ('reverse-triceps-bench-press', 'Reverse Triceps Bench Press', 'Arms', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.'], array['Reverse_Triceps_Bench_Press/0.jpg', 'Reverse_Triceps_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('rhomboids-smr', 'Rhomboids-SMR', 'Back', false, 'stretching', 'foam roll', 'intermediate', null, 'static', array['middle back'], array['traps'], array['Lay down with your back on the floor. Place a foam roll underneath your upper back, and cross your arms in front of you, protracting your shoulders. This will be your starting position.', 'Raise your hips off of the ground, placing your weight onto the foam roll. Shift your weight to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds.'], array['Rhomboids-SMR/0.jpg', 'Rhomboids-SMR/1.jpg'], 'free-exercise-db'),
  ('rickshaw-carry', 'Rickshaw Carry', 'Arms', false, 'strongman', 'other', 'intermediate', 'compound', null, array['forearms'], array['abdominals', 'calves', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps'], array['Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight.', 'Immediately begin walking briskly with quick, controlled steps. Keep your chest up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point.'], array['Rickshaw_Carry/0.jpg', 'Rickshaw_Carry/1.jpg'], 'free-exercise-db'),
  ('rickshaw-deadlift', 'Rickshaw Deadlift', 'Legs', false, 'strongman', 'other', 'intermediate', 'compound', 'pull', array['quadriceps'], array['forearms', 'glutes', 'hamstrings', 'lower back', 'traps'], array['Load the frame with the desired weight. Center yourself between the handles. You feet should be about hip width apart. Bend at the hips to grip the handles, allowing your shoulder blades to protract.', 'With your feet and your grip set, take a big breath and then lower your hips and flex the knees. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.', 'Lower the weight by bending at the hips and guiding it to the ground.'], array['Rickshaw_Deadlift/0.jpg', 'Rickshaw_Deadlift/1.jpg'], 'free-exercise-db'),
  ('ring-dips', 'Ring Dips', 'Arms', false, 'strength', 'other', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out.', 'Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.', 'Reverse the motion by extending the elbow, pushing yourself back up into the starting position.', 'Repeat for the desired number of repetitions.'], array['Ring_Dips/0.jpg', 'Ring_Dips/1.jpg'], 'free-exercise-db'),
  ('rocket-jump', 'Rocket Jump', 'Legs', false, 'plyometrics', 'body only', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'hamstrings'], array['Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.', 'To initiate the move, squat down halfway and explode back up as high as possible.', 'Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs.'], array['Rocket_Jump/0.jpg', 'Rocket_Jump/1.jpg'], 'free-exercise-db'),
  ('rocking-standing-calf-raise', 'Rocking Standing Calf Raise', 'Calves', false, 'strength', 'barbell', 'beginner', 'isolation', 'push', array['calves'], null, array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck).', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance. Also maintain a straight back and keep the knees with a slight bend; never locked. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending (other than the slight initial bend we created during positioning) at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Now lift your toes by contracting the tibia muscles in the front of the calves as you breathe out.', 'Hold for a second and bring them back down as you breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Rocking_Standing_Calf_Raise/0.jpg', 'Rocking_Standing_Calf_Raise/1.jpg'], 'free-exercise-db'),
  ('rocky-pull-ups-pulldowns', 'Rocky Pull-Ups/Pulldowns', 'Back', false, 'strength', 'other', 'intermediate', 'compound', 'pull', array['lats'], array['biceps', 'middle back', 'shoulders'], array['Grab the pull-up bar with the palms facing forward using a wide grip.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Now repeat the same movements as described above except this time your torso will remain straight as you go up and the bar will touch the back of the neck instead of the upper chest. Tip: Use the head to lean forward slightly as it will help you properly execute this portion of the exercise.', 'Once you have lowered yourself back down to the starting position, repeat the exercise for the prescribed amount of repetitions in your program.'], array['Rocky_Pull-Ups_Pulldowns/0.jpg', 'Rocky_Pull-Ups_Pulldowns/1.jpg'], 'free-exercise-db'),
  ('romanian-deadlift', 'Romanian Deadlift', 'Hamstrings', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['calves', 'glutes', 'lower back'], array['Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.', 'Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.', 'Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.', 'Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.', 'Repeat for the recommended amount of repetitions.'], array['Romanian_Deadlift/0.jpg', 'Romanian_Deadlift/1.jpg'], 'free-exercise-db'),
  ('romanian-deadlift-from-deficit', 'Romanian Deadlift from Deficit', 'Hamstrings', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['forearms', 'glutes', 'lower back', 'traps'], array['Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion.', 'Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings.', 'Reverse the motion to return to the starting position.'], array['Romanian_Deadlift_from_Deficit/0.jpg', 'Romanian_Deadlift_from_Deficit/1.jpg'], 'free-exercise-db'),
  ('rope-climb', 'Rope Climb', 'Back', false, 'strength', 'other', 'intermediate', 'compound', 'pull', array['lats'], array['biceps', 'forearms', 'middle back', 'shoulders'], array['Grab the rope with both hands above your head. Pull down on the rope as you take a small jump.', 'Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly.', 'Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest.', 'Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope.', 'To lower yourself, loosen the grip of your feet on the rope as you slide down using a hand over hand motion.'], array['Rope_Climb/0.jpg', 'Rope_Climb/1.jpg'], 'free-exercise-db'),
  ('rope-crunch', 'Rope Crunch', 'Core', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Kneel 1-2 feet in front of a cable system with a rope attached.', 'After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position.', 'To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down.', 'Pause at the bottom of the motion, and then slowly return to the starting position.', 'These can be done with twists or to the side to hit the obliques.'], array['Rope_Crunch/0.jpg', 'Rope_Crunch/1.jpg'], 'free-exercise-db'),
  ('rope-jumping', 'Rope Jumping', 'Legs', true, 'cardio', 'other', 'intermediate', null, null, array['quadriceps'], array['calves', 'hamstrings'], array['Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation.', 'Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running.'], array['Rope_Jumping/0.jpg', 'Rope_Jumping/1.jpg'], 'free-exercise-db'),
  ('rope-straight-arm-pulldown', 'Rope Straight-Arm Pulldown', 'Back', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['lats'], null, array['Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.', 'Keeping your arms straight, extend the shoulder to pull the rope down to your thighs.', 'Pause at the bottom of the motion, squeezing your lats.', 'Return to the starting position without allowing the weight to fully rest on the stack.'], array['Rope_Straight-Arm_Pulldown/0.jpg', 'Rope_Straight-Arm_Pulldown/1.jpg'], 'free-exercise-db'),
  ('round-the-world-shoulder-stretch', 'Round The World Shoulder Stretch', 'Shoulders', false, 'stretching', 'other', 'beginner', null, 'static', array['shoulders'], array['biceps', 'chest'], array['Stand up straight with your legs together, holding a bodybar or broomstick.', 'Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out.', 'Slowly lift your arms up behind your head. Don''t force it if it gets hard to lift further.'], array['Round_The_World_Shoulder_Stretch/0.jpg', 'Round_The_World_Shoulder_Stretch/1.jpg'], 'free-exercise-db'),
  ('rowing-machine', 'Rowing Machine', 'Full body', true, null, null, null, null, null, null, null, null, null, 'repple'),
  ('rowing-stationary', 'Rowing, Stationary', 'Legs', true, 'cardio', 'machine', 'intermediate', null, null, array['quadriceps'], array['biceps', 'calves', 'glutes', 'hamstrings', 'lower back', 'middle back'], array['To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.', 'There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.', 'The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase.'], array['Rowing_Stationary/0.jpg', 'Rowing_Stationary/1.jpg'], 'free-exercise-db'),
  ('runner-s-stretch', 'Runner''s Stretch', 'Hamstrings', false, 'stretching', null, 'beginner', null, 'static', array['hamstrings'], array['calves'], array['It''s easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor.', 'Keep the front heel on the floor (if it lifts up, scoot your other leg further back).', 'Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You''ll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front.'], array['Runners_Stretch/0.jpg', 'Runners_Stretch/1.jpg'], 'free-exercise-db'),
  ('running-treadmill', 'Running, Treadmill', 'Legs', true, 'cardio', 'machine', 'beginner', null, null, array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than running outside. A 150 lb person will burn over 450 calories running 8 miles per hour for 30 minutes. Maintain proper posture as you run, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.'], array['Running_Treadmill/0.jpg', 'Running_Treadmill/1.jpg'], 'free-exercise-db'),
  ('russian-twist', 'Russian Twist', 'Core', false, 'strength', 'body only', 'intermediate', 'compound', 'pull', array['abdominals'], array['lower back'], array['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.', 'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.', 'Twist your torso to the right side until your arms are parallel with the floor while breathing out.', 'Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.', 'Repeat for the recommended amount of repetitions.'], array['Russian_Twist/0.jpg', 'Russian_Twist/1.jpg'], 'free-exercise-db'),
  ('sandbag-load', 'Sandbag Load', 'Legs', false, 'strongman', 'other', 'beginner', 'compound', 'pull', array['quadriceps'], array['abdominals', 'biceps', 'calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'middle back', 'shoulders', 'traps'], array['To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet.', 'Begin by lifting the sandbag. Sandbags are extremely awkward, and the manner of lifting them can vary depending on the particular sandbag used. Reach as far around it as possible, extending through the hips and knees to pull it up high. Shouldering is usually not allowed.', 'Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible. Place it onto the platform, ensuring it doesn''t fall off.', 'Return to the starting position to retrieve the next sandbag, and repeat until the event is completed.'], array['Sandbag_Load/0.jpg', 'Sandbag_Load/1.jpg'], 'free-exercise-db'),
  ('scapular-pull-up', 'Scapular Pull-Up', 'Back', false, 'strength', null, 'beginner', 'isolation', 'pull', array['traps'], array['lats', 'middle back'], array['Take a pronated grip on a pull-up bar.', 'From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.', 'Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions.'], array['Scapular_Pull-Up/0.jpg', 'Scapular_Pull-Up/1.jpg'], 'free-exercise-db'),
  ('scissor-kick', 'Scissor Kick', 'Core', false, 'stretching', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.', 'With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position.', 'Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.', 'Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.', 'Repeat for the recommended amount of repetitions.'], array['Scissor_Kick/0.jpg', 'Scissor_Kick/1.jpg'], 'free-exercise-db'),
  ('scissors-jump', 'Scissors Jump', 'Legs', false, 'plyometrics', 'body only', 'beginner', 'compound', 'push', array['quadriceps'], array['glutes', 'hamstrings'], array['Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.', 'Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift.', 'As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.', 'As you land, absorb the impact through the legs by adopting the lunge position, and repeat.'], array['Scissors_Jump/0.jpg', 'Scissors_Jump/1.jpg'], 'free-exercise-db'),
  ('seated-band-hamstring-curl', 'Seated Band Hamstring Curl', 'Hamstrings', false, 'strength', 'other', 'beginner', 'isolation', 'pull', array['hamstrings'], null, array['Secure a band close to the ground and place a bench a couple feet away from it.', 'Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.', 'Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.', 'Pause at the completion of the movement, and then slowly return to the starting position.'], array['Seated_Band_Hamstring_Curl/0.jpg', 'Seated_Band_Hamstring_Curl/1.jpg'], 'free-exercise-db'),
  ('seated-barbell-military-press', 'Seated Barbell Military Press', 'Shoulders', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Barbell_Military_Press/0.jpg', 'Seated_Barbell_Military_Press/1.jpg'], 'free-exercise-db'),
  ('seated-barbell-twist', 'Seated Barbell Twist', 'Core', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs. Your feet should be shoulder width apart from each other.', 'Grip the bar with your palms facing down and make sure your hands are wider than shoulder width apart from each other. Begin to lift the barbell up over your head until your arms are fully extended.', 'Now lower the barbell behind your head until it is resting along the base of your neck. This is the starting position.', 'While keeping your feet and head stationary, move your waist from side to side so that your oblique muscles feel the contraction. Only move from side to side as far as your waist will allow you to go. Stretching or moving too far can cause an injury to occur. Tip: Use a slow and controlled motion.', 'Remember to breathe out while twisting your body to the side and in when moving back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Barbell_Twist/0.jpg', 'Seated_Barbell_Twist/1.jpg'], 'free-exercise-db'),
  ('seated-bent-over-one-arm-dumbbell-triceps-extension', 'Seated Bent-Over One-Arm Dumbbell Triceps Extension', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['triceps'], null, array['Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you).', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.', 'The upper arm with the dumbbell should be close to the torso and aligned with it (lifted up until it is parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.', 'Keeping the upper arm stationary, use the triceps to lift the weight as you exhale until the forearm is parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.', 'After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.', 'Repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the exercise.'], array['Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg', 'Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('seated-bent-over-rear-delt-raise', 'Seated Bent-Over Rear Delt Raise', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['shoulders'], null, array['Place a couple of dumbbells looking forward in front of a flat bench.', 'Sit on the end of the bench with your legs together and the dumbbells behind your calves.', 'Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position.', 'Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. (Note: avoid swinging the torso or bringing the arms back as opposed to the side.)', 'After a one second contraction at the top, slowly lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Bent-Over_Rear_Delt_Raise/0.jpg', 'Seated_Bent-Over_Rear_Delt_Raise/1.jpg'], 'free-exercise-db'),
  ('seated-bent-over-two-arm-dumbbell-triceps-extension', 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'push', array['triceps'], null, array['Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you).', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.', 'The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they are parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.', 'Keeping the upper arms stationary, use the triceps to lift the weight as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.', 'After a second contraction at the top, slowly lower the dumbbells back to the starting position as you inhale.', 'Repeat the movement for the prescribed amount of repetitions.'], array['Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg', 'Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('seated-biceps', 'Seated Biceps', 'Arms', false, 'stretching', 'body only', 'expert', 'isolation', 'static', array['biceps'], array['chest', 'shoulders'], array['Sit on the floor with your knees bent and your partner standing behind you. Extend your arms straight behind you with your palms facing each other. Your partner will hold your wrists for you. This will be the starting position.', 'Attempt to flex your elbows, while your partner prevents any actual movement.', 'After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or overstretching.'], array['Seated_Biceps/0.jpg', 'Seated_Biceps/1.jpg'], 'free-exercise-db'),
  ('seated-cable-rows', 'Seated Cable Rows', 'Back', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats', 'shoulders'], array['For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Cable_Rows/0.jpg', 'Seated_Cable_Rows/1.jpg'], 'free-exercise-db'),
  ('seated-cable-shoulder-press', 'Seated Cable Shoulder Press', 'Shoulders', false, 'strength', 'cable', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together above your head.', 'After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables.', 'You can also execute this movement with your back off the pad and alternate hands.'], array['Seated_Cable_Shoulder_Press/0.jpg', 'Seated_Cable_Shoulder_Press/1.jpg'], 'free-exercise-db'),
  ('seated-calf-raise', 'Seated Calf Raise', 'Calves', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['calves'], null, array['Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.', 'Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.', 'Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.', 'Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.', 'Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Calf_Raise/0.jpg', 'Seated_Calf_Raise/1.jpg'], 'free-exercise-db'),
  ('seated-calf-stretch', 'Seated Calf Stretch', 'Calves', false, 'stretching', null, 'beginner', null, 'static', array['calves'], array['hamstrings', 'lower back'], array['Sit up straight on an exercise mat.', 'Bend one knee and put that foot on the floor to stabilize the torso.', 'Straighten your other leg and flex your ankle.', 'Using a band, towel, or your hand if you can reach, pull the toes toward you. Hold for 10 to 20 seconds, then switch sides.'], array['Seated_Calf_Stretch/0.jpg', 'Seated_Calf_Stretch/1.jpg'], 'free-exercise-db'),
  ('seated-close-grip-concentration-barbell-curl', 'Seated Close-Grip Concentration Barbell Curl', 'Arms', false, 'strength', 'barbell', 'intermediate', 'isolation', 'pull', array['biceps'], null, array['Sit down on a flat bench with a barbell or E-Z Bar in front of you in between your legs. Your legs should be spread with the knees bent and the feet on the floor.', 'Use your arms to pick the barbell up and place the back of your upper arms on top of your inner thighs (around three and a half inches away from the front of the knee). A supinated grip closer than shoulder width is needed to perform this exercise. Tip: Your arm should be extended at arms length and the barbell should be above the floor. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the barbell back to starting position as your breathe in. Tip: Avoid swinging motions at any time.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Close-Grip_Concentration_Barbell_Curl/0.jpg', 'Seated_Close-Grip_Concentration_Barbell_Curl/1.jpg'], 'free-exercise-db'),
  ('seated-dumbbell-curl', 'Seated Dumbbell Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'Rotate the palms of the hands so that they are facing your torso. This will be your starting position.', 'While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only the forearms move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Dumbbell_Curl/0.jpg', 'Seated_Dumbbell_Curl/1.jpg'], 'free-exercise-db'),
  ('seated-dumbbell-inner-biceps-curl', 'Seated Dumbbell Inner Biceps Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Sit on the end of a flat bench with a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.', 'While holding the upper arms stationary, curl the dumbbells out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids. Tips:', 'Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to the starting position as your breathe in. Remember to rotate your arms as you lower the dumbbells so that you can switch back to a neutral grip.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Dumbbell_Inner_Biceps_Curl/0.jpg', 'Seated_Dumbbell_Inner_Biceps_Curl/1.jpg'], 'free-exercise-db'),
  ('seated-dumbbell-palms-down-wrist-curl', 'Seated Dumbbell Palms-Down Wrist Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Start out by placing two dumbbells on the floor in front of a flat bench.', 'Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.', 'Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.', 'When finished, simply lower the dumbbells to the floor.'], array['Seated_Dumbbell_Palms-Down_Wrist_Curl/0.jpg', 'Seated_Dumbbell_Palms-Down_Wrist_Curl/1.jpg'], 'free-exercise-db'),
  ('seated-dumbbell-palms-up-wrist-curl', 'Seated Dumbbell Palms-Up Wrist Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Start out by placing two dumbbells on the floor in front of a flat bench.', 'Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.', 'Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.', 'When finished, simply lower the dumbbells to the floor.'], array['Seated_Dumbbell_Palms-Up_Wrist_Curl/0.jpg', 'Seated_Dumbbell_Palms-Up_Wrist_Curl/1.jpg'], 'free-exercise-db'),
  ('seated-dumbbell-press', 'Seated Dumbbell Press', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.', 'Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side.', 'Rotate the wrists so that the palms of your hands are facing forward. This is your starting position.', 'As you exhale, push the dumbbells up until they touch at the top.', 'After a second pause, slowly come down back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Dumbbell_Press/0.jpg', 'Seated_Dumbbell_Press/1.jpg'], 'free-exercise-db'),
  ('seated-flat-bench-leg-pull-in', 'Seated Flat Bench Leg Pull-In', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.', 'Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.', 'After a second pause, go back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Flat_Bench_Leg_Pull-In/0.jpg', 'Seated_Flat_Bench_Leg_Pull-In/1.jpg'], 'free-exercise-db'),
  ('seated-floor-hamstring-stretch', 'Seated Floor Hamstring Stretch', 'Hamstrings', false, 'stretching', null, 'beginner', null, 'static', array['hamstrings'], array['calves'], array['Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh.', 'Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side.'], array['Seated_Floor_Hamstring_Stretch/0.jpg', 'Seated_Floor_Hamstring_Stretch/1.jpg'], 'free-exercise-db'),
  ('seated-front-deltoid', 'Seated Front Deltoid', 'Shoulders', false, 'stretching', 'body only', 'expert', null, 'static', array['shoulders'], array['chest'], array['Sit upright on the floor with your legs bent, your partner standing behind you. Stick your arms straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your wrists. This will be your starting position.', 'Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds.', 'Now, relax your muscles and allow your partner to gently increase the stretch on the shoulders and chest. Hold for 10 to 20 seconds.'], array['Seated_Front_Deltoid/0.jpg', 'Seated_Front_Deltoid/1.jpg'], 'free-exercise-db'),
  ('seated-glute', 'Seated Glute', 'Glutes', false, 'stretching', 'body only', 'expert', null, 'static', array['glutes'], array['adductors'], array['In a seated position with your knees bent, cross one ankle over the opposite knee. Your partner will stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.', 'Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.', 'Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.'], array['Seated_Glute/0.jpg', 'Seated_Glute/1.jpg'], 'free-exercise-db'),
  ('seated-good-mornings', 'Seated Good Mornings', 'Lower back', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'pull', array['lower back'], array['glutes'], array['Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders.', 'Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. This will be your starting position.', 'Keeping the bar tight, bend forward at the hips as much as possible. If you set the pins to what would be parallel, you not only have a safety if you fail, but know when to stop.', 'Pause just above the pins and reverse the motion until your torso it upright.'], array['Seated_Good_Mornings/0.jpg', 'Seated_Good_Mornings/1.jpg'], 'free-exercise-db'),
  ('seated-hamstring', 'Seated Hamstring', 'Hamstrings', false, 'stretching', null, 'expert', null, 'static', array['hamstrings'], array['calves'], array['In a seated position with your legs extended, have your partner stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.', 'Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.', 'Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.'], array['Seated_Hamstring/0.jpg', 'Seated_Hamstring/1.jpg'], 'free-exercise-db'),
  ('seated-hamstring-and-calf-stretch', 'Seated Hamstring and Calf Stretch', 'Hamstrings', false, 'stretching', 'other', 'intermediate', null, 'static', array['hamstrings'], array['calves'], array['Loop a belt, rope, or band around one foot. Sit down with both legs extended . This will be your starting position.', 'Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then repeat with the other leg.'], array['Seated_Hamstring_and_Calf_Stretch/0.jpg', 'Seated_Hamstring_and_Calf_Stretch/1.jpg'], 'free-exercise-db'),
  ('seated-head-harness-neck-resistance', 'Seated Head Harness Neck Resistance', 'Neck', false, 'strength', 'other', 'intermediate', 'isolation', 'pull', array['neck'], null, array['Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out.', 'Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on the floor to prevent any strain on the neck. Now grab the weight with both hands while elevating your torso back until it is almost perpendicular to the floor. Note: Your head and torso needs to be slightly tilted forward to perform this exercise.', 'Now place both hands on top of your knees. This is the starting position.', 'Slowly lower your neck down until your chin touches the upper part of your chest while breathing in.', 'While exhaling, bring your neck back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Head_Harness_Neck_Resistance/0.jpg', 'Seated_Head_Harness_Neck_Resistance/1.jpg'], 'free-exercise-db'),
  ('seated-leg-curl', 'Seated Leg Curl', 'Hamstrings', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['hamstrings'], null, array['Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.', 'Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.', 'As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Leg_Curl/0.jpg', 'Seated_Leg_Curl/1.jpg'], 'free-exercise-db'),
  ('seated-leg-tucks', 'Seated Leg Tucks', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.', 'Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.', 'After a second pause, go back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Leg_Tucks/0.jpg', 'Seated_Leg_Tucks/1.jpg'], 'free-exercise-db'),
  ('seated-one-arm-cable-pulley-rows', 'Seated One-arm Cable Pulley Rows', 'Back', false, 'strength', 'cable', 'intermediate', 'compound', 'pull', array['middle back'], array['biceps', 'lats', 'traps'], array['To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.', 'With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it as you rotate the wrist, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torso). Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard.', 'Hold that contraction for a second and slowly go back to the original position while breathing in. Tip: Remember to rotate the wrist as you go back to the starting position so that the palms are facing down again.', 'Repeat for the recommended amount of repetitions and then perform the same movement with the right hand.'], array['Seated_One-arm_Cable_Pulley_Rows/0.jpg', 'Seated_One-arm_Cable_Pulley_Rows/1.jpg'], 'free-exercise-db'),
  ('seated-one-arm-dumbbell-palms-down-wrist-curl', 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['forearms'], null, array['Sit on a flat bench with a dumbbell in your right hand.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.', 'Lean forward and place your right forearm on top of your upper right thigh with your palm down. Tip: Make sure that the back of the wrist lies on top of your knees. This will be your starting position.', 'Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.', 'Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.', 'Perform for the recommended amount of repetitions, switch arms and repeat the movement.'], array['Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/0.jpg', 'Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/1.jpg'], 'free-exercise-db'),
  ('seated-one-arm-dumbbell-palms-up-wrist-curl', 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Sit on a flat bench with a dumbbell in your right hand.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.', 'Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position.', 'Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.', 'Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.', 'Perform for the recommended amount of repetitions, switch arms and repeat the movement.'], array['Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/0.jpg', 'Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/1.jpg'], 'free-exercise-db'),
  ('seated-overhead-stretch', 'Seated Overhead Stretch', 'Core', false, 'stretching', null, 'beginner', 'isolation', 'static', array['abdominals'], null, array['Sit up straight on an exercise mat.', 'Touch the soles of your feet together with your feet six to eight inches in front of your hips.', 'Place one hand on the floor beside you and your other hand behind your head.', 'Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides.'], array['Seated_Overhead_Stretch/0.jpg', 'Seated_Overhead_Stretch/1.jpg'], 'free-exercise-db'),
  ('seated-palm-up-barbell-wrist-curl', 'Seated Palm-Up Barbell Wrist Curl', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.', 'Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position.', 'Lower the bar as far as possible while inhaling and keeping a tight grip.', 'Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move.'], array['Seated_Palm-Up_Barbell_Wrist_Curl/0.jpg', 'Seated_Palm-Up_Barbell_Wrist_Curl/1.jpg'], 'free-exercise-db'),
  ('seated-palms-down-barbell-wrist-curl', 'Seated Palms-Down Barbell Wrist Curl', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.', 'Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position.', 'Lower the bar as far as possible while inhaling and keeping a tight grip.', 'Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move.'], array['Seated_Palms-Down_Barbell_Wrist_Curl/0.jpg', 'Seated_Palms-Down_Barbell_Wrist_Curl/1.jpg'], 'free-exercise-db'),
  ('seated-row', 'Seated Row', 'Back', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats', 'shoulders'], array['For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Cable_Rows/0.jpg', 'Seated_Cable_Rows/1.jpg'], 'repple+free-exercise-db'),
  ('seated-side-lateral-raise', 'Seated Side Lateral Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], null, array['Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms'' length. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Side_Lateral_Raise/0.jpg', 'Seated_Side_Lateral_Raise/1.jpg'], 'free-exercise-db'),
  ('seated-triceps-press', 'Seated Triceps Press', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['triceps'], null, array['Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.', 'Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Triceps_Press/0.jpg', 'Seated_Triceps_Press/1.jpg'], 'free-exercise-db'),
  ('seated-two-arm-palms-up-low-pulley-wrist-curl', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.', 'Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up.', 'Now hold the handle with both hands, palms up, using a shoulder-width grip.', 'Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor.', 'Lean forward and place the forearms on your thighs with the back of your wrists over your knees. This will be your starting position.', 'Lower the bar as far as possible, while inhaling and keeping a tight grip.', 'Now curl the bar up as high as possible while contracting the forearms. Tip: Only the wrist should move; not the forearms.', 'After a second contraction at the top go back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/0.jpg', 'Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/1.jpg'], 'free-exercise-db'),
  ('see-saw-press-alternating-side-press', 'See-Saw Press (Alternating Side Press)', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['shoulders'], array['abdominals', 'triceps'], array['Grab a dumbbell with each hand and stand up erect.', 'Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position.', 'Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from your hip to your opposite side. Tip: If you perform the exercise correctly, is should look as if you are trying to reach for something overhead on the right hand side of your body, but with your left arm. Breathe out as you perform this movement.', 'Once you reach the top position breathe in. Then, with the weight fully extended overhead and you bent over to your right hand side, begin the movement to the left side.', 'Repeat for the recommended amount of repetitions.'], array['See-Saw_Press_Alternating_Side_Press/0.jpg', 'See-Saw_Press_Alternating_Side_Press/1.jpg'], 'free-exercise-db'),
  ('shotgun-row', 'Shotgun Row', 'Back', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back'], array['Attach a single handle to a low cable.', 'After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.', 'Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.', 'After a brief pause, return to the starting position.'], array['Shotgun_Row/0.jpg', 'Shotgun_Row/1.jpg'], 'free-exercise-db'),
  ('shoulder-circles', 'Shoulder Circles', 'Shoulders', false, 'stretching', null, 'beginner', null, 'pull', array['shoulders'], array['traps'], array['With shoulders relaxed and arms resting loosely at your sides (or in your lap if you''re seated), gently roll your shoulders forward, up, back, and down.', 'Reverse direction. You can do this exercise alternating shoulders or both at the same time.'], array['Shoulder_Circles/0.jpg', 'Shoulder_Circles/1.jpg'], 'free-exercise-db'),
  ('shoulder-press', 'Shoulder Press', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.', 'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.', 'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.', 'Now, exhale and push the dumbbells upward until they touch at the top.', 'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.'], array['Dumbbell_Shoulder_Press/0.jpg', 'Dumbbell_Shoulder_Press/1.jpg'], 'repple+free-exercise-db'),
  ('shoulder-press-with-bands', 'Shoulder Press - With Bands', 'Shoulders', false, 'strength', 'bands', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles and lift them so that the hands are at shoulder height at each side.', 'Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position.', 'As you exhale, lift the handles up until your arms are fully extended overhead.'], array['Shoulder_Press_-_With_Bands/0.jpg', 'Shoulder_Press_-_With_Bands/1.jpg'], 'free-exercise-db'),
  ('shoulder-raise', 'Shoulder Raise', 'Shoulders', false, 'stretching', null, 'beginner', null, 'pull', array['shoulders'], array['lats'], array['Relax your arms to your sides and raise your shoulders up toward your ears, then back down.'], array['Shoulder_Raise/0.jpg', 'Shoulder_Raise/1.jpg'], 'free-exercise-db'),
  ('shoulder-stretch', 'Shoulder Stretch', 'Shoulders', false, 'stretching', null, 'beginner', null, 'pull', array['shoulders'], null, array['Reach your left arm across your body and hold it straight.'], array['Shoulder_Stretch/0.jpg', 'Shoulder_Stretch/1.jpg'], 'free-exercise-db'),
  ('side-bridge', 'Side Bridge', 'Core', false, 'strength', 'body only', 'beginner', null, 'static', array['abdominals'], array['shoulders'], null, array['Side_Bridge/0.jpg', 'Side_Bridge/1.jpg'], 'free-exercise-db'),
  ('side-hop-sprint', 'Side Hop-Sprint', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'hamstrings'], array['Stand to the side of a cone or hurdle.', 'Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started.', 'Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop.'], array['Side_Hop-Sprint/0.jpg', 'Side_Hop-Sprint/1.jpg'], 'free-exercise-db'),
  ('side-jackknife', 'Side Jackknife', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, null, array['Side_Jackknife/0.jpg', 'Side_Jackknife/1.jpg'], 'free-exercise-db'),
  ('side-lateral-raise', 'Side Lateral Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], null, array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.', 'While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Side_Lateral_Raise/0.jpg', 'Side_Lateral_Raise/1.jpg'], 'free-exercise-db'),
  ('side-laterals-to-front-raise', 'Side Laterals to Front Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['shoulders'], array['traps'], array['In a standing position, hold a pair of dumbbells at your side. This will be your starting position.', 'Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.', 'At the top of the exercise move the weights out in front of you, keeping your arms extended.', 'Lower the weights with a controlled motion.', 'On the next repetition, raise the weights in front of you to shoulder height before moving the weights laterally to your sides.', 'Lower the weights to the starting position.'], array['Side_Laterals_to_Front_Raise/0.jpg', 'Side_Laterals_to_Front_Raise/1.jpg'], 'free-exercise-db'),
  ('side-leg-raises', 'Side Leg Raises', 'Legs', false, 'stretching', 'body only', 'beginner', null, 'pull', array['adductors'], null, array['Stand next to a chair, which you may hold onto as a support. Stand on one leg. This will be your starting position.', 'Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg.', 'Repeat this swinging motion 5-10 times, increasing the range of motion as you do so.'], array['Side_Leg_Raises/0.jpg', 'Side_Leg_Raises/1.jpg'], 'free-exercise-db'),
  ('side-lying-floor-stretch', 'Side-Lying Floor Stretch', 'Back', false, 'stretching', null, 'beginner', null, 'static', array['lats'], null, array['First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright).', 'Straighten your right leg and rest the right foot on the floor behind your left. Straighten your right arm over your head and gently pull on your right wrist to stretch the entire right side of the body. Switch sides.'], array['Side-Lying_Floor_Stretch/0.jpg', 'Side-Lying_Floor_Stretch/1.jpg'], 'free-exercise-db'),
  ('side-lying-groin-stretch', 'Side Lying Groin Stretch', 'Legs', false, 'stretching', null, 'beginner', 'isolation', 'static', array['adductors'], array['hamstrings'], array['Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.', 'Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder).', 'Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides.'], array['Side_Lying_Groin_Stretch/0.jpg', 'Side_Lying_Groin_Stretch/1.jpg'], 'free-exercise-db'),
  ('side-neck-stretch', 'Side Neck Stretch', 'Neck', false, 'stretching', null, 'beginner', 'isolation', 'static', array['neck'], null, array['Start with your shoulders relaxed, gently tilt your head towards your shoulder.', 'Assist stretch with a gentle pull on the side of the head.'], array['Side_Neck_Stretch/0.jpg', 'Side_Neck_Stretch/1.jpg'], 'free-exercise-db'),
  ('side-standing-long-jump', 'Side Standing Long Jump', 'Legs', false, 'plyometrics', null, 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position.', 'Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can.', 'Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body.'], array['Side_Standing_Long_Jump/0.jpg', 'Side_Standing_Long_Jump/1.jpg'], 'free-exercise-db'),
  ('side-to-side-box-shuffle', 'Side to Side Box Shuffle', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'hamstrings'], array['Stand to one side of the box with your left foot resting on the middle of it.', 'To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.', 'Continue shuffling back and forth across the box.'], array['Side_to_Side_Box_Shuffle/0.jpg', 'Side_to_Side_Box_Shuffle/1.jpg'], 'free-exercise-db'),
  ('side-to-side-chins', 'Side To Side Chins', 'Back', false, 'strength', 'other', 'intermediate', 'compound', 'pull', array['lats'], array['biceps', 'forearms', 'middle back', 'shoulders'], array['Grab the pull-up bar with the palms facing forward using a wide grip.', 'As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space (no swinging) and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of contraction, inhale as you go back to the starting position.', 'Now, pull your torso up while leaning to the right hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of contraction, inhale as you go back to the starting position.', 'Repeat steps 3-6 until you have performed the prescribed amount of repetitions for each side.'], array['Side_To_Side_Chins/0.jpg', 'Side_To_Side_Chins/1.jpg'], 'free-exercise-db'),
  ('side-wrist-pull', 'Side Wrist Pull', 'Shoulders', false, 'stretching', null, 'beginner', 'isolation', 'static', array['shoulders'], array['forearms', 'lats'], array['This stretch works best standing. Cross your left arm over the midline of your body and hold the left wrist in your right hand down at the level of your hips. Start the stretch with a bent left arm.', 'Slowly straighten, pull, and lift it up to shoulder height, as pictured. Feel this stretch originate in your back, not your shoulders, and don''t pull too hard on the shoulders joint. Switch sides.'], array['Side_Wrist_Pull/0.jpg', 'Side_Wrist_Pull/1.jpg'], 'free-exercise-db'),
  ('single-arm-cable-crossover', 'Single-Arm Cable Crossover', 'Chest', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['chest'], null, array['Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.', 'Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position.', 'Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.', 'Return your arm back to the starting position by pulling your hand back to the midline of the body.', 'Hold for a second at the starting position and repeat the movement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions.'], array['Single-Arm_Cable_Crossover/0.jpg', 'Single-Arm_Cable_Crossover/1.jpg'], 'free-exercise-db'),
  ('single-arm-linear-jammer', 'Single-Arm Linear Jammer', 'Shoulders', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['shoulders'], array['chest', 'triceps'], array['Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.', 'Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position.', 'Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force.', 'Return to the starting position.'], array['Single-Arm_Linear_Jammer/0.jpg', 'Single-Arm_Linear_Jammer/1.jpg'], 'free-exercise-db'),
  ('single-arm-push-up', 'Single-Arm Push-Up', 'Chest', false, 'strength', 'body only', 'intermediate', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up.', 'Maintain good posture, and place your free hand behind your back. This will be your starting position.', 'Lower yourself by allowing the elbow to flex until you touch the ground.', 'Descend slowly, and reverse direction be extending the arm to return to the starting position.'], array['Single-Arm_Push-Up/0.jpg', 'Single-Arm_Push-Up/1.jpg'], 'free-exercise-db'),
  ('single-cone-sprint-drill', 'Single-Cone Sprint Drill', 'Legs', false, 'plyometrics', 'other', 'beginner', null, 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward.', 'Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action.', 'Rest after three trips around the cone.'], array['Single-Cone_Sprint_Drill/0.jpg', 'Single-Cone_Sprint_Drill/1.jpg'], 'free-exercise-db'),
  ('single-dumbbell-raise', 'Single Dumbbell Raise', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'isolation', null, array['shoulders'], array['forearms', 'traps'], array['With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle. Your arms should be extended and hanging at the waist. This will be your starting position.', 'Raise the weight until it is above shoulder level, keeping your arms extended. Your torso and hips should remain stationary throughout the movement.', 'Return to the starting position and repeat for the recommended amount of repetitions.'], array['Single_Dumbbell_Raise/0.jpg', 'Single_Dumbbell_Raise/1.jpg'], 'free-exercise-db'),
  ('single-leg-butt-kick', 'Single Leg Butt Kick', 'Legs', false, 'plyometrics', 'body only', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'hamstrings'], array['Begin by standing on one leg, with the bent knee raised. This will be your start position.', 'Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg.', 'Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg.', 'Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill.'], array['Single_Leg_Butt_Kick/0.jpg', 'Single_Leg_Butt_Kick/1.jpg'], 'free-exercise-db'),
  ('single-leg-glute-bridge', 'Single Leg Glute Bridge', 'Glutes', false, 'strength', 'body only', 'beginner', 'isolation', 'push', array['glutes'], array['hamstrings'], array['Lay on the floor with your feet flat and knees bent.', 'Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.', 'Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.', 'Extend as far as possible, pause and then return to the starting position.'], array['Single_Leg_Glute_Bridge/0.jpg', 'Single_Leg_Glute_Bridge/1.jpg'], 'free-exercise-db'),
  ('single-leg-high-box-squat', 'Single-Leg High Box Squat', 'Legs', false, 'strength', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['glutes', 'hamstrings'], array['Position a box in a rack. Secure a band or rope in place above the box.', 'Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance', '. Continue stepping up and down on the same leg before switching to the opposite side.'], array['Single-Leg_High_Box_Squat/0.jpg', 'Single-Leg_High_Box_Squat/1.jpg'], 'free-exercise-db'),
  ('single-leg-hop-progression', 'Single-Leg Hop Progression', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'hamstrings'], array['Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position.', 'Hop forward, jumping and landing with the same leg over the cone.', 'Use a countermovement jump to hop from cone to cone.', 'At the end, turn around and go back on the other leg.'], array['Single-Leg_Hop_Progression/0.jpg', 'Single-Leg_Hop_Progression/1.jpg'], 'free-exercise-db'),
  ('single-leg-lateral-hop', 'Single-Leg Lateral Hop', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'hamstrings'], array['Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent.', 'To begin, execute a counterjump to hop sideways over the cone.', 'Land on your jumping leg, and immediately rebound out of it by jumping back to the start position.', 'Continue hopping back and forth.'], array['Single-Leg_Lateral_Hop/0.jpg', 'Single-Leg_Lateral_Hop/1.jpg'], 'free-exercise-db'),
  ('single-leg-leg-extension', 'Single-Leg Leg Extension', 'Legs', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['quadriceps'], null, array['Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities.', 'Maintaining good posture, fully extend one leg, pausing at the top of the motion.', 'Return to the starting position without letting the weight stop, keeping tension on the muscle.', 'Repeat for the desired number of repetitions.'], array['Single-Leg_Leg_Extension/0.jpg', 'Single-Leg_Leg_Extension/1.jpg'], 'free-exercise-db'),
  ('single-leg-push-off', 'Single Leg Push-off', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'hamstrings'], array['Stand on the ground with one foot resting on the box, heel close to the edge.', 'Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee.', 'Land with the same foot on top of the box, returning your other foot back to the start position.'], array['Single_Leg_Push-off/0.jpg', 'Single_Leg_Push-off/1.jpg'], 'free-exercise-db'),
  ('single-leg-stride-jump', 'Single-Leg Stride Jump', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'hamstrings'], array['Stand to the side of a box with your inside foot on top of it, close to the edge.', 'Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.', 'Land in the same position that you started, using your inside leg to decelerate the impact.'], array['Single-Leg_Stride_Jump/0.jpg', 'Single-Leg_Stride_Jump/1.jpg'], 'free-exercise-db'),
  ('sit-squats', 'Sit Squats', 'Legs', false, 'stretching', null, 'beginner', null, 'push', array['quadriceps'], array['abductors', 'glutes', 'hamstrings'], array['Stand with your feet shoulder width apart. This will be your starting position.', 'Begin the movement by flexing your knees and hips, sitting back with your hips.', 'Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position. Repeat for 5-10 repetitions.'], array['Sit_Squats/0.jpg', 'Sit_Squats/1.jpg'], 'free-exercise-db'),
  ('sit-up', 'Sit-Up', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.', 'Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.', 'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.', 'Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.'], array['Sit-Up/0.jpg', 'Sit-Up/1.jpg'], 'free-exercise-db'),
  ('skating', 'Skating', 'Legs', true, 'cardio', 'other', 'intermediate', null, null, array['quadriceps'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings'], array['Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance. It requires relatively good balance and coordination. It is necessary to learn the basics of skating including turning and stopping and to wear protective gear to avoid possible injury.', 'You can skate at a comfortable pace for 30 minutes straight. If you want a cardio challenge, do interval skating — speed skate two minutes of every five minutes, using the remaining three minutes to recover. A 150 lb person will typically burn about 175 calories in 30 minutes skating at a comfortable pace, similar to brisk walking.'], array['Skating/0.jpg', 'Skating/1.jpg'], 'free-exercise-db'),
  ('ski-erg', 'Ski Erg', 'Full body', true, null, null, null, null, null, null, null, null, null, 'repple'),
  ('sled-drag-harness', 'Sled Drag - Harness', 'Legs', false, 'strongman', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, load the sled with the desired weight and attach the pulling strap. You can pull with handles, use a harness, or attach the pulling strap to a weight belt.', 'Whether pulling forwards or backwards, lean in the direction of travel and progress by extending through the hips and knees.'], array['Sled_Drag_-_Harness/0.jpg', 'Sled_Drag_-_Harness/1.jpg'], 'free-exercise-db'),
  ('sled-overhead-backward-walk', 'Sled Overhead Backward Walk', 'Shoulders', false, 'strength', 'other', 'beginner', 'compound', 'pull', array['shoulders'], array['calves', 'middle back', 'quadriceps'], array['Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.', 'Face the sled, backing up until there is some tension in the line. Hold your hands directly above your head with your elbows extended. This will be your starting position.', 'Walk backwards, keeping your arms raised above your head. Avoid jerky movements.'], array['Sled_Overhead_Backward_Walk/0.jpg', 'Sled_Overhead_Backward_Walk/1.jpg'], 'free-exercise-db'),
  ('sled-overhead-triceps-extension', 'Sled Overhead Triceps Extension', 'Arms', false, 'strength', 'other', 'beginner', 'isolation', 'push', array['triceps'], null, array['Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load.', 'Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position.', 'Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps.', 'Upon full extension, step forward to take the slack out of the line. You may keep your feet staggered for more stability.'], array['Sled_Overhead_Triceps_Extension/0.jpg', 'Sled_Overhead_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('sled-push', 'Sled Push', 'Legs', false, 'strongman', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'chest', 'glutes', 'hamstrings', 'triceps'], array['Load your pushing sled with the desired weight.', 'Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain.'], array['Sled_Push/0.jpg', 'Sled_Push/1.jpg'], 'free-exercise-db'),
  ('sled-reverse-flye', 'Sled Reverse Flye', 'Shoulders', false, 'strength', 'other', 'beginner', 'isolation', 'pull', array['shoulders'], null, array['Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.', 'Face the sled, backing up until there is some tension in the line. Take both handles at arms length at about waist level. Bend the knees slightly and keep your chest and head up. This will be your starting position.', 'Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external rotation. Your palms should be facing forward as you do this.', 'Return to the starting position, taking a couple steps back to take the slack out of the line.'], array['Sled_Reverse_Flye/0.jpg', 'Sled_Reverse_Flye/1.jpg'], 'free-exercise-db'),
  ('sled-row', 'Sled Row', 'Back', false, 'strength', 'other', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate weight. Face the sled, backing up until there is some tension in the line.', 'With a handle in each hand, bend the knees slightly, keep your head and chest up, and begin with your arms extended.', 'To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you.', 'Take a step or two back to get tension in the line and repeat.'], array['Sled_Row/0.jpg', 'Sled_Row/1.jpg'], 'free-exercise-db'),
  ('sledgehammer-swings', 'Sledgehammer Swings', 'Core', false, 'plyometrics', 'other', 'beginner', 'compound', 'pull', array['abdominals'], array['calves', 'forearms', 'lats', 'middle back', 'shoulders'], array['You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer.', 'If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head.', 'As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire.', 'Repeat on the other side.'], array['Sledgehammer_Swings/0.jpg', 'Sledgehammer_Swings/1.jpg'], 'free-exercise-db'),
  ('smith-incline-shoulder-raise', 'Smith Incline Shoulder Raise', 'Shoulders', false, 'strength', 'barbell', 'beginner', 'isolation', 'push', array['shoulders'], array['chest'], array['Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your shoulders are aligned right under the barbell.', 'Using a shoulder width pronated (palms forward) grip, lift the bar from the rack and hold it straight over you with a slight bend at the elbows. This will be your starting position.', 'As you breathe out, lift the bar up until your arms are fully extended. Note: The contraction should be felt around the shoulders.', 'After a second pause, bring the bar back down to the starting position as you breathe in.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.'], array['Smith_Incline_Shoulder_Raise/0.jpg', 'Smith_Incline_Shoulder_Raise/1.jpg'], 'free-exercise-db'),
  ('smith-machine', 'Smith Machine', 'Full body', false, null, null, null, null, null, null, null, null, null, 'repple'),
  ('smith-machine-behind-the-back-shrug', 'Smith Machine Behind the Back Shrug', 'Back', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['traps'], array['shoulders'], array['With the bar at thigh level, load an appropriate weight.', 'Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position.', 'Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement.', 'After a brief pause return the weight to the starting position.', 'Repeat for the desired number of repetitions before engaging the hooks to rack the weight.'], array['Smith_Machine_Behind_the_Back_Shrug/0.jpg', 'Smith_Machine_Behind_the_Back_Shrug/1.jpg'], 'free-exercise-db'),
  ('smith-machine-bench-press', 'Smith Machine Bench Press', 'Chest', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, lock the bar back in the rack.'], array['Smith_Machine_Bench_Press/0.jpg', 'Smith_Machine_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('smith-machine-bent-over-row', 'Smith Machine Bent Over Row', 'Back', false, 'strength', 'machine', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats', 'shoulders'], array['Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up.', 'Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Smith_Machine_Bent_Over_Row/0.jpg', 'Smith_Machine_Bent_Over_Row/1.jpg'], 'free-exercise-db'),
  ('smith-machine-calf-raise', 'Smith Machine Calf Raise', 'Calves', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['calves'], null, array['Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.', 'Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.', 'Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down.', 'Return slowly to the starting position as you breathe in while lowering your heels.', 'Repeat for the recommended amount of repetitions.'], array['Smith_Machine_Calf_Raise/0.jpg', 'Smith_Machine_Calf_Raise/1.jpg'], 'free-exercise-db'),
  ('smith-machine-close-grip-bench-press', 'Smith Machine Close-Grip Bench Press', 'Arms', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, lock the bar back in the rack.'], array['Smith_Machine_Close-Grip_Bench_Press/0.jpg', 'Smith_Machine_Close-Grip_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('smith-machine-decline-press', 'Smith Machine Decline Press', 'Chest', false, 'strength', 'machine', 'beginner', 'compound', null, array['chest'], array['shoulders', 'triceps'], array['Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench.', 'Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position.', 'Begin the movement by flexing your arms, lowering the bar to your chest.', 'Pause briefly, and then extend your arms to push the weight back to the starting position.', 'After completing the desired number of repetitions, rotate the bar to rack the weight.'], array['Smith_Machine_Decline_Press/0.jpg', 'Smith_Machine_Decline_Press/1.jpg'], 'free-exercise-db'),
  ('smith-machine-hang-power-clean', 'Smith Machine Hang Power Clean', 'Hamstrings', false, 'strength', 'machine', 'intermediate', 'compound', 'pull', array['hamstrings'], array['glutes', 'lower back', 'quadriceps', 'shoulders', 'traps'], array['Position the bar at knee height and load it to an appropriate weight.', 'Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position.', 'Initate the movement by forcefully extending the hips and knees, accelerating into the bar. Ensure that you keep your arms straight during this part of the motion.', 'Upon full extension, rebend the hips and knees to lower your receiving position.', 'Allow the arms to flex at this point, rotating the elbows around the bar to receive it on your shoulders.', 'Extend through the hips and knees to come to a standing position with the bar racked on your shoulders to complete the movement.'], array['Smith_Machine_Hang_Power_Clean/0.jpg', 'Smith_Machine_Hang_Power_Clean/1.jpg'], 'free-exercise-db'),
  ('smith-machine-hip-raise', 'Smith Machine Hip Raise', 'Core', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position.', 'Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench. Maintain a slight bend in the knees throughout the motion.', 'After a brief pause, return the hips to the bench.', 'Repeat for the desired number of repetitions.'], array['Smith_Machine_Hip_Raise/0.jpg', 'Smith_Machine_Hip_Raise/1.jpg'], 'free-exercise-db'),
  ('smith-machine-incline-bench-press', 'Smith Machine Incline Bench Press', 'Chest', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your upper chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.'], array['Smith_Machine_Incline_Bench_Press/0.jpg', 'Smith_Machine_Incline_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('smith-machine-leg-press', 'Smith Machine Leg Press', 'Legs', false, 'strength', 'machine', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position.', 'Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your knees.', 'At the top of the motion, pause briefly before returning to the starting position.'], array['Smith_Machine_Leg_Press/0.jpg', 'Smith_Machine_Leg_Press/1.jpg'], 'free-exercise-db'),
  ('smith-machine-one-arm-upright-row', 'Smith Machine One-Arm Upright Row', 'Shoulders', false, 'strength', 'machine', 'beginner', 'compound', 'pull', array['shoulders'], array['biceps', 'traps'], array['With the bar at thigh level, load an appropriate weight.', 'Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position.', 'Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor.', 'After a brief pause, return the weight to the starting position.', 'Repeat for the desired number of repetitions before engaging the hooks to rack the weight.'], array['Smith_Machine_One-Arm_Upright_Row/0.jpg', 'Smith_Machine_One-Arm_Upright_Row/1.jpg'], 'free-exercise-db'),
  ('smith-machine-overhead-shoulder-press', 'Smith Machine Overhead Shoulder Press', 'Shoulders', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.', 'Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your arms are fully extended. This is the starting position.', 'Slowly begin to lower the barbell until it is level with your chin while inhaling.', 'Then lift the barbell back to the starting position using your shoulders while exhaling.', 'Repeat for the recommended amount of repetitions.'], array['Smith_Machine_Overhead_Shoulder_Press/0.jpg', 'Smith_Machine_Overhead_Shoulder_Press/1.jpg'], 'free-exercise-db'),
  ('smith-machine-pistol-squat', 'Smith Machine Pistol Squat', 'Legs', false, 'strength', 'machine', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders.', 'Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3', 'Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.', 'Maintaining good posture, lower yourself by flexing the knee and hip, going down as far as flexibility allows.', 'Pause briefly at the bottom and then return to the starting position by driving through the heel of your foot, extending the knee and hip.'], array['Smith_Machine_Pistol_Squat/0.jpg', 'Smith_Machine_Pistol_Squat/1.jpg'], 'free-exercise-db'),
  ('smith-machine-reverse-calf-raises', 'Smith Machine Reverse Calf Raises', 'Calves', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['calves'], null, array['Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar.', 'Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance.', 'Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: The barbell on your back is only for balance purposes.', 'Raise the balls of your feet as you breathe out by extending your toes as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position for a second before you start to go back down.', 'Slowly go back down to the starting position as you breathe in by lowering the balls of your feet and toes.', 'Repeat for the recommended amount of repetitions.'], array['Smith_Machine_Reverse_Calf_Raises/0.jpg', 'Smith_Machine_Reverse_Calf_Raises/1.jpg'], 'free-exercise-db'),
  ('smith-machine-squat', 'Smith Machine Squat', 'Legs', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Smith_Machine_Squat/0.jpg', 'Smith_Machine_Squat/1.jpg'], 'free-exercise-db'),
  ('smith-machine-stiff-legged-deadlift', 'Smith Machine Stiff-Legged Deadlift', 'Hamstrings', false, 'strength', 'machine', 'beginner', 'compound', 'pull', array['hamstrings'], array['glutes', 'lower back'], array['To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.', 'Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement', 'Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.'], array['Smith_Machine_Stiff-Legged_Deadlift/0.jpg', 'Smith_Machine_Stiff-Legged_Deadlift/1.jpg'], 'free-exercise-db'),
  ('smith-machine-upright-row', 'Smith Machine Upright Row', 'Back', false, 'strength', 'machine', 'beginner', 'compound', 'pull', array['traps'], array['biceps', 'middle back', 'shoulders'], array['To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.', 'Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position.', 'Use your side shoulders to lift the bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.'], array['Smith_Machine_Upright_Row/0.jpg', 'Smith_Machine_Upright_Row/1.jpg'], 'free-exercise-db'),
  ('smith-single-leg-split-squat', 'Smith Single-Leg Split Squat', 'Legs', false, 'strength', 'machine', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Position your legs by placing one foot slightly forward under the bar and extending your other leg back and place the top of your foot on the bench. This will be your starting position', 'Begin to slowly lower the bar by bending the knee as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calf becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knee should make an imaginary straight line with the toes that is perpendicular to the front. If your knee is past that imaginary line (if it is past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten your leg again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.', 'Switch legs and repeat the movement.'], array['Smith_Single-Leg_Split_Squat/0.jpg', 'Smith_Single-Leg_Split_Squat/1.jpg'], 'free-exercise-db'),
  ('snatch', 'Snatch', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['quadriceps'], array['biceps', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps', 'triceps'], array['Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.', 'With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.', 'Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.', 'As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.', 'Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.', 'Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.', 'Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead.'], array['Snatch/0.jpg', 'Snatch/1.jpg'], 'free-exercise-db'),
  ('snatch-balance', 'Snatch Balance', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'shoulders', 'triceps'], array['Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.', 'Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position.', 'Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs.', 'Continue to descend to full depth, and return to a standing position. Carefully lower the weight.'], array['Snatch_Balance/0.jpg', 'Snatch_Balance/1.jpg'], 'free-exercise-db'),
  ('snatch-deadlift', 'Snatch Deadlift', 'Hamstrings', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['forearms', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps'], array['The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward.', 'Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees.', 'At that point, drive your hips through the bar as you lay back. Return the bar to the platform by reversing the motion.'], array['Snatch_Deadlift/0.jpg', 'Snatch_Deadlift/1.jpg'], 'free-exercise-db'),
  ('snatch-from-blocks', 'Snatch from Blocks', 'Legs', false, 'olympic weightlifting', 'barbell', 'expert', 'compound', 'pull', array['quadriceps'], array['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps', 'triceps'], array['Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the boxes.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes.'], array['Snatch_from_Blocks/0.jpg', 'Snatch_from_Blocks/1.jpg'], 'free-exercise-db'),
  ('snatch-pull', 'Snatch Pull', 'Hamstrings', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['calves', 'glutes', 'lower back', 'quadriceps', 'traps'], array['With a barbell on the floor close to the shins, take a wide snatch grip. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the pull. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward.', 'There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.'], array['Snatch_Pull/0.jpg', 'Snatch_Pull/1.jpg'], 'free-exercise-db'),
  ('snatch-shrug', 'Snatch Shrug', 'Back', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['traps'], array['forearms', 'shoulders'], array['Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward.', 'Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down.'], array['Snatch_Shrug/0.jpg', 'Snatch_Shrug/1.jpg'], 'free-exercise-db'),
  ('speed-band-overhead-triceps', 'Speed Band Overhead Triceps', 'Arms', false, 'strength', 'bands', 'beginner', 'isolation', 'push', array['triceps'], null, array['For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.', 'To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.', 'To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.', 'Pause, and then return to the starting position.'], array['Speed_Band_Overhead_Triceps/0.jpg', 'Speed_Band_Overhead_Triceps/1.jpg'], 'free-exercise-db'),
  ('speed-box-squat', 'Speed Box Squat', 'Legs', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension.', 'Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn''t so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max.', 'Position the bar on your upper back, shoulder blades retracted, back arched and everything tight head to toe. This will be the starting position.', 'Unrack the bar and position yourself in front of the box. Sit back with your hips until you are seated on the box, ensuring that you descend under control and don''t crash onto the surface.', 'Pause briefly, and explode off of the box, extending through the hips and knees.'], array['Speed_Box_Squat/0.jpg', 'Speed_Box_Squat/1.jpg'], 'free-exercise-db'),
  ('speed-squats', 'Speed Squats', 'Legs', false, 'strength', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as fast as possible without involving momentum as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position. Note: You should perform these exercises as fast as possible but without breaking perfect form and without involving momentum.', 'Repeat for the recommended amount of repetitions.'], array['Speed_Squats/0.jpg', 'Speed_Squats/1.jpg'], 'free-exercise-db'),
  ('spell-caster', 'Spell Caster', 'Core', false, 'strength', 'dumbbell', 'beginner', 'compound', 'pull', array['abdominals'], array['glutes', 'shoulders'], array['Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position.', 'Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso.', 'Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side.', 'Continue alternating, rotating from one side to the other until the set is complete.'], array['Spell_Caster/0.jpg', 'Spell_Caster/1.jpg'], 'free-exercise-db'),
  ('spider-crawl', 'Spider Crawl', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], array['chest', 'shoulders', 'triceps'], array['Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.', 'Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.', 'Return this leg to the starting position and repeat on the opposite side.'], array['Spider_Crawl/0.jpg', 'Spider_Crawl/1.jpg'], 'free-exercise-db'),
  ('spider-curl', 'Spider Curl', 'Arms', false, 'strength', 'e-z curl bar', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.', 'Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.', 'Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.', 'Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.', 'Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the barbell back to the starting position as your breathe in. .', 'Repeat for the recommended amount of repetitions.'], array['Spider_Curl/0.jpg', 'Spider_Curl/1.jpg'], 'free-exercise-db'),
  ('spinal-stretch', 'Spinal Stretch', 'Back', false, 'stretching', null, 'beginner', 'isolation', 'static', array['middle back'], array['lats', 'lower back', 'neck', 'traps'], array['Sit in a chair so your back is straight and your feet planted on the floor.', 'Interlace your fingers behind your head, elbows out and your chin down.', 'Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.', 'Return to upright position and then repeat for your other side.'], array['Spinal_Stretch/0.jpg', 'Spinal_Stretch/1.jpg'], 'free-exercise-db'),
  ('split-clean', 'Split Clean', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['quadriceps'], array['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps'], array['With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so.', 'Receive the bar with the feet split, aggressively moving one foot forward and one foot back. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Bring the feet together as you stand up.'], array['Split_Clean/0.jpg', 'Split_Clean/1.jpg'], 'free-exercise-db'),
  ('split-jerk', 'Split Jerk', 'Legs', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['glutes', 'hamstrings', 'shoulders', 'triceps'], array['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward.', 'Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.', 'In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should be moved to a split stance, one foot forward, one foot back, with the knees partially bent. Receive the bar with the arms locked out overhead.', 'Return to a standing position, bringing the feet together.'], array['Split_Jerk/0.jpg', 'Split_Jerk/1.jpg'], 'free-exercise-db'),
  ('split-jump', 'Split Jump', 'Legs', false, 'plyometrics', 'body only', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.', 'Ensure that the front knee is over the midline of the foot.', 'Extending through both legs, jump as high as possible, swinging your arms to gain lift.', 'As you jump, bring your feet together, and move them back to their initial positions as you land.', 'Absorb the impact by reverting back to the starting position.'], array['Split_Jump/0.jpg', 'Split_Jump/1.jpg'], 'free-exercise-db'),
  ('split-snatch', 'Split Snatch', 'Hamstrings', false, 'olympic weightlifting', 'barbell', 'expert', 'compound', 'pull', array['hamstrings'], array['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'shoulders', 'traps', 'triceps'], array['Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move forcefully to a split position, one foot forward one foot back. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position, bringing your feet together.', 'Carefully return the weight to floor.'], array['Split_Snatch/0.jpg', 'Split_Snatch/1.jpg'], 'free-exercise-db'),
  ('split-squat-with-dumbbells', 'Split Squat with Dumbbells', 'Legs', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['quadriceps'], array['glutes', 'hamstrings'], array['Position yourself into a staggered stance with the rear foot elevated and front foot forward.', 'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.', 'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.', 'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.'], array['Split_Squat_with_Dumbbells/0.jpg', 'Split_Squat_with_Dumbbells/1.jpg'], 'free-exercise-db'),
  ('split-squats', 'Split Squats', 'Hamstrings', false, 'stretching', null, 'intermediate', null, 'push', array['hamstrings'], array['calves', 'glutes', 'quadriceps'], array['Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so.', 'As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg.'], array['Split_Squats/0.jpg', 'Split_Squats/1.jpg'], 'free-exercise-db'),
  ('squat-jerk', 'Squat Jerk', 'Legs', false, 'strength', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'shoulders', 'triceps'], array['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.', 'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should move forcefully to just outside the hips, turned out as necessary. Receive the bar with your body in a full squat and the arms fully extended overhead.', 'Keeping the bar aligned over the front of the heels, your head and chest up, drive throught heels of the feet to move to a standing position. Carefully return the weight to floor.'], array['Squat_Jerk/0.jpg', 'Squat_Jerk/1.jpg'], 'free-exercise-db'),
  ('squat-with-bands', 'Squat with Bands', 'Legs', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['adductors', 'calves', 'glutes', 'hamstrings', 'lower back'], array['Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.'], array['Squat_with_Bands/0.jpg', 'Squat_with_Bands/1.jpg'], 'free-exercise-db'),
  ('squat-with-chains', 'Squat with Chains', 'Legs', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['adductors', 'calves', 'glutes', 'hamstrings', 'lower back'], array['To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.'], array['Squat_with_Chains/0.jpg', 'Squat_with_Chains/1.jpg'], 'free-exercise-db'),
  ('squat-with-plate-movers', 'Squat with Plate Movers', 'Legs', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings'], array['To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it.', 'Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso.', 'Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up at all times. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees and hips. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees.', 'Raise the bar as you exhale by pushing the floor with the heels of your feet as you extend the hips and knees.', 'At the top of the movement, side step, bringing your feet together on the opposite side of the plate.', 'Using your inside foot, push the weight plate, sliding it across the floor to where you were just standing.', 'Place your inside foot on the weight plate, adopting a wide stance for the next repetition.'], array['Squat_with_Plate_Movers/0.jpg', 'Squat_with_Plate_Movers/1.jpg'], 'free-exercise-db'),
  ('squats-with-bands', 'Squats - With Bands', 'Legs', false, 'strength', 'bands', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other.', 'When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting position.', 'Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling.', 'Use the heel of your feet to push your body up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.'], array['Squats_-_With_Bands/0.jpg', 'Squats_-_With_Bands/1.jpg'], 'free-exercise-db'),
  ('stair-climber', 'Stair Climber', 'Legs', true, null, null, null, null, null, null, null, null, null, 'repple'),
  ('stairmaster', 'Stairmaster', 'Legs', true, 'cardio', 'machine', 'intermediate', null, null, array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise.', 'Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don''t fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.', 'Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.'], array['Stairmaster/0.jpg', 'Stairmaster/1.jpg'], 'free-exercise-db'),
  ('standing-alternating-dumbbell-press', 'Standing Alternating Dumbbell Press', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position.', 'Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement.', 'After a brief pause, return the weight to the starting position.', 'Repeat for the opposite side, continuing to alternate between arms.'], array['Standing_Alternating_Dumbbell_Press/0.jpg', 'Standing_Alternating_Dumbbell_Press/1.jpg'], 'free-exercise-db'),
  ('standing-barbell-calf-raise', 'Standing Barbell Calf Raise', 'Calves', false, 'strength', 'barbell', 'beginner', 'isolation', 'push', array['calves'], null, array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck).', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: For better range of motion you may also place the ball of your feet on a wooden block but be careful as this option requires more balance and a sturdy block.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Barbell_Calf_Raise/0.jpg', 'Standing_Barbell_Calf_Raise/1.jpg'], 'free-exercise-db'),
  ('standing-barbell-press-behind-neck', 'Standing Barbell Press Behind Neck', 'Shoulders', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Your back should be kept straight while performing this exercise. This will be your starting position.', 'Elevate the barbell overhead by fully extending your arms while breathing out.', 'Hold the contraction for a second and lower the barbell back down to the starting position by inhaling.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Barbell_Press_Behind_Neck/0.jpg', 'Standing_Barbell_Press_Behind_Neck/1.jpg'], 'free-exercise-db'),
  ('standing-bent-over-one-arm-dumbbell-triceps-extension', 'Standing Bent-Over One-Arm Dumbbell Triceps Extension', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['triceps'], array['shoulders'], array['With a dumbbell in one hand and the palm facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.', 'The upper arm should be close to the torso and parallel to the floor while the forearm is pointing towards the floor as the hand holds the weight. Tip: There should be a 90-degree angle between the forearm and the upper arm. This is your starting position.', 'Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.', 'After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.', 'Repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the exercise.'], array['Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg', 'Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('standing-bent-over-two-arm-dumbbell-triceps-extension', 'Standing Bent-Over Two-Arm Dumbbell Triceps Extension', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['triceps'], null, array['With a dumbbell in each hand and the palms facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms should be close to the torso and parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights. Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.', 'Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arms are extended. Like many other arm exercises, only the forearm moves.', 'After a second contraction at the top, slowly lower the dumbbells back to their starting position as you inhale.', 'Repeat the movement for the prescribed amount of repetitions.'], array['Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg', 'Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('standing-biceps-cable-curl', 'Standing Biceps Cable Curl', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the curl bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Biceps_Cable_Curl/0.jpg', 'Standing_Biceps_Cable_Curl/1.jpg'], 'free-exercise-db'),
  ('standing-biceps-stretch', 'Standing Biceps Stretch', 'Arms', false, 'stretching', 'other', 'beginner', 'isolation', 'static', array['biceps'], array['chest', 'shoulders'], array['Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward.', 'Raise your arms up and hold until you feel a stretch in your biceps.'], array['Standing_Biceps_Stretch/0.jpg', 'Standing_Biceps_Stretch/1.jpg'], 'free-exercise-db'),
  ('standing-bradford-press', 'Standing Bradford Press', 'Shoulders', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position.', 'Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head.', 'Lower the bar down to the back of the head until your elbow forms a right angle.', 'Lift the bar back over your head by extending the elbows', 'Lower the bar down to the starting position.', 'Alternate in this manner until you complete the recommended amount of repetitions.'], array['Standing_Bradford_Press/0.jpg', 'Standing_Bradford_Press/1.jpg'], 'free-exercise-db'),
  ('standing-cable-chest-press', 'Standing Cable Chest Press', 'Chest', false, 'strength', 'cable', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability.', 'Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position.', 'Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you.', 'Pause at the top of the motion, and return to the starting position.'], array['Standing_Cable_Chest_Press/0.jpg', 'Standing_Cable_Chest_Press/1.jpg'], 'free-exercise-db'),
  ('standing-cable-lift', 'Standing Cable Lift', 'Core', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['abdominals'], array['shoulders'], array['Connect a standard handle on a tower, and move the cable to the lowest pulley position.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.', 'With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.', 'In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.', 'Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.', 'Retract your arms and then your body. Return to the neutral position in a slow and controlled manner.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.'], array['Standing_Cable_Lift/0.jpg', 'Standing_Cable_Lift/1.jpg'], 'free-exercise-db'),
  ('standing-cable-wood-chop', 'Standing Cable Wood Chop', 'Core', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['abdominals'], array['shoulders'], array['Connect a standard handle to a tower, and move the cable to the highest pulley position.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.', 'With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.', 'In one motion, pull the handle down and across your body to your front knee while rotating your torso.', 'Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.', 'Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.'], array['Standing_Cable_Wood_Chop/0.jpg', 'Standing_Cable_Wood_Chop/1.jpg'], 'free-exercise-db'),
  ('standing-calf-raise', 'Standing Calf Raise', 'Calves', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['calves'], null, array['Adjust the padded lever of the calf raise machine to fit your height.', 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Calf_Raises/0.jpg', 'Standing_Calf_Raises/1.jpg'], 'repple+free-exercise-db'),
  ('standing-calf-raises', 'Standing Calf Raises', 'Calves', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['calves'], null, array['Adjust the padded lever of the calf raise machine to fit your height.', 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Calf_Raises/0.jpg', 'Standing_Calf_Raises/1.jpg'], 'free-exercise-db'),
  ('standing-concentration-curl', 'Standing Concentration Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], array['forearms'], array['Taking a dumbbell in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the elbow pointing out. This will be your starting position.', 'Flex the elbow to curl the weight, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause.', 'Lower the dumbbell back to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.'], array['Standing_Concentration_Curl/0.jpg', 'Standing_Concentration_Curl/1.jpg'], 'free-exercise-db'),
  ('standing-dumbbell-calf-raise', 'Standing Dumbbell Calf Raise', 'Calves', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'push', array['calves'], null, array['Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.', 'With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.', 'As you inhale, go back to the starting position by slowly lowering the heels.', 'Repeat for the recommended amount of times.'], array['Standing_Dumbbell_Calf_Raise/0.jpg', 'Standing_Dumbbell_Calf_Raise/1.jpg'], 'free-exercise-db'),
  ('standing-dumbbell-press', 'Standing Dumbbell Press', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.', 'Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.', 'Pause, and slowly return the weight to the starting position.'], array['Standing_Dumbbell_Press/0.jpg', 'Standing_Dumbbell_Press/1.jpg'], 'free-exercise-db'),
  ('standing-dumbbell-reverse-curl', 'Standing Dumbbell Reverse Curl', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['biceps'], array['forearms'], array['To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Dumbbell_Reverse_Curl/0.jpg', 'Standing_Dumbbell_Reverse_Curl/1.jpg'], 'free-exercise-db'),
  ('standing-dumbbell-straight-arm-front-delt-raise-above-head', 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'push', array['shoulders'], null, array['Hold the dumbbells in front of your thighs, palms facing your thighs.', 'Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position.', 'Raise the dumbbells in a semicircular motion to arm''s length overhead as you exhale.', 'Slowly return to the starting position using the same path as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/0.jpg', 'Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/1.jpg'], 'free-exercise-db'),
  ('standing-dumbbell-triceps-extension', 'Standing Dumbbell Triceps Extension', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['triceps'], null, array['To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.', 'The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.', 'Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Dumbbell_Triceps_Extension/0.jpg', 'Standing_Dumbbell_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('standing-dumbbell-upright-row', 'Standing Dumbbell Upright Row', 'Back', false, 'strength', 'dumbbell', 'beginner', 'compound', 'pull', array['traps'], array['biceps', 'shoulders'], array['Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Dumbbell_Upright_Row/0.jpg', 'Standing_Dumbbell_Upright_Row/1.jpg'], 'free-exercise-db'),
  ('standing-elevated-quad-stretch', 'Standing Elevated Quad Stretch', 'Legs', false, 'stretching', 'other', 'beginner', null, 'static', array['quadriceps'], null, array['Start by standing with your back about two to three feet away from a bench or step.', 'Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable.', 'Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides.'], array['Standing_Elevated_Quad_Stretch/0.jpg', 'Standing_Elevated_Quad_Stretch/1.jpg'], 'free-exercise-db'),
  ('standing-front-barbell-raise-over-head', 'Standing Front Barbell Raise Over Head', 'Shoulders', false, 'strength', 'barbell', 'intermediate', 'isolation', 'push', array['shoulders'], null, array['To begin, stand straight with a barbell in your hands. You should grip the bar with palms facing down and a closer than shoulder width grip apart from each other.', 'Your feet should be shoulder width apart from each other. Your elbows should be slightly bent. This is the starting position.', 'Lift the barbell up until it is directly over your head while exhaling. Make sure to keep your elbows slightly bent when performing each repetition.', 'Once you feel the contraction, begin to lower the barbell back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Front_Barbell_Raise_Over_Head/0.jpg', 'Standing_Front_Barbell_Raise_Over_Head/1.jpg'], 'free-exercise-db'),
  ('standing-gastrocnemius-calf-stretch', 'Standing Gastrocnemius Calf Stretch', 'Calves', false, 'stretching', null, 'beginner', null, 'static', array['calves'], array['hamstrings'], array['Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight.', 'Support your weight on your left leg and place your left hand on your left thigh.', 'Pull your right toes toward your knee until you feel a stretch in your calf.'], array['Standing_Gastrocnemius_Calf_Stretch/0.jpg', 'Standing_Gastrocnemius_Calf_Stretch/1.jpg'], 'free-exercise-db'),
  ('standing-hamstring-and-calf-stretch', 'Standing Hamstring and Calf Stretch', 'Hamstrings', false, 'stretching', 'other', 'beginner', null, 'static', array['hamstrings'], null, array['Being by looping a belt, band, or rope around one foot. While standing, place that foot forward.', 'Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward.', 'Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot.'], array['Standing_Hamstring_and_Calf_Stretch/0.jpg', 'Standing_Hamstring_and_Calf_Stretch/1.jpg'], 'free-exercise-db'),
  ('standing-hip-circles', 'Standing Hip Circles', 'Glutes', false, 'stretching', 'body only', 'beginner', 'isolation', 'pull', array['abductors'], array['adductors'], array['Begin standing on one leg, holding to a vertical support.', 'Raise the unsupported knee to 90 degrees. This will be your starting position.', 'Open the hip as far as possible, attempting to make a big circle with your knee.', 'Perform this movement slowly for a number of repetitions, and repeat on the other side.'], array['Standing_Hip_Circles/0.jpg', 'Standing_Hip_Circles/1.jpg'], 'free-exercise-db'),
  ('standing-hip-flexors', 'Standing Hip Flexors', 'Legs', false, 'stretching', null, 'beginner', 'isolation', 'static', array['quadriceps'], null, array['Stand up straight with the spine vertical, the left foot slightly in front of the right.', 'Bend both knees and lift the back heel off the floor as you press the right hip forward. You can''t get a thorough, deep stretch in this position, however, because it''s hard to relax the hip flexor and stand on it at the same time. Switch sides.'], array['Standing_Hip_Flexors/0.jpg', 'Standing_Hip_Flexors/1.jpg'], 'free-exercise-db'),
  ('standing-inner-biceps-curl', 'Standing Inner-Biceps Curl', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['biceps'], null, array['Stand up with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Your legs should be at about shoulder''s width apart from each other.', 'Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.', 'While holding the upper arms stationary, curl the weights out while contracting the biceps as you breathe out. Your wrist should turn so that when the weights are fully elevated you have supinated grip (palms facing up).', 'Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: Keep the forearms aligned with your outer deltoids.', 'Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to the starting position as your breathe in. Remember to rotate the wrists as you lower the weight in order to switch back to a neutral grip.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Inner-Biceps_Curl/0.jpg', 'Standing_Inner-Biceps_Curl/1.jpg'], 'free-exercise-db'),
  ('standing-lateral-stretch', 'Standing Lateral Stretch', 'Core', false, 'stretching', null, 'beginner', null, 'static', array['abdominals'], null, array['Take a slightly wider than hip distance stance with your knees slightly bent.', 'Place your right hand on your right hip to support the spine.', 'Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torso to the right.', 'Keep your weight evenly distributed between both legs (don''t lean into your left hip). Switch sides.'], array['Standing_Lateral_Stretch/0.jpg', 'Standing_Lateral_Stretch/1.jpg'], 'free-exercise-db'),
  ('standing-leg-curl', 'Standing Leg Curl', 'Hamstrings', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['hamstrings'], null, array['Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.', 'Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.', 'As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.', 'Perform the same exercise now for the left leg.'], array['Standing_Leg_Curl/0.jpg', 'Standing_Leg_Curl/1.jpg'], 'free-exercise-db'),
  ('standing-long-jump', 'Standing Long Jump', 'Legs', false, 'plyometrics', 'body only', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.', 'Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.', 'Attempt to land with your feet out in front you, reaching as far as possible with your legs.', 'Measure the distance from your landing point to the starting point and track results.'], array['Standing_Long_Jump/0.jpg', 'Standing_Long_Jump/1.jpg'], 'free-exercise-db'),
  ('standing-low-pulley-deltoid-raise', 'Standing Low-Pulley Deltoid Raise', 'Shoulders', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['shoulders'], array['forearms'], array['Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.', 'Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position.', 'Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.', 'Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.'], array['Standing_Low-Pulley_Deltoid_Raise/0.jpg', 'Standing_Low-Pulley_Deltoid_Raise/1.jpg'], 'free-exercise-db'),
  ('standing-low-pulley-one-arm-triceps-extension', 'Standing Low-Pulley One-Arm Triceps Extension', 'Arms', false, 'strength', 'cable', 'intermediate', 'isolation', 'push', array['triceps'], array['chest', 'shoulders'], array['Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This is the starting position.', 'Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the single handle. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.'], array['Standing_Low-Pulley_One-Arm_Triceps_Extension/0.jpg', 'Standing_Low-Pulley_One-Arm_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('standing-military-press', 'Standing Military Press', 'Shoulders', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.', 'Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Military_Press/0.jpg', 'Standing_Military_Press/1.jpg'], 'free-exercise-db'),
  ('standing-olympic-plate-hand-squeeze', 'Standing Olympic Plate Hand Squeeze', 'Arms', false, 'strength', 'other', 'beginner', 'isolation', 'static', array['forearms'], array['biceps'], array['To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position.', 'Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates.', 'Now raise the plates back to the starting position as you exhale by closing your hands.', 'Repeat for the recommended amount of repetitions prescribed in your program.'], array['Standing_Olympic_Plate_Hand_Squeeze/0.jpg', 'Standing_Olympic_Plate_Hand_Squeeze/1.jpg'], 'free-exercise-db'),
  ('standing-one-arm-cable-curl', 'Standing One-Arm Cable Curl', 'Arms', false, 'strength', 'cable', 'intermediate', 'isolation', 'pull', array['biceps'], null, array['Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight.', 'Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance.', 'Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling. Tip: Only the forearm should move.', 'Hold the contraction position as you squeeze the bicep and then lower the single handle back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.', 'Switch arms while performing this exercise.'], array['Standing_One-Arm_Cable_Curl/0.jpg', 'Standing_One-Arm_Cable_Curl/1.jpg'], 'free-exercise-db'),
  ('standing-one-arm-dumbbell-curl-over-incline-bench', 'Standing One-Arm Dumbbell Curl Over Incline Bench', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Stand on the back side of an incline bench as if you were going to be a spotter for someone. Have a dumbbell in one hand and rest it across the incline bench with a supinated (palms up) grip.', 'Position your non lifting hand at the corner or side of the incline bench. The chest should be pressed against the top part of the incline and your feet should be pressed against the floor at a wide stance. This is the starting position.', 'While holding the upper arm stationary, curl the dumbbell upward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a second.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.', 'Switch arms while performing this exercise.'], array['Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/0.jpg', 'Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/1.jpg'], 'free-exercise-db'),
  ('standing-one-arm-dumbbell-triceps-extension', 'Standing One-Arm Dumbbell Triceps Extension', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['triceps'], array['chest', 'shoulders'], array['To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head.', 'This will be your starting position.', 'Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearm touch your bicep. Tip: The upper arm should remain stationary and only the forearm should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.'], array['Standing_One-Arm_Dumbbell_Triceps_Extension/0.jpg', 'Standing_One-Arm_Dumbbell_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('standing-overhead-barbell-triceps-extension', 'Standing Overhead Barbell Triceps Extension', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'push', array['triceps'], array['shoulders'], array['To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart.', 'Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position.', 'Keeping your upper arms close to your head and elbows in, perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the barbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Overhead_Barbell_Triceps_Extension/0.jpg', 'Standing_Overhead_Barbell_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('standing-palm-in-one-arm-dumbbell-press', 'Standing Palm-In One-Arm Dumbbell Press', 'Shoulders', false, 'strength', 'dumbbell', 'beginner', 'compound', 'push', array['shoulders'], array['triceps'], array['Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance.', 'Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise.', 'Slowly lift the dumbbell up until your arm is fully extended. This the starting position.', 'While inhaling lower the weight down until your arm is at a 90 degree angle again.', 'Feel the contraction for a second and then lift the weight back up towards the starting position while exhaling. Remember to hold on to the incline bench and keep your feet positioned to keep balance during the exercise.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.'], array['Standing_Palm-In_One-Arm_Dumbbell_Press/0.jpg', 'Standing_Palm-In_One-Arm_Dumbbell_Press/1.jpg'], 'free-exercise-db'),
  ('standing-palms-in-dumbbell-press', 'Standing Palms-In Dumbbell Press', 'Shoulders', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position.', 'Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbells up until your arms are fully extended.', 'While inhaling lower the weights down until your arm is at a 90 degree angle again.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Palms-In_Dumbbell_Press/0.jpg', 'Standing_Palms-In_Dumbbell_Press/1.jpg'], 'free-exercise-db'),
  ('standing-palms-up-barbell-behind-the-back-wrist-curl', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.', 'You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.', 'While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.', 'Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.', 'When finished, lower the barbell down to the squat rack or the floor by bending the knees. Tip: It is easiest to either pick it up from a squat rack or have a partner hand it to you.'], array['Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/0.jpg', 'Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/1.jpg'], 'free-exercise-db'),
  ('standing-pelvic-tilt', 'Standing Pelvic Tilt', 'Lower back', false, 'stretching', null, 'beginner', 'isolation', 'static', array['lower back'], array['glutes'], array['Start off with your feet hip-distance apart.', 'Bend your knees slightly to keep them soft and springy.', 'You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch.'], array['Standing_Pelvic_Tilt/0.jpg', 'Standing_Pelvic_Tilt/1.jpg'], 'free-exercise-db'),
  ('standing-rope-crunch', 'Standing Rope Crunch', 'Core', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Attach a rope to a high pulley and select an appropriate weight.', 'Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position.', 'Perform the movement by flexing the spine, crunching the weight down as far as you can.', 'Hold the peak contraction for a moment before returning to the starting position.'], array['Standing_Rope_Crunch/0.jpg', 'Standing_Rope_Crunch/1.jpg'], 'free-exercise-db'),
  ('standing-soleus-and-achilles-stretch', 'Standing Soleus And Achilles Stretch', 'Calves', false, 'stretching', null, 'beginner', 'isolation', 'static', array['calves'], null, array['Stand with your feet hip-distance apart, one foot slightly in front of the other.', 'Bend both knees, keeping your back heel on the floor. Switch sides.'], array['Standing_Soleus_And_Achilles_Stretch/0.jpg', 'Standing_Soleus_And_Achilles_Stretch/1.jpg'], 'free-exercise-db'),
  ('standing-toe-touches', 'Standing Toe Touches', 'Hamstrings', false, 'stretching', null, 'beginner', null, 'static', array['hamstrings'], array['calves'], array['Stand with some space in front and behind you.', 'Bend at the waist, keeping your legs straight, until you can relax and let your upper body hang down in front of you. Let your arms and hands hang down naturally. Hold for 10 to 20 seconds.'], array['Standing_Toe_Touches/0.jpg', 'Standing_Toe_Touches/1.jpg'], 'free-exercise-db'),
  ('standing-towel-triceps-extension', 'Standing Towel Triceps Extension', 'Arms', false, 'strength', 'body only', 'beginner', 'isolation', 'push', array['triceps'], null, array['To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.', 'Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the towel. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.'], array['Standing_Towel_Triceps_Extension/0.jpg', 'Standing_Towel_Triceps_Extension/1.jpg'], 'free-exercise-db'),
  ('standing-two-arm-overhead-throw', 'Standing Two-Arm Overhead Throw', 'Shoulders', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'pull', array['shoulders'], array['chest', 'lats'], array['Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back.', 'Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement.', 'The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back.'], array['Standing_Two-Arm_Overhead_Throw/0.jpg', 'Standing_Two-Arm_Overhead_Throw/1.jpg'], 'free-exercise-db'),
  ('star-jump', 'Star Jump', 'Legs', false, 'plyometrics', 'body only', 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'shoulders'], array['Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.', 'To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.', 'As you land, bring your limbs back in and absorb your impact through the legs.'], array['Star_Jump/0.jpg', 'Star_Jump/1.jpg'], 'free-exercise-db'),
  ('step-mill', 'Step Mill', 'Legs', true, 'cardio', 'machine', 'intermediate', null, null, array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall.', 'Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outside while offering a similar rate of calories burned. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.'], array['Step_Mill/0.jpg', 'Step_Mill/1.jpg'], 'free-exercise-db'),
  ('step-up-with-knee-raise', 'Step-up with Knee Raise', 'Glutes', false, 'strength', 'body only', 'beginner', 'compound', 'push', array['glutes'], array['hamstrings', 'quadriceps'], array['Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.', 'Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.', 'Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.'], array['Step-up_with_Knee_Raise/0.jpg', 'Step-up_with_Knee_Raise/1.jpg'], 'free-exercise-db'),
  ('stiff-leg-barbell-good-morning', 'Stiff Leg Barbell Good Morning', 'Lower back', false, 'strength', 'barbell', 'beginner', 'compound', 'push', array['lower back'], array['glutes', 'hamstrings'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.', 'Keeping your legs stationary, move your torso forward by bending at the hips while inhaling. Lower your torso until it is parallel with the floor.', 'Begin to raise the bar as you exhale by elevating your torso back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Stiff_Leg_Barbell_Good_Morning/0.jpg', 'Stiff_Leg_Barbell_Good_Morning/1.jpg'], 'free-exercise-db'),
  ('stiff-legged-barbell-deadlift', 'Stiff-Legged Barbell Deadlift', 'Hamstrings', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['glutes', 'lower back'], array['Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.', 'Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.'], array['Stiff-Legged_Barbell_Deadlift/0.jpg', 'Stiff-Legged_Barbell_Deadlift/1.jpg'], 'free-exercise-db'),
  ('stiff-legged-dumbbell-deadlift', 'Stiff-Legged Dumbbell Deadlift', 'Hamstrings', false, 'strength', 'dumbbell', 'beginner', 'compound', 'pull', array['hamstrings'], array['glutes', 'lower back'], array['Grasp a couple of dumbbells holding them by your side at arm''s length.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement', 'Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.'], array['Stiff-Legged_Dumbbell_Deadlift/0.jpg', 'Stiff-Legged_Dumbbell_Deadlift/1.jpg'], 'free-exercise-db'),
  ('stomach-vacuum', 'Stomach Vacuum', 'Core', false, 'stretching', 'body only', 'beginner', 'isolation', 'static', array['abdominals'], null, array['To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.', 'Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone.', 'One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position.', 'Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds.', 'Repeat for the recommended amount of sets.'], array['Stomach_Vacuum/0.jpg', 'Stomach_Vacuum/1.jpg'], 'free-exercise-db'),
  ('straight-arm-dumbbell-pullover', 'Straight-Arm Dumbbell Pullover', 'Chest', false, 'strength', 'dumbbell', 'intermediate', 'compound', 'pull', array['chest'], array['lats', 'shoulders', 'triceps'], array['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.', 'Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position.
Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.', 'While keeping your arms straight, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.', 'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.'], array['Straight-Arm_Dumbbell_Pullover/0.jpg', 'Straight-Arm_Dumbbell_Pullover/1.jpg'], 'free-exercise-db'),
  ('straight-arm-pulldown', 'Straight-Arm Pulldown', 'Back', false, 'strength', 'cable', 'beginner', 'isolation', 'pull', array['lats'], null, array['You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.', 'Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.', 'While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.', 'While keeping the arms straight, go back to the starting position while breathing in.', 'Repeat for the recommended amount of repetitions.'], array['Straight-Arm_Pulldown/0.jpg', 'Straight-Arm_Pulldown/1.jpg'], 'free-exercise-db'),
  ('straight-bar-bench-mid-rows', 'Straight Bar Bench Mid Rows', 'Back', false, 'strength', 'barbell', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position.', 'Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking.', 'After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down.'], array['Straight_Bar_Bench_Mid_Rows/0.jpg', 'Straight_Bar_Bench_Mid_Rows/1.jpg'], 'free-exercise-db'),
  ('straight-raises-on-incline-bench', 'Straight Raises on Incline Bench', 'Shoulders', false, 'strength', 'barbell', 'beginner', 'isolation', 'push', array['shoulders'], array['traps'], array['Place a bar on the ground behind the head of an incline bench.', 'Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position.', 'To begin, raise the barbell out in front of your head while keeping your arms extended.', 'Return to the starting position.'], array['Straight_Raises_on_Incline_Bench/0.jpg', 'Straight_Raises_on_Incline_Bench/1.jpg'], 'free-exercise-db'),
  ('stride-jump-crossover', 'Stride Jump Crossover', 'Legs', false, 'plyometrics', 'other', 'beginner', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'hamstrings'], array['Stand to the side of a box with your inside foot on top of it, close to the edge.', 'Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.', 'Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box.', 'Repeat the movement, crossing back over to the other side.'], array['Stride_Jump_Crossover/0.jpg', 'Stride_Jump_Crossover/1.jpg'], 'free-exercise-db'),
  ('sumo-deadlift', 'Sumo Deadlift', 'Hamstrings', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['adductors', 'forearms', 'glutes', 'lower back', 'middle back', 'quadriceps', 'traps'], array['Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.'], array['Sumo_Deadlift/0.jpg', 'Sumo_Deadlift/1.jpg'], 'free-exercise-db'),
  ('sumo-deadlift-with-bands', 'Sumo Deadlift with Bands', 'Hamstrings', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['adductors', 'forearms', 'glutes', 'lower back', 'middle back', 'quadriceps', 'traps'], array['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor.', 'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.'], array['Sumo_Deadlift_with_Bands/0.jpg', 'Sumo_Deadlift_with_Bands/1.jpg'], 'free-exercise-db'),
  ('sumo-deadlift-with-chains', 'Sumo Deadlift with Chains', 'Hamstrings', false, 'powerlifting', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['abductors', 'adductors', 'forearms', 'glutes', 'lower back', 'middle back', 'quadriceps', 'traps'], array['You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the weight.', 'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.'], array['Sumo_Deadlift_with_Chains/0.jpg', 'Sumo_Deadlift_with_Chains/1.jpg'], 'free-exercise-db'),
  ('superman', 'Superman', 'Lower back', false, 'stretching', 'body only', 'beginner', 'compound', 'static', array['lower back'], array['glutes', 'hamstrings'], array['To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.', 'Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.', 'Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions prescribed in your program.'], array['Superman/0.jpg', 'Superman/1.jpg'], 'free-exercise-db'),
  ('supine-chest-throw', 'Supine Chest Throw', 'Arms', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['This drill is great for chest passes when you lack a partner or a wall of sufficient strength. Lay on the ground on your back with your knees bent.', 'Begin with the ball on your chest, held with both hands on the bottom.', 'Explode up, extending through the elbow to throw the ball directly above you as high as possible.', 'Catch the ball with both hands as it comes down.'], array['Supine_Chest_Throw/0.jpg', 'Supine_Chest_Throw/1.jpg'], 'free-exercise-db'),
  ('supine-one-arm-overhead-throw', 'Supine One-Arm Overhead Throw', 'Core', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'pull', array['abdominals'], array['chest', 'lats', 'shoulders'], array['Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position.', 'Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.', 'The ball can be thrown to a partner or bounced off of a wall.'], array['Supine_One-Arm_Overhead_Throw/0.jpg', 'Supine_One-Arm_Overhead_Throw/1.jpg'], 'free-exercise-db'),
  ('supine-two-arm-overhead-throw', 'Supine Two-Arm Overhead Throw', 'Core', false, 'plyometrics', 'medicine ball', 'beginner', 'compound', 'pull', array['abdominals'], array['chest', 'lats', 'shoulders'], array['Lay on the ground on your back with your knees bent.', 'Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position.', 'Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.', 'The ball can be thrown to a partner or bounced off of a wall.'], array['Supine_Two-Arm_Overhead_Throw/0.jpg', 'Supine_Two-Arm_Overhead_Throw/1.jpg'], 'free-exercise-db'),
  ('suspended-fallout', 'Suspended Fallout', 'Core', false, 'strength', 'other', 'intermediate', 'isolation', 'pull', array['abdominals'], array['chest', 'lower back', 'shoulders'], array['Adjust the straps so the handles are at an appropriate height, below waist level.', 'Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position.', 'Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head.', 'Maintain a neutral spine and keep the rest of your body straight, your shoulders being the only joints allowed to move.', 'Pause during the peak contraction, and then return to the starting position.'], array['Suspended_Fallout/0.jpg', 'Suspended_Fallout/1.jpg'], 'free-exercise-db'),
  ('suspended-push-up', 'Suspended Push-Up', 'Chest', false, 'strength', 'other', 'beginner', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Anchor your suspension straps securely to the top of a rack or other object.', 'Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with your arms fully extended, maintaining good posture.', 'Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex.', 'Continue until your elbows break 90 degrees, pausing before you extend to return to the starting position.'], array['Suspended_Push-Up/0.jpg', 'Suspended_Push-Up/1.jpg'], 'free-exercise-db'),
  ('suspended-reverse-crunch', 'Suspended Reverse Crunch', 'Core', false, 'strength', 'other', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack.', 'Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position.', 'Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt your pelvis, allowing your spine to flex.', 'At the top of the controlled motion, return to the starting position.'], array['Suspended_Reverse_Crunch/0.jpg', 'Suspended_Reverse_Crunch/1.jpg'], 'free-exercise-db'),
  ('suspended-row', 'Suspended Row', 'Back', false, 'strength', 'other', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position.', 'Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so.', 'At the completion of the motion pause, and then return to the starting position.'], array['Suspended_Row/0.jpg', 'Suspended_Row/1.jpg'], 'free-exercise-db'),
  ('suspended-split-squat', 'Suspended Split Squat', 'Legs', false, 'strength', 'other', 'intermediate', 'compound', 'push', array['quadriceps'], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings'], array['Suspend your straps so the handles are 18-30 inches from the floor.', 'Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your chest up, with your knee slightly bent. This will be your starting position.', 'Descend by flexing the knee and hips, lowering yourself to the ground. Keep your weight on the heel of your foot and maintain your posture throughout the exercise.', 'At the bottom of the movement, reverse the motion, extending through the hip and knee to return to the starting position.'], array['Suspended_Split_Squat/0.jpg', 'Suspended_Split_Squat/1.jpg'], 'free-exercise-db'),
  ('svend-press', 'Svend Press', 'Chest', false, 'strength', 'other', 'beginner', 'compound', 'push', array['chest'], array['forearms', 'shoulders', 'triceps'], array['Begin in a standing position.', 'Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position.', 'Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.', 'Pause at the top of the motion, and then slowly return to the starting position.'], array['Svend_Press/0.jpg', 'Svend_Press/1.jpg'], 'free-exercise-db'),
  ('t-bar-row-with-handle', 'T-Bar Row with Handle', 'Back', false, 'strength', 'barbell', 'beginner', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.', 'Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.', 'Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.', 'Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.', 'After a brief pause, return to the starting position.'], array['T-Bar_Row_with_Handle/0.jpg', 'T-Bar_Row_with_Handle/1.jpg'], 'free-exercise-db'),
  ('tate-press', 'Tate Press', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'push', array['triceps'], array['chest', 'shoulders'], array['Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.', 'Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.', 'As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.'], array['Tate_Press/0.jpg', 'Tate_Press/1.jpg'], 'free-exercise-db'),
  ('the-straddle', 'The Straddle', 'Hamstrings', false, 'stretching', null, 'beginner', null, 'static', array['hamstrings'], array['adductors', 'calves'], array['Begin in a seated, upright position. Start by extending your legs in front of you in a V.', 'With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds.'], array['The_Straddle/0.jpg', 'The_Straddle/1.jpg'], 'free-exercise-db'),
  ('thigh-abductor', 'Thigh Abductor', 'Glutes', false, 'strength', 'machine', 'beginner', 'isolation', 'push', array['abductors'], array['glutes'], array['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them away from each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.'], array['Thigh_Abductor/0.jpg', 'Thigh_Abductor/1.jpg'], 'free-exercise-db'),
  ('thigh-adductor', 'Thigh Adductor', 'Legs', false, 'strength', 'machine', 'beginner', 'isolation', 'pull', array['adductors'], array['glutes', 'hamstrings'], array['To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them towards each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.'], array['Thigh_Adductor/0.jpg', 'Thigh_Adductor/1.jpg'], 'free-exercise-db'),
  ('tire-flip', 'Tire Flip', 'Legs', false, 'strongman', 'other', 'intermediate', 'compound', 'pull', array['quadriceps'], array['calves', 'chest', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps', 'triceps'], array['Begin by gripping the bottom of the tire on the tread, and position your feet back a bit. Your chest should be driving into the tire.', 'To lift the tire, extend through the hips, knees, and ankles, driving into the tire and up.', 'As the tire reaches a 45 degree angle, step forward and drive a knee into the tire. As you do so adjust your grip to the upper portion of the tire and push it forward as hard as possible to complete the turn. Repeat as necessary.'], array['Tire_Flip/0.jpg', 'Tire_Flip/1.jpg'], 'free-exercise-db'),
  ('toe-touchers', 'Toe Touchers', 'Core', false, 'stretching', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.', 'Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor.', 'Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position.', 'While keeping your lower back pressed against the floor, slowly lift your torso and use your hands to try and touch your toes. Remember to exhale while perform this part of the exercise.', 'Slowly begin to lower your torso and arms back down to the starting position while inhaling. Remember to keep your arms straight out pointing towards your toes.', 'Repeat for the recommended amount of repetitions.'], array['Toe_Touchers/0.jpg', 'Toe_Touchers/1.jpg'], 'free-exercise-db'),
  ('torso-rotation', 'Torso Rotation', 'Core', false, 'stretching', 'exercise ball', 'beginner', null, 'pull', array['abdominals'], null, array['Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position.', 'Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions.'], array['Torso_Rotation/0.jpg', 'Torso_Rotation/1.jpg'], 'free-exercise-db'),
  ('trail-running-walking', 'Trail Running/Walking', 'Legs', true, 'cardio', null, 'beginner', null, null, array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Running or hiking on trails will get the blood pumping and heart beating almost immediately. Make sure you have good shoes. While you use the muscles in your calves and buttocks to pull yourself up a hill, the knees, joints and ankles absorb the bulk of the pounding coming back down. Take smaller steps as you walk downhill, keep your knees bent to reduce the impact and slow down to avoid falling.', 'A 150 lb person can burn over 200 calories for 30 minutes walking uphill, compared to 175 on a flat surface. If running the trail, a 150 lb person can burn well over 500 calories in 30 minutes.'], array['Trail_Running_Walking/0.jpg', 'Trail_Running_Walking/1.jpg'], 'free-exercise-db'),
  ('trap-bar-deadlift', 'Trap Bar Deadlift', 'Legs', false, 'strength', 'other', 'beginner', 'compound', 'pull', array['quadriceps'], array['glutes', 'hamstrings'], array['For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.', 'Lower your hips, look forward with your head and keep your chest up.', 'Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.', 'At the completion of the movement, lower the weight back to the ground under control.'], array['Trap_Bar_Deadlift/0.jpg', 'Trap_Bar_Deadlift/1.jpg'], 'free-exercise-db'),
  ('treadmill', 'Treadmill', 'Legs', true, null, null, null, null, null, null, null, null, null, 'repple'),
  ('tricep-dumbbell-kickback', 'Tricep Dumbbell Kickback', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'push', array['triceps'], null, array['Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.', 'Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.', 'After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.'], array['Tricep_Dumbbell_Kickback/0.jpg', 'Tricep_Dumbbell_Kickback/1.jpg'], 'free-exercise-db'),
  ('tricep-pushdown', 'Tricep Pushdown', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.'], array['Triceps_Pushdown/0.jpg', 'Triceps_Pushdown/1.jpg'], 'repple+free-exercise-db'),
  ('tricep-side-stretch', 'Tricep Side Stretch', 'Arms', false, 'stretching', null, 'beginner', null, 'static', array['triceps'], array['shoulders'], array['Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep. Then repeat for your other arm.'], array['Tricep_Side_Stretch/0.jpg', 'Tricep_Side_Stretch/1.jpg'], 'free-exercise-db'),
  ('triceps-overhead-extension-with-rope', 'Triceps Overhead Extension with Rope', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable.', 'Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position.', 'To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head.', 'Squeeze your triceps at the top of the movement, and slowly lower the weight back to the start position.'], array['Triceps_Overhead_Extension_with_Rope/0.jpg', 'Triceps_Overhead_Extension_with_Rope/1.jpg'], 'free-exercise-db'),
  ('triceps-pushdown', 'Triceps Pushdown', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.'], array['Triceps_Pushdown/0.jpg', 'Triceps_Pushdown/1.jpg'], 'free-exercise-db'),
  ('triceps-pushdown-rope-attachment', 'Triceps Pushdown - Rope Attachment', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.', 'Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.'], array['Triceps_Pushdown_-_Rope_Attachment/0.jpg', 'Triceps_Pushdown_-_Rope_Attachment/1.jpg'], 'free-exercise-db'),
  ('triceps-pushdown-v-bar-attachment', 'Triceps Pushdown - V-Bar Attachment', 'Arms', false, 'strength', 'cable', 'beginner', 'isolation', 'push', array['triceps'], null, array['Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.'], array['Triceps_Pushdown_-_V-Bar_Attachment/0.jpg', 'Triceps_Pushdown_-_V-Bar_Attachment/1.jpg'], 'free-exercise-db'),
  ('triceps-stretch', 'Triceps Stretch', 'Arms', false, 'stretching', null, 'beginner', 'isolation', 'static', array['triceps'], array['lats'], array['Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides.'], array['Triceps_Stretch/0.jpg', 'Triceps_Stretch/1.jpg'], 'free-exercise-db'),
  ('tuck-crunch', 'Tuck Crunch', 'Core', false, 'strength', 'body only', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.', 'Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs.', 'Move your arms from the floor and cross them so they are resting on your chest. This is the starting position.', 'While keeping your lower back pressed against the floor, slowly lift your torso. Remember to exhale while perform this part of the exercise.', 'Slowly begin to lower your torso back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.'], array['Tuck_Crunch/0.jpg', 'Tuck_Crunch/1.jpg'], 'free-exercise-db'),
  ('two-arm-dumbbell-preacher-curl', 'Two-Arm Dumbbell Preacher Curl', 'Arms', false, 'strength', 'dumbbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height.', 'Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.'], array['Two-Arm_Dumbbell_Preacher_Curl/0.jpg', 'Two-Arm_Dumbbell_Preacher_Curl/1.jpg'], 'free-exercise-db'),
  ('two-arm-kettlebell-clean', 'Two-Arm Kettlebell Clean', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['shoulders'], array['calves', 'glutes', 'hamstrings', 'lower back', 'traps'], array['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so.', 'Lower the kettlebells back to the starting position and repeat.'], array['Two-Arm_Kettlebell_Clean/0.jpg', 'Two-Arm_Kettlebell_Clean/1.jpg'], 'free-exercise-db'),
  ('two-arm-kettlebell-jerk', 'Two-Arm Kettlebell Jerk', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['calves', 'quadriceps', 'triceps'], array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise.'], array['Two-Arm_Kettlebell_Jerk/0.jpg', 'Two-Arm_Kettlebell_Jerk/1.jpg'], 'free-exercise-db'),
  ('two-arm-kettlebell-military-press', 'Two-Arm Kettlebell Military Press', 'Shoulders', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'push', array['shoulders'], array['triceps'], array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward.', 'Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability.'], array['Two-Arm_Kettlebell_Military_Press/0.jpg', 'Two-Arm_Kettlebell_Military_Press/1.jpg'], 'free-exercise-db'),
  ('two-arm-kettlebell-row', 'Two-Arm Kettlebell Row', 'Back', false, 'strength', 'kettlebells', 'intermediate', 'compound', 'pull', array['middle back'], array['biceps', 'lats'], array['Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position.', 'Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat.'], array['Two-Arm_Kettlebell_Row/0.jpg', 'Two-Arm_Kettlebell_Row/1.jpg'], 'free-exercise-db'),
  ('underhand-cable-pulldowns', 'Underhand Cable Pulldowns', 'Back', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back', 'shoulders'], array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.'], array['Underhand_Cable_Pulldowns/0.jpg', 'Underhand_Cable_Pulldowns/1.jpg'], 'free-exercise-db'),
  ('upper-back-leg-grab', 'Upper Back-Leg Grab', 'Hamstrings', false, 'stretching', null, 'beginner', null, 'static', array['hamstrings'], array['lower back', 'middle back'], array['While seated, bend forward to hug your thighs from underneath with both arms.', 'Keep your knees together and your legs extended out as you bring your chest down to your knees. You can also stretch your middle back by pulling your back away from your knees as your hugging them.'], array['Upper_Back-Leg_Grab/0.jpg', 'Upper_Back-Leg_Grab/1.jpg'], 'free-exercise-db'),
  ('upper-back-stretch', 'Upper Back Stretch', 'Back', false, 'stretching', null, 'beginner', null, 'static', array['middle back'], array['middle back'], array['Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward.'], array['Upper_Back_Stretch/0.jpg', 'Upper_Back_Stretch/1.jpg'], 'free-exercise-db'),
  ('upright-barbell-row', 'Upright Barbell Row', 'Shoulders', false, 'strength', 'barbell', 'beginner', 'compound', 'pull', array['shoulders'], array['traps'], array['Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.', 'Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.'], array['Upright_Barbell_Row/0.jpg', 'Upright_Barbell_Row/1.jpg'], 'free-exercise-db'),
  ('upright-bike', 'Upright Bike', 'Legs', true, null, null, null, null, null, null, null, null, null, 'repple'),
  ('upright-cable-row', 'Upright Cable Row', 'Back', false, 'strength', 'cable', 'intermediate', 'compound', 'pull', array['traps'], array['shoulders'], array['Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.'], array['Upright_Cable_Row/0.jpg', 'Upright_Cable_Row/1.jpg'], 'free-exercise-db'),
  ('upright-row-with-bands', 'Upright Row - With Bands', 'Back', false, 'strength', 'bands', 'beginner', 'compound', 'pull', array['traps'], array['shoulders'], array['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.'], array['Upright_Row_-_With_Bands/0.jpg', 'Upright_Row_-_With_Bands/1.jpg'], 'free-exercise-db'),
  ('upward-stretch', 'Upward Stretch', 'Shoulders', false, 'stretching', null, 'beginner', null, 'static', array['shoulders'], array['chest', 'lats'], array['Extend both hands straight above your head, palms touching.', 'Slowly push your hands up and back, keeping your back straight.'], array['Upward_Stretch/0.jpg', 'Upward_Stretch/1.jpg'], 'free-exercise-db'),
  ('v-bar-pulldown', 'V-Bar Pulldown', 'Back', false, 'strength', 'cable', 'intermediate', 'compound', 'pull', array['lats'], array['biceps', 'middle back', 'shoulders'], array['Sit down on a pull-down machine with a V-Bar attached to the top pulley.', 'Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.', 'Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.', 'After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.', 'Repeat for the prescribed number of repetitions.'], array['V-Bar_Pulldown/0.jpg', 'V-Bar_Pulldown/1.jpg'], 'free-exercise-db'),
  ('v-bar-pullup', 'V-Bar Pullup', 'Back', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back', 'shoulders'], array['Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.', 'Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position.', 'Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.', 'After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in.', 'Repeat for the prescribed number of repetitions.'], array['V-Bar_Pullup/0.jpg', 'V-Bar_Pullup/1.jpg'], 'free-exercise-db'),
  ('vertical-swing', 'Vertical Swing', 'Hamstrings', false, 'plyometrics', 'dumbbell', 'beginner', 'compound', 'pull', array['hamstrings'], array['glutes', 'quadriceps', 'shoulders'], array['Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.', 'Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly.', 'Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.', 'As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition.'], array['Vertical_Swing/0.jpg', 'Vertical_Swing/1.jpg'], 'free-exercise-db'),
  ('walking-lunge', 'Walking Lunge', 'Legs', false, 'strength', null, 'beginner', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Begin standing with your feet shoulder width apart and your hands on your hips.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.'], array['Bodyweight_Walking_Lunge/0.jpg', 'Bodyweight_Walking_Lunge/1.jpg'], 'repple+free-exercise-db'),
  ('walking-treadmill', 'Walking, Treadmill', 'Legs', true, 'cardio', 'machine', 'beginner', null, null, array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn''t burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.'], array['Walking_Treadmill/0.jpg', 'Walking_Treadmill/1.jpg'], 'free-exercise-db'),
  ('weighted-ball-hyperextension', 'Weighted Ball Hyperextension', 'Lower back', false, 'strength', 'exercise ball', 'intermediate', 'compound', 'pull', array['lower back'], array['glutes', 'hamstrings', 'middle back'], array['To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position.', 'Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement.', 'Hold the contraction on your lower back for a second and lower your torso back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions prescribed in your program.'], array['Weighted_Ball_Hyperextension/0.jpg', 'Weighted_Ball_Hyperextension/1.jpg'], 'free-exercise-db'),
  ('weighted-ball-side-bend', 'Weighted Ball Side Bend', 'Core', false, 'strength', 'exercise ball', 'intermediate', 'isolation', 'pull', array['abdominals'], null, array['To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball.', 'Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head.', 'Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left forearm and upper arm. This is the starting position.', 'Raise the side of your torso up by laterally flexing at the waist while exhaling.', 'Hold the contraction for a second and slowly lower yourself back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.', 'Switch sides and repeat the exercise.'], array['Weighted_Ball_Side_Bend/0.jpg', 'Weighted_Ball_Side_Bend/1.jpg'], 'free-exercise-db'),
  ('weighted-bench-dip', 'Weighted Bench Dip', 'Arms', false, 'strength', 'other', 'intermediate', 'compound', 'push', array['triceps'], array['chest', 'shoulders'], array['For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended.', 'The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exercise is best performed with a partner as placing the weight on your lap can be challenging and cause injury without assistance. This will be your starting position.', 'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.', 'Using your triceps to bring your torso up again, lift yourself back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.'], array['Weighted_Bench_Dip/0.jpg', 'Weighted_Bench_Dip/1.jpg'], 'free-exercise-db'),
  ('weighted-crunches', 'Weighted Crunches', 'Core', false, 'strength', 'medicine ball', 'beginner', 'isolation', 'pull', array['abdominals'], null, array['Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.', 'Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position.', 'Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor.', 'At the top of the movement, flex your abdominals and hold for a brief pause.', 'Then inhale and slowly lower yourself back down to the starting position.'], array['Weighted_Crunches/0.jpg', 'Weighted_Crunches/1.jpg'], 'free-exercise-db'),
  ('weighted-jump-squat', 'Weighted Jump Squat', 'Legs', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['Position a lightly loaded barbell across the back of your shoulders. You could also use a weighted vest, sandbag, or other type of resistance for this exercise.', 'The weight should be light enough that it doesn''t slow you down significantly. Your feet should be just outside of shoulder width with your head and chest up. This will be your starting position.', 'Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips, knees, and ankles. Maintain good posture throughout the jump.', 'As you return to the ground, absorb the impact through your legs.'], array['Weighted_Jump_Squat/0.jpg', 'Weighted_Jump_Squat/1.jpg'], 'free-exercise-db'),
  ('weighted-pull-ups', 'Weighted Pull Ups', 'Back', false, 'strength', 'other', 'intermediate', 'compound', 'pull', array['lats'], array['biceps', 'middle back'], array['Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip.', 'You''ll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position.', 'Now, exhale and pull your torso up until your head is above your hands. Concentrate on squeezing yourshoulder blades back and down as you reach the top contracted position.', 'After a brief moment at the top contracted position, inhale and slowly lower your torso back to the starting position with your arms extended and your lats fully stretched.'], array['Weighted_Pull_Ups/0.jpg', 'Weighted_Pull_Ups/1.jpg'], 'free-exercise-db'),
  ('weighted-sissy-squat', 'Weighted Sissy Squat', 'Legs', false, 'strength', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position.', 'As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second.', 'After your one second hold, use your thigh muscles to bring your torso back up to the starting position. Exhale as you move up.', 'Repeat for the recommended amount of times.'], array['Weighted_Sissy_Squat/0.jpg', 'Weighted_Sissy_Squat/1.jpg'], 'free-exercise-db'),
  ('weighted-sit-ups-with-bands', 'Weighted Sit-Ups - With Bands', 'Core', false, 'strength', 'other', 'intermediate', 'isolation', 'pull', array['abdominals'], null, array['Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.', 'Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.', 'Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.'], array['Weighted_Sit-Ups_-_With_Bands/0.jpg', 'Weighted_Sit-Ups_-_With_Bands/1.jpg'], 'free-exercise-db'),
  ('weighted-squat', 'Weighted Squat', 'Legs', false, 'strength', 'other', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out.', 'Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting position.', 'Begin by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that are perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to move the body back up by pushing the floor of the flat bench with the ball of your foot mainly as you straighten the legs again and go back to the starting position. Exhale as you perform this portion of the exercise.', 'Repeat for the recommended amount of repetitions.'], array['Weighted_Squat/0.jpg', 'Weighted_Squat/1.jpg'], 'free-exercise-db'),
  ('wide-grip-barbell-bench-press', 'Wide-Grip Barbell Bench Press', 'Chest', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.'], array['Wide-Grip_Barbell_Bench_Press/0.jpg', 'Wide-Grip_Barbell_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('wide-grip-decline-barbell-bench-press', 'Wide-Grip Decline Barbell Bench Press', 'Chest', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['chest'], array['shoulders', 'triceps'], array['Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your lower chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.'], array['Wide-Grip_Decline_Barbell_Bench_Press/0.jpg', 'Wide-Grip_Decline_Barbell_Bench_Press/1.jpg'], 'free-exercise-db'),
  ('wide-grip-decline-barbell-pullover', 'Wide-Grip Decline Barbell Pullover', 'Chest', false, 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['chest'], array['shoulders', 'triceps'], array['Lie down on a decline bench with both legs securely locked in position. Reach for the barbell behind the head using a pronated grip (palms facing out). Make sure to grab the barbell wider than shoulder width apart for this exercise. Slowly lift the barbell up from the floor by using your arms.', 'When positioned properly, your arms should be fully extended and perpendicular to the floor. This is the starting position.', 'Begin by moving the barbell back down in a semicircular motion as if you were going to place it on the floor, but instead, stop when the arms are parallel to the floor. Tip: Keep the arms fully extended at all times. The movement should only happen at the shoulder joint. Inhale as you perform this portion of the movement.', 'Now bring the barbell up while exhaling until you are back at the starting position. Remember to keep full control of the barbell at all times.', 'Repeat the movement for the prescribed amount of repetitions of your training program.', 'When finished with your set, slowly lower the barbell back down until it is level with your head and release it.'], array['Wide-Grip_Decline_Barbell_Pullover/0.jpg', 'Wide-Grip_Decline_Barbell_Pullover/1.jpg'], 'free-exercise-db'),
  ('wide-grip-lat-pulldown', 'Wide-Grip Lat Pulldown', 'Back', false, 'strength', 'cable', 'beginner', 'compound', 'pull', array['lats'], array['biceps', 'middle back', 'shoulders'], array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.'], array['Wide-Grip_Lat_Pulldown/0.jpg', 'Wide-Grip_Lat_Pulldown/1.jpg'], 'free-exercise-db'),
  ('wide-grip-pulldown-behind-the-neck', 'Wide-Grip Pulldown Behind The Neck', 'Back', false, 'strength', 'cable', 'intermediate', 'compound', 'pull', array['lats'], array['biceps', 'middle back', 'shoulders'], array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso and head forward. Think of an imaginary line from the center of the bar down to the back of your neck. This is your starting position.', 'As you breathe out, bring the bar down until it touches the back of your neck by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second on the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.'], array['Wide-Grip_Pulldown_Behind_The_Neck/0.jpg', 'Wide-Grip_Pulldown_Behind_The_Neck/1.jpg'], 'free-exercise-db'),
  ('wide-grip-rear-pull-up', 'Wide-Grip Rear Pull-Up', 'Back', false, 'strength', 'body only', 'intermediate', 'compound', 'pull', array['lats'], array['biceps', 'middle back', 'shoulders'], array['Grab the pull-up bar with the palms facing forward using a wide grip.', 'As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position.', 'Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.'], array['Wide-Grip_Rear_Pull-Up/0.jpg', 'Wide-Grip_Rear_Pull-Up/1.jpg'], 'free-exercise-db'),
  ('wide-grip-standing-barbell-curl', 'Wide-Grip Standing Barbell Curl', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['biceps'], null, array['Stand up with your torso upright while holding a barbell at the wide outer handle. The palm of your hands should be facing forward. The elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.'], array['Wide-Grip_Standing_Barbell_Curl/0.jpg', 'Wide-Grip_Standing_Barbell_Curl/1.jpg'], 'free-exercise-db'),
  ('wide-stance-barbell-squat', 'Wide Stance Barbell Squat', 'Legs', false, 'strength', 'barbell', 'intermediate', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings', 'lower back'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a wider-than-shoulder-width stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance, and also maintain a straight back. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Wide_Stance_Barbell_Squat/0.jpg', 'Wide_Stance_Barbell_Squat/1.jpg'], 'free-exercise-db'),
  ('wide-stance-stiff-legs', 'Wide Stance Stiff Legs', 'Hamstrings', false, 'olympic weightlifting', 'barbell', 'intermediate', 'compound', 'pull', array['hamstrings'], array['adductors', 'glutes', 'lower back'], array['Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position.', 'Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then slowly return the weight to the starting position. For successive reps, the weight need not touch the floor.'], array['Wide_Stance_Stiff_Legs/0.jpg', 'Wide_Stance_Stiff_Legs/1.jpg'], 'free-exercise-db'),
  ('wind-sprints', 'Wind Sprints', 'Core', false, 'strength', 'body only', 'beginner', 'compound', 'pull', array['abdominals'], null, array['Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.', 'Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3', 'Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.', 'Continue alternating between legs until the set is complete.'], array['Wind_Sprints/0.jpg', 'Wind_Sprints/1.jpg'], 'free-exercise-db'),
  ('windmills', 'Windmills', 'Glutes', false, 'stretching', null, 'intermediate', null, 'pull', array['abductors'], array['glutes', 'hamstrings', 'lower back'], array['Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.', 'Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand.', 'Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions.'], array['Windmills/0.jpg', 'Windmills/1.jpg'], 'free-exercise-db'),
  ('world-s-greatest-stretch', 'World''s Greatest Stretch', 'Hamstrings', false, 'stretching', null, 'intermediate', null, 'static', array['hamstrings'], array['calves', 'glutes', 'quadriceps'], array['This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds.', 'Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the stretch.', 'After 10-20 seconds, place your hands on either side of your front foot. Raise the toes of the front foot off of the ground, and straighten your leg. You may need to reposition your rear leg to do so. Hold for 10-20 seconds, and then repeat the entire sequence for the other side.'], array['Worlds_Greatest_Stretch/0.jpg', 'Worlds_Greatest_Stretch/1.jpg'], 'free-exercise-db'),
  ('wrist-circles', 'Wrist Circles', 'Arms', false, 'stretching', 'body only', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Start by standing straight with your feet being shoulder width apart from each other. Elevate your arms to the side of you until they are fully extended and parallel to the floor at a height that is evenly aligned with your shoulders. Tip: Your torso and arms should form the letter "T: Your palms should be facing down. This is the starting position.', 'Keeping your entire body stationary except for the wrists, begin to rotate both wrists forward in a circular motion. Tip: Pretend that you are trying to draw circles by using your hands as the brush. Breathe normally as you perform this exercise.', 'Repeat for the recommended amount of repetitions.'], array['Wrist_Circles/0.jpg', 'Wrist_Circles/1.jpg'], 'free-exercise-db'),
  ('wrist-roller', 'Wrist Roller', 'Arms', false, 'strength', 'other', 'beginner', 'isolation', 'pull', array['forearms'], array['shoulders'], array['To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart.', 'Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position.', 'Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.', 'Once the weight has reached the bar, slowly begin to lower the weight back down by rotating the wrist in a downward motion until the weight reaches the starting position.', 'Repeat for the prescribed amount of repetitions in your program.'], array['Wrist_Roller/0.jpg', 'Wrist_Roller/1.jpg'], 'free-exercise-db'),
  ('wrist-rotations-with-straight-bar', 'Wrist Rotations with Straight Bar', 'Arms', false, 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['forearms'], null, array['Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position.', 'Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure.', 'Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure.'], array['Wrist_Rotations_with_Straight_Bar/0.jpg', 'Wrist_Rotations_with_Straight_Bar/1.jpg'], 'free-exercise-db'),
  ('yoke-walk', 'Yoke Walk', 'Legs', false, 'strongman', 'other', 'intermediate', 'compound', null, array['quadriceps'], array['abdominals', 'abductors', 'adductors', 'calves', 'glutes', 'hamstrings', 'lower back'], array['The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects.', 'Begin by racking the apparatus across the back of the shoulders. With your head looking forward and back arched, lift the yoke by driving through the heels.', 'Begin walking as quickly as possible using short, quick steps. You may hold the side posts of the yoke to help steady it and hold it in position. Continue for the given distance as fast as possible, usually 75-100 feet.'], array['Yoke_Walk/0.jpg', 'Yoke_Walk/1.jpg'], 'free-exercise-db'),
  ('zercher-squats', 'Zercher Squats', 'Legs', false, 'strength', 'barbell', 'expert', 'compound', 'push', array['quadriceps'], array['calves', 'glutes', 'hamstrings'], array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm.', 'Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have your arms crossed but with a bar running across them.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the ball of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.'], array['Zercher_Squats/0.jpg', 'Zercher_Squats/1.jpg'], 'free-exercise-db'),
  ('zottman-curl', 'Zottman Curl', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['biceps'], array['forearms'], array['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'Make sure the palms of the hands are facing each other. This will be your starting position.', 'While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a second as you squeeze the biceps.', 'Now during the contracted position, rotate your wrist until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky.', 'Slowly begin to bring the dumbbells back down using the pronated grip.', 'As the dumbbells close your thighs, start rotating the wrist so that you go back to a neutral (palms facing your body) grip.', 'Repeat for the recommended amount of repetitions.'], array['Zottman_Curl/0.jpg', 'Zottman_Curl/1.jpg'], 'free-exercise-db'),
  ('zottman-preacher-curl', 'Zottman Preacher Curl', 'Arms', false, 'strength', 'dumbbell', 'intermediate', 'isolation', 'pull', array['biceps'], array['forearms'], array['Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position.', 'As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched.', 'Now rotate your wrists once you are at the bottom of the movement so that the palms of the hands are facing up.', 'As you exhale, use your biceps to curl the weights up until they are fully contracted and the dumbbells are at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.', 'Squeeze the biceps hard for a second at the contracted position and rotate your wrists so that the palms are facing down again.', 'Repeat for the recommended amount of repetitions.'], array['Zottman_Preacher_Curl/0.jpg', 'Zottman_Preacher_Curl/1.jpg'], 'free-exercise-db')
on conflict (id) do update set
  -- name and muscle_group are deliberately NOT updated. A row already in the
  -- catalogue is referenced by programs and logs under the name it has.
  category          = excluded.category,
  equipment         = excluded.equipment,
  level             = excluded.level,
  mechanic          = excluded.mechanic,
  force             = excluded.force,
  primary_muscles   = excluded.primary_muscles,
  secondary_muscles = excluded.secondary_muscles,
  instructions      = excluded.instructions,
  image_paths       = excluded.image_paths,
  source            = excluded.source;

-- ▶ profile-name-backfill.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Names that signup captured and the profiles row never received.
--
-- Reported as "doesn't show my name on the home screen after Good Morning".
--
-- The home screen greets people from `profiles.full_name`. handle_new_user()
-- copies `raw_user_meta_data->>'full_name'` into that column — but it ends
-- `on conflict (id) do nothing`, so a profiles row inserted by anything else
-- first keeps a blank name, and accounts created before that trigger existed
-- never got one at all. The reporter's own account is from the day after the
-- project was created: the name "Timothy Rodgers" was sitting in the auth
-- record the whole time, and the app was reading a column nobody had filled.
--
-- ── Only blanks ────────────────────────────────────────────────────────────
--
-- A name somebody has since edited in the app is theirs. Overwriting it with
-- whatever they happened to type at signup would be a worse bug than the one
-- being fixed, and a silent one — nobody checks whether their own name is
-- still what they set it to.
--
-- The app now also falls back to the auth record when this column is blank
-- (src/ui/clientData.tsx), so a future account that slips through the same gap
-- heals itself on first launch rather than waiting for another backfill.
-- ─────────────────────────────────────────────────────────────────────────

update public.profiles p
set full_name = btrim(u.raw_user_meta_data->>'full_name')
from auth.users u
where u.id = p.id
  and (p.full_name is null or btrim(p.full_name) = '')
  and btrim(coalesce(u.raw_user_meta_data->>'full_name', '')) <> '';

-- ▶ exercise-demo-animations.sql

-- ─────────────────────────────────────────────────────────────────────────
-- Where a bought animation pack lands.
--
-- The catalogue stores image_paths as PATHS rather than URLs precisely so that
-- swapping the media never means rewriting 917 rows. This is that swap
-- arriving: a licensed looping clip per movement, resolved at read time exactly
-- as the reference frames are.
--
-- Two photographs are a start position and an end position. Cross-fading them
-- removes the jolt and invents no motion, but it is not an animation and was
-- reported, correctly, as choppy. This is the fix; the frames stay as the
-- fallback for movements the pack does not cover.
--
-- ── A separate bucket from exercise-videos ─────────────────────────────────
--
-- `exercise-videos` holds clips a COACH recorded, governed by per-clip
-- visibility and gym membership — a client may see one and not another. These
-- are stock content shown to everybody, and mixing them would put licensed
-- third-party media under RLS written to answer "is this my coach's client".
--
-- Private, not public. A commercial licence usually permits use inside the app
-- and says nothing kind about leaving the files openly fetchable. The app
-- already signs URLs for coach clips, so this costs nothing new; if the licence
-- bought permits it, flipping to public is one statement and gains CDN caching.
--
-- ── demo_licence, and why it is not optional ───────────────────────────────
--
-- A preview bundle is CC BY-NC: fine for deciding whether to buy, never fine in
-- a product that sells memberships. The realistic failure is not a decision
-- anybody makes — it is one nobody revisits. Somebody wires the preview in to
-- look at it, it works, and four builds later it is in an App Store binary that
-- nobody re-checked. So the licence travels with the row and is asked every
-- time it is about to render (src/lib/exerciseMedia.ts, demoIsShippable), and
-- a NULL is treated as unlicensed rather than as permission — the reason it is
-- unrecorded is unknown, and the expensive guess is the permissive one.
-- ─────────────────────────────────────────────────────────────────────────

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('exercise-demos', 'exercise-demos', false, 52428800,
        array['video/mp4','video/webm','image/webp','image/gif','application/json'])
on conflict (id) do nothing;

alter table public.exercises add column if not exists animation_path text;
alter table public.exercises add column if not exists demo_licence   text;

comment on column public.exercises.animation_path is
  'Storage key in the exercise-demos bucket for this movement''s looping clip. A path, never a URL — the media can be replaced without touching this table.';
comment on column public.exercises.demo_licence is
  'Licence of the animation: ''commercial'' once bought, ''evaluation'' for a CC BY-NC preview bundle, NULL when there is no animation. An ''evaluation'' asset must never render in a release build.';

create index if not exists exercises_animation_path_idx
  on public.exercises (animation_path)
  where animation_path is not null;

-- ▶ repdb-catalogue.sql

-- ─────────────────────────────────────────────────────────────────────────
-- The RepDB catalogue: 601 movements, each with a description.
--
-- GENERATED by scripts/build-repdb-catalogue.mjs from data/repdb-exercises.json.
-- Do not hand-edit; change the generator.
--
-- ── What this adds that we could not get before ───────────────────────────
--
-- A DESCRIPTION on every row. The catalogue has carried step-by-step
-- instructions since the free-exercise-db import and no description at all, so
-- the exercise screen could tell somebody how to do a Pendlay row and never
-- what one is or what it is for. That was the original request, and it was the
-- one part the previous dataset could not answer, because it has no such field.
--
-- Also difficulty, MET, goals and tags, and — the part that matters most —
-- ONE consistent illustrated style with ids already in our slug convention.
-- Every other vendor would have meant hand-confirming roughly 750 mappings,
-- where a single wrong one puts a barbell animation on a dumbbell page. That is
-- the mistake Hevy actually shipped, on the page we were sent as the example to
-- follow. Here there is no mapping step to get wrong.
--
-- ── Names are NOT preserved on conflict, unlike part 71 ───────────────────
--
-- Part 71 refused to update name or muscle_group, because programs and logs
-- reference a row by the name it has. That still holds for OUR original rows.
-- A RepDB row landing on an id we already ship enriches it and leaves the name
-- alone for the same reason.
--
-- ── Licence: free tier, commercial use, attribution required ──────────────
--
-- Usable in a paid app at no cost, with a visible credit — it is not
-- evaluation-only. Two consequences, both load bearing:
--
--   · images are served from our own PRIVATE bucket. Term 3 forbids
--     republishing the dataset, and a public bucket is arguably exactly that.
--   · every row is stamped 'repdb', so the app can refuse to render RepDB
--     content in a build that does not carry the attribution, and preflight
--     can fail on it rather than trusting somebody to remember.
-- ─────────────────────────────────────────────────────────────────────────

-- ── The four columns this part is the first to need ──────────────────────
--
-- Part 71 added category, equipment, level, mechanic, force and the arrays.
-- description, met, goals and tags arrived with RepDB and nothing declares
-- them, so the insert below named four columns that do not exist on a database
-- built from setup.sql — the whole part fails on `column "description" of
-- relation "exercises" does not exist`, and a fresh environment ends up with
-- the 917-row free-exercise-db catalogue and no descriptions at all, which is
-- the one thing this dataset was adopted for.
alter table public.exercises add column if not exists description text;
-- numeric(4,1) rather than bare numeric: production already carries these four
-- columns, added by hand, and met is 4,1 there. A fresh database built from
-- this file must match it exactly rather than nearly — two environments whose
-- column types differ is the drift check-schema.mjs exists to catch.
alter table public.exercises add column if not exists met         numeric(4,1);
alter table public.exercises add column if not exists goals       text[];
alter table public.exercises add column if not exists tags        text[];
-- Coaching cues, kept apart from the ordered steps in instructions: a cue
-- buried in the middle of a numbered list is a cue nobody reads.
alter table public.exercises add column if not exists tips        text[];

comment on column public.exercises.description is
  'What the movement IS, in one sentence — distinct from instructions, which are how to perform it. Null on rows that predate RepDB; a screen must say nothing rather than invent one.';

-- ── Every id is the slug of the name, including on a database already run ─
--
-- 80 of the 601 rows were keyed by RepDB's own id, which for those is
-- not the slug of the name we display: RepDB's `bench-press` is named "Barbell
-- Bench Press". Every screen resolves a program's exercise NAME through
-- exerciseSlug(), so those rows were in the catalogue and unreachable from it —
-- illustrated, described, and answering "not in our catalogue" when tapped.
--
-- The insert below now keys on the name. This repoints the rows an earlier run
-- already wrote, so a database that has run this part is corrected rather than
-- given a second copy of all 80. Skipped where the destination id is taken,
-- which means the free-exercise-db row for the same movement is there and the
-- insert enriches it instead.
update public.exercises set id = 'machine-assisted-dips'
  where id = 'assisted-dips' and source = 'repdb'
    and not exists (select 1 from public.exercises x where x.id = 'machine-assisted-dips');
