  where id = 'wrist-curl' and source = 'repdb'
    and not exists (select 1 from public.exercises x where x.id = 'bilateral-dumbbell-wrist-curl');

insert into public.exercises
  (id, name, muscle_group, is_cardio, description, category, equipment, level, mechanic, force,
   primary_muscles, secondary_muscles, instructions, tips, image_paths, met, goals, tags, source) values
  ('ab-wheel-rollout', 'Ab Wheel Rollout', 'Core', false, 'A core exercise rolling a wheel forward and back, training anti-extension of the spine.', 'strength', 'ab wheel', 'intermediate', 'compound', 'pull', array['rectus abdominis', 'transverse abdominis'], array['anterior deltoid', 'latissimus dorsi', 'obliques', 'serratus anterior'], array['Kneel on the floor and grip the ab wheel handles shoulder-width.', 'Brace the core hard so the lower back stays neutral.', 'Roll the wheel slowly forward, extending the body as far as you can control.', 'Stop before the hips sag or the back arches.', 'Pull the wheel back to the knees by contracting the abs.'], array['Brace the core before each rep — do not let the lower back arch.', 'Build range gradually, stopping short of any hip sag.', 'Drop to a wall stop if you cannot control the bottom.'], array['images/flat/ab-wheel-rollout-start.webp', 'images/flat/ab-wheel-rollout-peak.webp'], 6, array['hypertrophy', 'strength'], array['core_focus'], 'repdb'),
  ('air-bike', 'Air Bike', 'Full body', true, 'A full-body conditioning exercise on the air bike, combining pedaling with an arm push-pull for sustained power output.', 'cardio', 'air bike', 'intermediate', 'compound', 'push', array['hamstrings', 'quadriceps'], array['gluteus maximus', 'latissimus dorsi', 'pectoralis major', 'rectus abdominis'], array['Sit on the air bike and grip the moving handles.', 'Place your feet on the pedals and brace your core.', 'Push and pull the handles while pedaling at a steady pace.', 'Drive with both arms and legs to maintain power output.', 'Continue for the desired duration or distance.'], array['Keep your torso upright and avoid slumping over the handles.', 'Breathe rhythmically to sustain effort over longer intervals.', 'Pull the handles with your back, not just your arms.'], array['images/flat/air-bike-main.webp'], 8, array['hypertrophy', 'strength'], array['lower_back_safe', 'shoulder_safe', 'no_axial_load', 'knee_safe'], 'repdb'),
  ('archer-pull-ups', 'Archer Pull Ups', 'Back', false, 'A unilateral pull-up shifting the body toward one hand while the other arm stays straight, building single-arm pulling strength.', 'strength', 'pull up bar', 'advanced', 'compound', 'pull', array['latissimus dorsi'], array['biceps brachii', 'forearm flexors', 'posterior deltoid', 'rhomboids'], array['Grip the bar wider than shoulder width with palms facing away.', 'Pull yourself up while shifting your body toward one hand.', 'Keep the opposite arm straight as a support.', 'Lower yourself under control back to the hang.', 'Alternate sides each rep or complete reps on one side first.'], array['Keep the straight arm fully extended and use it only as a guide.', 'Pull your chin toward the working hand, not straight up.', 'Master wide-grip pull-ups before progressing to archers.'], array['images/flat/archer-pull-ups-start.webp', 'images/flat/archer-pull-ups-peak.webp'], 6, array['hypertrophy', 'strength'], array['knee_safe', 'no_axial_load', 'lower_back_safe', 'shoulder_safe'], 'repdb'),
  ('archer-push-ups', 'Archer Push Ups', 'Chest', false, 'A wide push-up lowering toward one hand while the opposite arm stays straight, loading one side at a time.', 'strength', null, 'advanced', 'compound', 'push', array['pectoralis major'], array['anterior deltoid', 'rectus abdominis', 'serratus anterior', 'triceps brachii'], array['Set up in a wide push-up position with arms straight.', 'Lower yourself toward one hand while keeping the other arm straight.', 'Keep your core tight and body in a straight line.', 'Press back up to the start position.', 'Alternate sides each rep for the desired number of reps.'], array['Keep your hips square to the floor as you shift sideways.', 'Let the straight arm assist as little as possible.', 'Start from wide push-ups and shift a little further each session.'], array['images/flat/archer-push-ups-start.webp', 'images/flat/archer-push-ups-peak.webp'], 5, array['hypertrophy', 'strength'], array['knee_safe', 'no_axial_load', 'lower_back_safe', 'shoulder_safe'], 'repdb'),
  ('arnold-press', 'Arnold Press', 'Shoulders', false, 'An overhead press variation rotating the palms from facing the body to facing forward, working the front and side deltoids.', 'strength', 'dumbbell', 'intermediate', 'compound', 'push', array['anterior deltoid', 'lateral deltoid'], array['serratus anterior', 'trapezius', 'triceps brachii'], array['Hold a pair of dumbbells at shoulder height with palms facing you.', 'Press the dumbbells overhead while rotating your palms to face forward.', 'Fully extend your arms at the top without locking the elbows.', 'Reverse the motion and rotate back to the start.', 'Repeat for the desired number of reps.'], array['Time the palm rotation evenly throughout the press, not all at once.', 'Avoid arching your lower back as the weight goes overhead.', 'Use a lighter load than a standard press to control the rotation.'], array['images/flat/arnold-press-start.webp', 'images/flat/arnold-press-peak.webp'], 6, array['hypertrophy', 'strength'], array['knee_safe', 'lower_back_safe', 'no_axial_load'], 'repdb'),
  ('machine-assisted-dips', 'Machine Assisted Dips', 'Full body', false, 'A beginner-friendly dip performed on an assisted machine that offsets body weight, training the chest and triceps.', 'strength', 'dip machine', 'beginner', 'compound', 'push', array['pectoralis major', 'triceps brachii'], array['anterior deltoid', 'rhomboids'], array['Step onto the assisted dip machine with knees on the pad.', 'Grip the parallel bars and support your weight with straight arms.', 'Lower your body by bending your elbows until shoulders are below elbows.', 'Press back up to the start position.', 'Repeat for the desired number of reps.'], array['Keep your elbows tracking back rather than flaring out wide.', 'Stop the descent if you feel pinching in the shoulders.', 'Reduce the assistance gradually as pressing strength improves.'], array['images/flat/assisted-dips-start.webp', 'images/flat/assisted-dips-peak.webp'], 6, array['hypertrophy', 'strength'], array['knee_safe', 'no_axial_load', 'lower_back_safe'], 'repdb'),
  ('assisted-pull-ups', 'Assisted Pull Ups', 'Back', false, 'A machine-assisted pull-up reducing the effective body weight, allowing beginners to train the lats through a full range.', 'strength', 'assisted pullup machine', 'beginner', 'compound', 'pull', array['latissimus dorsi'], array['biceps brachii', 'forearm flexors', 'posterior deltoid', 'rhomboids'], array['Place your knees on the assisted pull-up machine pad.', 'Grip the bar with palms facing away, slightly wider than shoulders.', 'Pull your chest toward the bar by driving your elbows down.', 'Lower yourself under control to a full hang.', 'Repeat for the desired number of reps.'], array['Pull your shoulder blades down before bending your arms.', 'Avoid swinging or using momentum from the knee pad.', 'Decrease the assistance over time to progress toward unassisted reps.'], array['images/flat/assisted-pull-ups-start.webp', 'images/flat/assisted-pull-ups-peak.webp'], 6, array['hypertrophy', 'strength'], array['knee_safe', 'no_axial_load', 'lower_back_safe', 'shoulder_safe'], 'repdb'),
  ('back-extension', 'Back Extension', 'Back', false, 'An isolation movement targeting the lower back erector spinae on a hyperextension bench.', 'strength', null, 'beginner', 'isolation', 'pull', array['erector spinae'], array['gluteus maximus', 'hamstrings'], array['Lie face down on a hyperextension bench with hips at the pad edge.', 'Lower your upper body toward the floor.', 'Raise your torso back up until your body is straight.', 'Repeat.'], array['Keep movements controlled.', 'Do not hyperextend beyond neutral spine.'], array['images/flat/back-extension-start.webp', 'images/flat/back-extension-peak.webp'], 3.5, array['hypertrophy', 'rehabilitation'], array['leg_day', 'knee_safe', 'no_axial_load', 'lower_back_safe', 'shoulder_safe'], 'repdb'),
  ('back-lever', 'Back Lever', 'Full body', false, 'An advanced gymnastic isometric: hanging from a bar, the body is held horizontal and face-down in a straight line, demanding total-body tension through the lats, core, and posterior chain.', 'strength', 'pull up bar', 'advanced', 'compound', 'static', array['erector spinae', 'latissimus dorsi'], array['anterior deltoid', 'gluteus maximus', 'rectus abdominis'], array['Hang from a bar with an overhand grip and rotate backward through the arms until inverted.', 'Lower the body forward and down until it is horizontal, facing the floor.', 'Keep the arms straight and the whole body in one rigid line from head to heels.', 'Brace the core and squeeze the glutes so the hips and shoulders do not sag.', 'Hold for time, then rotate back up under control.'], array['Build up with tucked and one-leg progressions before the full straight-body lever.', 'Depress and retract the shoulder blades to protect the shoulders.', 'Stay rigid -- any pike or arch collapses the hold.'], array['images/flat/back-lever-main.webp'], 6, array['strength'], null, 'repdb'),
  ('stability-ball-leg-curl', 'Stability Ball Leg Curl', 'Hamstrings', false, 'A bodyweight hamstring curl using a stability ball, rolling the heels toward the glutes while bridging the hips.', 'strength', 'stability ball', 'intermediate', 'isolation', 'pull', array['hamstrings'], array['gastrocnemius', 'gluteus maximus'], array['Lie face-up on the floor with your heels and lower calves on top of a stability ball, arms out for balance.', 'Press through the heels to raise your hips into a straight line from shoulders to ankles.', 'Keeping the hips up, bend the knees to roll the ball toward your glutes.', 'Extend the legs back out under control without dropping the hips.', 'Complete all reps, then lower the hips and step off the ball.'], array['Hips stay up for the whole set — this is a combo bridge plus curl.', 'Start with both feet; progress to single-leg when it becomes easy.'], array['images/flat/ball-leg-curl-start.webp', 'images/flat/ball-leg-curl-peak.webp'], 5, array['hypertrophy', 'strength'], array['leg_day'], 'repdb'),
  ('ball-pike', 'Ball Pike', 'Core', false, 'An advanced core exercise where the hips pike up while the feet roll a stability ball toward the chest.', 'strength', 'stability ball', 'advanced', 'compound', 'pull', array['obliques', 'rectus abdominis'], array['anterior deltoid', 'hip flexors', 'serratus anterior'], array['Place the shins on a stability ball and hands on the floor in a high plank.', 'Brace the core and keep the legs straight.', 'Pike the hips up, rolling the ball toward the chest as the body forms an inverted V.', 'Pause briefly at the top.', 'Roll the ball back out to the starting plank.'], array['Keep the legs straight throughout — no knee bend.', 'Move at the hips, not the lower back.', 'Build up with knee tucks first if the pike is too hard.'], array['images/flat/ball-pike-start.webp', 'images/flat/ball-pike-peak.webp'], 6, array['hypertrophy', 'strength'], array['core_focus'], 'repdb'),
  ('band-assisted-pull-ups', 'Band Assisted Pull Ups', 'Back', false, 'A pull-up variation using a resistance band for assistance, reducing the load to build toward unassisted reps.', 'strength', 'resistance band', 'beginner', 'compound', 'pull', array['latissimus dorsi'], array['biceps brachii', 'forearm flexors', 'posterior deltoid', 'rhomboids'], array['Loop a resistance band over the pull-up bar and step one foot into it.', 'Grip the bar with palms facing away, shoulder-width apart.', 'Pull your chest toward the bar by driving your elbows down.', 'Lower yourself under control to a full hang.', 'Repeat for the desired number of reps.'], array['Avoid letting the band''s recoil bounce you out of the bottom.', 'Keep the banded foot steady so the band cannot slip off.', 'Progress to thinner bands as your pulling strength increases.'], array['images/flat/band-assisted-pull-ups-start.webp', 'images/flat/band-assisted-pull-ups-peak.webp'], 6, array['hypertrophy', 'strength'], array['knee_safe', 'no_axial_load', 'lower_back_safe', 'shoulder_safe'], 'repdb'),
  ('band-pull-apart', 'Band Pull Apart', 'Shoulders', false, 'A high-volume rear delt and scapular retractor exercise performed by pulling a resistance band apart at shoulder height.', 'strength', 'resistance band', 'beginner', 'isolation', 'pull', array['posterior deltoid'], array['rhomboids', 'trapezius'], array['Stand holding a light resistance band with both hands, arms extended straight in front at shoulder height.', 'Hands start shoulder-width apart, palms facing down.', 'Keeping arms straight, pull the band apart by driving the hands out to the sides.', 'Finish with the band touching your chest and the shoulder blades squeezed together.', 'Return slowly to the starting position and repeat.'], array['Lead the movement with the little fingers — this externally rotates the shoulders.', 'Use a band light enough to do 15–30 clean reps; this is a high-rep prehab exercise.'], array['images/flat/band-pull-apart-start.webp', 'images/flat/band-pull-apart-peak.webp'], 5, array['hypertrophy', 'rehabilitation'], array['pull_day', 'shoulder_safe'], 'repdb'),
  ('banded-adductor-stretch', 'Banded Adductor Stretch', 'Legs', false, 'A lying stretch that uses a band to guide one straight leg out to the side and lengthen the inner thigh.', 'stretching', 'resistance band', 'beginner', 'isolation', 'static', array['adductors'], array['hamstrings'], array['Lie on your back with a band looped around one foot.', 'Raise that leg and let it open out to the side.', 'Hold the band to control how far the leg lowers.', 'Hold for 20 to 30 seconds, breathing steadily.', 'Switch sides and repeat.'], array['Keep your hips flat and both glutes on the floor.', 'Stretch to mild tension, never to pain.'], array['images/flat/banded-adductor-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('banded-ankle-stretch', 'Banded Ankle Stretch', 'Full body', false, 'A seated stretch that uses a band around the forefoot to flex the ankle and lengthen the calf.', 'stretching', 'resistance band', 'beginner', 'isolation', 'static', array['gastrocnemius'], array['soleus'], array['Sit with one leg extended and a band around the forefoot.', 'Hold the band in both hands.', 'Pull so the toes draw back toward your shin.', 'Hold for 20 to 30 seconds, breathing steadily.', 'Switch sides and repeat.'], array['Keep the leg straight and relaxed.', 'Stretch to mild tension, never to pain.'], array['images/flat/banded-ankle-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('banded-calf-stretch', 'Banded Calf Stretch', 'Full body', false, 'A lying stretch that uses a band around the ball of the foot to flex the ankle and lengthen the calf.', 'stretching', 'resistance band', 'beginner', 'isolation', 'static', array['gastrocnemius'], array['soleus'], array['Lie on your back and loop a band around the ball of one foot.', 'Raise the leg and keep it fairly straight.', 'Pull the band so your toes draw back toward your shin.', 'Hold for 20 to 30 seconds, breathing steadily.', 'Switch sides and repeat.'], array['Keep the pull steady, not jerky.', 'Keep the knee softly straight.'], array['images/flat/banded-calf-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('banded-chest-stretch', 'Banded Chest Stretch', 'Chest', false, 'A standing stretch that opens the chest by holding a band behind the back and drawing the arms apart.', 'stretching', 'resistance band', 'beginner', 'isolation', 'static', array['pectoralis major'], array['anterior deltoid'], array['Hold a band behind your back with both hands.', 'Straighten your arms and draw them apart.', 'Lift your chest and squeeze your shoulder blades.', 'Hold for 20 to 30 seconds, breathing steadily.'], array['Keep your shoulders down away from your ears.', 'Stretch to mild tension, never to pain.'], array['images/flat/banded-chest-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('banded-clamshell', 'Banded Clamshell', 'Full body', false, 'A clamshell hip-abduction performed with a loop band wrapped above the knees. The band adds constant tension on the gluteus medius — a small, focused isolation drill for hip stability.', 'strength', 'loop band', 'beginner', 'isolation', 'pull', array['gluteus medius'], array['gluteus maximus'], array['Lie on your side with hips and knees bent to roughly 45 degrees, feet stacked.', 'Place a loop band around both legs above the knees.', 'Keep the feet pressed together and the pelvis stable — do not roll back as you move.', 'Open the top knee upward against the band, like a clamshell opening, until you feel the glute fire.', 'Pause briefly at the top, then lower under control to the start.', 'Complete all reps on one side, then switch.'], array['The pelvis stays stacked — the moment you start rocking back, the glute disengages.', 'Slow controlled tempo beats heavy band; this is a stability drill, not a strength PR.', 'If you cramp in the side of the hip, that is exactly the right muscle. Shorten the set.'], array['images/flat/banded-clamshell-start.webp', 'images/flat/banded-clamshell-peak.webp'], 5, array['rehabilitation', 'endurance', 'hypertrophy'], array['leg_day', 'warm_up'], 'repdb'),
  ('banded-figure-4-stretch', 'Banded Figure-4 Stretch', 'Full body', false, 'A lying glute stretch in a figure-4 position, using a band to draw both legs toward the chest.', 'stretching', 'resistance band', 'beginner', 'isolation', 'static', array['gluteus maximus'], array['gluteus medius'], array['Lie on your back and cross one ankle over the opposite thigh.', 'Loop a band around the supporting thigh.', 'Pull both legs toward your chest with the band.', 'Hold for 20 to 30 seconds, breathing steadily.', 'Switch sides and repeat.'], array['Keep your head and shoulders relaxed on the floor.', 'Let the crossed knee fall open.'], array['images/flat/banded-figure-4-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('banded-fire-hydrant', 'Banded Fire Hydrant', 'Full body', false, 'This isolation exercise uses a loop band to target and strengthen the gluteus medius and maximus, improving hip abduction and stability.', 'strength', 'loop band', 'beginner', 'isolation', 'push', array['gluteus medius'], array['gluteus maximus'], array['Place a loop band just above your knees and assume a quadruped position with hands under shoulders and knees under hips.', 'Keep your core engaged and back flat, maintaining a neutral spine throughout the movement.', 'Slowly lift one knee out to the side, keeping the knee bent at 90 degrees, until your thigh is parallel to the floor.', 'Hold briefly at the top, squeezing your glute, then slowly lower your leg back to the starting position with control.', 'Complete all repetitions on one side before switching to the other side.'], array['Focus on controlled movement; avoid using momentum to lift your leg.', 'Keep your hips stable and prevent your torso from rotating or leaning.', 'Ensure the band stays taut throughout the entire range of motion.'], array['images/flat/banded-fire-hydrant-start.webp', 'images/flat/banded-fire-hydrant-peak.webp'], 5, array['hypertrophy'], array['leg_day', 'glute_focus'], 'repdb'),
  ('banded-glute-bridge', 'Banded Glute Bridge', 'Full body', false, 'A glute bridge with a loop band placed above the knees. Driving the knees out against the band recruits the gluteus medius alongside the prime glute-max bridge — a cheap accessory that doubles as hip activation.', 'strength', 'loop band', 'beginner', 'compound', 'push', array['gluteus maximus'], array['gluteus medius', 'hamstrings'], array['Lie on your back with the knees bent and feet flat on the floor, shoulder-width apart.', 'Place a loop band around both legs just above the knees.', 'Press the lower back into the floor and brace the core.', 'Drive through the heels and squeeze the glutes to lift the hips into a bridge — keep the band tension by pushing the knees outward.', 'At the top, the body forms a straight line from shoulders to knees. Pause briefly.', 'Lower under control to the start and repeat for the recommended number of repetitions.'], array['The knees want to cave inward — that is the band telling you to push them out.', 'Stop the lift when your hips are level with your shoulders and knees; do not hyperextend the lower back.', 'Squeeze hard at the top — a fast, half-rep bridge feels easy because it is.'], array['images/flat/banded-glute-bridge-start.webp', 'images/flat/banded-glute-bridge-peak.webp'], 6, array['hypertrophy', 'rehabilitation', 'endurance'], array['leg_day'], 'repdb'),
  ('banded-good-morning', 'Banded Good Morning', 'Full body', false, 'A hip-hinge with a loop band over the upper back, targeting the hamstrings and glutes.', 'strength', 'loop band', 'beginner', 'compound', 'pull', array['gluteus maximus', 'hamstrings'], array['erector spinae'], array['Stand on a loop band with both feet and pass it over the back of your neck.', 'Set feet hip-width with a soft bend in the knees.', 'Hinge at the hips, pushing them back with a flat back.', 'Lower until you feel a stretch in the hamstrings.', 'Drive the hips forward to return to standing.'], array['Move from the hips, not the lower back.', 'Keep the chest up and the back flat throughout.', 'Use a band light enough to allow full range of motion.'], array['images/flat/banded-good-morning-start.webp', 'images/flat/banded-good-morning-peak.webp'], 6, array['hypertrophy'], array['pull_day', 'leg_day'], 'repdb'),
  ('banded-hamstring-stretch', 'Banded Hamstring Stretch', 'Hamstrings', false, 'A lying stretch that uses a band around the foot to draw a straight leg toward the torso and lengthen the hamstring.', 'stretching', 'resistance band', 'beginner', 'isolation', 'static', array['hamstrings'], array['gastrocnemius'], array['Lie on your back and loop a band around one foot.', 'Raise that leg straight up, holding the band in both hands.', 'Gently pull the band to draw the leg toward you.', 'Hold for 20 to 30 seconds, breathing steadily.', 'Switch sides and repeat.'], array['Keep the raised leg as straight as you can.', 'Keep the other leg flat on the floor.'], array['images/flat/banded-hamstring-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('banded-hip-thrust', 'Banded Hip Thrust', 'Full body', false, 'This exercise uses a loop band to increase glute activation during a hip thrust, effectively targeting the gluteus maximus, hamstrings, and gluteus medius for improved lower body strength.', 'strength', 'loop band', 'beginner', 'compound', 'push', array['gluteus maximus'], array['gluteus medius', 'hamstrings'], array['Place a loop band just above your knees and sit on the floor with your upper back against a bench.', 'Bend your knees, plant your feet hip-width apart, and position the band to create tension.', 'Drive through your heels, extend your hips, and lift your glutes off the floor until your body forms a straight line from shoulders to knees.', 'Squeeze your glutes forcefully at the top, ensuring your knees are pushed out against the band.', 'Slowly lower your hips back to the starting position with control.'], array['Maintain constant tension on the band throughout the movement.', 'Focus on a strong glute contraction at the peak of the thrust.', 'Keep your chin tucked and gaze forward to maintain a neutral spine.', 'Ensure your shins are vertical at the top of the movement.'], array['images/flat/banded-hip-thrust-start.webp', 'images/flat/banded-hip-thrust-peak.webp'], 6, array['hypertrophy', 'strength'], array['leg_day', 'glute_focus', 'requires_bench'], 'repdb'),
  ('banded-it-band-stretch', 'Banded IT-Band Stretch', 'Glutes', false, 'A lying stretch that uses a band to draw one leg across the body and target the outer thigh and hip.', 'stretching', 'resistance band', 'beginner', 'isolation', 'static', array['abductors'], array['gluteus maximus', 'gluteus medius'], array['Lie on your back with a band around one raised foot.', 'Hold the band with the opposite hand.', 'Draw the straight leg across your body toward the floor.', 'Hold for 20 to 30 seconds, breathing steadily.', 'Switch sides and repeat.'], array['Keep both shoulders down on the floor.', 'Stop when you feel a stretch along the outer thigh.'], array['images/flat/banded-it-band-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('banded-kneeling-hip-thrust', 'Banded Kneeling Hip Thrust', 'Full body', false, 'This exercise strengthens the glutes and hamstrings by driving the hips forward against band resistance from a kneeling position.', 'strength', 'loop band', 'beginner', 'compound', 'push', array['gluteus maximus'], array['hamstrings'], array['Place a loop band just above your knees. Kneel on the floor with your torso upright and knees hip-width apart.', 'Lean slightly forward from your hips, keeping your back straight and core braced.', 'Initiate the movement by squeezing your glutes, driving your hips forward until your torso is upright.', 'Squeeze your glutes hard at the top, maintaining tension on the band.', 'Slowly reverse the movement, controlling the band''s resistance as you return to the starting position.'], array['Focus on a strong glute contraction at the top of the movement.', 'Keep your core engaged throughout to prevent arching your lower back.', 'Maintain constant tension on the band by pushing your knees slightly outwards.'], array['images/flat/banded-kneeling-hip-thrust-start.webp', 'images/flat/banded-kneeling-hip-thrust-peak.webp'], 6, array['hypertrophy'], array['leg_day', 'glute_focus'], 'repdb'),
  ('banded-lat-stretch', 'Banded Lat Stretch', 'Back', false, 'A standing stretch that lengthens the lats by hinging forward while holding a band overhead under tension.', 'stretching', 'resistance band', 'beginner', 'isolation', 'static', array['latissimus dorsi'], array['posterior deltoid'], array['Hold a band overhead with both hands under light tension.', 'Hinge forward at the hips with your arms reaching ahead.', 'Let your chest sink to lengthen the sides of your back.', 'Hold for 20 to 30 seconds, breathing steadily.'], array['Keep your arms straight and shoulders relaxed.', 'Relax and keep breathing throughout.'], array['images/flat/banded-lat-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('banded-lateral-walk', 'Banded Lateral Walk', 'Full body', false, 'A side-stepping movement performed with a loop band wrapped above the knees or around the ankles. Constant abduction tension fires the gluteus medius — a staple warm-up and rehab drill for hip stability.', 'strength', 'loop band', 'beginner', 'compound', 'dynamic', array['gluteus medius'], array['gluteus maximus', 'quadriceps'], array['Place a loop band around the legs above the knees (or around the ankles for a harder version).', 'Stand in a quarter-squat: feet shoulder-width, hips back, chest up, knees tracking over the toes.', 'Step one foot directly out to the side against the band tension.', 'Bring the trailing foot in toward the lead — keep tension on the band the entire time, do not let the feet snap together.', 'Continue side-stepping in one direction for the prescribed reps or distance, then reverse.', 'Stay low throughout; do not pop up between steps.'], array['Keep the toes pointing straight forward — do not let the lead foot turn out.', 'Hips stay level; do not rock side-to-side as you step.', 'If the knees cave inward, the band is too strong — drop to a lighter one.'], array['images/flat/banded-lateral-walk-start.webp', 'images/flat/banded-lateral-walk-peak.webp'], 6, array['rehabilitation', 'endurance', 'hypertrophy'], array['leg_day', 'warm_up'], 'repdb'),
  ('banded-rear-delt-stretch', 'Banded Rear Delt Stretch', 'Shoulders', false, 'A standing stretch that targets the rear shoulder by pulling one arm across the body against band tension.', 'stretching', 'resistance band', 'beginner', 'isolation', 'static', array['posterior deltoid'], array['rhomboids', 'trapezius'], array['Loop a band around one arm and hold the other end.', 'Draw that arm horizontally across your chest.', 'Use the band to deepen the pull gently.', 'Hold for 20 to 30 seconds, breathing steadily.', 'Switch sides and repeat.'], array['Keep the working shoulder relaxed and down.', 'Relax and keep breathing throughout.'], array['images/flat/banded-rear-delt-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('banded-romanian-deadlift', 'Banded Romanian Deadlift', 'Full body', false, 'A Romanian deadlift using a loop band, ideal for warm-ups and learning the hip-hinge pattern.', 'strength', 'loop band', 'beginner', 'compound', 'pull', array['gluteus maximus', 'hamstrings'], array['erector spinae'], array['Stand on a loop band with both feet and grip the top of the band.', 'Set feet hip-width with a soft bend in the knees.', 'Hinge at the hips, sliding the hands down the legs.', 'Lower until you feel a stretch in the hamstrings.', 'Drive the hips forward to return to standing.'], array['Keep the band close to the legs throughout.', 'Stop at the bottom of your clean range — no rounded back.', 'The movement is a hinge, not a squat — knees barely bend.'], array['images/flat/banded-romanian-deadlift-start.webp', 'images/flat/banded-romanian-deadlift-peak.webp'], 6, array['hypertrophy'], array['pull_day', 'leg_day'], 'repdb'),
  ('banded-seated-hip-abduction', 'Banded Seated Hip Abduction', 'Full body', false, 'This isolation exercise targets the gluteus medius and maximus by externally rotating the hips against band resistance while seated.', 'strength', 'loop band', 'beginner', 'isolation', 'push', array['gluteus medius'], array['gluteus maximus'], array['Sit on a bench or chair with a loop band around your knees.', 'Keep your feet flat on the floor, hip-width apart, and maintain an upright posture.', 'Push your knees outwards against the band, engaging your glutes.', 'Hold the peak contraction briefly, then slowly return your knees to the starting position.', 'Control the movement throughout the entire range of motion.'], array['Focus on squeezing your glutes to initiate the movement.', 'Avoid leaning back or using momentum; keep your torso stable.', 'Choose a band resistance that allows for controlled movement.', 'Maintain tension on the band even in the starting position.'], array['images/flat/banded-seated-hip-abduction-start.webp', 'images/flat/banded-seated-hip-abduction-peak.webp'], 5, array['hypertrophy'], array['leg_day', 'glute_focus'], 'repdb'),
  ('banded-shoulder-stretch', 'Banded Shoulder Stretch', 'Shoulders', false, 'A standing stretch that opens the shoulders and chest by holding a band behind the back, one hand high and one low.', 'stretching', 'resistance band', 'beginner', 'isolation', 'static', array['anterior deltoid'], array['pectoralis major'], array['Hold a band behind your back, one hand high and one low.', 'Keep light tension in the band.', 'Open your chest and draw your shoulders gently back.', 'Hold for 20 to 30 seconds, breathing steadily.'], array['Keep your ribs down and avoid arching your back.', 'Move your hands farther apart to ease the stretch.'], array['images/flat/banded-shoulder-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('banded-squat', 'Banded Squat', 'Full body', false, 'A bodyweight squat with a loop band above the knees to teach knees-out tracking.', 'strength', 'loop band', 'beginner', 'compound', 'push', array['gluteus maximus', 'quadriceps'], array['gluteus medius', 'hamstrings'], array['Place a loop band just above the knees.', 'Stand with feet shoulder-width apart, toes slightly out.', 'Push the knees out against the band as you squat down.', 'Descend until thighs are parallel or below.', 'Drive through the heels to stand back up.'], array['Push the knees out against the band the whole rep.', 'Keep the chest up and the back flat.', 'Do not let the knees collapse inward.'], array['images/flat/banded-squat-start.webp', 'images/flat/banded-squat-peak.webp'], 6, array['hypertrophy'], array['leg_day'], 'repdb'),
  ('banded-standing-leg-curl', 'Banded Standing Leg Curl', 'Hamstrings', false, 'A standing hamstring curl using a loop band anchored around the ankle, useful for travel or as a low-load hamstring finisher.', 'strength', 'loop band', 'beginner', 'isolation', 'pull', array['hamstrings'], array['gastrocnemius'], array['Loop a resistance band around one ankle and anchor the other end under your standing foot or a fixed point in front of you.', 'Stand tall, holding onto something for balance if needed, with a slight bend in the standing knee.', 'Curl the banded heel up and back toward your glute, keeping the thigh still.', 'Squeeze the hamstring at the top, then lower under control to a full stretch.', 'Complete all reps on one side, then switch legs.'], array['Keep the thigh stationary — only the lower leg should move.', 'Avoid swinging the hips to generate momentum.', 'Use a lighter band if you can''t control the descent.'], array['images/flat/banded-standing-curl-start.webp', 'images/flat/banded-standing-curl-peak.webp'], 5, array['hypertrophy'], array['arm_day', 'pull_day'], 'repdb'),
  ('banded-standing-hip-abduction', 'Banded Standing Hip Abduction', 'Full body', false, 'This isolation exercise targets the gluteus medius and maximus, improving hip stability and strength by abducting the leg against band resistance.', 'strength', 'loop band', 'beginner', 'isolation', 'push', array['gluteus medius'], array['gluteus maximus'], array['Place a loop band around your ankles or just above your knees.', 'Stand tall with a slight bend in your knees and brace your core.', 'Shift your weight onto one leg, maintaining a stable torso.', 'Slowly abduct the free leg out to the side, feeling the glute contract.', 'Control the movement as you return the leg to the starting position.', 'Complete all reps per side before switching.'], array['Keep your torso upright and avoid leaning to the side.', 'Focus on a controlled movement, not momentum.', 'Ensure the band maintains tension throughout the entire range of motion.', 'Initiate the movement from your hip, not your foot.'], array['images/flat/banded-standing-hip-abduction-start.webp', 'images/flat/banded-standing-hip-abduction-peak.webp'], 5, array['hypertrophy'], array['leg_day', 'glute_focus'], 'repdb'),
  ('banded-standing-hip-adduction', 'Banded Standing Hip Adduction', 'Legs', false, 'A standing hip adduction with a loop band, isolating the inner thigh adductors.', 'strength', 'loop band', 'beginner', 'isolation', 'pull', array['adductors'], null, array['Anchor a loop band to a sturdy upright at ankle height.', 'Step into the loop with the working leg facing the anchor side.', 'Stand a few feet away so the band has tension.', 'Sweep the working leg across the body toward the standing leg.', 'Return slowly to the start. Complete reps per side, then switch.'], array['Keep the standing leg slightly bent for stability.', 'Move only the working leg — torso stays still.', 'Control the eccentric for full adductor stretch.'], array['images/flat/banded-standing-hip-adduction-start.webp', 'images/flat/banded-standing-hip-adduction-peak.webp'], 5, array['hypertrophy'], array['leg_day'], 'repdb'),
  ('banded-sumo-walk', 'Banded Sumo Walk', 'Full body', false, 'A wide-stance lateral walk with a loop band above the knees, targeting the glute medius and maximus.', 'strength', 'loop band', 'beginner', 'compound', 'push', array['gluteus maximus', 'gluteus medius'], array['quadriceps'], array['Place a loop band just above the knees.', 'Drop into a quarter squat with feet wider than shoulder-width.', 'Step forward in a wide stance, keeping tension on the band.', 'Continue stepping forward, alternating feet, for the prescribed distance.', 'Stay low throughout — do not stand up between steps.'], array['Keep tension on the band the entire set.', 'Stay in a quarter-squat — do not stand tall between steps.', 'Take small, controlled steps with toes pointed slightly out.'], array['images/flat/banded-sumo-walk-start.webp', 'images/flat/banded-sumo-walk-peak.webp'], 6, array['hypertrophy', 'endurance'], array['leg_day', 'glute_focus', 'warm_up'], 'repdb'),
  ('banded-terminal-knee-extension', 'Banded Terminal Knee Extension', 'Legs', false, 'An isolation drill that locks out the knee against band resistance, often used for VMO and knee rehab.', 'strength', 'loop band', 'beginner', 'isolation', 'push', array['quadriceps'], null, array['Anchor a loop band to a sturdy upright at knee height.', 'Step into the loop so the band sits behind one knee.', 'Step back so the band pulls the knee into a slight bend.', 'Extend the knee fully against the band, contracting the quad.', 'Return slowly. Complete reps per side, then switch.'], array['Squeeze the quadriceps hard at full extension.', 'Keep the foot flat — do not lift the heel.', 'Move only at the knee — the hip stays still.'], array['images/flat/banded-terminal-knee-extension-start.webp', 'images/flat/banded-terminal-knee-extension-peak.webp'], 5, array['hypertrophy', 'mobility'], array['leg_day', 'rehab'], 'repdb'),
  ('banded-triceps-stretch', 'Banded Triceps Stretch', 'Full body', false, 'A standing stretch that lengthens the triceps by reaching one hand behind the head against band tension.', 'stretching', 'resistance band', 'beginner', 'isolation', 'static', array['triceps brachii'], array['latissimus dorsi'], array['Hold a band that runs down your back, top hand behind your head.', 'Anchor the lower hand at your lower back.', 'Reach the top hand down to feel the triceps lengthen.', 'Hold for 20 to 30 seconds, breathing steadily.', 'Switch sides and repeat.'], array['Keep your head upright and ribs down.', 'Relax and keep breathing throughout.'], array['images/flat/banded-triceps-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('barbell-ab-rollout', 'Barbell Ab Rollout', 'Core', false, 'A kneeling ab rollout using a loaded barbell with plates, giving smoother rolling and adjustable load compared to an ab wheel.', 'strength', 'barbell', 'intermediate', 'compound', 'dynamic', array['rectus abdominis'], array['latissimus dorsi', 'obliques', 'transverse abdominis'], array['Load plates of equal size on both ends of a barbell and place it on the floor.', 'Kneel behind the bar and grip it shoulder-width, arms extended.', 'Brace the core hard, then roll the bar forward away from your body.', 'Go as far as you can keep a neutral spine — stop before the hips sag.', 'Pull the bar back to the starting position by contracting the abs and lats.', 'Repeat for the recommended number of repetitions.'], array['Start with small plates for a limited range; graduate to 45s for full rollouts.', 'The moment the lower back arches or drops, stop — you''ve exceeded your range.'], array['images/flat/barbell-ab-rollout-start.webp', 'images/flat/barbell-ab-rollout-peak.webp'], 6, array['hypertrophy', 'strength'], array['core', 'lower_back_safe'], 'repdb'),
  ('barbell-calf-raise', 'Barbell Calf Raise', 'Full body', false, 'A standing calf raise loaded with a barbell across the upper back, using a raised platform for a deeper heel stretch.', 'strength', 'barbell', 'intermediate', 'isolation', 'push', array['gastrocnemius'], array['soleus'], array['Place a barbell across your upper back as in a squat.', 'Stand with the balls of your feet on a raised platform.', 'Push up onto your toes as high as possible.', 'Pause and squeeze your calves at the top.', 'Lower your heels below the platform and repeat.'], array['Avoid bouncing out of the bottom stretch position.', 'Keep your knees straight but not locked throughout the set.', 'Move slowly to stay balanced under the bar.'], array['images/flat/barbell-calf-raise-start.webp', 'images/flat/barbell-calf-raise-peak.webp'], 5, array['hypertrophy'], array['knee_safe', 'shoulder_safe', 'lower_back_safe', 'no_axial_load'], 'repdb'),
  ('barbell-curl', 'Barbell Curl', 'Full body', false, 'A classic biceps isolation exercise using a barbell for maximal loading.', 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['biceps brachii'], array['brachialis', 'forearm flexors'], array['Stand holding a barbell with a shoulder-width underhand grip.', 'Curl the bar up toward your shoulders.', 'Squeeze at the top, then lower under control.', 'Repeat.'], array['Avoid swinging the torso.', 'Keep elbows pinned at your sides.'], array['images/flat/barbell-curl-start.webp', 'images/flat/barbell-curl-peak.webp'], 5, array['hypertrophy'], array['arm_day', 'knee_safe', 'shoulder_safe', 'lower_back_safe', 'no_axial_load'], 'repdb'),
  ('barbell-front-raise', 'Barbell Front Raise', 'Shoulders', false, 'An isolation exercise raising a barbell from the thighs to shoulder height, targeting the front deltoids.', 'strength', 'barbell', 'intermediate', 'isolation', 'push', array['anterior deltoid'], array['lateral deltoid', 'pectoralis major', 'serratus anterior'], array['Stand holding a barbell with an overhand grip at thigh level.', 'Keep your arms straight and core braced.', 'Raise the barbell in front of you to shoulder height.', 'Pause briefly at the top.', 'Lower under control and repeat.'], array['Use a light weight to avoid swinging the bar up.', 'Avoid leaning back as the bar rises.', 'Keep your wrists neutral rather than letting them bend backward.'], array['images/flat/barbell-front-raise-start.webp', 'images/flat/barbell-front-raise-peak.webp'], 5, array['hypertrophy'], array['knee_safe', 'lower_back_safe', 'shoulder_safe', 'no_axial_load'], 'repdb'),
  ('barbell-glute-bridge', 'Barbell Glute Bridge', 'Full body', false, 'A weighted glute bridge using a barbell for increased resistance.', 'strength', 'barbell', 'intermediate', 'compound', 'push', array['gluteus maximus'], array['hamstrings'], array['Lie on the floor with a barbell across your hips and knees bent.', 'Drive your hips up by squeezing your glutes.', 'Hold at the top with hips fully extended.', 'Lower with control.', 'Repeat.'], array['Drive through your heels rather than your toes.', 'Finish with your ribs down to avoid arching the lower back.', 'Keep your knees in line with your feet, not caving inward.'], array['images/flat/barbell-glute-bridge-start.webp', 'images/flat/barbell-glute-bridge-peak.webp'], 6, array['hypertrophy', 'strength'], array['leg_day', 'lower_back_safe', 'knee_safe', 'shoulder_safe', 'no_axial_load'], 'repdb'),
  ('barbell-lunge', 'Barbell Lunge', 'Full body', false, 'A forward lunge with a barbell across the upper back, training the quads and glutes one leg at a time.', 'strength', 'barbell', 'intermediate', 'compound', 'push', array['gluteus maximus', 'quadriceps'], array['erector spinae', 'gluteus medius', 'hamstrings'], array['Place a barbell across your upper back and stand tall.', 'Step forward with one leg into a long stride.', 'Lower your back knee toward the ground until your front thigh is parallel.', 'Drive through your front heel to return to standing.', 'Complete reps on one side, then switch.'], array['Take a stride long enough that your front knee stays over your ankle.', 'Keep your torso upright and core braced under the bar.', 'Push the floor away through the front heel, not the toes.'], array['images/flat/barbell-reverse-lunge-start.webp', 'images/flat/barbell-reverse-lunge-peak.webp'], 6, array['hypertrophy', 'strength'], array['knee_safe'], 'repdb'),
  ('barbell-overhead-extension', 'Barbell Overhead Extension', 'Full body', false, 'This isolation exercise effectively targets the triceps brachii by extending the elbows overhead, promoting muscle hypertrophy and strength.', 'strength', 'barbell', 'intermediate', 'isolation', 'push', array['triceps brachii'], null, array['Load a barbell with an appropriate weight and stand or sit with a neutral spine.', 'Grip the barbell with an overhand, shoulder-width grip, and press it overhead.', 'Slowly lower the barbell behind your head by flexing your elbows, keeping your upper arms stable.', 'Extend your elbows to press the barbell back to the starting overhead position, squeezing your triceps.', 'Maintain control throughout the movement, avoiding momentum.'], array['Keep your elbows tucked in and pointing forward to maximize triceps engagement and protect your shoulders.', 'Control the eccentric (lowering) phase to enhance muscle tension and growth.', 'Avoid arching your lower back excessively; brace your core to maintain stability.'], array['images/flat/barbell-overhead-extension-start.webp', 'images/flat/barbell-overhead-extension-peak.webp'], 5, array['hypertrophy', 'strength'], array['arm_day', 'push_day'], 'repdb'),
  ('barbell-preacher-curl', 'Barbell Preacher Curl', 'Full body', false, 'This isolation exercise targets the biceps brachii and brachialis by fixing the upper arms on a preacher bench, minimizing momentum and maximizing tension.', 'strength', 'barbell', 'intermediate', 'isolation', 'pull', array['biceps brachii'], array['brachialis'], array['Sit on a preacher bench with your chest against the pad, gripping a barbell with an underhand, shoulder-width grip.', 'Position your upper arms firmly against the pad, ensuring your elbows are slightly bent at the start.', 'Curl the barbell upwards by contracting your biceps, keeping your upper arms stationary on the pad.', 'Squeeze your biceps at the top of the movement, focusing on peak contraction.', 'Slowly lower the barbell back to the starting position, controlling the eccentric phase.', 'Fully extend your arms at the bottom to achieve a complete stretch in the biceps.'], array['Maintain constant tension on the biceps throughout the entire range of motion.', 'Avoid lifting your elbows off the pad; this indicates you''re using too much weight or momentum.', 'Focus on a controlled eccentric (lowering) phase to maximize muscle damage and growth.', 'Keep your wrists straight and aligned with your forearms to prevent strain.'], array['images/flat/barbell-preacher-curl-start.webp', 'images/flat/barbell-preacher-curl-peak.webp'], 5, array['hypertrophy'], array['arm_day', 'pull_day'], 'repdb'),
  ('barbell-pullover', 'Barbell Pullover', 'Back', false, 'A compound movement stretching and loading the lats and chest through a wide arc.', 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['latissimus dorsi', 'pectoralis major'], array['triceps brachii'], array['Lie across a bench with a barbell held over your chest.', 'Lower the bar back over your head in an arc.', 'Pull it back to the start over your chest.', 'Repeat.'], array['Keep a slight bend in the elbows.', 'Engage the lats to drive the bar back.'], array['images/flat/barbell-pullover-start.webp', 'images/flat/barbell-pullover-peak.webp'], 6, array['hypertrophy'], array['pull_day', 'knee_safe', 'no_axial_load', 'lower_back_safe', 'shoulder_safe', 'requires_bench'], 'repdb'),
  ('barbell-rear-delt-row', 'Barbell Rear Delt Row', 'Shoulders', false, 'A bent-over barbell row with flared elbows that shifts emphasis from the lats to the posterior deltoids and upper back.', 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['posterior deltoid'], array['latissimus dorsi', 'rhomboids', 'trapezius'], array['Hinge at the hips with a flat back until your torso is nearly parallel to the floor.', 'Hold a barbell with an overhand, wider-than-shoulder-width grip, arms hanging.', 'Row the bar up toward your upper chest with the elbows flaring out to the sides.', 'Pause and squeeze the rear delts and upper back at the top.', 'Lower the bar under control and repeat.'], array['Pull with the elbows, not the hands — think of driving them up and out.', 'Use a lighter load than a standard row; the wide grip reduces leverage.'], array['images/flat/barbell-rear-delt-row-start.webp', 'images/flat/barbell-rear-delt-row-peak.webp'], 6, array['hypertrophy', 'strength'], array['pull_day'], 'repdb'),
  ('barbell-reverse-lunge', 'Barbell Reverse Lunge', 'Full body', false, 'A barbell lunge stepping backward instead of forward, keeping the front shin vertical while loading the quads and glutes.', 'strength', 'barbell', 'intermediate', 'compound', 'push', array['gluteus maximus', 'quadriceps'], array['erector spinae', 'gluteus medius', 'hamstrings'], array['Place a barbell across your upper back and stand tall.', 'Step one foot backward into a long stride.', 'Lower your back knee toward the ground under control.', 'Drive through your front heel to return to standing.', 'Complete reps on one side, then switch.'], array['Step back far enough to keep your front shin close to vertical.', 'Lower the back knee straight down rather than leaning forward.', 'Keep your chest tall and hips square throughout.'], array['images/flat/barbell-reverse-lunge-start.webp', 'images/flat/barbell-reverse-lunge-peak.webp'], 6, array['hypertrophy', 'strength'], array['knee_safe'], 'repdb'),
  ('bent-over-barbell-row', 'Bent-Over Barbell Row', 'Back', false, 'A compound pulling movement that targets the upper and middle back.', 'strength', 'barbell', 'intermediate', 'compound', 'pull', array['latissimus dorsi', 'rhomboids'], array['biceps brachii', 'posterior deltoid'], array['Hinge at the hips with a slight knee bend.', 'Grip the bar slightly wider than shoulder-width.', 'Pull the bar to your lower chest, squeezing your shoulder blades.', 'Lower the bar under control.', 'Repeat.'], array['Keep your torso at roughly 45 degrees.', 'Do not use momentum to swing the weight.'], array['images/flat/barbell-row-start.webp', 'images/flat/barbell-row-peak.webp'], 6, array['hypertrophy', 'strength'], array['pull_day', 'knee_safe', 'shoulder_safe'], 'repdb'),
  ('barbell-wrist-curl', 'Barbell Wrist Curl', 'Full body', false, 'A barbell wrist curl that isolates the forearm flexors for grip and forearm size.', 'strength', 'barbell', 'beginner', 'isolation', 'pull', array['forearm flexors'], null, array['Sit on a bench with forearms resting on the thighs, palms up.', 'Hold a barbell with hands shoulder-width, wrists hanging off the knees.', 'Let the bar roll down to the fingertips at the bottom.', 'Curl the bar up by flexing the wrists.', 'Lower under control.'], array['Move only at the wrist — keep the forearms still.', 'Roll the bar to the fingertips for full range.', 'Use a thumbless grip if it helps wrist comfort.'], array['images/flat/barbell-wrist-curl-start.webp', 'images/flat/barbell-wrist-curl-peak.webp'], 5, array['hypertrophy'], array['arm_day', 'grip_focus'], 'repdb'),
  ('battle-rope-double-slam', 'Battle Rope Double Slam', 'Full body', true, 'A conditioning movement in which both rope ends are driven up and slammed down together, producing one large wave per rep instead of the alternating waves of the standard battle rope drill.', 'cardio', 'battle rope', 'intermediate', 'compound', 'dynamic', array['anterior deltoid', 'latissimus dorsi'], array['forearm flexors', 'gluteus maximus', 'obliques', 'quadriceps', 'rectus abdominis', 'trapezius'], array['Take one rope end in each hand and face the anchor, standing far enough back that the ropes have a slight slack.', 'Set your feet slightly wider than your hips and sit into a quarter squat with your chest up.', 'Swing both arms up together, letting the ropes rise in front of you as you extend through the hips.', 'Slam both ends down to the floor at the same time, hinging at the hips and driving through your lats.', 'Ride the rebound straight back into the next slam, keeping both arms moving in unison rather than alternating.', 'Keep slamming for the desired time or number of reps.'], array['Both arms move together — the moment they start alternating you are doing the standard wave drill, which is a different exercise.', 'Drive the slam with your hips and lats rather than your arms, or your shoulders will burn out long before your lungs do.', 'Stand at the right distance from the anchor: too close and the rope goes slack, too far and you cannot get a wave into it at all.'], array['images/flat/battle-rope-double-slam-start.webp', 'images/flat/battle-rope-double-slam-peak.webp'], 10.3, array['endurance', 'power'], array['full_body', 'conditioning'], 'repdb'),
  ('battle-ropes', 'Battle Ropes', 'Full body', true, 'A high-intensity conditioning movement using thick ropes, training the upper back, shoulders, and grip.', 'cardio', 'battle rope', 'intermediate', 'compound', 'dynamic', array['anterior deltoid', 'lateral deltoid', 'latissimus dorsi'], array['forearm flexors', 'quadriceps', 'rectus abdominis', 'trapezius'], array['Anchor the ropes to a fixed point and grab one end in each hand.', 'Step back so the ropes have moderate slack.', 'Drop into a quarter squat with feet shoulder-width.', 'Drive each arm up and down rapidly to send waves through the ropes.', 'Continue for the prescribed work interval.'], array['Stay in the quarter-squat the entire interval.', 'Drive force from the legs and hips, not just the arms.', 'Keep the waves consistent and tight.'], array['images/flat/battle-ropes-main.webp'], 10.3, array['endurance', 'power'], array['full_body', 'conditioning'], 'repdb'),
  ('bear-crawl', 'Bear Crawl', 'Full body', false, 'A quadruped bodyweight crawl on hands and toes with the knees hovering just off the floor, building shoulder stability and core control as you travel forward.', 'strength', null, 'beginner', 'compound', 'dynamic', array['anterior deltoid', 'rectus abdominis'], array['obliques', 'quadriceps', 'triceps brachii'], array['Start on all fours with your hands under your shoulders and knees under your hips.', 'Tuck your toes and lift your knees a few centimeters off the floor.', 'Keeping your back flat and hips low, step your right hand and left foot forward together.', 'Then move your left hand and right foot, crawling forward in a controlled rhythm.', 'Keep your core braced and your hips from swaying side to side.'], array['Move opposite hand and foot together, like an exaggerated crawl.', 'Keep your knees low and hips level — do not let them pop up or rock.'], array['images/flat/bear-crawl-start.webp', 'images/flat/bear-crawl-peak.webp'], 5, array['endurance'], array['full_body', 'conditioning', 'core', 'bodyweight'], 'repdb'),
  ('behind-the-back-barbell-shrug', 'Behind the Back Barbell Shrug', 'Back', false, 'A shrug variation with the barbell held behind the body, targeting the trapezius.', 'strength', 'barbell', 'intermediate', 'isolation', 'pull', array['trapezius'], array['forearm flexors', 'rhomboids'], array['Stand holding a barbell behind your back with an overhand grip.', 'Keep your arms straight and chest up.', 'Shrug your shoulders straight up toward your ears.', 'Pause and squeeze at the top.', 'Lower under control and repeat.'], array['Lift straight up and down without rolling the shoulders.', 'Avoid bending your elbows to heave the weight higher.', 'Stand tall with a neutral neck and look straight ahead.'], array['images/flat/behind-the-back-barbell-shrug-start.webp', 'images/flat/behind-the-back-barbell-shrug-peak.webp'], 5, array['hypertrophy'], array['knee_safe', 'lower_back_safe', 'shoulder_safe', 'no_axial_load'], 'repdb'),
  ('behind-the-neck-lat-pulldown', 'Behind-the-Neck Lat Pulldown', 'Back', false, 'A wide-grip lat pulldown taken behind the head, targeting the upper lats and traps — requires full overhead shoulder mobility.', 'strength', 'lat pulldown machine', 'advanced', 'compound', 'pull', array['latissimus dorsi'], array['posterior deltoid', 'rhomboids', 'trapezius'], array['Sit at a lat pulldown station with thighs secured under the pad.', 'Grip the bar with a wide, overhand grip — wider than shoulder-width.', 'Keep the torso upright and tuck the chin slightly forward.', 'Pull the bar down behind the head until it touches the base of the neck.', 'Return under control to the full overhead stretch.', 'Repeat for the recommended number of repetitions.'], array['Only perform this if you have full, pain-free overhead shoulder mobility.', 'Use a moderate load — this is not a strength lift, it''s a hypertrophy accessory.'], array['images/flat/behind-the-neck-lat-pulldown-start.webp', 'images/flat/behind-the-neck-lat-pulldown-peak.webp'], 6, array['hypertrophy'], array['pull_day'], 'repdb'),
  ('behind-the-neck-press', 'Behind the Neck Press', 'Shoulders', false, 'An overhead press performed with the barbell starting behind the neck, emphasizing the front and side deltoids.', 'strength', 'barbell', 'intermediate', 'compound', 'push', array['anterior deltoid', 'lateral deltoid'], array['trapezius', 'triceps brachii'], array['Sit or stand with a barbell resting on your upper traps behind your neck.', 'Grip the bar wider than shoulder width.', 'Press the bar straight up overhead until your arms are extended.', 'Lower the bar back to the starting position under control.', 'Repeat for the desired number of reps.'], array['Lower the bar only as far as your shoulders allow comfortably.', 'Keep your forearms vertical under the bar throughout the press.', 'Brace your core to avoid arching the lower back overhead.'], array['images/flat/behind-the-neck-press-start.webp', 'images/flat/behind-the-neck-press-peak.webp'], 6, array['hypertrophy', 'strength'], array['knee_safe'], 'repdb'),
  ('behind-the-neck-pull-up', 'Behind-the-Neck Pull-Up', 'Back', false, 'A wide-grip pull-up pulled high enough that the bar passes behind the head at the top instead of under the chin, which forces the shoulders into end-range external rotation.', 'strength', 'pull up bar', 'advanced', 'compound', 'pull', array['latissimus dorsi'], array['biceps brachii', 'posterior deltoid', 'rhomboids', 'trapezius'], array['Grip the pull-up bar with an overhand grip wider than shoulder-width and hang at full arm extension with your legs together.', 'Keep your torso vertical rather than leaning back, and pull your elbows down and out to the sides.', 'Continue pulling until the bar passes behind your head and the back of your neck comes level with it, without letting the bar touch your neck.', 'Lower yourself under control back to a full dead hang, keeping your head still rather than letting it snap forward.', 'Repeat for the desired number of reps.'], array['This variation is widely discouraged. Finishing behind the head loads the shoulder at the end of its external rotation, where the joint has the least capacity to protect itself, and any contact between the bar and the neck puts that load through the cervical spine.', 'A standard or wide-grip pull-up trains the same muscles through the same shoulder range — nothing about back development requires the bar to travel behind the head, so there is no benefit here to trade the risk against.', 'If you perform it anyway, stop well short of touching the bar to your neck and leave it out entirely if you lack full pain-free overhead shoulder mobility or have any history of shoulder or neck problems.'], array['images/flat/behind-the-neck-pull-ups-start.webp', 'images/flat/behind-the-neck-pull-ups-peak.webp'], 6, array['hypertrophy', 'strength'], array['knee_safe', 'no_axial_load', 'lower_back_safe'], 'repdb'),
  ('bench-adductor-stretch', 'Bench Adductor Stretch', 'Legs', false, 'A standing stretch with one straight leg resting on a bench out to the side to lengthen the inner thigh.', 'stretching', 'flat bench', 'beginner', 'isolation', 'static', array['adductors'], array['hamstrings'], array['Stand side-on to a bench.', 'Rest one straight leg up on the bench out to the side.', 'Keep your torso upright and shift gently toward the bench.', 'Hold for 20 to 30 seconds, breathing steadily.', 'Switch sides and repeat.'], array['Keep both legs straight.', 'Keep the standing foot pointing forward.'], array['images/flat/bench-adductor-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
  ('bench-ankle-stretch', 'Bench Ankle Stretch', 'Full body', false, 'A standing stretch with the foot flat on a bench, driving the knee forward over the toes to flex the ankle.', 'stretching', 'flat bench', 'beginner', 'isolation', 'static', array['gastrocnemius'], array['soleus'], array['Place one whole foot flat on top of a bench.', 'Keep your torso upright.', 'Drive that knee forward over your toes.', 'Hold for 20 to 30 seconds, breathing steadily.', 'Switch sides and repeat.'], array['Keep your heel down on the bench.', 'Move slowly and keep the foot flat.'], array['images/flat/bench-ankle-stretch-main.webp'], 5, array['mobility'], array['mobility', 'stretching'], 'repdb'),
