  ('bicycle-crunch', 'Bicycle Crunch', 'Core', false, 'A dynamic crunch variation targeting both the rectus abdominis and obliques.', 'strength', null, 'beginner', 'compound', 'pull', array['obliques', 'rectus abdominis'], array['hip flexors'], array['Lie on your back with hands behind your head and legs raised.', 'Bring one knee toward your chest while rotating your torso to meet it with the opposite elbow.', 'Extend that leg while bringing the other knee in.', 'Continue alternating in a pedaling motion.', 'Repeat.'], array['Avoid pulling on your neck with your hands.', 'Lead the rotation with your shoulder, not your elbow.', 'Move slowly and deliberately rather than racing through reps.'], array['images/flat/bicycle-crunch-start.webp', 'images/flat/bicycle-crunch-peak.webp'], 5, array['hypertrophy'], array['core', 'knee_safe', 'shoulder_safe', 'no_axial_load', 'lower_back_safe'], 'repdb'),
  ('bird-dog', 'Bird-Dog', 'Core', false, 'A core stability exercise extending opposite arm and leg to challenge the erector spinae and deep core.', 'strength', null, 'beginner', 'compound', 'dynamic', array['erector spinae', 'transverse abdominis'], array['gluteus maximus'], array['Start on all fours with a neutral spine.', 'Extend your right arm forward and left leg back simultaneously.', 'Hold for a moment, then return.', 'Repeat on the other side.', 'Alternate.'], array['Move slowly and with control.', 'Keep hips level throughout.'], array['images/flat/bird-dog-start.webp', 'images/flat/bird-dog-peak.webp'], 5, array['endurance', 'rehabilitation'], array['core', 'lower_back_safe', 'knee_safe', 'no_axial_load', 'shoulder_safe'], 'repdb'),
